window.UP={"version":2,"updated":"2026-09-19","references":{"pebc":["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"],"blueprint":["PEBC examination blueprint","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/examination-blueprint/"],"napra":["NAPRA professional resources","https://www.napra.ca/resources/publications/"],"ocp":["Ontario exam preparation","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/prepare-for-the-exam/"],"warfarin":["Thrombosis Canada: Warfarin","https://thrombosiscanada.ca/clinical_guides/pdfs/WARFARIN_43.pdf"],"hypertension":["Hypertension Canada guidelines","https://hypertension.ca/guidelines/"],"diabetes":["Diabetes Canada guidelines","https://www.diabetes.ca/for-professionals/full-guidelines"],"canada":["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],"privacy":["Ontario privacy guidance","https://www.ipc.on.ca/en/health-organizations"]},"provinces":[{"name":"Alberta","regulator":"Alberta College of Pharmacy","url":"https://abpharmacy.ca/"},{"name":"British Columbia","regulator":"College of Pharmacists of British Columbia","url":"https://www.bcpharmacists.org/"},{"name":"Manitoba","regulator":"College of Pharmacists of Manitoba","url":"https://cphm.ca/"},{"name":"New Brunswick","regulator":"New Brunswick College of Pharmacists","url":"https://www.nbpharmacists.ca/"},{"name":"Newfoundland and Labrador","regulator":"College of Pharmacy of Newfoundland and Labrador","url":"https://cpnl.ca/"},{"name":"Nova Scotia","regulator":"Nova Scotia Pharmacy Regulator","url":"https://nspharmacy.ca/"},{"name":"Ontario","regulator":"Ontario College of Pharmacists","url":"https://ocpinfo.com/"},{"name":"Prince Edward Island","regulator":"Prince Edward Island College of Pharmacy","url":"https://www.pepharmacists.ca/"},{"name":"Quebec","regulator":"Ordre des pharmaciens du Québec","url":"https://www.opq.org/"},{"name":"Saskatchewan","regulator":"Saskatchewan College of Pharmacy Professionals","url":"https://saskpharm.ca/"}],"subjects":[{"name":"Cardiology","icon":"heart-pulse"},{"name":"Infectious Disease","icon":"shield-plus"},{"name":"Dermatology","icon":"scan-face"},{"name":"Psychiatry","icon":"brain"},{"name":"GI, GU & Reproductive Health","icon":"activity"},{"name":"Neurology","icon":"brain-circuit"},{"name":"Musculoskeletal","icon":"bone"},{"name":"Endocrine & Metabolic","icon":"droplets"},{"name":"Respiratory","icon":"wind"},{"name":"Minor Ailments","icon":"cross"},{"name":"Ophthalmology","icon":"eye"},{"name":"Oncology","icon":"ribbon"},{"name":"Anemias, Electrolytes & Nutrition","icon":"flask-conical"},{"name":"Kidney Health","icon":"activity"},{"name":"Law & Ethics","icon":"scale"},{"name":"Evidence & Research","icon":"chart-no-axes-combined"},{"name":"Pharmacy Practice","icon":"clipboard-check"},{"name":"Pharmacy Foundations","icon":"book-open"},{"name":"Special Populations","icon":"users"},{"name":"Devices & Technique","icon":"stethoscope"}],"lessons":[{"id":"hypertension","title":"Hypertension","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":3,"competency":"Clinical Care","sources":[["Hypertension Canada guidelines","https://hypertension.ca/guidelines/"],["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assess before changing therapy","text":["Confirm measurement technique, cuff suitability, readings over time and relevant home or ambulatory measurements. Review symptoms, cardiovascular risk, comorbidities, medicines and adherence.","A severe reading with concerning acute symptoms needs prompt assessment. A single reading without context should not become an automatic treatment change."]},{"title":"Plan and monitor","text":["Use current Canadian guidance to identify the applicable diagnostic threshold, treatment target and options for this patient. Discuss feasible lifestyle measures alongside medicine assessment.","Link the monitoring plan to both effectiveness and safety. Evaluate tolerability, orthostatic symptoms and relevant laboratory needs after changes."]}],"quick":["Check measurement quality","Use current targets and patient context","Monitor safety as well as pressure"],"date":"2026-09-18","overview":"Reliable measurement and the patient’s overall risk are central to evaluating blood pressure.","hi":"उच्च रक्तचाप में पहले मापने की सही विधि, कफ का आकार और कई रीडिंग देखें। एक संख्या से तुरंत इलाज बदलना सही नहीं। घर या एम्बुलेटरी रीडिंग और कुल हृदय जोखिम उपयोगी हैं। गंभीर रीडिंग के साथ छाती दर्द, सांस या न्यूरोलॉजिकल लक्षण हों तो तुरंत जांच जरूरी है। वर्तमान कनाडाई दिशानिर्देश से लक्ष्य और दवा चुनें। जीवनशैली, दवा पालन, चक्कर, इलेक्ट्रोलाइट और गुर्दे की निगरानी साथ रखें। दवा बदलने के बाद लाभ और नुकसान दोनों की समीक्षा करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"warfarin-dosing","title":"Warfarin Dosing","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":3,"competency":"Clinical Care","sources":[["Thrombosis Canada: Warfarin","https://thrombosiscanada.ca/clinical_guides/pdfs/WARFARIN_43.pdf"],["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Before a dose decision","text":["Confirm indication, the prescribed INR target, current regimen, recent doses and recent INR trend. Ask about missed doses, dietary changes, acute illness and new or stopped medicines.","Do not adjust from one number without context. Use the current local anticoagulation protocol and patient-specific clinical assessment."]},{"title":"Counselling priorities","text":["Explain the purpose of INR monitoring and the individualized dosing schedule. Discuss adherence, interactions, consistent dietary habits and the agreed plan for missed doses.","Serious bleeding, a head injury or symptoms suggesting thrombosis need urgent assessment. Explain warning signs and whom to contact using the current care plan."]}],"quick":["Confirm indication and target INR","Use trends and the actual dosing history","Escalate serious bleeding or head injury"],"date":"2026-09-18","overview":"Warfarin assessment connects indication, INR results, bleeding risk and changes in the patient’s regimen.","hi":"वारफरिन में पहले कारण, निर्धारित आई एन आर लक्ष्य और वर्तमान साप्ताहिक योजना पुष्टि करें। आज का आई एन आर उसके पिछले पैटर्न, छूटी खुराक, भोजन, बीमारी और नई दवाओं के साथ समझें। खून आने के संकेत पहले पूछें। केवल एक संख्या से याद की हुई खुराक न दें। उत्पाद और स्थानीय प्रोटोकॉल के अनुसार सही टीम से योजना लें। अगली जांच की तारीख और मरीज को हर दिन की स्पष्ट मात्रा बताएं। विटामिन के वाले भोजन को बिल्कुल बंद करने के बजाय स्थिर सेवन की सलाह दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"stroke-transient-ischemic-attack-tia","title":"Stroke & Transient Ischemic Attack (TIA)","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assessment","text":["Sudden facial weakness, arm weakness or speech difficulty may represent stroke. Record when the person was last known well; resolved symptoms can still indicate a TIA and require urgent assessment."]},{"title":"Treatment principles","text":["Activate emergency care for suspected acute stroke. Brain imaging and specialist assessment distinguish bleeding from ischaemia and determine treatment. Later prevention depends on the cause: antiplatelet therapy and anticoagulation are not interchangeable."]},{"title":"Safety and follow-up","text":["Do not delay referral to measure every risk factor or give oral medication to someone with impaired swallowing. After discharge, reconcile medicines and review blood pressure, lipids, smoking, adherence and bleeding symptoms."]}],"quick":["Sudden facial weakness, arm weakness or speech difficulty may represent stroke","Activate emergency care for suspected acute stroke","Do not delay referral to measure every risk factor or give oral medication to someone with impaired swallowing"],"date":"2026-09-18","overview":"Sudden facial weakness, arm weakness or speech difficulty may represent stroke.","hi":"अचानक चेहरा टेढ़ा होना, हाथ कमजोर होना या बोलने में परेशानी स्ट्रोक का संकेत हो सकता है। लक्षण शुरू होने से पहले मरीज आखिरी बार कब सामान्य था, यह समय लिखें। लक्षण ठीक हो जाएं तब भी तुरंत जांच जरूरी है। आपातकालीन मदद बुलाएं। निगलने में परेशानी हो तो मुंह से दवा न दें। जांच के बिना एस्पिरिन या खून पतला करने की दवा शुरू न करें। बाद में कारण के अनुसार इलाज, रक्तचाप, कोलेस्ट्रॉल और दवा पालन की समीक्षा करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"syncope","title":"Syncope","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assessment","text":["Clarify whether there was true loss of consciousness, the posture and trigger, warning symptoms, duration, injury and recovery. Ask about exertion, palpitations, chest pain, heart disease and medicines that lower blood pressure or prolong QT."]},{"title":"Treatment principles","text":["A typical faint may have a recognizable trigger and rapid recovery, but a medicine explanation does not exclude an arrhythmia. Assess hydration, orthostatic symptoms and recent dose changes; arrange appropriate medical evaluation."]},{"title":"Safety and follow-up","text":["Exertional collapse, chest pain, persistent confusion, neurological symptoms or a family history of sudden death are concerning. Do not advise driving until the cause and relevant restrictions have been assessed."]}],"quick":["Clarify whether there was true loss of consciousness, the posture and trigger, warning symptoms, duration, injury and recovery","A typical faint may have a recognizable trigger and rapid recovery, but a medicine explanation does not exclude an arrhythmia","Exertional collapse, chest pain, persistent confusion, neurological symptoms or a family history of sudden death are concerning"],"date":"2026-09-18","overview":"Clarify whether there was true loss of consciousness, the posture and trigger, warning symptoms, duration, injury and recovery.","hi":"बेहोशी के बारे में पूछें: घटना किस स्थिति में हुई, पहले क्या महसूस हुआ और होश कितनी जल्दी आया। व्यायाम के दौरान बेहोशी, छाती में दर्द, धड़कन या परिवार में अचानक मृत्यु का इतिहास गंभीर संकेत हैं। रक्तचाप कम करने वाली और हृदय की लय बदलने वाली दवाएं जांचें। केवल पानी की कमी मानकर बात खत्म न करें। कारण की जांच और सुरक्षित गतिविधियों की सलाह जरूरी है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"dyslipidaemia","title":"Dyslipidaemia","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assessment","text":["Interpret lipids with overall cardiovascular risk, previous vascular disease, diabetes, kidney disease and family history. Ask about secondary causes and medicines; LDL cholesterol alone does not describe the whole decision."]},{"title":"Treatment principles","text":["Lifestyle measures accompany medication when indicated. Statins reduce cardiovascular events in appropriate patients; select intensity and additional therapy using current Canadian guidance, expected benefit, tolerability and preferences."]},{"title":"Safety and follow-up","text":["Review interacting medicines and unexplained muscle symptoms. Severe muscle pain with weakness or dark urine needs prompt assessment. Check adherence and follow-up lipids before labelling a regimen ineffective; avoid stopping long-term prevention without a plan."]}],"quick":["Interpret lipids with overall cardiovascular risk, previous vascular disease, diabetes, kidney disease and family history","Lifestyle measures accompany medication when indicated","Review interacting medicines and unexplained muscle symptoms"],"date":"2026-09-18","overview":"Interpret lipids with overall cardiovascular risk, previous vascular disease, diabetes, kidney disease and family history.","hi":"कोलेस्ट्रॉल का निर्णय केवल एल डी एल संख्या से नहीं होता। पहले हृदय रोग, मधुमेह, गुर्दे की बीमारी और कुल जोखिम देखें। उचित मरीजों में स्टैटिन दिल के दौरे और स्ट्रोक का जोखिम घटाती हैं। जीवनशैली और दवा पालन साथ चलें। नई मांसपेशियों की कमजोरी या गहरे रंग का पेशाब हो तो जल्दी जांच करवाएं। उपचार बदलने से पहले दवा का नियमित उपयोग, दवा अंतःक्रिया और दोबारा जांच की समीक्षा करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"dvt-and-pe","title":"DVT and PE","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assessment","text":["One swollen painful leg may indicate deep-vein thrombosis. New unexplained breathlessness, pleuritic chest pain, coughing blood or collapse may indicate pulmonary embolism. Symptoms require assessment; they do not confirm the diagnosis alone."]},{"title":"Treatment principles","text":["Suspected PE needs urgent emergency evaluation. Anticoagulant selection and duration depend on the confirmed diagnosis, provoking factors, recurrence risk, bleeding risk, kidney function, pregnancy and cancer context."]},{"title":"Safety and follow-up","text":["Check the exact anticoagulant and treatment phase because starting and maintenance regimens can differ. Teach adherence, bleeding precautions and what to do for missed doses using the product-specific plan. Do not substitute aspirin for prescribed VTE treatment."]}],"quick":["One swollen painful leg may indicate deep-vein thrombosis","Suspected PE needs urgent emergency evaluation","Check the exact anticoagulant and treatment phase because starting and maintenance regimens can differ"],"date":"2026-09-18","overview":"One swollen painful leg may indicate deep-vein thrombosis.","hi":"एक पैर में नई सूजन और दर्द गहरी नस में थक्का होने का संकेत हो सकता है। अचानक सांस फूलना, छाती में दर्द या बेहोशी फेफड़े में थक्के के गंभीर संकेत हैं। तुरंत चिकित्सा जांच करवाएं। खून पतला करने वाली दवा का चुनाव और अवधि मरीज के जोखिम पर निर्भर हैं। शुरुआती और बाद की खुराक अलग हो सकती है। दवा का सही चरण, गुर्दे की स्थिति, रक्तस्राव और छूटी खुराक की सलाह जांचें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"atrial-fibrillation","title":"Atrial Fibrillation","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assessment","text":["An irregular pulse requires diagnostic assessment. Separate symptoms and ventricular-rate control from prevention of embolic stroke. Review heart failure, valvular disease, kidney function, previous stroke and bleeding factors."]},{"title":"Treatment principles","text":["Rate control, rhythm control and anticoagulation address different goals. Use the applicable Canadian risk approach and shared decision-making. Some valve conditions require warfarin rather than a direct oral anticoagulant."]},{"title":"Safety and follow-up","text":["Verify anticoagulant dose criteria and interacting medicines rather than reducing the dose solely because a person is older. Monitor symptoms, pulse, renal function and bleeding. Haemodynamic instability or new stroke symptoms requires emergency care."]}],"quick":["An irregular pulse requires diagnostic assessment","Rate control, rhythm control and anticoagulation address different goals","Verify anticoagulant dose criteria and interacting medicines rather than reducing the dose solely because a person is older"],"date":"2026-09-18","overview":"An irregular pulse requires diagnostic assessment.","hi":"एट्रियल फिब्रिलेशन में तीन अलग लक्ष्य याद रखें: हृदय की गति, उसकी लय और स्ट्रोक से बचाव। केवल धड़कन नियंत्रित होने से स्ट्रोक का खतरा खत्म नहीं होता। वाल्व की बीमारी, उम्र, वजन, गुर्दे की कार्यक्षमता और रक्तस्राव का जोखिम जांचें। कुछ वाल्व स्थितियों में वारफरिन जरूरी होती है। केवल बुजुर्ग होने पर खुराक कम न करें। नई कमजोरी, बोलने में परेशानी या अस्थिर हालत में तुरंत आपातकालीन मदद लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"heart-failure","title":"Heart Failure","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assessment","text":["Assess breathlessness, swelling, weight trend, exercise tolerance, blood pressure and congestion. Identify the heart-failure phenotype and triggers such as missed medicines, infection, arrhythmia or NSAID exposure."]},{"title":"Treatment principles","text":["In reduced-ejection-fraction heart failure, disease-modifying classes include renin–angiotensin system therapy, selected beta blockers, mineralocorticoid antagonists and SGLT2 inhibitors when appropriate. Diuretics relieve congestion but do not replace the other indicated therapies."]},{"title":"Safety and follow-up","text":["Review potassium, kidney function, dizziness and fluid status after changes. Provide an individualized action plan for worsening symptoms. Severe breathlessness at rest, chest pain or confusion requires emergency assessment; do not independently double every medicine."]}],"quick":["Assess breathlessness, swelling, weight trend, exercise tolerance, blood pressure and congestion","In reduced-ejection-fraction heart failure, disease-modifying classes include renin–angiotensin system therapy, selected beta blockers, mineralocorticoid antagonists and SGLT2 inhibitors when appropriate","Review potassium, kidney function, dizziness and fluid status after changes"],"date":"2026-09-18","overview":"Assess breathlessness, swelling, weight trend, exercise tolerance, blood pressure and congestion.","hi":"हार्ट फेल्योर में सांस, पैरों की सूजन, वजन, रक्तचाप और रोजमर्रा की क्षमता देखें। बीमारी का प्रकार जानना जरूरी है। कुछ दवाएं लंबे समय के परिणाम सुधारती हैं और मूत्रवर्धक दवाएं अतिरिक्त पानी कम करती हैं; दोनों का काम अलग है। दवा बदलने पर पोटैशियम और गुर्दे की जांच देखें। आराम में तेज सांस फूलना, छाती में दर्द या भ्रम हो तो आपातकालीन मदद लें। वजन बढ़ने पर अपनी लिखित योजना के अनुसार कदम उठाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"raynaud-s-phenomenon","title":"Raynaud's Phenomenon","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assessment","text":["Ask about cold- or stress-triggered colour changes, symmetry, pain, ulcers and associated autoimmune symptoms. New severe, asymmetric or late-onset symptoms raise concern for a secondary cause."]},{"title":"Treatment principles","text":["Keep the body and hands warm, avoid smoking and review vasoconstricting medicines. Persistent symptoms may need a clinician-directed vasodilator such as a dihydropyridine calcium-channel blocker, with attention to blood pressure and tolerability."]},{"title":"Safety and follow-up","text":["Persistent ischaemic pain, ulcers or a finger remaining cold and discoloured need prompt assessment. Do not assume every colour change is benign Raynaud's; assess circulation and the broader history."]}],"quick":["Ask about cold- or stress-triggered colour changes, symmetry, pain, ulcers and associated autoimmune symptoms","Keep the body and hands warm, avoid smoking and review vasoconstricting medicines","Persistent ischaemic pain, ulcers or a finger remaining cold and discoloured need prompt assessment"],"date":"2026-09-18","overview":"Ask about cold- or stress-triggered colour changes, symmetry, pain, ulcers and associated autoimmune symptoms.","hi":"ठंड या तनाव से उंगलियों का रंग बदलना रेनॉड की समस्या हो सकती है। दोनों हाथों में समान लक्षण हैं या केवल एक तरफ, यह पूछें। शरीर और हाथ गर्म रखें, धूम्रपान और रक्तवाहिकाएं सिकोड़ने वाली दवाओं की समीक्षा करें। लगातार दर्द, घाव या उंगली ठंडी और नीली रहने पर जल्दी जांच जरूरी है। हर रंग परिवर्तन को सामान्य रेनॉड न मानें। जरूरत पर डॉक्टर रक्तवाहिका फैलाने वाली दवा चुनते हैं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"acute-coronary-syndrome-and-stable-angina","title":"Acute Coronary Syndrome and Stable Angina","subject":"Cardiology","icon":"heart-pulse","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]],"sections":[{"title":"Assessment","text":["New, prolonged or worsening chest pressure, especially at rest or with sweating, breathlessness or nausea, may represent acute coronary syndrome. A previous angina diagnosis does not make new symptoms safe."]},{"title":"Treatment principles","text":["Activate emergency services for suspected acute coronary syndrome and follow the emergency plan. Stable angina management combines symptom relief with cardiovascular risk reduction. Confirm the patient's prescribed nitroglycerin instructions and contraindicating interactions."]},{"title":"Safety and follow-up","text":["Nitrates can interact dangerously with phosphodiesterase-5 inhibitors; clarify the exact drug and timing. Do not let apparent relief with an antacid or nitroglycerin rule out an infarction. Review adherence and prevention after acute care."]}],"quick":["New, prolonged or worsening chest pressure, especially at rest or with sweating, breathlessness or nausea, may represent acute coronary syndrome","Activate emergency services for suspected acute coronary syndrome and follow the emergency plan","Nitrates can interact dangerously with phosphodiesterase-5 inhibitors; clarify the exact drug and timing"],"date":"2026-09-18","overview":"New, prolonged or worsening chest pressure, especially at rest or with sweating, breathlessness or nausea, may represent acute coronary syndrome.","hi":"नया या बढ़ता छाती का दबाव, पसीना, मतली या सांस फूलना दिल के दौरे का संकेत हो सकता है। पुरानी एंजाइना होने से नया दर्द सुरक्षित नहीं हो जाता। आपातकालीन मदद लें। नाइट्रोग्लिसरीन की निर्धारित योजना और दूसरी दवाएं जांचें। इरेक्टाइल डिसफंक्शन की कुछ दवाओं के साथ नाइट्रेट खतरनाक रक्तचाप गिरा सकते हैं। दर्द कम होने से दिल का दौरा खारिज नहीं होता।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"sinusitis","title":"Sinusitis","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Ask about duration, initial improvement followed by worsening, fever, unilateral symptoms and dental pain. Most early acute sinus symptoms accompany viral illness; discharge colour alone does not establish bacterial infection."]},{"title":"Treatment principles","text":["Analgesia and saline measures can support symptom relief. Consider intranasal treatment and antibiotic assessment according to severity, duration and local guidance. Check pregnancy, allergies and comorbidities before recommending a product."]},{"title":"Safety and follow-up","text":["Eye swelling, visual change, severe frontal headache, neurological symptoms or systemic illness require urgent evaluation. Explain the expected course and when reassessment is needed rather than promising antibiotics for every episode."]}],"quick":["Ask about duration, initial improvement followed by worsening, fever, unilateral symptoms and dental pain","Analgesia and saline measures can support symptom relief","Eye swelling, visual change, severe frontal headache, neurological symptoms or systemic illness require urgent evaluation"],"date":"2026-09-18","overview":"Ask about duration, initial improvement followed by worsening, fever, unilateral symptoms and dental pain.","hi":"साइनस में दर्द और नाक बहना अक्सर वायरस से होता है। लक्षण कितने दिन से हैं और पहले ठीक होकर फिर बिगड़े हैं या नहीं, पूछें। केवल पीले या हरे स्राव से एंटीबायोटिक तय नहीं करें। दर्द नियंत्रण और नमक वाले पानी से राहत मिल सकती है। आंख के आसपास सूजन, नजर बदलना, बहुत तेज सिरदर्द या गंभीर बीमारी हो तो तुरंत जांच करवाएं। सुधार न होने पर दोबारा मूल्यांकन की योजना दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"meningitis","title":"Meningitis","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Fever with severe headache, neck stiffness, altered consciousness or a concerning rash can signal meningitis. Infants and immunocompromised people may have less typical findings; absence of the classic combination does not exclude serious illness."]},{"title":"Treatment principles","text":["Suspected meningitis requires emergency assessment and timely hospital treatment. Empiric treatment depends on age, host factors and likely organism, then is refined with investigations. Pharmacy work includes allergy clarification, renal review and timely supply."]},{"title":"Safety and follow-up","text":["Do not delay emergency transfer for a complete community medication interview. Some organisms trigger public-health action and prophylaxis for specified contacts; casual contacts should not self-start leftover antibiotics."]}],"quick":["Fever with severe headache, neck stiffness, altered consciousness or a concerning rash can signal meningitis","Suspected meningitis requires emergency assessment and timely hospital treatment","Do not delay emergency transfer for a complete community medication interview"],"date":"2026-09-18","overview":"Fever with severe headache, neck stiffness, altered consciousness or a concerning rash can signal meningitis.","hi":"बुखार के साथ तेज सिरदर्द, गर्दन अकड़ना, भ्रम या चिंताजनक चकत्ते मेनिन्जाइटिस के संकेत हो सकते हैं। छोटे बच्चों और कमजोर प्रतिरक्षा वाले मरीजों में सभी सामान्य लक्षण नहीं होते। तुरंत अस्पताल की जांच और इलाज जरूरी है। लंबी दवा सूची बनाने के लिए रेफरल न रोकें। कुछ संक्रमणों में खास संपर्कों को बचाव की दवा दी जाती है, लेकिन यह सार्वजनिक स्वास्थ्य टीम के निर्देश से होनी चाहिए।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"uti","title":"UTI","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Distinguish bladder symptoms from fever, flank pain, vomiting or systemic illness suggesting upper-tract infection. Ask about pregnancy, sex, age, catheters, previous cultures and recent antibiotics."]},{"title":"Treatment principles","text":["Choice of therapy depends on the infection site, local resistance, kidney function, allergies and culture information when indicated. A medicine appropriate for cystitis may not achieve adequate tissue levels for pyelonephritis."]},{"title":"Safety and follow-up","text":["Bacteria in urine without relevant symptoms is not automatically an indication for antibiotics; important exceptions require a specific indication. Escalate suspected pyelonephritis, sepsis or pregnancy-related concerns and reassess persistent symptoms."]}],"quick":["Distinguish bladder symptoms from fever, flank pain, vomiting or systemic illness suggesting upper-tract infection","Choice of therapy depends on the infection site, local resistance, kidney function, allergies and culture information when indicated","Bacteria in urine without relevant symptoms is not automatically an indication for antibiotics; important exceptions require a specific indication"],"date":"2026-09-18","overview":"Distinguish bladder symptoms from fever, flank pain, vomiting or systemic illness suggesting upper-tract infection.","hi":"पेशाब में जलन और बार-बार पेशाब को बुखार, कमर के एक तरफ दर्द और उल्टी से अलग करें। बाद वाले लक्षण गुर्दे के संक्रमण का संकेत हो सकते हैं। गर्भावस्था, पुरानी कल्चर रिपोर्ट, गुर्दे की स्थिति और एंटीबायोटिक का इतिहास देखें। मूत्राशय के संक्रमण की हर दवा गुर्दे के संक्रमण के लिए सही नहीं होती। बिना लक्षण केवल बैक्टीरिया मिलने पर हमेशा एंटीबायोटिक जरूरी नहीं है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"covid","title":"COVID","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Establish symptom onset, severity, risk of progression, vaccination history and current medicines. Breathlessness, low oxygen when reliably measured, confusion or inability to maintain hydration warrants urgent assessment."]},{"title":"Treatment principles","text":["Antiviral eligibility and timing follow current provincial guidance. Before nirmatrelvir/ritonavir, reconcile all medicines and assess interactions and kidney function; some interactions need an alternative treatment rather than a simple dose separation."]},{"title":"Safety and follow-up","text":["Provide symptom care, transmission precautions and follow-up advice appropriate to current public-health guidance. Do not promise an antiviral to everyone or recommend an unreviewed interruption of an essential medicine."]}],"quick":["Establish symptom onset, severity, risk of progression, vaccination history and current medicines","Antiviral eligibility and timing follow current provincial guidance","Provide symptom care, transmission precautions and follow-up advice appropriate to current public-health guidance"],"date":"2026-09-18","overview":"Establish symptom onset, severity, risk of progression, vaccination history and current medicines.","hi":"कोविड में लक्षण शुरू होने का समय, गंभीरता और बिगड़ने का जोखिम देखें। सांस फूलना, भ्रम या पानी न पी पाना गंभीर संकेत हैं। एंटीवायरल की पात्रता और समय प्रांतीय निर्देशों पर निर्भर है। नर्माट्रेलविर और रिटोनाविर देने से पहले सभी दवाएं और गुर्दे की स्थिति जांचें। कुछ दवा अंतःक्रियाएं केवल समय अलग करने से ठीक नहीं होतीं। जरूरी दवा अपने आप बंद न करवाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"acute-otitis-media","title":"Acute Otitis Media","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Paediatric Society: acute otitis media","https://cps.ca/en/documents/position/acute-otitis-media"]],"sections":[{"title":"Assessment","text":["Ear pain alone does not confirm middle-ear infection. Diagnosis depends on otoscopic findings and symptoms. Assess age, severity, duration, fever, discharge and the child's ability to drink."]},{"title":"Treatment principles","text":["Pain relief is important whether observation or antibiotics are selected. Appropriate observation requires a reliable follow-up plan; antibiotic decisions depend on age, diagnostic certainty, severity and current guidance."]},{"title":"Safety and follow-up","text":["Swelling or tenderness behind the ear, a protruding ear, severe illness or neurological signs need urgent assessment. Check weight and concentration when dispensing a liquid; do not infer millilitres directly from a milligram dose."]}],"quick":["Ear pain alone does not confirm middle-ear infection","Pain relief is important whether observation or antibiotics are selected","Swelling or tenderness behind the ear, a protruding ear, severe illness or neurological signs need urgent assessment"],"date":"2026-09-18","overview":"Ear pain alone does not confirm middle-ear infection.","hi":"कान का दर्द अकेले मध्य कान का संक्रमण साबित नहीं करता; कान की जांच जरूरी है। बच्चे की उम्र, बुखार, दर्द और पानी पीने की क्षमता देखें। दर्द कम करना महत्वपूर्ण है। कुछ स्थितियों में निगरानी और कुछ में एंटीबायोटिक जरूरी होते हैं। कान के पीछे सूजन, कान बाहर की ओर आना या गंभीर कमजोरी हो तो जल्दी जांच कराएं। तरल दवा में बच्चे का वजन और बोतल की सांद्रता अलग से जांचें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"sepsis-septic-shock","title":"Sepsis & Septic Shock","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Sepsis is life-threatening organ dysfunction related to infection. Confusion, marked deterioration, rapid breathing, low blood pressure or poor urine output are concerning; fever need not be present."]},{"title":"Treatment principles","text":["Activate urgent emergency care. Hospital priorities include assessment, timely antimicrobials, source control and haemodynamic support. Obtain cultures when appropriate without creating a harmful delay in treatment."]},{"title":"Safety and follow-up","text":["Pharmacy review includes allergies, likely source, organ function, dose timing, compatibility and subsequent narrowing of therapy. Do not manage a patient with shock by simply recommending oral fluids and an outpatient antibiotic."]}],"quick":["Sepsis is life-threatening organ dysfunction related to infection","Activate urgent emergency care","Pharmacy review includes allergies, likely source, organ function, dose timing, compatibility and subsequent narrowing of therapy"],"date":"2026-09-18","overview":"Sepsis is life-threatening organ dysfunction related to infection.","hi":"सेप्सिस में संक्रमण के साथ अंगों की कार्यक्षमता बिगड़ती है। भ्रम, तेज सांस, कम रक्तचाप या कम पेशाब गंभीर संकेत हैं; बुखार न होने पर भी खतरा हो सकता है। तुरंत आपातकालीन इलाज जरूरी है। अस्पताल में समय पर एंटीबायोटिक, संक्रमण के स्रोत का नियंत्रण और रक्तसंचार की सहायता दी जाती है। फार्मासिस्ट एलर्जी, गुर्दे की स्थिति, सही समय और दवा की उपयुक्तता जांचता है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"diabetic-foot-infections","title":"Diabetic Foot Infections","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Examine the history of an ulcer, neuropathy, circulation, trauma and systemic symptoms. Infection requires clinical evidence; colonization of a wound is not the same as an infected ulcer."]},{"title":"Treatment principles","text":["Management combines wound care, pressure off-loading, perfusion assessment, glycaemic care and antimicrobials when infection is present. Deep or severe infection may need imaging, surgical input and appropriately obtained cultures."]},{"title":"Safety and follow-up","text":["Spreading infection, necrosis, systemic illness or suspected critical ischaemia requires urgent assessment. Antibiotics alone cannot correct pressure injury or inadequate blood supply. Teach daily foot inspection and prompt reporting of new lesions."]}],"quick":["Examine the history of an ulcer, neuropathy, circulation, trauma and systemic symptoms","Management combines wound care, pressure off-loading, perfusion assessment, glycaemic care and antimicrobials when infection is present","Spreading infection, necrosis, systemic illness or suspected critical ischaemia requires urgent assessment"],"date":"2026-09-18","overview":"Examine the history of an ulcer, neuropathy, circulation, trauma and systemic symptoms.","hi":"मधुमेह के पैर के घाव में संक्रमण, रक्तप्रवाह और संवेदना तीनों देखें। हर कल्चर में बैक्टीरिया मिलना संक्रमण नहीं है। इलाज में घाव की देखभाल, दबाव कम करना, रक्तप्रवाह और शुगर नियंत्रण शामिल हैं। गहरा संक्रमण या मृत ऊतक होने पर अस्पताल की जरूरत हो सकती है। केवल एंटीबायोटिक पर्याप्त नहीं होती। रोज पैर देखें और नया घाव, सूजन या रंग बदलने पर जल्दी सूचना दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"onychomycosis","title":"Onychomycosis","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Thick or discoloured nails have several causes. Confirm fungal infection before prolonged systemic treatment when indicated, and assess extent, other skin infection, diabetes and circulation."]},{"title":"Treatment principles","text":["Topical and oral options differ in effectiveness, duration and monitoring. Oral terbinafine requires review of liver disease, interactions and appropriate baseline assessment. Nail appearance improves slowly as a healthy nail grows."]},{"title":"Safety and follow-up","text":["Avoid promising a normal-looking nail in a few days. Review adherence and adverse effects; concerning liver symptoms require assessment. Painful surrounding infection or a high-risk diabetic foot needs a broader evaluation."]}],"quick":["Thick or discoloured nails have several causes","Topical and oral options differ in effectiveness, duration and monitoring","Avoid promising a normal-looking nail in a few days"],"date":"2026-09-18","overview":"Thick or discoloured nails have several causes.","hi":"मोटा या बदरंग नाखून हमेशा फंगस नहीं होता। लंबे समय की खाने वाली दवा से पहले निदान की पुष्टि करें। बाहरी और खाने वाली दवाओं की अवधि और असर अलग हैं। टर्बिनाफिन से पहले लिवर और दवा अंतःक्रिया देखें। नया नाखून धीरे बढ़ता है, इसलिए परिणाम में समय लगता है। लिवर संबंधी लक्षण या मधुमेह में दर्द वाला घाव हो तो जांच जरूरी है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"principles-of-infectious-disease","title":"Principles of Infectious Disease","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Identify the likely site, organism, severity and host factors. Ask whether infection is actually present and whether cultures or other tests will change management."]},{"title":"Treatment principles","text":["Choose an antimicrobial using spectrum, penetration, local susceptibility, allergy history and organ function. Empiric treatment is reassessed when microbiology and clinical progress become available; narrow or stop therapy when appropriate."]},{"title":"Safety and follow-up","text":["Correct drug selection does not replace drainage, device removal or other source control. Document indication and review date. Discuss adherence, relevant adverse effects and reassessment if symptoms worsen or fail to improve."]}],"quick":["Identify the likely site, organism, severity and host factors","Choose an antimicrobial using spectrum, penetration, local susceptibility, allergy history and organ function","Correct drug selection does not replace drainage, device removal or other source control"],"date":"2026-09-18","overview":"Identify the likely site, organism, severity and host factors.","hi":"संक्रमण में पहले स्थान, गंभीरता, संभावित जीवाणु और मरीज के जोखिम पहचानें। सही एंटीबायोटिक चुनने में उसका क्षेत्र, ऊतक में पहुंच, स्थानीय प्रतिरोध, एलर्जी और गुर्दे की स्थिति शामिल हैं। कल्चर और मरीज की प्रगति मिलने पर इलाज दोबारा देखें। जहां जरूरी हो पस निकालना या संक्रमित उपकरण हटाना भी जरूरी है। हर एंटीबायोटिक के लिए कारण और समीक्षा की तारीख लिखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"tick-borne-infections","title":"Tick-Borne Infections","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Ask where exposure occurred, attachment duration if known, removal time, rash and systemic symptoms. Lyme disease is only one tick-borne illness; geography and travel affect the differential."]},{"title":"Treatment principles","text":["Remove an attached tick correctly and assess whether the current local criteria support prophylaxis. Prophylaxis is not automatically indicated after every bite and is distinct from treating established disease."]},{"title":"Safety and follow-up","text":["An expanding rash, facial weakness, severe headache, palpitations or systemic illness needs assessment. A negative early antibody test does not reliably exclude early infection. Record exposure details and provide a symptom follow-up plan."]}],"quick":["Ask where exposure occurred, attachment duration if known, removal time, rash and systemic symptoms","Remove an attached tick correctly and assess whether the current local criteria support prophylaxis","An expanding rash, facial weakness, severe headache, palpitations or systemic illness needs assessment"],"date":"2026-09-18","overview":"Ask where exposure occurred, attachment duration if known, removal time, rash and systemic symptoms.","hi":"टिक काटने पर जगह, चिपके रहने का समय, हटाने का समय और लक्षण पूछें। हर टिक काटने के बाद बचाव की एंटीबायोटिक जरूरी नहीं होती। स्थानीय मानदंड देखें। फैलता लाल चकत्ता, चेहरे की कमजोरी, धड़कन या तेज सिरदर्द हो तो जांच कराएं। शुरुआती जांच नकारात्मक होने से बीमारी पूरी तरह खारिज नहीं होती। बचाव की खुराक और स्थापित बीमारी का इलाज अलग हैं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"fungal-infections","title":"Fungal Infections","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Distinguish a localized skin infection from mucosal or invasive disease. Site, immune status, previous treatment and possible mimics guide assessment; a rash is not automatically fungal."]},{"title":"Treatment principles","text":["Select topical or systemic therapy according to the site and organism. Systemic azoles have important interactions and may require hepatic or electrocardiographic review. Some medicines suitable for skin cannot treat invasive infection."]},{"title":"Safety and follow-up","text":["Avoid masking an uncertain fungal rash with corticosteroid monotherapy. Fever in a severely immunocompromised patient needs urgent evaluation. Teach correct application, duration and when nonresponse requires diagnostic reassessment."]}],"quick":["Distinguish a localized skin infection from mucosal or invasive disease","Select topical or systemic therapy according to the site and organism","Avoid masking an uncertain fungal rash with corticosteroid monotherapy"],"date":"2026-09-18","overview":"Distinguish a localized skin infection from mucosal or invasive disease.","hi":"फंगल संक्रमण में त्वचा, मुंह और शरीर के अंदर के संक्रमण अलग हैं। स्थान और प्रतिरक्षा की स्थिति के अनुसार इलाज चुनें। खाने वाली एजोल दवाओं की महत्वपूर्ण अंतःक्रियाएं हो सकती हैं। बिना स्पष्ट निदान स्टेरॉयड अकेले लगाने से फंगस छिप या बिगड़ सकता है। कमजोर प्रतिरक्षा वाले मरीज में बुखार हो तो तुरंत जांच जरूरी है। इलाज से सुधार न हो तो निदान दोबारा देखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pep-occupational-infections","title":"PEP & Occupational Infections","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Public Health Agency of Canada: STBBI guidelines","https://www.canada.ca/en/public-health/services/infectious-diseases/sexual-health-sexually-transmitted-infections/canadian-guidelines.html"]],"sections":[{"title":"Assessment","text":["After a needlestick or mucosal exposure, establish the exposure type, time, source information, vaccination history and baseline health. Provide immediate first aid and use the workplace exposure pathway promptly."]},{"title":"Treatment principles","text":["Assess HIV, hepatitis B and hepatitis C separately. HIV post-exposure prophylaxis is time sensitive; hepatitis B management depends on immunity and exposure circumstances. There is no vaccine against hepatitis C."]},{"title":"Safety and follow-up","text":["Do not wait for every result before urgent specialist advice. Protect confidentiality, document the event and arrange baseline and follow-up testing. A reassuring appearance of the source person does not establish absence of infection."]}],"quick":["After a needlestick or mucosal exposure, establish the exposure type, time, source information, vaccination history and baseline health","Assess HIV, hepatitis B and hepatitis C separately","Do not wait for every result before urgent specialist advice"],"date":"2026-09-18","overview":"After a needlestick or mucosal exposure, establish the exposure type, time, source information, vaccination history and baseline health.","hi":"सुई चुभने या श्लेष्मा पर खून लगने के बाद समय, संपर्क का प्रकार और हेपेटाइटिस बी टीकाकरण पूछें। तुरंत प्राथमिक सहायता और कार्यस्थल की प्रक्रिया अपनाएं। एच आई वी की बचाव दवा समय पर शुरू करनी होती है। हेपेटाइटिस बी की योजना प्रतिरक्षा पर निर्भर है; हेपेटाइटिस सी का टीका नहीं है। जरूरी सलाह के लिए सभी रिपोर्ट का इंतजार न करें। गोपनीयता और बाद की जांच सुनिश्चित करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"tuberculosis","title":"Tuberculosis","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Public Health Agency of Canada: Canadian Tuberculosis Standards","https://www.canada.ca/en/public-health/services/diseases/tuberculosis/health-professionals/canadian-tuberculosis-standards.html"]],"sections":[{"title":"Assessment","text":["Persistent cough, weight loss, night sweats, fever and relevant exposure warrant assessment. Distinguish active TB disease from TB infection without disease; their public-health implications and regimens differ."]},{"title":"Treatment principles","text":["Active TB generally requires several medicines under specialist and public-health supervision. Review adherence support, liver risk, vision monitoring when relevant and the substantial interaction burden of rifamycins."]},{"title":"Safety and follow-up","text":["Suspected infectious pulmonary TB needs appropriate infection-control arrangements before routine in-person care. Do not treat active disease with a single drug. Stopping or missing treatment requires coordinated follow-up rather than blame."]}],"quick":["Persistent cough, weight loss, night sweats, fever and relevant exposure warrant assessment","Active TB generally requires several medicines under specialist and public-health supervision","Suspected infectious pulmonary TB needs appropriate infection-control arrangements before routine in-person care"],"date":"2026-09-18","overview":"Persistent cough, weight loss, night sweats, fever and relevant exposure warrant assessment.","hi":"लंबी खांसी, वजन कम होना, रात का पसीना और संपर्क का इतिहास टी बी की जांच का कारण हैं। सक्रिय बीमारी और केवल संक्रमण की स्थिति अलग हैं। सक्रिय टी बी में विशेषज्ञ की निगरानी में कई दवाएं दी जाती हैं। लिवर, कुछ दवाओं में नजर और रिफामाइसिन की अंतःक्रियाएं देखें। सक्रिय बीमारी का इलाज एक दवा से न करें। दवा पालन में परेशानी पर सहयोग और सार्वजनिक स्वास्थ्य टीम से समन्वय करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pharyngitis-bronchitis","title":"Pharyngitis & Bronchitis","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess throat pain, cough, duration, fever, airway symptoms and illness severity. Viral causes are common. Clinical assessment and indicated testing distinguish streptococcal pharyngitis; sputum colour does not prove bacterial bronchitis."]},{"title":"Treatment principles","text":["Offer suitable symptom care and explain expected recovery. Antibiotics are reserved for an appropriate bacterial indication. Persistent cough may have alternatives such as asthma, pneumonia, pertussis or a medicine effect."]},{"title":"Safety and follow-up","text":["Stridor, drooling, inability to swallow fluids, respiratory distress or significant systemic illness requires urgent assessment. Do not prescribe an antibiotic solely because the patient requests one or had one previously."]}],"quick":["Assess throat pain, cough, duration, fever, airway symptoms and illness severity","Offer suitable symptom care and explain expected recovery","Stridor, drooling, inability to swallow fluids, respiratory distress or significant systemic illness requires urgent assessment"],"date":"2026-09-18","overview":"Assess throat pain, cough, duration, fever, airway symptoms and illness severity.","hi":"गले में दर्द और खांसी अक्सर वायरस से होते हैं। हरे कफ से बैक्टीरिया सिद्ध नहीं होते। स्ट्रेप गले की बीमारी में उपयुक्त जांच मदद करती है। लक्षणों से राहत और ठीक होने की अपेक्षित अवधि समझाएं। सांस में कठिनाई, लार टपकना या पानी न निगल पाना गंभीर संकेत हैं। पुरानी बार एंटीबायोटिक मिली थी, यह इस बार देने का पर्याप्त कारण नहीं है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pneumonia","title":"Pneumonia","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess cough, fever, breathlessness, chest pain, oxygenation where available, comorbidities and mental status. Older or immunocompromised people may present atypically; severity determines the care setting."]},{"title":"Treatment principles","text":["Treatment considers community versus healthcare exposure, likely pathogens, local resistance, allergies and organ function. Reassess response and investigations; not every cough needs antibiotic therapy."]},{"title":"Safety and follow-up","text":["Hypoxia, confusion, haemodynamic instability or inability to take oral treatment needs urgent escalation. Review interacting QT-prolonging medicines and antibiotic adverse effects. Give a clear plan if breathing worsens or improvement does not occur."]}],"quick":["Assess cough, fever, breathlessness, chest pain, oxygenation where available, comorbidities and mental status","Treatment considers community versus healthcare exposure, likely pathogens, local resistance, allergies and organ function","Hypoxia, confusion, haemodynamic instability or inability to take oral treatment needs urgent escalation"],"date":"2026-09-18","overview":"Assess cough, fever, breathlessness, chest pain, oxygenation where available, comorbidities and mental status.","hi":"निमोनिया में खांसी के साथ सांस, बुखार, छाती का दर्द और मानसिक स्थिति देखें। बुजुर्गों में लक्षण अलग हो सकते हैं। गंभीरता तय करती है कि घर या अस्पताल में इलाज हो। ऑक्सीजन कम होना, भ्रम या दवा और पानी न ले पाना गंभीर है। एंटीबायोटिक का चुनाव एलर्जी, गुर्दे की स्थिति और स्थानीय प्रतिरोध के अनुसार करें। सुधार न होने पर दोबारा जांच का स्पष्ट निर्देश दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"influenza","title":"Influenza","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Ask about onset, severity, risk factors and exposure. Influenza can worsen chronic disease, and serious illness can occur without a textbook presentation."]},{"title":"Treatment principles","text":["Antiviral treatment depends on timing, severity and risk of complications; severe or high-risk illness may merit treatment even when presentation is later. Supportive care and prevention remain important. Adjust relevant medicines for kidney function."]},{"title":"Safety and follow-up","text":["Breathing difficulty, dehydration, confusion or deterioration after initial improvement needs reassessment. Avoid aspirin-containing products in children and adolescents with viral illness. Vaccination decisions follow current Canadian recommendations."]}],"quick":["Ask about onset, severity, risk factors and exposure","Antiviral treatment depends on timing, severity and risk of complications; severe or high-risk illness may merit treatment even when presentation is later","Breathing difficulty, dehydration, confusion or deterioration after initial improvement needs reassessment"],"date":"2026-09-18","overview":"Ask about onset, severity, risk factors and exposure.","hi":"इन्फ्लुएंजा में लक्षण शुरू होने का समय और गंभीर बीमारी का जोखिम देखें। एंटीवायरल का निर्णय केवल एक समय सीमा से नहीं; गंभीरता और जोखिम से भी होता है। सांस में कठिनाई, पानी की कमी या पहले सुधार के बाद बिगड़ना दोबारा जांच का कारण है। वायरल बीमारी में बच्चों और किशोरों को एस्प्रिन वाले उत्पाद न दें। टीकाकरण के लिए वर्तमान कनाडाई सलाह देखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pep-prep","title":"PEP & PrEP","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Public Health Agency of Canada: STBBI guidelines","https://www.canada.ca/en/public-health/services/infectious-diseases/sexual-health-sexually-transmitted-infections/canadian-guidelines.html"]],"sections":[{"title":"Assessment","text":["PEP follows a possible HIV exposure; PrEP prevents acquisition during ongoing risk. Establish timing, HIV status, exposure context, kidney health, hepatitis B status and the person's preferences without judgment."]},{"title":"Treatment principles","text":["PEP assessment is urgent and should follow a current specialist or provincial protocol. PrEP requires appropriate HIV testing and follow-up; choosing a regimen depends on exposure type, formulation, adherence and clinical factors."]},{"title":"Safety and follow-up","text":["Neither approach replaces testing and broader sexual-health care. Starting prevention in unrecognized HIV infection can complicate treatment. Clarify missed doses and follow-up appointments; do not transfer one person's regimen to another."]}],"quick":["PEP follows a possible HIV exposure; PrEP prevents acquisition during ongoing risk","PEP assessment is urgent and should follow a current specialist or provincial protocol","Neither approach replaces testing and broader sexual-health care"],"date":"2026-09-18","overview":"PEP follows a possible HIV exposure; PrEP prevents acquisition during ongoing risk.","hi":"पी ई पी संभावित एच आई वी संपर्क के बाद और प्रेप लगातार जोखिम से बचाव के लिए है। संपर्क का समय, एच आई वी जांच, गुर्दे और हेपेटाइटिस बी की स्थिति पूछें। पी ई पी का मूल्यांकन तुरंत करें। प्रेप से पहले और दौरान उचित जांच जरूरी है। बिना पहचाने एच आई वी संक्रमण में रोकथाम की दवा शुरू करना समस्या पैदा कर सकता है। एक व्यक्ति की योजना दूसरे को न दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"sexually-transmitted-infections","title":"Sexually Transmitted Infections","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Public Health Agency of Canada: STBBI guidelines","https://www.canada.ca/en/public-health/services/infectious-diseases/sexual-health-sexually-transmitted-infections/canadian-guidelines.html"]],"sections":[{"title":"Assessment","text":["Take a confidential, nonjudgmental sexual history based on anatomy, sites of exposure, symptoms and partners. Pregnancy possibility, assault concerns and systemic symptoms change the assessment."]},{"title":"Treatment principles","text":["Use current Canadian organism-specific testing and treatment guidance. Resistance patterns and recommendations change; confirm the regimen rather than recalling an old dose. Address partner management, reinfection prevention and follow-up testing when indicated."]},{"title":"Safety and follow-up","text":["Pelvic pain, testicular pain, pregnancy with concerning symptoms or disseminated illness needs prompt assessment. Explain confidentiality and its legal limits. Treat a positive result in context and arrange the required public-health process."]}],"quick":["Take a confidential, nonjudgmental sexual history based on anatomy, sites of exposure, symptoms and partners","Use current Canadian organism-specific testing and treatment guidance","Pelvic pain, testicular pain, pregnancy with concerning symptoms or disseminated illness needs prompt assessment"],"date":"2026-09-18","overview":"Take a confidential, nonjudgmental sexual history based on anatomy, sites of exposure, symptoms and partners.","hi":"यौन संक्रमण में बिना निर्णय किए गोपनीय इतिहास लें। संपर्क का स्थान, लक्षण, गर्भावस्था और साथी की जानकारी उपचार को प्रभावित करते हैं। वर्तमान कनाडाई निर्देश से जांच और दवा चुनें; पुरानी खुराक याद करके न दें। साथी की देखभाल और दोबारा जांच की योजना बनाएं। पेट के नीचे तेज दर्द, अंडकोष में दर्द या गंभीर बीमारी हो तो जल्दी जांच जरूरी है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"herpes-simplex-virus","title":"Herpes Simplex Virus","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Ask about the site, first versus recurrent episode, onset, pain, pregnancy and immune status. Oral or genital lesions can have alternative causes; diagnosis may need testing."]},{"title":"Treatment principles","text":["Antiviral treatment can shorten or suppress episodes but does not eradicate latent virus. Episodic and suppressive strategies have different purposes. Review kidney function and timing, and discuss transmission even when lesions are absent."]},{"title":"Safety and follow-up","text":["Eye pain or visual symptoms, neonatal exposure, extensive disease in an immunocompromised person or severe urinary difficulty needs prompt care. Use respectful counselling and avoid implying that recurrence proves recent acquisition."]}],"quick":["Ask about the site, first versus recurrent episode, onset, pain, pregnancy and immune status","Antiviral treatment can shorten or suppress episodes but does not eradicate latent virus","Eye pain or visual symptoms, neonatal exposure, extensive disease in an immunocompromised person or severe urinary difficulty needs prompt care"],"date":"2026-09-18","overview":"Ask about the site, first versus recurrent episode, onset, pain, pregnancy and immune status.","hi":"हर्पीस में पहला और बार-बार होने वाला एपिसोड अलग समझें। एंटीवायरल लक्षण कम कर सकती है, लेकिन वायरस को शरीर से पूरी तरह नहीं निकालती। कभी-कभी रोज की रोकथाम और कभी शुरुआत में उपचार दिया जाता है। घाव न होने पर भी संक्रमण फैल सकता है। आंख में दर्द या नजर बदलना, नवजात का संपर्क या कमजोर प्रतिरक्षा में व्यापक बीमारी हो तो तुरंत चिकित्सा सलाह लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"osteomyelitis-skin-and-soft-tissue-infections","title":"Osteomyelitis & Skin and Soft Tissue Infections","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Distinguish cellulitis, a drainable abscess and deeper infection. Ask about trauma, wounds, diabetes, injection exposure and systemic symptoms; persistent focal bone pain raises concern for osteomyelitis."]},{"title":"Treatment principles","text":["An abscess may need drainage; antibiotics are chosen for the likely organisms and severity. Suspected bone infection often requires imaging, microbiological diagnosis and an extended coordinated treatment plan."]},{"title":"Safety and follow-up","text":["Pain out of proportion, rapid spread, bullae, crepitus or toxicity can indicate a surgical emergency. Do not wait for routine oral-antibiotic follow-up when these signs are present. Mark progression and arrange reassessment where appropriate."]}],"quick":["Distinguish cellulitis, a drainable abscess and deeper infection","An abscess may need drainage; antibiotics are chosen for the likely organisms and severity","Pain out of proportion, rapid spread, bullae, crepitus or toxicity can indicate a surgical emergency"],"date":"2026-09-18","overview":"Distinguish cellulitis, a drainable abscess and deeper infection.","hi":"त्वचा के संक्रमण, पस के फोड़े और हड्डी के संक्रमण को अलग करें। फोड़े में पस निकालना जरूरी हो सकता है। लगातार हड्डी का दर्द गहरी जांच मांगता है। दर्द बहुत ज्यादा होना, तेजी से फैलना, फफोले या गंभीर कमजोरी शल्य चिकित्सा की आपातस्थिति हो सकती है। ऐसे में केवल खाने वाली एंटीबायोटिक देकर इंतजार न करें। घाव, मधुमेह और चोट का इतिहास लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"otitis-externa","title":"Otitis Externa","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Pain with movement of the outer ear and canal symptoms suggest otitis externa, but examine or refer to establish the diagnosis. Ask about swimming, instrumentation, discharge, diabetes and tympanic-membrane status."]},{"title":"Treatment principles","text":["Topical therapy is often central for uncomplicated disease. Product selection must account for a possible perforation or tube; not all ear drops are appropriate when the middle ear may be exposed."]},{"title":"Safety and follow-up","text":["Severe persistent pain, cranial-nerve findings or illness in a person with diabetes or immunosuppression needs urgent assessment. Teach correct drop use and avoidance of canal trauma; do not advise inserting cotton swabs deeply."]}],"quick":["Pain with movement of the outer ear and canal symptoms suggest otitis externa, but examine or refer to establish the diagnosis","Topical therapy is often central for uncomplicated disease","Severe persistent pain, cranial-nerve findings or illness in a person with diabetes or immunosuppression needs urgent assessment"],"date":"2026-09-18","overview":"Pain with movement of the outer ear and canal symptoms suggest otitis externa, but examine or refer to establish the diagnosis.","hi":"बाहरी कान हिलाने पर दर्द और कान की नली के लक्षण बाहरी कान के संक्रमण में हो सकते हैं। तैरना, कान में वस्तु डालना और पर्दे की स्थिति पूछें। हर ईयर ड्रॉप फटे पर्दे में सुरक्षित नहीं होती। मधुमेह या कमजोर प्रतिरक्षा में बहुत तेज लगातार दर्द हो तो तुरंत जांच कराएं। बूंदें सही तरीके से डालना सिखाएं और कान में रुई की डंडी अंदर न डालने को कहें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"intra-abdominal-infections","title":"Intra-abdominal Infections","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Abdominal infection assessment includes pain location, fever, vomiting, bowel symptoms, prior surgery and haemodynamic status. Peritoneal signs, instability or severe deterioration need urgent care."]},{"title":"Treatment principles","text":["Management often requires source control in addition to antibiotics. Regimens depend on the suspected source, severity, resistant-organism risk and kidney function; broad therapy is reassessed after clinical and microbiological information."]},{"title":"Safety and follow-up","text":["Do not treat possible perforation or appendicitis as simple indigestion. Review allergies, intravenous compatibility and antimicrobial duration after adequate source control. Monitor for ongoing infection and antibiotic-related complications."]}],"quick":["Abdominal infection assessment includes pain location, fever, vomiting, bowel symptoms, prior surgery and haemodynamic status","Management often requires source control in addition to antibiotics","Do not treat possible perforation or appendicitis as simple indigestion"],"date":"2026-09-18","overview":"Abdominal infection assessment includes pain location, fever, vomiting, bowel symptoms, prior surgery and haemodynamic status.","hi":"पेट के अंदर संक्रमण में दर्द की जगह, बुखार, उल्टी, ऑपरेशन का इतिहास और रक्तचाप देखें। पेट बहुत कड़ा होना या हालत तेजी से बिगड़ना गंभीर है। इलाज में एंटीबायोटिक के साथ संक्रमण का स्रोत नियंत्रित करना जरूरी हो सकता है। अपेंडिक्स या आंत में छेद की संभावना को साधारण अपच न मानें। गुर्दे की स्थिति, एलर्जी और इलाज की समीक्षा की तारीख जांचें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"viral-hepatitis","title":"Viral Hepatitis","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Differentiate acute illness from chronic infection and identify the virus with appropriate testing. Ask about exposure, immunization, alcohol, medicines and signs of liver dysfunction."]},{"title":"Treatment principles","text":["Hepatitis A and B are vaccine-preventable; hepatitis C has curative antiviral regimens for many patients but no vaccine. Chronic B and C management requires staged assessment and careful interaction review."]},{"title":"Safety and follow-up","text":["Confusion, significant bleeding or severe jaundice with deterioration needs urgent care. Check for hepatitis B reactivation considerations when relevant therapies are used. Counsel on transmission, avoidance of harmful exposures and specialist follow-up."]}],"quick":["Differentiate acute illness from chronic infection and identify the virus with appropriate testing","Hepatitis A and B are vaccine-preventable; hepatitis C has curative antiviral regimens for many patients but no vaccine","Confusion, significant bleeding or severe jaundice with deterioration needs urgent care"],"date":"2026-09-18","overview":"Differentiate acute illness from chronic infection and identify the virus with appropriate testing.","hi":"वायरल हेपेटाइटिस में वायरस का प्रकार और नई या पुरानी बीमारी का अंतर जानें। हेपेटाइटिस ए और बी के टीके हैं, सी का टीका नहीं है। हेपेटाइटिस सी के कई मरीज एंटीवायरल से ठीक हो सकते हैं। इलाज से पहले दवा अंतःक्रिया और लिवर की स्थिति देखें। भ्रम, रक्तस्राव या तेजी से बिगड़ता पीलिया हो तो तुरंत अस्पताल की जांच जरूरी है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"croup","title":"Croup","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Paediatric Society: acute croup management","https://cps.ca/en/documents/position/acute-management-of-croup"]],"sections":[{"title":"Assessment","text":["A barking cough and hoarseness in a young child can indicate croup. Assess stridor at rest, work of breathing, colour, alertness and ability to drink; consider alternative airway emergencies."]},{"title":"Treatment principles","text":["Keep the child calm while arranging the appropriate level of care. Corticosteroid treatment and, for more severe illness, nebulized epinephrine are clinician-directed treatments; observation is important after temporary improvement."]},{"title":"Safety and follow-up","text":["Stridor at rest with distress, cyanosis, exhaustion, drooling or reduced responsiveness requires urgent emergency assessment. Steam exposure is not a substitute for treatment and hot water can burn. Avoid upsetting the child with unnecessary throat inspection."]}],"quick":["A barking cough and hoarseness in a young child can indicate croup","Keep the child calm while arranging the appropriate level of care","Stridor at rest with distress, cyanosis, exhaustion, drooling or reduced responsiveness requires urgent emergency assessment"],"date":"2026-09-18","overview":"A barking cough and hoarseness in a young child can indicate croup.","hi":"क्रूप में बच्चे को भौंकने जैसी खांसी और आवाज बैठना हो सकता है। आराम में सांस की आवाज, छाती का खिंचाव, रंग और जागरूकता देखें। बच्चे को शांत रखें। गंभीर स्थिति में डॉक्टर स्टेरॉयड और नेब्युलाइज्ड एपिनेफ्रिन देते हैं और निगरानी रखते हैं। नीला पड़ना, अत्यधिक थकना या लार टपकना गंभीर संकेत हैं। गर्म भाप को इलाज का विकल्प न बनाएं; जलने का खतरा है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"infective-endocarditis","title":"Infective Endocarditis","subject":"Infectious Disease","icon":"shield-plus","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Persistent fever with risk factors such as a prosthetic valve, previous endocarditis or bloodstream infection warrants assessment. Embolic signs or new heart-failure symptoms increase concern."]},{"title":"Treatment principles","text":["Diagnosis uses clinical findings, blood cultures and cardiac imaging. Treatment is prolonged, organism-directed and sometimes surgical. Pharmacy review includes antimicrobial exposure, renal function, drug levels when indicated and line-related issues."]},{"title":"Safety and follow-up","text":["Do not assume every person with a murmur needs dental antibiotic prophylaxis; eligibility and procedures are specific. New neurological symptoms or haemodynamic deterioration need urgent care. Support adherence and monitoring during outpatient intravenous treatment."]}],"quick":["Persistent fever with risk factors such as a prosthetic valve, previous endocarditis or bloodstream infection warrants assessment","Diagnosis uses clinical findings, blood cultures and cardiac imaging","Do not assume every person with a murmur needs dental antibiotic prophylaxis; eligibility and procedures are specific"],"date":"2026-09-18","overview":"Persistent fever with risk factors such as a prosthetic valve, previous endocarditis or bloodstream infection warrants assessment.","hi":"लगातार बुखार के साथ कृत्रिम वाल्व या पुराने एंडोकार्डाइटिस का इतिहास महत्वपूर्ण है। निदान में ब्लड कल्चर और हृदय की जांच होती है। इलाज लंबे समय का, जीवाणु के अनुसार और कभी ऑपरेशन सहित होता है। हर हार्ट मर्मर वाले व्यक्ति को दांत के इलाज से पहले एंटीबायोटिक जरूरी नहीं है। गुर्दे की स्थिति, दवा स्तर और नस की लाइन की निगरानी करें। नई न्यूरोलॉजिकल समस्या में तत्काल मदद लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pruritus-itch","title":"Pruritus (Itch)","subject":"Dermatology","icon":"scan-face","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess distribution, rash, duration, new medicines, contacts and systemic symptoms. Generalized itch without a primary rash can reflect more than a skin problem, including liver, kidney or haematological disease."]},{"title":"Treatment principles","text":["Gentle skin care and regular moisturization help dry-skin itch. Treatment should address the cause; an antihistamine is more useful for histamine-mediated symptoms than for every form of itch."]},{"title":"Safety and follow-up","text":["Jaundice, systemic illness, blistering, mucosal involvement or severe widespread symptoms need medical assessment. Sedating antihistamines can worsen falls, confusion and anticholinergic burden, especially in older adults."]}],"quick":["Assess distribution, rash, duration, new medicines, contacts and systemic symptoms","Gentle skin care and regular moisturization help dry-skin itch","Jaundice, systemic illness, blistering, mucosal involvement or severe widespread symptoms need medical assessment"],"date":"2026-09-18","overview":"Assess distribution, rash, duration, new medicines, contacts and systemic symptoms.","hi":"खुजली में जगह, चकत्ता, समय, नई दवा और घर के अन्य लोगों के लक्षण पूछें। बिना चकत्ते पूरे शरीर की खुजली में लिवर या गुर्दे जैसे कारण भी हो सकते हैं। सूखी त्वचा में मॉइस्चराइज़र मदद करता है। हर खुजली में एंटीहिस्टामिन समान रूप से काम नहीं करती। नींद लाने वाली दवाएं बुजुर्गों में गिरने और भ्रम का जोखिम बढ़ा सकती हैं। पीलिया, फफोले या गंभीर लक्षण में जांच करवाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"acne","title":"Acne","subject":"Dermatology","icon":"scan-face","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess comedones versus inflammatory or nodular disease, scarring, psychosocial impact, pregnancy possibility and previous treatment. Steroid use and other medicines can contribute to acne-like eruptions."]},{"title":"Treatment principles","text":["Topical retinoids and benzoyl peroxide are common components of care. Start tolerably and explain that improvement takes weeks. Avoid antibiotic monotherapy; systemic treatment requires assessment of severity, contraindications and duration."]},{"title":"Safety and follow-up","text":["Isotretinoin is highly teratogenic and requires a structured prescribing and pregnancy-prevention process. Do not combine acne products indiscriminately when irritation develops. Painful nodules, scarring or substantial distress support earlier referral."]}],"quick":["Assess comedones versus inflammatory or nodular disease, scarring, psychosocial impact, pregnancy possibility and previous treatment","Topical retinoids and benzoyl peroxide are common components of care","Isotretinoin is highly teratogenic and requires a structured prescribing and pregnancy-prevention process"],"date":"2026-09-18","overview":"Assess comedones versus inflammatory or nodular disease, scarring, psychosocial impact, pregnancy possibility and previous treatment.","hi":"मुंहासों में ब्लैकहेड, सूजन, गांठ, निशान और मानसिक असर देखें। बेंज़ोइल पेरॉक्साइड और रेटिनॉइड आम विकल्प हैं, लेकिन असर में कई सप्ताह लगते हैं। जलन होने पर सभी उत्पाद ज्यादा मात्रा में न लगाएं। एंटीबायोटिक अकेली और अनिश्चित समय तक न चलाएं। आइसोट्रेटिनॉइन गर्भावस्था में गंभीर नुकसान कर सकती है और विशेष निगरानी चाहिए। गांठ, निशान या बहुत परेशानी हो तो रेफर करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"psoriasis","title":"Psoriasis","subject":"Dermatology","icon":"scan-face","status":"available","minutes":2,"competency":"Clinical Care","sources":[["NICE (UK): Psoriasis guidance; apply Canadian context","https://www.nice.org.uk/guidance/cg153/chapter/recommendations"]],"sections":[{"title":"Assessment","text":["Assess affected sites, extent, symptoms, nail changes, joint symptoms and quality of life. A small area on a sensitive or functional site can still cause major impairment."]},{"title":"Treatment principles","text":["Topical corticosteroids and vitamin-D analogues are options for selected disease; potency and duration depend on the site. More extensive or difficult disease may need phototherapy or systemic treatment with specialist monitoring."]},{"title":"Safety and follow-up","text":["New swollen painful joints warrant assessment for psoriatic arthritis. Widespread redness, pustules or systemic illness can be urgent. Avoid applying a potent steroid to the face or folds without a specific plan."]}],"quick":["Assess affected sites, extent, symptoms, nail changes, joint symptoms and quality of life","Topical corticosteroids and vitamin-D analogues are options for selected disease; potency and duration depend on the site","New swollen painful joints warrant assessment for psoriatic arthritis"],"date":"2026-09-18","overview":"Assess affected sites, extent, symptoms, nail changes, joint symptoms and quality of life.","hi":"सोरायसिस में केवल त्वचा का प्रतिशत नहीं, जगह और जीवन पर असर भी देखें। नाखून और जोड़ों के लक्षण पूछें। बाहरी स्टेरॉयड की ताकत और अवधि शरीर की जगह के अनुसार होती है। गंभीर बीमारी में विशेषज्ञ की दवा या प्रकाश उपचार लग सकता है। दर्द वाले सूजे जोड़ सोरायटिक आर्थराइटिस का संकेत हैं। चेहरे पर शक्तिशाली स्टेरॉयड अपनी तरफ से न लगाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"burns-and-sunburns","title":"Burns and Sunburns","subject":"Dermatology","icon":"scan-face","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Establish the cause, time, depth, size and site of injury. Electrical, chemical or inhalation injury, extensive burns and burns involving critical areas need professional assessment."]},{"title":"Treatment principles","text":["For a recent thermal burn, use appropriate cool running water and remove constricting items if safe; avoid ice and unproven household remedies. Protect the area with a suitable clean dressing and assess analgesia and tetanus needs."]},{"title":"Safety and follow-up","text":["Airway symptoms, facial burns with smoke exposure, deep burns or signs of infection require urgent care. Young children and frail people need a lower referral threshold. Sunburn prevention includes shade, clothing and appropriate sunscreen use."]}],"quick":["Establish the cause, time, depth, size and site of injury","For a recent thermal burn, use appropriate cool running water and remove constricting items if safe; avoid ice and unproven household remedies","Airway symptoms, facial burns with smoke exposure, deep burns or signs of infection require urgent care"],"date":"2026-09-18","overview":"Establish the cause, time, depth, size and site of injury.","hi":"जलने में कारण, समय, गहराई, क्षेत्र और शरीर की जगह देखें। सामान्य ताप से जलने पर सुरक्षित ठंडे बहते पानी से ठंडा करें; बर्फ या घरेलू पेस्ट न लगाएं। साफ उपयुक्त ड्रेसिंग और दर्द की देखभाल करें। रसायन, बिजली, धुएं से सांस की समस्या या गहरा घाव तुरंत जांच मांगता है। बच्चों और कमजोर बुजुर्गों में जल्दी रेफर करें। धूप से बचाव में कपड़े और छाया भी जरूरी हैं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"rosacea","title":"Rosacea","subject":"Dermatology","icon":"scan-face","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Look for persistent facial redness, flushing, inflammatory lesions and ocular symptoms. Rosacea is different from acne; comedones are not a defining feature. Ask about triggers and previous topical steroid use."]},{"title":"Treatment principles","text":["Gentle skin care, sun protection and avoidance of individual triggers support treatment. Prescription topical or oral therapy depends on the dominant features and severity, with realistic expectations about control rather than a permanent cure."]},{"title":"Safety and follow-up","text":["Eye pain, light sensitivity or visual change needs prompt assessment. Facial corticosteroids can aggravate rosacea. Review irritation from cosmetics and avoid assuming every red facial rash has the same diagnosis."]}],"quick":["Look for persistent facial redness, flushing, inflammatory lesions and ocular symptoms","Gentle skin care, sun protection and avoidance of individual triggers support treatment","Eye pain, light sensitivity or visual change needs prompt assessment"],"date":"2026-09-18","overview":"Look for persistent facial redness, flushing, inflammatory lesions and ocular symptoms.","hi":"रोसैशिया में चेहरे की लाली, फ्लशिंग और सूजन वाले दाने होते हैं; यह सामान्य मुंहासों से अलग है। व्यक्तिगत ट्रिगर, धूप और स्टेरॉयड क्रीम का इतिहास पूछें। कोमल त्वचा देखभाल और धूप से बचाव मदद करते हैं। दवा प्रमुख लक्षण के अनुसार चुनी जाती है। आंख में दर्द, रोशनी से परेशानी या नजर बदलना जल्दी जांच का कारण है। चेहरे की स्टेरॉयड क्रीम बीमारी बढ़ा सकती है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"lice-scabies","title":"Lice & Scabies","subject":"Dermatology","icon":"scan-face","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Confirm an active infestation where possible. Head lice and scabies differ in organism, spread, treatment application and contact management. Scabies often causes marked night-time itch and affects close contacts."]},{"title":"Treatment principles","text":["Follow the chosen product's exact application and repeat-treatment directions. Scabies usually requires coordinated treatment of relevant close contacts. For lice, assess live lice and correct combing/product use before declaring resistance."]},{"title":"Safety and follow-up","text":["Itch can persist after successful scabies treatment; assess new lesions and exposure rather than repeatedly applying insecticide without review. Crusted scabies, secondary infection, pregnancy and young infants need tailored advice."]}],"quick":["Confirm an active infestation where possible","Follow the chosen product's exact application and repeat-treatment directions","Itch can persist after successful scabies treatment; assess new lesions and exposure rather than repeatedly applying insecticide without review"],"date":"2026-09-18","overview":"Confirm an active infestation where possible.","hi":"जूं और स्केबीज़ अलग समस्याएं हैं। सक्रिय संक्रमण की पुष्टि करें और उत्पाद लगाने तथा दोहराने के सही निर्देश दें। स्केबीज़ में संबंधित करीबी संपर्कों का साथ इलाज जरूरी हो सकता है। इलाज के बाद कुछ समय खुजली रहने का मतलब हमेशा असफलता नहीं है। नई सुरंग, नए दाने और दोबारा संपर्क देखें। छोटे बच्चे, गर्भावस्था या पपड़ी वाली गंभीर स्केबीज़ में विशेष सलाह लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"atopic-dermatitis","title":"Atopic Dermatitis","subject":"Dermatology","icon":"scan-face","status":"available","minutes":2,"competency":"Clinical Care","sources":[["NICE (UK): Atopic Dermatitis guidance; apply Canadian context","https://www.nice.org.uk/guidance/cg57/chapter/recommendations"]],"sections":[{"title":"Assessment","text":["Assess itch, dryness, flare sites, infection, sleep and trigger exposure. Treatment failure may reflect insufficient quantity, unsuitable potency, difficult application or an incorrect diagnosis."]},{"title":"Treatment principles","text":["Regular emollients support the skin barrier; anti-inflammatory treatment controls flares. Explain site-appropriate topical steroid use and the planned duration rather than advising either indefinite use or avoidance of all steroids."]},{"title":"Safety and follow-up","text":["Painful rapidly spreading lesions, punched-out erosions, eye involvement or systemic illness needs urgent assessment. Do not routinely use antibiotics for every eczema flare. Demonstration and a written plan can reduce fear and improve correct use."]}],"quick":["Assess itch, dryness, flare sites, infection, sleep and trigger exposure","Regular emollients support the skin barrier; anti-inflammatory treatment controls flares","Painful rapidly spreading lesions, punched-out erosions, eye involvement or systemic illness needs urgent assessment"],"date":"2026-09-18","overview":"Assess itch, dryness, flare sites, infection, sleep and trigger exposure.","hi":"एटॉपिक डर्मेटाइटिस में सूखापन, खुजली, नींद और संक्रमण देखें। मॉइस्चराइज़र त्वचा की सुरक्षा मजबूत करता है, जबकि सूजन की दवा फ्लेयर नियंत्रित करती है। स्टेरॉयड की सही ताकत, मात्रा और अवधि समझाएं। हर फ्लेयर में एंटीबायोटिक जरूरी नहीं है। दर्द वाले तेजी से फैलते छोटे घाव, आंख की समस्या या बुखार हो तो तुरंत जांच करवाएं। लगाने की विधि दिखाना उपयोगी है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"attention-deficit-hyperactivity-disorder-adhd","title":"Attention Deficit Hyperactivity Disorder (ADHD)","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["NICE (UK): Attention Deficit Hyperactivity Disorder (ADHD) guidance; apply Canadian context","https://www.nice.org.uk/guidance/ng87/chapter/recommendations"]],"sections":[{"title":"Assessment","text":["ADHD assessment considers persistent impairment across settings, developmental history and alternative explanations. Review sleep, anxiety, substance use, cardiovascular history and actual functional goals."]},{"title":"Treatment principles","text":["Medication and behavioural or educational supports can complement each other. Stimulant and nonstimulant products differ in onset, duration and titration. Monitor appetite, sleep, blood pressure, pulse and growth in children where relevant."]},{"title":"Safety and follow-up","text":["Do not interchange modified-release products solely by matching milligrams. Discuss secure storage and diversion prevention without stigma. New severe psychiatric symptoms, concerning cardiovascular symptoms or major weight loss needs reassessment."]}],"quick":["ADHD assessment considers persistent impairment across settings, developmental history and alternative explanations","Medication and behavioural or educational supports can complement each other","Do not interchange modified-release products solely by matching milligrams"],"date":"2026-09-18","overview":"ADHD assessment considers persistent impairment across settings, developmental history and alternative explanations.","hi":"ए डी एच डी में कई जगहों पर लगातार कामकाज की परेशानी और विकास का इतिहास देखें। नींद, चिंता और दूसरी वजहों की समीक्षा करें। दवा के साथ व्यवहार और पढ़ाई की सहायता महत्वपूर्ण है। भूख, नींद, रक्तचाप, नाड़ी और बच्चों की बढ़त देखें। अलग लंबे असर वाले उत्पाद केवल मिलीग्राम बराबर होने पर बदल न दें। सुरक्षित भंडारण और दवा साझा न करने की सलाह दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"dementia","title":"Dementia","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Establish the pattern and pace of cognitive change, daily function, medicines, sensory needs and caregiver concerns. Acute fluctuating confusion suggests delirium and needs assessment for reversible causes."]},{"title":"Treatment principles","text":["Support routines, communication and safety while reviewing anticholinergic and sedating medicines. Cognitive-symptom medicines have limited goals and require assessment of benefit, tolerability and the specific dementia diagnosis."]},{"title":"Safety and follow-up","text":["Behavioural symptoms first require assessment of pain, infection, environment and unmet needs. Antipsychotics carry important risks and are not a routine response to every behaviour. Respect capacity, consent and caregiver roles individually."]}],"quick":["Establish the pattern and pace of cognitive change, daily function, medicines, sensory needs and caregiver concerns","Support routines, communication and safety while reviewing anticholinergic and sedating medicines","Behavioural symptoms first require assessment of pain, infection, environment and unmet needs"],"date":"2026-09-18","overview":"Establish the pattern and pace of cognitive change, daily function, medicines, sensory needs and caregiver concerns.","hi":"डिमेंशिया में याददाश्त के साथ रोजमर्रा की क्षमता और बदलाव की गति देखें। अचानक उतार-चढ़ाव वाला भ्रम डिलीरियम हो सकता है और कारण खोजने की जरूरत है। नींद लाने वाली और एंटीकोलिनर्जिक दवाओं की समीक्षा करें। व्यवहार बदलने पर दर्द, संक्रमण और वातावरण देखें। हर व्यवहार पर एंटीसाइकोटिक देना सही नहीं। मरीज की क्षमता, सहमति और देखभाल करने वाले की भूमिका अलग समझें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"insomnia","title":"Insomnia","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Clarify difficulty falling asleep, staying asleep or waking early, duration and daytime impairment. Review shift work, sleep apnoea symptoms, pain, mood, caffeine, alcohol and medicines."]},{"title":"Treatment principles","text":["Cognitive behavioural therapy for insomnia is a central long-term approach. Sleep timing and behavioural strategies are more than a simple instruction to relax. If a medicine is used, define the goal, duration and reassessment plan."]},{"title":"Safety and follow-up","text":["Sedatives can impair driving and increase falls; combining them with alcohol or opioids adds risk. Do not abruptly stop a long-used benzodiazepine. Persistent snoring with witnessed apnoeas or marked daytime sleepiness warrants evaluation."]}],"quick":["Clarify difficulty falling asleep, staying asleep or waking early, duration and daytime impairment","Cognitive behavioural therapy for insomnia is a central long-term approach","Sedatives can impair driving and increase falls; combining them with alcohol or opioids adds risk"],"date":"2026-09-18","overview":"Clarify difficulty falling asleep, staying asleep or waking early, duration and daytime impairment.","hi":"अनिद्रा में सोने में देर, बीच में जागना और दिन के काम पर असर पूछें। कैफीन, शराब, शिफ्ट काम, दर्द और स्लीप एप्निया की संभावना देखें। अनिद्रा की व्यवहार आधारित चिकित्सा लंबे समय में महत्वपूर्ण है। नींद की दवा के लिए अवधि और समीक्षा तय करें। शराब या ओपिओइड के साथ जोखिम बढ़ता है। लंबे समय की बेंज़ोडायज़ेपीन अचानक बंद न करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"eating-disorders","title":"Eating Disorders","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess restrictive eating, bingeing, compensatory behaviours, rapid weight change, medical symptoms and psychological distress without focusing only on body size. Serious instability can occur at different weights."]},{"title":"Treatment principles","text":["Care requires coordinated medical, nutritional and psychological assessment. Review medicines that affect appetite, electrolytes or QT interval and explore laxative or diuretic misuse respectfully."]},{"title":"Safety and follow-up","text":["Syncope, severe weakness, dehydration, bradycardia or electrolyte abnormalities may require urgent care. Refeeding after prolonged undernutrition can cause dangerous metabolic shifts; nutritional restoration needs an appropriate monitored plan."]}],"quick":["Assess restrictive eating, bingeing, compensatory behaviours, rapid weight change, medical symptoms and psychological distress without focusing only on body size","Care requires coordinated medical, nutritional and psychological assessment","Syncope, severe weakness, dehydration, bradycardia or electrolyte abnormalities may require urgent care"],"date":"2026-09-18","overview":"Assess restrictive eating, bingeing, compensatory behaviours, rapid weight change, medical symptoms and psychological distress without focusing only on body size.","hi":"खाने के विकार में केवल वजन नहीं, प्रतिबंध, बिंज ईटिंग, उल्टी, जुलाब और तेजी से वजन बदलना पूछें। अलग-अलग वजन पर गंभीर अस्थिरता हो सकती है। चिकित्सा, पोषण और मानसिक स्वास्थ्य टीम की संयुक्त देखभाल जरूरी है। बेहोशी, बहुत कमजोरी या इलेक्ट्रोलाइट बिगड़ना गंभीर संकेत हैं। लंबे कुपोषण के बाद भोजन तेजी से बढ़ाने में रीफीडिंग का जोखिम होता है और निगरानी चाहिए।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"schizophrenia","title":"Schizophrenia","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Review psychotic symptoms, functioning, physical health, substance use, medication response and adverse effects. Distinguish relapse from delirium, intoxication and other causes."]},{"title":"Treatment principles","text":["Antipsychotic selection considers previous benefit, metabolic effects, movement disorders, prolactin, QT effects and patient preferences. Long-acting injections can help selected patients but require the exact product initiation and missed-dose protocol."]},{"title":"Safety and follow-up","text":["Clozapine requires specific blood monitoring and assessment for serious adverse effects, including severe constipation and myocarditis symptoms. Fever, rigidity and altered consciousness during antipsychotic therapy can be an emergency. Plan ongoing metabolic monitoring and supportive care."]}],"quick":["Review psychotic symptoms, functioning, physical health, substance use, medication response and adverse effects","Antipsychotic selection considers previous benefit, metabolic effects, movement disorders, prolactin, QT effects and patient preferences","Clozapine requires specific blood monitoring and assessment for serious adverse effects, including severe constipation and myocarditis symptoms"],"date":"2026-09-18","overview":"Review psychotic symptoms, functioning, physical health, substance use, medication response and adverse effects.","hi":"स्किज़ोफ्रेनिया में लक्षण, रोजमर्रा का काम, नशे का उपयोग और दवा के दुष्प्रभाव देखें। एंटीसाइकोटिक चुनते समय वजन, शुगर, गति संबंधी दुष्प्रभाव और हृदय की लय पर असर देखें। लंबे असर वाले इंजेक्शन की शुरुआत और छूटी खुराक के नियम उत्पाद अनुसार हैं। क्लोज़ापिन में रक्त जांच और गंभीर कब्ज की निगरानी जरूरी है। बुखार, अकड़न और भ्रम तुरंत जांच मांगते हैं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"acute-agitation","title":"Acute Agitation","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Prioritize immediate safety and assess possible delirium, pain, hypoglycaemia, intoxication, withdrawal or psychiatric illness. Agitation is a presentation, not a diagnosis."]},{"title":"Treatment principles","text":["Use a calm voice, space, respectful choices and reduced stimulation when safe. Medication, restraint and emergency interventions require the appropriate clinical setting, consent framework and monitoring; avoid escalating a confrontation."]},{"title":"Safety and follow-up","text":["Altered consciousness, unstable vital signs, head injury or severe intoxication needs urgent medical care. Sedating medicines can suppress breathing, especially in combination. Document the cause assessment, response and ongoing monitoring."]}],"quick":["Prioritize immediate safety and assess possible delirium, pain, hypoglycaemia, intoxication, withdrawal or psychiatric illness","Use a calm voice, space, respectful choices and reduced stimulation when safe","Altered consciousness, unstable vital signs, head injury or severe intoxication needs urgent medical care"],"date":"2026-09-18","overview":"Prioritize immediate safety and assess possible delirium, pain, hypoglycaemia, intoxication, withdrawal or psychiatric illness.","hi":"तीव्र उत्तेजना में पहले मरीज और आसपास के लोगों की सुरक्षा देखें। कारण दर्द, कम शुगर, नशा, विड्रॉल या डिलीरियम भी हो सकता है। शांत आवाज, जगह और सरल विकल्प दें। बहस या टकराव न बढ़ाएं। बेहोशी, अस्थिर रक्तचाप या सिर की चोट में आपातकालीन जांच जरूरी है। शांत करने वाली दवाओं से सांस दब सकती है, इसलिए उचित निगरानी आवश्यक है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"anxiety-and-related-disorders","title":"Anxiety and Related Disorders","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess pattern, triggers, avoidance, functional impairment, sleep and medical or substance-related causes. Panic-like symptoms can overlap with acute cardiac or respiratory illness."]},{"title":"Treatment principles","text":["Psychological therapy and selected medicines are options according to the disorder and preferences. Antidepressants can take time to help and may initially cause adverse effects; explain titration, adherence and follow-up."]},{"title":"Safety and follow-up","text":["Benzodiazepines have dependence, sedation and withdrawal risks. Do not dismiss new chest pain as anxiety without assessment. Review worsening mood, major functional decline and safety concerns promptly."]}],"quick":["Assess pattern, triggers, avoidance, functional impairment, sleep and medical or substance-related causes","Psychological therapy and selected medicines are options according to the disorder and preferences","Benzodiazepines have dependence, sedation and withdrawal risks"],"date":"2026-09-18","overview":"Assess pattern, triggers, avoidance, functional impairment, sleep and medical or substance-related causes.","hi":"चिंता में पैटर्न, ट्रिगर, बचने का व्यवहार और रोज के काम पर असर देखें। छाती का नया दर्द केवल पैनिक मानकर न छोड़ें। मनोचिकित्सा और चुनी हुई दवाएं मदद कर सकती हैं। कुछ दवाओं का असर धीरे आता है और शुरुआत में दुष्प्रभाव हो सकते हैं। बेंज़ोडायज़ेपीन में निर्भरता और विड्रॉल का जोखिम समझाएं। सुधार और नुकसान दोनों की समीक्षा की तारीख तय करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"bipolar-disorder","title":"Bipolar Disorder","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["NICE (UK): Bipolar Disorder guidance; apply Canadian context","https://www.nice.org.uk/guidance/cg185/chapter/recommendations"]],"sections":[{"title":"Assessment","text":["A history of mania or hypomania changes the interpretation of depressive symptoms. Ask about reduced need for sleep, increased activity, impulsivity, psychosis and previous episodes."]},{"title":"Treatment principles","text":["Treatment depends on whether the person has mania, bipolar depression or maintenance needs. Mood stabilizers and selected antipsychotics have different roles. Antidepressant monotherapy is generally unsuitable for bipolar I depression."]},{"title":"Safety and follow-up","text":["Lithium requires correctly timed levels, renal and thyroid monitoring, and attention to dehydration and interactions. Pregnancy planning is essential for potentially teratogenic therapies. Severe mania, psychosis or inability to maintain safety requires urgent care."]}],"quick":["A history of mania or hypomania changes the interpretation of depressive symptoms","Treatment depends on whether the person has mania, bipolar depression or maintenance needs","Lithium requires correctly timed levels, renal and thyroid monitoring, and attention to dehydration and interactions"],"date":"2026-09-18","overview":"A history of mania or hypomania changes the interpretation of depressive symptoms.","hi":"बाइपोलर में अवसाद के साथ पुराने उन्माद या हाइपोमेनिया का इतिहास पूछें। कम नींद में भी बहुत ऊर्जा, आवेग और बढ़ी गतिविधि महत्वपूर्ण हैं। उन्माद, अवसाद और रखरखाव के इलाज अलग हो सकते हैं। बाइपोलर वन में केवल एंटीडिप्रेसेंट सामान्यतः उचित नहीं। लिथियम में सही समय का स्तर, गुर्दे, थायरॉइड, पानी की कमी और अंतःक्रियाएं देखें। गर्भावस्था की योजना पहले चर्चा करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"depression","title":"Depression","subject":"Psychiatry","icon":"brain","status":"available","minutes":2,"competency":"Clinical Care","sources":[["NICE (UK): Depression guidance; apply Canadian context","https://www.nice.org.uk/guidance/ng222/chapter/recommendations"]],"sections":[{"title":"Assessment","text":["Assess duration, functional impact, sleep, appetite, medical causes and previous treatment. Ask about bipolar symptoms and immediate safety concerns before assuming unipolar depression."]},{"title":"Treatment principles","text":["Treatment may include psychological therapy, social supports and an antidepressant selected for benefit, adverse effects, interactions and preference. Explain that response takes time and use planned follow-up rather than automatic early switching."]},{"title":"Safety and follow-up","text":["Assess worsening agitation, emerging mania, serotonin toxicity and discontinuation symptoms. Do not abruptly stop long-term therapy without a taper plan when appropriate. Immediate safety concerns or severe deterioration require urgent professional assessment."]}],"quick":["Assess duration, functional impact, sleep, appetite, medical causes and previous treatment","Treatment may include psychological therapy, social supports and an antidepressant selected for benefit, adverse effects, interactions and preference","Assess worsening agitation, emerging mania, serotonin toxicity and discontinuation symptoms"],"date":"2026-09-18","overview":"Assess duration, functional impact, sleep, appetite, medical causes and previous treatment.","hi":"अवसाद में अवधि, कामकाज, नींद, भूख और पुराने इलाज की समीक्षा करें। बाइपोलर के लक्षण और तत्काल सुरक्षा की चिंता भी पूछें। बातचीत की चिकित्सा, सामाजिक सहायता और दवा का चुनाव मरीज के अनुसार करें। असर में समय लग सकता है, इसलिए फॉलो अप तय करें। नई अत्यधिक उत्तेजना, उन्माद या गंभीर बिगड़ाव पर जल्दी मदद लें। लंबे इलाज की दवा अचानक बंद न करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"nausea-vomiting","title":"Nausea & Vomiting","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess duration, fluid intake, urine output, abdominal pain, headache, pregnancy possibility and medicine changes. Identify the likely cause before choosing an antiemetic."]},{"title":"Treatment principles","text":["Oral rehydration and treatment of the cause are often central. Antiemetics differ in indication, sedation, anticholinergic effects, movement effects and QT risk; check other medicines and patient factors."]},{"title":"Safety and follow-up","text":["Blood or coffee-ground vomit, severe abdominal pain, neurological symptoms, marked dehydration or persistent vomiting requires prompt assessment. Children and frail adults can deteriorate quickly. A medicine that suppresses vomiting should not mask an unresolved serious cause."]}],"quick":["Assess duration, fluid intake, urine output, abdominal pain, headache, pregnancy possibility and medicine changes","Oral rehydration and treatment of the cause are often central","Blood or coffee-ground vomit, severe abdominal pain, neurological symptoms, marked dehydration or persistent vomiting requires prompt assessment"],"date":"2026-09-18","overview":"Assess duration, fluid intake, urine output, abdominal pain, headache, pregnancy possibility and medicine changes.","hi":"मतली और उल्टी में समय, पानी पीने की क्षमता, पेशाब, पेट दर्द, गर्भावस्था और नई दवा पूछें। पहले कारण पहचानें। पानी और नमक की कमी पूरी करना महत्वपूर्ण है। उल्टी रोकने वाली दवाओं में नींद, हृदय की लय और दूसरे दुष्प्रभाव अलग हैं। खून वाली उल्टी, तेज पेट दर्द, भ्रम या गंभीर पानी की कमी में तुरंत जांच करवाएं। लक्षण दबने से गंभीर कारण खत्म नहीं होता।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"ulcerative-colitis-crohn-s-disease","title":"Ulcerative Colitis & Crohn's Disease","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess bowel frequency, bleeding, pain, weight loss, extraintestinal symptoms and infection risk. Ulcerative colitis and Crohn's disease differ in location and complications; confirm the diagnosis and disease activity."]},{"title":"Treatment principles","text":["Induction and maintenance therapy serve different purposes. Corticosteroids can control selected flares but are not a routine maintenance solution. Immunomodulators and advanced therapies require screening, vaccination planning and monitoring."]},{"title":"Safety and follow-up","text":["Severe pain, distension, fever, significant bleeding or dehydration requires urgent assessment. Review infection before assuming every deterioration is a flare. Discuss adherence, nutrition, smoking and avoidance of unreviewed NSAID use."]}],"quick":["Assess bowel frequency, bleeding, pain, weight loss, extraintestinal symptoms and infection risk","Induction and maintenance therapy serve different purposes","Severe pain, distension, fever, significant bleeding or dehydration requires urgent assessment"],"date":"2026-09-18","overview":"Assess bowel frequency, bleeding, pain, weight loss, extraintestinal symptoms and infection risk.","hi":"अल्सरेटिव कोलाइटिस और क्रोन्स में दस्त, खून, दर्द और वजन देखें। सक्रिय फ्लेयर का इलाज और लंबे समय की रोकथाम अलग हैं। स्टेरॉयड कुछ फ्लेयर में उपयोगी हैं, लेकिन नियमित रखरखाव का विकल्प नहीं। प्रतिरक्षा प्रभावित करने वाली दवाओं से पहले संक्रमण की जांच और टीकों की योजना चाहिए। तेज दर्द, पेट फूलना, बुखार या अधिक रक्तस्राव पर तुरंत जांच करवाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"women-s-health","title":"Women's Health","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Start with the person's symptoms and goals rather than assumptions about age, anatomy, gender or pregnancy intentions. Menstrual history, bleeding pattern, pain, medicines and relevant screening help focus the assessment."]},{"title":"Treatment principles","text":["Common pharmacy discussions include menstrual symptoms, contraception, iron deficiency, pregnancy planning and menopause. Match recommendations to the identified problem, contraindications and the patient's preferences."]},{"title":"Safety and follow-up","text":["Heavy bleeding with faintness, severe pelvic pain, possible ectopic pregnancy or new postmenopausal bleeding requires assessment. Use a private setting, consent and inclusive language. Do not attribute every symptom to hormones without considering alternatives."]}],"quick":["Start with the person's symptoms and goals rather than assumptions about age, anatomy, gender or pregnancy intentions","Common pharmacy discussions include menstrual symptoms, contraception, iron deficiency, pregnancy planning and menopause","Heavy bleeding with faintness, severe pelvic pain, possible ectopic pregnancy or new postmenopausal bleeding requires assessment"],"date":"2026-09-18","overview":"Start with the person's symptoms and goals rather than assumptions about age, anatomy, gender or pregnancy intentions.","hi":"महिला स्वास्थ्य में उम्र या पहचान के आधार पर अनुमान न लगाएं। मरीज की समस्या, लक्ष्य, मासिक धर्म, खून की मात्रा, दर्द और गर्भावस्था की संभावना पूछें। गर्भनिरोध, आयरन की कमी, गर्भ की योजना और मेनोपॉज अलग जरूरतें हैं। बहुत खून के साथ चक्कर, तेज पेल्विक दर्द या मेनोपॉज के बाद नया रक्तस्राव जांच मांगता है। गोपनीयता और सम्मानजनक भाषा रखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"dyspepsia-gerd-peptic-ulcer-disease","title":"Dyspepsia, GERD & Peptic Ulcer Disease","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Distinguish reflux symptoms from dyspepsia and possible ulcer disease. Ask about alarm symptoms, NSAIDs, aspirin, prior Helicobacter pylori treatment and medicines that aggravate symptoms."]},{"title":"Treatment principles","text":["Lifestyle measures and acid suppression are selected according to the diagnosis. H. pylori treatment uses a current locally appropriate combination regimen and confirmation-of-eradication plan. Test timing and acid-suppressing medicines can affect results."]},{"title":"Safety and follow-up","text":["Dysphagia, GI bleeding, unintentional weight loss or persistent vomiting requires evaluation. New chest pain should not simply be labelled reflux. Reassess the indication and lowest appropriate duration of long-term acid suppression."]}],"quick":["Distinguish reflux symptoms from dyspepsia and possible ulcer disease","Lifestyle measures and acid suppression are selected according to the diagnosis","Dysphagia, GI bleeding, unintentional weight loss or persistent vomiting requires evaluation"],"date":"2026-09-18","overview":"Distinguish reflux symptoms from dyspepsia and possible ulcer disease.","hi":"एसिड रिफ्लक्स, अपच और अल्सर को अलग समझें। एन एस ए आई डी, एस्प्रिन और एच पाइलोरी का इतिहास पूछें। एच पाइलोरी में वर्तमान उपयुक्त कई दवाओं की योजना और इलाज के बाद पुष्टि जरूरी है। जांच का समय और एसिड की दवा परिणाम बदल सकती है। निगलने में परेशानी, वजन घटना या रक्तस्राव में जांच करवाएं। नए छाती दर्द को केवल एसिड न मानें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"medical-abortion","title":"Medical Abortion","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Provide confidential, nonjudgmental care. Confirm the prescribed regimen, gestational assessment, access to follow-up and warning signs that could suggest ectopic pregnancy or another urgent problem."]},{"title":"Treatment principles","text":["Mifepristone and misoprostol have distinct roles in common medication-abortion regimens. Dispense against the current Canadian monograph and care protocol, explaining the sequence, expected bleeding and pain-management plan."]},{"title":"Safety and follow-up","text":["Give clear instructions for excessive bleeding, fainting, severe persistent pain, fever or feeling very unwell. Confirm how completion will be assessed. Medication abortion does not treat ectopic pregnancy; do not improvise a regimen or omit the follow-up plan."]}],"quick":["Provide confidential, nonjudgmental care","Mifepristone and misoprostol have distinct roles in common medication-abortion regimens","Give clear instructions for excessive bleeding, fainting, severe persistent pain, fever or feeling very unwell"],"date":"2026-09-18","overview":"Provide confidential, nonjudgmental care.","hi":"दवा से गर्भसमापन में गोपनीय और बिना निर्णय वाली देखभाल दें। निर्धारित योजना, गर्भ की अवधि और फॉलो अप स्पष्ट करें। मिफेप्रिस्टोन और मिसोप्रोस्टोल का क्रम अलग भूमिका निभाता है; वर्तमान कनाडाई निर्देश के अनुसार समझाएं। बहुत अधिक रक्तस्राव, बेहोशी, लगातार तेज दर्द या बुखार में तुरंत मदद लें। एक्टोपिक गर्भ का इलाज इन दवाओं से नहीं होता। समापन की पुष्टि कैसे होगी, यह जरूर बताएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pancreatitis","title":"Pancreatitis","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Severe upper-abdominal pain, often with vomiting and possible radiation to the back, needs medical assessment. Gallstones, alcohol, high triglycerides and medicines are among possible contributors."]},{"title":"Treatment principles","text":["Acute pancreatitis is managed with assessment of severity, supportive care and treatment of the cause. Antibiotics are not routinely used for uncomplicated sterile inflammation. Chronic pancreatitis can cause pain, malabsorption and diabetes."]},{"title":"Safety and follow-up","text":["Persistent severe pain, dehydration, jaundice or instability warrants urgent care. If pancreatic enzymes are prescribed, teach their relationship to meals and snacks and the exact product directions. Avoid crushing delayed-release enzyme products without specialist product-specific advice."]}],"quick":["Severe upper-abdominal pain, often with vomiting and possible radiation to the back, needs medical assessment","Acute pancreatitis is managed with assessment of severity, supportive care and treatment of the cause","Persistent severe pain, dehydration, jaundice or instability warrants urgent care"],"date":"2026-09-18","overview":"Severe upper-abdominal pain, often with vomiting and possible radiation to the back, needs medical assessment.","hi":"अग्न्याशय की सूजन में ऊपर पेट का तेज दर्द और उल्टी हो सकती है। पथरी, शराब, बहुत अधिक ट्राइग्लिसराइड और दवाएं कारण हो सकते हैं। तीव्र बीमारी में गंभीरता और कारण का अस्पताल में मूल्यांकन जरूरी है। बिना संक्रमण हर मरीज को एंटीबायोटिक नहीं चाहिए। पैंक्रियाटिक एंजाइम भोजन के साथ सही तरीके से लें और विशेष कैप्सूल अपनी तरफ से न कुचलें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"ibs","title":"IBS","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["IBS involves recurrent abdominal pain associated with bowel changes after appropriate assessment. Determine constipation-, diarrhoea- or mixed-predominant symptoms and the effect on daily life."]},{"title":"Treatment principles","text":["Management combines explanation, individual dietary and lifestyle measures, and symptom-targeted treatment. A restrictive diet should have a structured review and reintroduction plan, ideally with dietetic support."]},{"title":"Safety and follow-up","text":["Blood in stool, unexplained weight loss, anaemia, nocturnal symptoms or a concerning new pattern requires reassessment. Do not assume an existing IBS diagnosis explains every future abdominal symptom. Match treatment to the predominant bowel pattern."]}],"quick":["IBS involves recurrent abdominal pain associated with bowel changes after appropriate assessment","Management combines explanation, individual dietary and lifestyle measures, and symptom-targeted treatment","Blood in stool, unexplained weight loss, anaemia, nocturnal symptoms or a concerning new pattern requires reassessment"],"date":"2026-09-18","overview":"IBS involves recurrent abdominal pain associated with bowel changes after appropriate assessment.","hi":"आई बी एस में बार-बार पेट दर्द और मल की आदत बदलती है। कब्ज, दस्त या दोनों का पैटर्न पहचानें। भोजन और जीवनशैली का व्यक्तिगत बदलाव और लक्षण अनुसार दवा मदद कर सकते हैं। बहुत प्रतिबंध वाला आहार बिना समीक्षा हमेशा न चलाएं। मल में खून, वजन घटना, एनीमिया या नया रात का लक्षण हो तो दोबारा जांच करें। पुराना आई बी एस हर नए दर्द का कारण नहीं है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"constipation","title":"Constipation","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess stool pattern, straining, duration, diet, mobility and constipating medicines. Ask about severe pain, vomiting, bleeding, weight loss and possible obstruction before recommending a laxative."]},{"title":"Treatment principles","text":["Gradual fibre changes, suitable fluid intake and activity may help when appropriate. Osmotic or stimulant laxatives are selected according to the cause and response. Opioid-related constipation often needs a proactive medication plan."]},{"title":"Safety and follow-up","text":["Fibre is not a remedy for suspected obstruction or every case of faecal impaction. Avoid inappropriate magnesium- or phosphate-containing products in susceptible patients. Reassess new persistent constipation and document response to treatment."]}],"quick":["Assess stool pattern, straining, duration, diet, mobility and constipating medicines","Gradual fibre changes, suitable fluid intake and activity may help when appropriate","Fibre is not a remedy for suspected obstruction or every case of faecal impaction"],"date":"2026-09-18","overview":"Assess stool pattern, straining, duration, diet, mobility and constipating medicines.","hi":"कब्ज में मल का पैटर्न, जोर लगाना, भोजन, चलना और कब्ज करने वाली दवाएं देखें। तेज दर्द, उल्टी या खून हो तो पहले जांच जरूरी है। उपयुक्त मरीज में फाइबर धीरे बढ़ाएं और पानी तथा गतिविधि पर बात करें। ओपिओइड के साथ पहले से कब्ज की योजना चाहिए। आंत रुकने की संभावना में केवल फाइबर न दें। गुर्दे की बीमारी में कुछ मैग्नीशियम या फॉस्फेट उत्पाद अनुपयुक्त हो सकते हैं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"contraception","title":"Contraception","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Explore pregnancy intentions, preferred method, adherence, menstrual concerns, smoking, migraine history, thrombotic risk and interacting medicines. Emergency contraception is a separate time-sensitive assessment."]},{"title":"Treatment principles","text":["Methods differ in effectiveness, user dependence, bleeding effects and contraindications. Estrogen-containing methods are unsuitable for some patients; long-acting reversible options and progestin-only choices may be appropriate alternatives."]},{"title":"Safety and follow-up","text":["Use the exact product's missed-dose and backup instructions. Enzyme-inducing medicines can reduce some methods' effectiveness. Contraception does not generally protect against STIs; discuss barrier protection and confidential shared decisions."]}],"quick":["Explore pregnancy intentions, preferred method, adherence, menstrual concerns, smoking, migraine history, thrombotic risk and interacting medicines","Methods differ in effectiveness, user dependence, bleeding effects and contraindications","Use the exact product's missed-dose and backup instructions"],"date":"2026-09-18","overview":"Explore pregnancy intentions, preferred method, adherence, menstrual concerns, smoking, migraine history, thrombotic risk and interacting medicines.","hi":"गर्भनिरोध में मरीज की पसंद, गर्भ की योजना, नियमित उपयोग, माइग्रेन, धूम्रपान और थक्के का जोखिम पूछें। सभी तरीकों में एस्ट्रोजन नहीं होता और प्रभावशीलता तथा ब्लीडिंग अलग हैं। छूटी खुराक और अतिरिक्त बचाव के निर्देश उत्पाद अनुसार दें। एंजाइम बढ़ाने वाली कुछ दवाएं असर कम कर सकती हैं। अधिकांश गर्भनिरोध तरीके यौन संक्रमण से नहीं बचाते। आपातकालीन गर्भनिरोध समय पर मूल्यांकन मांगता है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"benign-prostatic-hyperplasia","title":"Benign Prostatic Hyperplasia","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess voiding and storage symptoms, severity, medicines and complications. Lower urinary tract symptoms are not automatically BPH; infection, cancer, neurological disease and medicine effects may need consideration."]},{"title":"Treatment principles","text":["Alpha blockers can improve symptoms, while 5-alpha-reductase inhibitors have a different role in selected patients with prostate enlargement. Explain expected onset and monitor dizziness, blood pressure and sexual adverse effects."]},{"title":"Safety and follow-up","text":["Acute inability to pass urine, fever with urinary symptoms, visible blood or renal concerns requires assessment. Inform the eye surgeon about current or previous alpha-blocker use before cataract surgery. Review decongestant and anticholinergic exposure."]}],"quick":["Assess voiding and storage symptoms, severity, medicines and complications","Alpha blockers can improve symptoms, while 5-alpha-reductase inhibitors have a different role in selected patients with prostate enlargement","Acute inability to pass urine, fever with urinary symptoms, visible blood or renal concerns requires assessment"],"date":"2026-09-18","overview":"Assess voiding and storage symptoms, severity, medicines and complications.","hi":"प्रोस्टेट बढ़ने में पेशाब शुरू करने में देर, कमजोर धार और बार-बार पेशाब देखें। हर लक्षण को प्रोस्टेट न मानें। अल्फा ब्लॉकर और फाइव अल्फा रिडक्टेज अवरोधक का काम और असर का समय अलग है। चक्कर और रक्तचाप देखें। पेशाब बिल्कुल न होना आपातस्थिति है। मोतियाबिंद ऑपरेशन से पहले अल्फा ब्लॉकर के वर्तमान या पुराने उपयोग की जानकारी आंख के डॉक्टर को दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"urinary-incontinence","title":"Urinary Incontinence","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Distinguish stress, urge, overflow and functional incontinence. Review onset, urinary symptoms, mobility, cognition, constipation, fluids and medicines; treatment differs by mechanism."]},{"title":"Treatment principles","text":["Bladder training, pelvic-floor approaches and addressing contributing factors are often important. Antimuscarinic and beta-3 agonist therapies have different risks and require individual assessment rather than a generic 'bladder pill'."]},{"title":"Safety and follow-up","text":["Retention, haematuria, recurrent infection or new neurological findings needs evaluation. Anticholinergic burden can worsen cognition and constipation; some alternatives require blood-pressure monitoring. Reassess benefit and daily-life goals."]}],"quick":["Distinguish stress, urge, overflow and functional incontinence","Bladder training, pelvic-floor approaches and addressing contributing factors are often important","Retention, haematuria, recurrent infection or new neurological findings needs evaluation"],"date":"2026-09-18","overview":"Distinguish stress, urge, overflow and functional incontinence.","hi":"पेशाब छूटने में खांसने पर, तेज इच्छा के साथ, रुकावट के कारण और चलने की परेशानी वाले प्रकार अलग हैं। कब्ज, दवाएं और तरल सेवन देखें। ब्लैडर ट्रेनिंग और पेल्विक फ्लोर सहायता उपयोगी हो सकती है। हर व्यक्ति को एक जैसी दवा नहीं चाहिए। एंटीकोलिनर्जिक दवाएं भ्रम और कब्ज बढ़ा सकती हैं। पेशाब रुकना, खून या नई कमजोरी हो तो जांच करवाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"menopause","title":"Menopause","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess vasomotor symptoms, sleep, genitourinary symptoms, bleeding and personal treatment goals. Review thrombotic, cardiovascular and cancer history and whether the uterus is present."]},{"title":"Treatment principles","text":["Hormonal and nonhormonal options are selected through individualized benefit–risk discussion. Systemic and local vaginal therapies have different purposes. People with a uterus generally need appropriate endometrial protection with systemic estrogen."]},{"title":"Safety and follow-up","text":["New postmenopausal bleeding needs assessment. Menopausal hormone therapy is not contraception and should not be presented as universal prevention of chronic disease. Review symptom response, adverse effects and ongoing need."]}],"quick":["Assess vasomotor symptoms, sleep, genitourinary symptoms, bleeding and personal treatment goals","Hormonal and nonhormonal options are selected through individualized benefit–risk discussion","New postmenopausal bleeding needs assessment"],"date":"2026-09-18","overview":"Assess vasomotor symptoms, sleep, genitourinary symptoms, bleeding and personal treatment goals.","hi":"मेनोपॉज में गर्मी के दौरे, नींद, योनि के लक्षण और मरीज के लक्ष्य पूछें। थक्के, कैंसर और गर्भाशय की स्थिति उपचार बदलती है। पूरे शरीर की हार्मोन दवा और स्थानीय योनि दवा का काम अलग है। गर्भाशय होने पर सिस्टमिक एस्ट्रोजन के साथ उचित सुरक्षा जरूरी होती है। मेनोपॉज के बाद नया रक्तस्राव जांच मांगता है। हार्मोन थेरेपी गर्भनिरोध नहीं है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"erectile-dysfunction","title":"Erectile Dysfunction","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Ask privately about onset, consistency, libido, psychological factors and medicines. Erectile dysfunction can accompany diabetes, vascular disease or hormonal problems and merits a broader risk assessment."]},{"title":"Treatment principles","text":["PDE5 inhibitors require counselling on timing, sexual stimulation, food effects where relevant and realistic expectations. Review cardiovascular suitability and interacting medicines before recommending treatment."]},{"title":"Safety and follow-up","text":["Nitrates and PDE5 inhibitors can produce dangerous hypotension; assess the exact product and timing. Persistent painful erection or sudden vision/hearing symptoms requires urgent care. Do not source unregulated enhancement products."]}],"quick":["Ask privately about onset, consistency, libido, psychological factors and medicines","PDE5 inhibitors require counselling on timing, sexual stimulation, food effects where relevant and realistic expectations","Nitrates and PDE5 inhibitors can produce dangerous hypotension; assess the exact product and timing"],"date":"2026-09-18","overview":"Ask privately about onset, consistency, libido, psychological factors and medicines.","hi":"इरेक्टाइल डिसफंक्शन पर निजी और सम्मानजनक बातचीत करें। मधुमेह, रक्तवाहिका की बीमारी, दवाएं और मानसिक कारण देखें। पी डी ई फाइव दवा में समय, भोजन और यौन उत्तेजना के निर्देश अलग हो सकते हैं। नाइट्रेट के साथ खतरनाक रक्तचाप गिर सकता है। लंबे दर्द वाले इरेक्शन या अचानक नजर और सुनने में बदलाव पर तुरंत मदद लें। अनियमित ऑनलाइन उत्पाद से बचें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"reproductive-health","title":"Reproductive Health","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Use an inclusive history focused on anatomy, fertility goals, sexual health, pregnancy potential and medicines. Do not infer reproductive needs from gender identity or relationship status."]},{"title":"Treatment principles","text":["Preconception care includes medication review, appropriate supplementation and vaccination review. Fertility or pregnancy-related therapies require product-specific counselling, storage and administration teaching."]},{"title":"Safety and follow-up","text":["Possible ectopic pregnancy, severe pelvic pain or heavy bleeding requires urgent assessment. Discuss consent, confidentiality and safeguarding where appropriate. Coordinate changes to essential medicines instead of abruptly stopping them because pregnancy is possible."]}],"quick":["Use an inclusive history focused on anatomy, fertility goals, sexual health, pregnancy potential and medicines","Preconception care includes medication review, appropriate supplementation and vaccination review","Possible ectopic pregnancy, severe pelvic pain or heavy bleeding requires urgent assessment"],"date":"2026-09-18","overview":"Use an inclusive history focused on anatomy, fertility goals, sexual health, pregnancy potential and medicines.","hi":"प्रजनन स्वास्थ्य में पहचान के आधार पर अनुमान न लगाएं। संबंधित अंग, गर्भ की संभावना, प्रजनन लक्ष्य और दवाएं पूछें। गर्भ से पहले दवा, उचित सप्लीमेंट और टीके की समीक्षा करें। कुछ इलाज में विशेष भंडारण और लगाने की विधि होती है। तेज पेल्विक दर्द, बहुत रक्तस्राव या एक्टोपिक गर्भ की संभावना में तुरंत जांच करें। जरूरी दवा अचानक बंद करवाने के बजाय समन्वित योजना बनाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"upper-gi-bleeding","title":"Upper GI Bleeding","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Vomiting blood or coffee-ground material and black tarry stool can indicate upper GI bleeding. Assess dizziness, collapse, anticoagulants, NSAIDs, liver disease and the amount and timing of bleeding."]},{"title":"Treatment principles","text":["Suspected significant bleeding needs urgent hospital assessment, stabilization and source evaluation. Acid suppression or a medicine review does not replace emergency care. Antithrombotic decisions require the responsible clinical team."]},{"title":"Safety and follow-up","text":["Do not independently advise a universal stop or restart date for anticoagulation. After treatment, reconcile the plan, address the cause and clarify follow-up. Iron or bismuth can darken stool, but do not use that fact to dismiss concerning symptoms."]}],"quick":["Vomiting blood or coffee-ground material and black tarry stool can indicate upper GI bleeding","Suspected significant bleeding needs urgent hospital assessment, stabilization and source evaluation","Do not independently advise a universal stop or restart date for anticoagulation"],"date":"2026-09-18","overview":"Vomiting blood or coffee-ground material and black tarry stool can indicate upper GI bleeding.","hi":"खून या कॉफी जैसे रंग की उल्टी और काला चिपचिपा मल ऊपर पाचन तंत्र के रक्तस्राव का संकेत हो सकता है। चक्कर, बेहोशी, खून पतला करने वाली दवा और एन एस ए आई डी पूछें। गंभीर रक्तस्राव में तुरंत अस्पताल जाएं। एसिड की दवा आपातकालीन देखभाल का विकल्प नहीं। एंटीकोआगुलेंट कब रोकना या शुरू करना है, यह इलाज करने वाली टीम तय करे।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"drugs-in-pregnancy-lactation","title":"Drugs in Pregnancy & Lactation","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Assessment","text":["Assessment depends on gestational stage or infant age, indication, dose, route, duration and alternatives. A medicine's pregnancy risk cannot be inferred solely from whether it enters breast milk."]},{"title":"Treatment principles","text":["Balance the risks of treatment against untreated disease using a current teratology or lactation reference. Consider premature infants, infant health and the extent of exposure. Optimize necessary treatment with the relevant clinicians."]},{"title":"Safety and follow-up","text":["Do not describe all natural products as safe or recommend stopping every medicine. Document the source and counselling. A new exposure needs a specific risk assessment; uncertainty alone is not proof that harm has occurred."]}],"quick":["Assessment depends on gestational stage or infant age, indication, dose, route, duration and alternatives","Balance the risks of treatment against untreated disease using a current teratology or lactation reference","Do not describe all natural products as safe or recommend stopping every medicine"],"date":"2026-09-18","overview":"Assessment depends on gestational stage or infant age, indication, dose, route, duration and alternatives.","hi":"गर्भावस्था और स्तनपान की दवा समीक्षा अलग है। गर्भ का समय, शिशु की उम्र, दवा की जरूरत, मात्रा और अवधि देखें। बीमारी का इलाज न होने का जोखिम भी तौलें। वर्तमान विश्वसनीय गर्भ और स्तनपान संदर्भ इस्तेमाल करें। प्राकृतिक उत्पाद हमेशा सुरक्षित नहीं होते। सभी दवाएं बंद न करवाएं। अनिश्चितता का मतलब यह नहीं कि नुकसान निश्चित हुआ है; व्यक्तिगत मूल्यांकन करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"hepatic-encephalopathy","title":"Hepatic Encephalopathy","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["New confusion in cirrhosis needs assessment for infection, bleeding, constipation, dehydration, medicines and other causes. Do not attribute every altered mental state to the liver without evaluation."]},{"title":"Treatment principles","text":["Management targets precipitating factors and commonly uses lactulose, with rifaximin in appropriate circumstances. The plan should specify the stool goal and follow-up rather than encouraging uncontrolled diarrhoea."]},{"title":"Safety and follow-up","text":["Severe drowsiness or inability to protect the airway requires emergency care. Excessive diarrhoea can worsen dehydration and electrolytes. Review sedatives, adherence and caregiver understanding, and distinguish a clinical assessment from an ammonia number alone."]}],"quick":["New confusion in cirrhosis needs assessment for infection, bleeding, constipation, dehydration, medicines and other causes","Management targets precipitating factors and commonly uses lactulose, with rifaximin in appropriate circumstances","Severe drowsiness or inability to protect the airway requires emergency care"],"date":"2026-09-18","overview":"New confusion in cirrhosis needs assessment for infection, bleeding, constipation, dehydration, medicines and other causes.","hi":"सिरोसिस में नया भ्रम होने पर संक्रमण, रक्तस्राव, कब्ज, पानी की कमी और दवाएं देखें। हर भ्रम को केवल लिवर का कारण न मानें। लैक्टुलोज और कुछ स्थितियों में रिफैक्सिमिन उपयोग होती हैं। मल का लक्ष्य डॉक्टर की योजना से समझाएं; बहुत दस्त होना अच्छा लक्ष्य नहीं। अत्यधिक नींद या सांस की सुरक्षा न रख पाना आपातस्थिति है। परिवार को निगरानी और फॉलो अप बताएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"diarrhoea","title":"Diarrhoea","subject":"GI, GU & Reproductive Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess duration, frequency, blood, fever, dehydration, travel, antibiotics and vulnerable contacts. Recent antibiotic exposure or hospitalization raises concern for C. difficile; chronic diarrhoea needs a wider assessment."]},{"title":"Treatment principles","text":["Oral rehydration is central. Symptom medicines are appropriate only after considering age, cause and contraindications. Antibiotics are not routine for every episode; organism-specific treatment and infection-control measures may be needed."]},{"title":"Safety and follow-up","text":["Blood, severe pain, high fever, marked dehydration or significant immunocompromise warrants assessment. Avoid indiscriminate antimotility treatment in suspected invasive disease. Review urine output, fluid intake and a clear plan if symptoms persist."]}],"quick":["Assess duration, frequency, blood, fever, dehydration, travel, antibiotics and vulnerable contacts","Oral rehydration is central","Blood, severe pain, high fever, marked dehydration or significant immunocompromise warrants assessment"],"date":"2026-09-18","overview":"Assess duration, frequency, blood, fever, dehydration, travel, antibiotics and vulnerable contacts.","hi":"दस्त में अवधि, खून, बुखार, यात्रा और हाल की एंटीबायोटिक पूछें। पानी और नमक की कमी पूरी करना सबसे जरूरी कदमों में है। हर दस्त में एंटीबायोटिक नहीं चाहिए। खून, तेज पेट दर्द, गंभीर पानी की कमी या कमजोर प्रतिरक्षा में जांच करवाएं। आक्रामक संक्रमण की संभावना में दस्त रोकने की दवा बिना समीक्षा न दें। पेशाब और तरल सेवन की निगरानी तथा फॉलो अप समझाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"opioid-and-alcohol-use-disorder","title":"Opioid and Alcohol Use Disorder","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["BC Centre on Substance Use: clinical guidance","https://www.bccsu.ca/clinical-care-guidance/"],["BC Centre on Substance Use: opioid use disorder guideline","https://www.bccsu.ca/opioid-use-disorder/"]],"sections":[{"title":"Assessment","text":["Use a nonjudgmental assessment of substance use, goals, withdrawal, overdose history, other sedatives and support. Physical dependence, tolerance and use disorder are related but not identical concepts."]},{"title":"Treatment principles","text":["Offer harm reduction and evidence-based treatment referral. Opioid agonist treatment has product-specific initiation and missed-dose rules. Alcohol withdrawal can require monitored medical treatment; long-term relapse-prevention treatment is a separate decision."]},{"title":"Safety and follow-up","text":["Slow or absent breathing after opioid exposure requires emergency response and naloxone when available. Severe alcohol withdrawal can cause seizures or delirium. Do not advise abrupt unsupported withdrawal in a person at risk or restart an old opioid dose after lost tolerance."]}],"quick":["Use a nonjudgmental assessment of substance use, goals, withdrawal, overdose history, other sedatives and support","Offer harm reduction and evidence-based treatment referral","Slow or absent breathing after opioid exposure requires emergency response and naloxone when available"],"date":"2026-09-18","overview":"Use a nonjudgmental assessment of substance use, goals, withdrawal, overdose history, other sedatives and support.","hi":"ओपिओइड और शराब के उपयोग पर बिना दोष दिए बात करें। विड्रॉल, ओवरडोज, दूसरी नींद की दवाएं और लक्ष्य पूछें। शारीरिक निर्भरता और उपयोग विकार एक ही बात नहीं हैं। नालॉक्सोन और नुकसान कम करने की सहायता दें। गंभीर शराब विड्रॉल में दौरे या डिलीरियम हो सकता है। लंबे अंतराल के बाद पुरानी ओपिओइड खुराक फिर शुरू करना खतरनाक है क्योंकि सहनशीलता घट सकती है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"bell-palsy-and-gbs","title":"Bell Palsy and GBS","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Sudden facial weakness requires assessment to distinguish Bell palsy from stroke and other causes. Guillain–Barré syndrome can present with progressive weakness, sensory symptoms and reduced reflexes, often after infection."]},{"title":"Treatment principles","text":["Bell palsy care includes timely assessment and eye protection when closure is impaired. Suspected GBS requires urgent hospital evaluation for respiratory and autonomic involvement; it is not a routine self-care problem."]},{"title":"Safety and follow-up","text":["Facial weakness with speech or limb symptoms requires emergency stroke assessment. Ascending weakness, swallowing difficulty or breathlessness can deteriorate rapidly. Do not delay referral while trying a topical or over-the-counter remedy."]}],"quick":["Sudden facial weakness requires assessment to distinguish Bell palsy from stroke and other causes","Bell palsy care includes timely assessment and eye protection when closure is impaired","Facial weakness with speech or limb symptoms requires emergency stroke assessment"],"date":"2026-09-18","overview":"Sudden facial weakness requires assessment to distinguish Bell palsy from stroke and other causes.","hi":"अचानक चेहरे की कमजोरी में बेल पाल्सी और स्ट्रोक को अलग करना जरूरी है। आंख बंद न हो तो आंख की सुरक्षा की योजना चाहिए। गिलैन बारे में बढ़ती कमजोरी और सांस या निगलने की परेशानी हो सकती है। बोलने या हाथ-पैर की कमजोरी के साथ चेहरे का बदलाव आपातकालीन स्ट्रोक जांच मांगता है। बढ़ती कमजोरी को घर की दवा से संभालने की कोशिश में रेफरल न रोकें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"cannabis","title":"Cannabis","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Ask about formulation, THC and CBD content, route, frequency, goals, other medicines and adverse effects. Oral and inhaled products differ in onset and duration; a product being legal does not establish that it is risk free."]},{"title":"Treatment principles","text":["Discuss impairment, interactions, safer storage and uncertainty about benefit for the intended condition. Delayed oral effects can lead to repeated dosing before the first dose has taken effect."]},{"title":"Safety and follow-up","text":["Avoid driving while impaired and combining with sedatives. Pregnancy, adolescent use and a history of psychosis require particular caution. Severe vomiting, chest pain, marked confusion or accidental child ingestion needs assessment."]}],"quick":["Ask about formulation, THC and CBD content, route, frequency, goals, other medicines and adverse effects","Discuss impairment, interactions, safer storage and uncertainty about benefit for the intended condition","Avoid driving while impaired and combining with sedatives"],"date":"2026-09-18","overview":"Ask about formulation, THC and CBD content, route, frequency, goals, other medicines and adverse effects.","hi":"कैनबिस में टी एच सी, सी बी डी, रूप, मात्रा और उपयोग का कारण पूछें। खाने वाले उत्पाद का असर देर से आता है और जल्दी दोबारा लेने से नुकसान हो सकता है। वैध होने का मतलब जोखिम रहित नहीं। नशे में गाड़ी न चलाएं और नींद की दवाओं के साथ खतरा समझें। बच्चे द्वारा गलती से लेना, गंभीर भ्रम या लगातार उल्टी होने पर चिकित्सा मदद लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"parkinson-s-disease","title":"Parkinson's Disease","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess movement symptoms, falls, swallowing, cognition, hallucinations, constipation and fluctuations related to dose timing. Medicines that block dopamine can worsen parkinsonism."]},{"title":"Treatment principles","text":["Levodopa regimens are time sensitive and individualized. Preserve the exact schedule during transitions of care and assess wearing-off or dyskinesia with the treating team. Dopamine agonists can affect impulse control and cause sleepiness."]},{"title":"Safety and follow-up","text":["Do not abruptly stop dopaminergic therapy. Review orthostatic symptoms and hallucinations without assuming every problem is disease progression. If swallowing becomes difficult, obtain a safe formulation plan rather than crushing all products."]}],"quick":["Assess movement symptoms, falls, swallowing, cognition, hallucinations, constipation and fluctuations related to dose timing","Levodopa regimens are time sensitive and individualized","Do not abruptly stop dopaminergic therapy"],"date":"2026-09-18","overview":"Assess movement symptoms, falls, swallowing, cognition, hallucinations, constipation and fluctuations related to dose timing.","hi":"पार्किन्सन में गति के साथ गिरना, निगलना, कब्ज, भ्रम और खुराक के समय से बदलते लक्षण देखें। लेवोडोपा का सही समय महत्वपूर्ण है, खासकर अस्पताल में। डोपामिन रोकने वाली कुछ दवाएं लक्षण बिगाड़ सकती हैं। दवा अचानक बंद न करें। कुछ डोपामिन एगोनिस्ट आवेग नियंत्रण और नींद प्रभावित करते हैं। निगलने में परेशानी पर हर गोली कुचलने के बजाय सही विकल्प की योजना लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"headaches-migraines","title":"Headaches & Migraines","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Clarify onset, pattern, neurological symptoms, triggers and frequency of acute medicine use. A first thunderclap headache, new deficit, fever with stiffness or concerning pregnancy-related headache needs urgent assessment."]},{"title":"Treatment principles","text":["Acute and preventive migraine therapies serve different goals. Select treatment around comorbidities, interactions and contraindications. Frequent use of acute medicines can contribute to medication-overuse headache."]},{"title":"Safety and follow-up","text":["Triptans are not suitable for every vascular-risk context. Track headache days, disability and medicine days in a diary. Do not dismiss a major change in pattern because the patient has a previous migraine diagnosis."]}],"quick":["Clarify onset, pattern, neurological symptoms, triggers and frequency of acute medicine use","Acute and preventive migraine therapies serve different goals","Triptans are not suitable for every vascular-risk context"],"date":"2026-09-18","overview":"Clarify onset, pattern, neurological symptoms, triggers and frequency of acute medicine use.","hi":"सिरदर्द में शुरुआत, पैटर्न, न्यूरोलॉजिकल लक्षण और दर्द की दवा कितने दिन ली जाती है, पूछें। अचानक सबसे तेज सिरदर्द या नई कमजोरी में तुरंत जांच करें। माइग्रेन के तत्काल और रोकथाम के इलाज अलग हैं। ज्यादा बार दर्द की दवा लेने से सिरदर्द बढ़ सकता है। ट्रिप्टान सभी मरीजों के लिए सही नहीं। सिरदर्द और दवा वाले दिनों का रिकॉर्ड रखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pain-management-palliative-care","title":"Pain Management & Palliative Care","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess the pain mechanism, severity, function, goals and emotional context. Palliative care addresses quality of life and symptoms; it is not restricted to the final days of life."]},{"title":"Treatment principles","text":["Combine appropriate non-drug strategies with medicines selected for the pain mechanism and patient. Opioid therapy requires a clear indication, individualized titration, constipation planning and assessment of sedation and breathing risk."]},{"title":"Safety and follow-up","text":["Account for kidney function, other sedatives, falls and previous opioid exposure. Do not apply a simple equianalgesic conversion without accounting for incomplete cross-tolerance and clinical context. New neurological deficits or severe unexplained pain needs assessment."]}],"quick":["Assess the pain mechanism, severity, function, goals and emotional context","Combine appropriate non-drug strategies with medicines selected for the pain mechanism and patient","Account for kidney function, other sedatives, falls and previous opioid exposure"],"date":"2026-09-18","overview":"Assess the pain mechanism, severity, function, goals and emotional context.","hi":"दर्द में तीव्रता के साथ कारण, कामकाज और मरीज के लक्ष्य देखें। पैलिएटिव देखभाल जीवन की गुणवत्ता पर केंद्रित है और केवल अंतिम दिनों के लिए नहीं है। ओपिओइड में कब्ज, नींद, सांस और गुर्दे की स्थिति की योजना चाहिए। दूसरी नींद की दवाओं से जोखिम बढ़ता है। एक ओपिओइड से दूसरी में बदलते समय केवल गणित की बराबरी पर्याप्त नहीं; सहनशीलता और व्यक्तिगत स्थिति जरूरी हैं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"chronic-spasticity","title":"Chronic Spasticity","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Determine whether increased muscle tone is painful, limits function or sometimes helps transfers. Review the neurological cause, triggers, weakness and goals with the patient and rehabilitation team."]},{"title":"Treatment principles","text":["Physical and positioning strategies may accompany medicines such as baclofen or focal treatments. Balance reduced tone against sedation and loss of useful strength; renal function is important for some agents."]},{"title":"Safety and follow-up","text":["Abrupt baclofen withdrawal, especially interruption of an intrathecal pump, can be dangerous. Sudden severe worsening, fever, confusion or suspected pump failure requires urgent assessment. Document the exact route and delivery system."]}],"quick":["Determine whether increased muscle tone is painful, limits function or sometimes helps transfers","Physical and positioning strategies may accompany medicines such as baclofen or focal treatments","Abrupt baclofen withdrawal, especially interruption of an intrathecal pump, can be dangerous"],"date":"2026-09-18","overview":"Determine whether increased muscle tone is painful, limits function or sometimes helps transfers.","hi":"स्पास्टिसिटी में मांसपेशी का बढ़ा खिंचाव दर्द और काम को कैसे प्रभावित करता है, पूछें। कभी कुछ टोन खड़े होने में मदद भी करता है। व्यायाम, स्थिति और दवा की योजना साथ बनाएं। बैक्लोफेन से नींद और कमजोरी हो सकती है। दवा अचानक बंद करना, खासकर पंप रुकना, खतरनाक है। बुखार, भ्रम या तेजी से बिगड़ाव में तुरंत मदद लें और सही मार्ग दर्ज करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"multiple-sclerosis","title":"Multiple Sclerosis","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Distinguish a possible relapse from temporary worsening during infection, heat or another stressor. Assess new neurological symptoms, functional change, current disease-modifying therapy and infection risk."]},{"title":"Treatment principles","text":["Acute relapse treatment, long-term disease modification and symptom control are separate plans. Disease-modifying products differ substantially in infection screening, vaccines, laboratory monitoring, reproductive counselling and administration."]},{"title":"Safety and follow-up","text":["Do not stop or switch treatment without a coordinated plan because rebound or disease activity may be relevant. New severe neurological symptoms require assessment. Review fatigue, mobility, bladder symptoms and adherence respectfully."]}],"quick":["Distinguish a possible relapse from temporary worsening during infection, heat or another stressor","Acute relapse treatment, long-term disease modification and symptom control are separate plans","Do not stop or switch treatment without a coordinated plan because rebound or disease activity may be relevant"],"date":"2026-09-18","overview":"Distinguish a possible relapse from temporary worsening during infection, heat or another stressor.","hi":"मल्टिपल स्क्लेरोसिस में असली रिलैप्स और बुखार या गर्मी से अस्थायी बिगड़ाव अलग करें। नई न्यूरोलॉजिकल समस्या की जांच जरूरी है। रिलैप्स का इलाज, बीमारी बदलने वाली दवा और लक्षण नियंत्रण तीन अलग लक्ष्य हैं। दवाओं में संक्रमण जांच, टीके और गर्भ की योजना अलग होती है। उपचार अपने आप बंद या बदलने से पहले विशेषज्ञ से समन्वय करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"restless-leg-syndrome","title":"Restless Leg Syndrome","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["An urge to move the legs that worsens at rest and in the evening and improves with movement suggests restless legs. Distinguish cramps, neuropathy, akathisia and other mimics."]},{"title":"Treatment principles","text":["Review iron status, kidney disease, sleep and aggravating medicines. Treat reversible contributors and select medication using current guidance; the appropriate iron plan depends on laboratory findings and context."]},{"title":"Safety and follow-up","text":["Dopaminergic treatment can cause augmentation, with symptoms starting earlier or becoming more extensive. Do not repeatedly increase a dose without reassessment. Monitor sleepiness, falls and the effect on daily function."]}],"quick":["An urge to move the legs that worsens at rest and in the evening and improves with movement suggests restless legs","Review iron status, kidney disease, sleep and aggravating medicines","Dopaminergic treatment can cause augmentation, with symptoms starting earlier or becoming more extensive"],"date":"2026-09-18","overview":"An urge to move the legs that worsens at rest and in the evening and improves with movement suggests restless legs.","hi":"रेस्टलेस लेग्स में आराम और शाम को पैर हिलाने की इच्छा बढ़ती और हिलाने से घटती है। ऐंठन या न्यूरोपैथी से अलग करें। आयरन, गुर्दे, नींद और बढ़ाने वाली दवाएं देखें। कुछ डोपामिन दवाओं से लक्षण दिन में पहले और ज्यादा फैल सकते हैं; इसे ऑगमेंटेशन कहते हैं। ऐसी स्थिति में खुराक बार-बार बढ़ाने के बजाय दोबारा मूल्यांकन करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"chronic-fatigue-syndrome","title":"Chronic Fatigue Syndrome","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["NICE (UK): Chronic Fatigue Syndrome guidance; apply Canadian context","https://www.nice.org.uk/guidance/ng206/chapter/recommendations"]],"sections":[{"title":"Assessment","text":["ME/CFS involves substantial functional impairment and characteristic post-exertional symptom worsening. Assess sleep, cognition, orthostatic symptoms and alternative or coexisting medical causes."]},{"title":"Treatment principles","text":["Support individualized energy management and symptom care. Activity plans should respect the person's limits and post-exertional worsening rather than impose fixed increases regardless of symptoms."]},{"title":"Safety and follow-up","text":["Do not frame the illness as lack of motivation. Review medicines that worsen fatigue and define practical goals. New focal signs, significant weight loss or a major change from baseline needs reassessment for another cause."]}],"quick":["ME/CFS involves substantial functional impairment and characteristic post-exertional symptom worsening","Support individualized energy management and symptom care","Do not frame the illness as lack of motivation"],"date":"2026-09-18","overview":"ME/CFS involves substantial functional impairment and characteristic post-exertional symptom worsening.","hi":"एम ई या क्रॉनिक फटीग सिंड्रोम में गतिविधि के बाद लक्षण बढ़ना महत्वपूर्ण है। नींद, ध्यान, खड़े होने पर परेशानी और दूसरे कारण देखें। ऊर्जा का उपयोग मरीज की क्षमता के अनुसार बांटें। लक्षण बिगड़ने पर भी तय मात्रा में व्यायाम बढ़ाने की जिद न करें। इसे आलस न कहें। नया अलग लक्षण या वजन घटना हो तो अन्य कारण की जांच करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"drug-withdrawal-syndromes","title":"Drug Withdrawal Syndromes","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["BC Centre on Substance Use: clinical guidance","https://www.bccsu.ca/clinical-care-guidance/"]],"sections":[{"title":"Assessment","text":["Identify the substance or medicine, dose, duration, last use, taper history and symptoms. Withdrawal can occur with prescribed medicines as well as nonmedical substances."]},{"title":"Treatment principles","text":["Different agents need different plans: benzodiazepines, alcohol, opioids, antidepressants, corticosteroids and other therapies are not managed by a single taper schedule. Coordinate an individualized plan and monitor response."]},{"title":"Safety and follow-up","text":["Seizures, delirium, severe autonomic symptoms or suspected adrenal crisis require emergency assessment. Rebound symptoms can resemble recurrence of disease. Do not advise abrupt discontinuation simply because a medicine has adverse effects."]}],"quick":["Identify the substance or medicine, dose, duration, last use, taper history and symptoms","Different agents need different plans: benzodiazepines, alcohol, opioids, antidepressants, corticosteroids and other therapies are not managed by a single taper schedule","Seizures, delirium, severe autonomic symptoms or suspected adrenal crisis require emergency assessment"],"date":"2026-09-18","overview":"Identify the substance or medicine, dose, duration, last use, taper history and symptoms.","hi":"विड्रॉल में कौन सी दवा, कितनी अवधि और आखिरी खुराक कब ली, पूछें। लिखी हुई दवा से भी विड्रॉल हो सकता है। शराब, बेंज़ोडायज़ेपीन, ओपिओइड, एंटीडिप्रेसेंट और स्टेरॉयड की योजना एक जैसी नहीं है। दौरे, डिलीरियम या गंभीर कमजोरी में तुरंत मदद लें। लक्षण लौटना बीमारी या विड्रॉल दोनों हो सकता है। दुष्प्रभाव होने पर भी बिना योजना अचानक बंद न करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"seizures","title":"Seizures","subject":"Neurology","icon":"brain-circuit","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Clarify the event, duration, recovery, known seizure diagnosis, missed doses, triggers and medicines. A first seizure needs medical assessment; not every collapse is epilepsy."]},{"title":"Treatment principles","text":["Antiseizure therapy depends on seizure type, comorbidities, interactions and reproductive considerations. Maintain consistent use and the exact formulation. Rescue medicines require a written individualized plan and caregiver teaching."]},{"title":"Safety and follow-up","text":["A prolonged seizure, repeated seizures without recovery, breathing difficulty or major injury needs emergency care. Protect from injury, do not restrain and put nothing in the mouth. Abruptly stopping long-term antiseizure treatment can provoke seizures."]}],"quick":["Clarify the event, duration, recovery, known seizure diagnosis, missed doses, triggers and medicines","Antiseizure therapy depends on seizure type, comorbidities, interactions and reproductive considerations","A prolonged seizure, repeated seizures without recovery, breathing difficulty or major injury needs emergency care"],"date":"2026-09-18","overview":"Clarify the event, duration, recovery, known seizure diagnosis, missed doses, triggers and medicines.","hi":"दौरे में अवधि, होश लौटने का समय, पुरानी बीमारी और छूटी दवा पूछें। हर बेहोशी मिर्गी नहीं है। दवा दौरे के प्रकार और गर्भ संबंधी जोखिम के अनुसार चुनी जाती है। लंबे दौरे या बीच में होश न लौटने पर आपातकालीन मदद लें। चोट से बचाएं, मरीज को न दबाएं और मुंह में कुछ न डालें। दवा अचानक बंद न करें; रेस्क्यू योजना लिखित हो।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"gout","title":"Gout","subject":"Musculoskeletal","icon":"bone","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["An acutely hot swollen joint needs assessment; septic arthritis is an important alternative. Review attack pattern, kidney function, medicines, alcohol and previous urate-lowering treatment."]},{"title":"Treatment principles","text":["Acute anti-inflammatory treatment and long-term urate reduction address different goals. Colchicine, NSAIDs and corticosteroids have patient-specific limitations. Starting urate-lowering therapy involves a titration and flare-prevention plan."]},{"title":"Safety and follow-up","text":["Colchicine can have serious interactions and toxicity, especially with organ impairment. Do not routinely stop established urate-lowering therapy during a flare without clinical direction. Fever or concern for joint infection requires urgent assessment."]}],"quick":["An acutely hot swollen joint needs assessment; septic arthritis is an important alternative","Acute anti-inflammatory treatment and long-term urate reduction address different goals","Colchicine can have serious interactions and toxicity, especially with organ impairment"],"date":"2026-09-18","overview":"An acutely hot swollen joint needs assessment; septic arthritis is an important alternative.","hi":"गाउट में अचानक गर्म सूजे जोड़ को देखें, लेकिन जोड़ का संक्रमण भी संभव है। तीव्र दर्द कम करना और लंबे समय में यूरिक एसिड कम करना अलग लक्ष्य हैं। कोल्चिसिन, एन एस ए आई डी और स्टेरॉयड की सीमाएं मरीज अनुसार हैं। कोल्चिसिन की गंभीर अंतःक्रियाएं हो सकती हैं। फ्लेयर में पुरानी यूरिक एसिड की दवा अपने आप बंद न करें। बुखार या संक्रमण की आशंका में जल्दी जांच करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"rheumatoid-arthritis","title":"Rheumatoid Arthritis","subject":"Musculoskeletal","icon":"bone","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Persistent inflammatory joint symptoms, morning stiffness and functional decline warrant early assessment. RA is systemic disease, not simply age-related joint wear."]},{"title":"Treatment principles","text":["Disease-modifying antirheumatic drugs aim to control inflammation and prevent damage; analgesics do not replace them. Methotrexate for inflammatory disease is commonly weekly, with a specific folate and monitoring plan."]},{"title":"Safety and follow-up","text":["Daily-versus-weekly methotrexate errors can be fatal. Verify the indication, schedule, interactions, blood counts, liver and kidney monitoring. Infection symptoms and reproductive planning require careful coordination with the treating team."]}],"quick":["Persistent inflammatory joint symptoms, morning stiffness and functional decline warrant early assessment","Disease-modifying antirheumatic drugs aim to control inflammation and prevent damage; analgesics do not replace them","Daily-versus-weekly methotrexate errors can be fatal"],"date":"2026-09-18","overview":"Persistent inflammatory joint symptoms, morning stiffness and functional decline warrant early assessment.","hi":"रूमेटॉइड आर्थराइटिस में सुबह की अकड़न और लगातार सूजे जोड़ जल्दी जांच मांगते हैं। बीमारी नियंत्रित करने वाली दवाएं नुकसान रोकती हैं; केवल दर्द की दवा उनका विकल्प नहीं। सूजन की बीमारी में मेथोट्रेक्सेट आमतौर पर साप्ताहिक होती है। उसे गलती से रोज लेना जानलेवा हो सकता है। समय, फोलेट, रक्त, लिवर और गुर्दे की निगरानी स्पष्ट करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"osteoporosis","title":"Osteoporosis","subject":"Musculoskeletal","icon":"bone","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess fracture history, falls, bone density when available, glucocorticoids and other risk factors. Treatment decisions use overall fracture risk rather than bone density alone."]},{"title":"Treatment principles","text":["Exercise suited to the person, fall prevention and appropriate calcium/vitamin-D intake accompany drug therapy when indicated. Oral bisphosphonates have exact fasting, water and upright-position instructions that vary by product."]},{"title":"Safety and follow-up","text":["Check renal function, swallowing or oesophageal problems and dental concerns where relevant. Denosumab should not be delayed or stopped without a follow-on plan because rebound fracture risk matters. New severe back pain may represent a vertebral fracture."]}],"quick":["Assess fracture history, falls, bone density when available, glucocorticoids and other risk factors","Exercise suited to the person, fall prevention and appropriate calcium/vitamin-D intake accompany drug therapy when indicated","Check renal function, swallowing or oesophageal problems and dental concerns where relevant"],"date":"2026-09-18","overview":"Assess fracture history, falls, bone density when available, glucocorticoids and other risk factors.","hi":"ऑस्टियोपोरोसिस में पुराना फ्रैक्चर, गिरना, हड्डी की जांच और स्टेरॉयड का उपयोग देखें। कुल फ्रैक्चर जोखिम से निर्णय लें। व्यायाम, गिरने से बचाव और उचित कैल्शियम तथा विटामिन डी साथ जरूरी हैं। खाने वाली बिसफॉस्फोनेट की पानी, खाली पेट और सीधे बैठने की विधि समझाएं। डेनोसुमैब बिना आगे की योजना बंद या देर न करें; फ्रैक्चर जोखिम बढ़ सकता है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"msk-pain","title":"MSK Pain","subject":"Musculoskeletal","icon":"bone","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Establish location, injury mechanism, duration, swelling, neurological symptoms and functional goals. Differentiate a self-limited strain from fracture, infection or a neurological emergency."]},{"title":"Treatment principles","text":["Activity modification, appropriate movement and physical strategies may accompany topical or oral analgesia. Select an NSAID only after considering GI bleeding, kidney disease, cardiovascular risk, pregnancy and interacting medicines."]},{"title":"Safety and follow-up","text":["Do not combine multiple NSAIDs unknowingly through combination products. Red flags include severe trauma, hot swollen joint with systemic illness, progressive weakness or new bladder/bowel dysfunction with back pain. Reassess persistent symptoms."]}],"quick":["Establish location, injury mechanism, duration, swelling, neurological symptoms and functional goals","Activity modification, appropriate movement and physical strategies may accompany topical or oral analgesia","Do not combine multiple NSAIDs unknowingly through combination products"],"date":"2026-09-18","overview":"Establish location, injury mechanism, duration, swelling, neurological symptoms and functional goals.","hi":"मांसपेशी और जोड़ के दर्द में चोट, सूजन, अवधि और काम पर असर देखें। हल्की खिंचाव और फ्रैक्चर या संक्रमण अलग हैं। दवा चुनते समय पेट का रक्तस्राव, गुर्दे, हृदय, गर्भावस्था और दूसरी दवाएं देखें। अलग ब्रांड से दो एन एस ए आई डी साथ न लें। पीठ दर्द के साथ नई पेशाब या मल की समस्या और कमजोरी आपात जांच मांगती है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"systemic-lupus-erythematosus","title":"Systemic Lupus Erythematosus","subject":"Musculoskeletal","icon":"bone","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Lupus can affect skin, joints, blood, kidneys and other organs. Assess the current organ involvement, symptoms, infection risk and prescribed monitoring rather than treating it as one uniform rash disorder."]},{"title":"Treatment principles","text":["Hydroxychloroquine and immunomodulating therapies have roles determined by the disease and patient. Eye monitoring, adherence, sun protection and reproductive planning are important elements of ongoing care."]},{"title":"Safety and follow-up","text":["Infection and flare can look similar, particularly during immunosuppression. New chest pain, neurological symptoms, marked swelling or renal concerns need assessment. Do not independently increase corticosteroids whenever symptoms recur."]}],"quick":["Lupus can affect skin, joints, blood, kidneys and other organs","Hydroxychloroquine and immunomodulating therapies have roles determined by the disease and patient","Infection and flare can look similar, particularly during immunosuppression"],"date":"2026-09-18","overview":"Lupus can affect skin, joints, blood, kidneys and other organs.","hi":"लुपस त्वचा, जोड़, रक्त, गुर्दे और अन्य अंगों को प्रभावित कर सकता है। वर्तमान अंग संबंधी समस्या और संक्रमण जोखिम देखें। हाइड्रॉक्सीक्लोरोक्वीन में आंख की निगरानी, नियमित उपयोग और धूप से बचाव महत्वपूर्ण हैं। संक्रमण और फ्लेयर एक जैसे दिख सकते हैं। नया छाती दर्द, न्यूरोलॉजिकल लक्षण या सूजन में जांच कराएं। हर बार अपनी तरफ से स्टेरॉयड न बढ़ाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"polymyalgia-rheumatica-giant-cell-arteritis","title":"Polymyalgia Rheumatica & Giant Cell Arteritis","subject":"Musculoskeletal","icon":"bone","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["PMR commonly causes shoulder and hip-girdle pain and stiffness in older adults. New headache, scalp tenderness, jaw claudication or visual symptoms raises concern for associated giant cell arteritis."]},{"title":"Treatment principles","text":["Suspected giant cell arteritis requires urgent medical evaluation and time-sensitive treatment to protect vision. PMR treatment and tapering require follow-up of symptoms and adverse effects; the two conditions need different levels of urgency."]},{"title":"Safety and follow-up","text":["Do not delay referral for a routine analgesic trial when vision is threatened. Long-term corticosteroid care includes bone, glucose, blood-pressure and infection-risk review. Relapse assessment should consider alternative diagnoses."]}],"quick":["PMR commonly causes shoulder and hip-girdle pain and stiffness in older adults","Suspected giant cell arteritis requires urgent medical evaluation and time-sensitive treatment to protect vision","Do not delay referral for a routine analgesic trial when vision is threatened"],"date":"2026-09-18","overview":"PMR commonly causes shoulder and hip-girdle pain and stiffness in older adults.","hi":"पॉलीमायल्जिया में बुजुर्गों के कंधे और कूल्हे में दर्द तथा अकड़न होती है। नया सिरदर्द, सिर की त्वचा में दर्द, चबाने पर जबड़े में दर्द या नजर बदलना जाइंट सेल आर्टराइटिस का संकेत हो सकता है। दृष्टि बचाने के लिए तत्काल चिकित्सा जांच जरूरी है। केवल दर्द की दवा देकर इंतजार न करें। लंबे स्टेरॉयड में हड्डी, शुगर, रक्तचाप और संक्रमण की निगरानी करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"osteoarthritis","title":"Osteoarthritis","subject":"Musculoskeletal","icon":"bone","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess activity-related joint pain, stiffness, mobility and daily-life goals. A hot joint, systemic illness or a rapid unusual change should prompt consideration of another diagnosis."]},{"title":"Treatment principles","text":["Exercise, strengthening and weight-management support when relevant are central. Topical NSAIDs can be useful for selected superficial joints; oral therapy requires a GI, renal and cardiovascular risk assessment."]},{"title":"Safety and follow-up","text":["Imaging changes and pain severity do not always match. Avoid escalating medicines without reviewing benefit and function. Injections and surgery are individualized options; persistent major disability merits referral and shared decision-making."]}],"quick":["Assess activity-related joint pain, stiffness, mobility and daily-life goals","Exercise, strengthening and weight-management support when relevant are central","Imaging changes and pain severity do not always match"],"date":"2026-09-18","overview":"Assess activity-related joint pain, stiffness, mobility and daily-life goals.","hi":"ऑस्टियोआर्थराइटिस में गतिविधि से दर्द, अकड़न और रोजमर्रा की क्षमता देखें। व्यायाम, ताकत बढ़ाना और जरूरत पर वजन प्रबंधन मुख्य भाग हैं। कुछ जोड़ों में बाहरी एन एस ए आई डी मदद कर सकती है। खाने वाली दवा से पहले पेट, गुर्दे और हृदय जोखिम देखें। एक्स रे और दर्द हमेशा समान नहीं होते। बिना लाभ देखे दवा बढ़ाते न जाएं; कार्यक्षमता का लक्ष्य तय करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"fibromyalgia","title":"Fibromyalgia","subject":"Musculoskeletal","icon":"bone","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Widespread pain with fatigue, sleep and cognitive symptoms requires a positive clinical assessment and consideration of alternatives. The symptoms are real even when routine inflammatory tests are normal."]},{"title":"Treatment principles","text":["Education, individualized physical activity, sleep strategies and psychological support form part of care. Selected medicines target pain and associated symptoms; benefit should be judged against adverse effects and function."]},{"title":"Safety and follow-up","text":["Avoid assuming that stronger opioid treatment is the default next step. Set gradual achievable goals and review sedating combinations. New focal deficits, inflammatory signs or a significant change in symptoms needs reassessment."]}],"quick":["Widespread pain with fatigue, sleep and cognitive symptoms requires a positive clinical assessment and consideration of alternatives","Education, individualized physical activity, sleep strategies and psychological support form part of care","Avoid assuming that stronger opioid treatment is the default next step"],"date":"2026-09-18","overview":"Widespread pain with fatigue, sleep and cognitive symptoms requires a positive clinical assessment and consideration of alternatives.","hi":"फाइब्रोमायल्जिया में पूरे शरीर का दर्द, थकान, नींद और ध्यान की समस्या हो सकती है। सामान्य सूजन जांच होने पर भी लक्षण वास्तविक हैं। समझाना, व्यक्ति अनुसार गतिविधि, नींद और मानसिक सहायता महत्वपूर्ण हैं। दवा का लाभ कार्यक्षमता और दुष्प्रभाव से तौलें। अधिक शक्तिशाली ओपिओइड को स्वतः अगला कदम न मानें। नई अलग कमजोरी या सूजन में दोबारा जांच करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"diabetes","title":"Diabetes","subject":"Endocrine & Metabolic","icon":"droplets","status":"available","minutes":3,"competency":"Clinical Care","sources":[["Diabetes Canada guidelines","https://www.diabetes.ca/for-professionals/full-guidelines"]],"sections":[{"title":"Build the picture","text":["Clarify diabetes type, current therapy, glucose pattern, individualized targets, hypoglycemia history and the person’s daily routine. Review kidney function, comorbidities, access and device use.","Do not treat a single glucose reading as the whole assessment. Acute illness, symptoms and the ability to eat or drink may change the urgency and plan."]},{"title":"Support safe use","text":["Teach relevant monitoring, recognition of hypoglycemia, device technique and a patient-specific sick-day plan using current guidance. Confirm understanding through teach-back.","Choose and reassess treatment with current Canadian recommendations, individualized goals, risks, preferences and prescriber collaboration."]}],"quick":["Individualize targets and treatment","Assess hypoglycemia and technique","Use an agreed sick-day plan"],"date":"2026-09-18","overview":"Diabetes care considers glucose, treatment burden and cardiovascular, kidney and other risks.","hi":"मधुमेह में शुगर के साथ हृदय, गुर्दे, कम शुगर का जोखिम और इलाज का बोझ देखें। मरीज के लक्ष्य और स्वयं निगरानी की क्षमता पूछें। दवा का चुनाव केवल एच बी ए वन सी से नहीं होता। कम शुगर की पहचान और व्यक्ति की उपचार योजना समझाएं। बीमारी के दिनों में पानी, जांच और दवाओं की स्पष्ट योजना चाहिए। मतली, उल्टी, पेट दर्द या तेज सांस में कीटोएसिडोसिस की संभावना पर जांच करें; कुछ दवाओं में शुगर बहुत ऊंची न होने पर भी यह हो सकता है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"hypothyroidism","title":"Hypothyroidism","subject":"Endocrine & Metabolic","icon":"droplets","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess symptoms alongside thyroid results, diagnosis, adherence and interfering medicines. Fatigue alone is nonspecific; distinguish primary thyroid disease from other causes and special situations."]},{"title":"Treatment principles","text":["Levothyroxine is taken consistently according to product instructions. Food, calcium, iron and other agents can affect absorption. Dose assessment uses the appropriate follow-up interval because thyroid hormone and TSH do not stabilize immediately."]},{"title":"Safety and follow-up","text":["Avoid rapid repeated dose changes based on a few days of symptoms. Pregnancy, older age and cardiac disease require tailored review. Excess replacement may cause palpitations and contribute to atrial fibrillation or bone loss."]}],"quick":["Assess symptoms alongside thyroid results, diagnosis, adherence and interfering medicines","Levothyroxine is taken consistently according to product instructions","Avoid rapid repeated dose changes based on a few days of symptoms"],"date":"2026-09-18","overview":"Assess symptoms alongside thyroid results, diagnosis, adherence and interfering medicines.","hi":"हाइपोथायरॉइड में लक्षण के साथ सही जांच और दवा पालन देखें। केवल थकान से निदान न करें। लेवोथायरॉक्सिन एक जैसी विधि से लें; भोजन, कैल्शियम और आयरन अवशोषण बदल सकते हैं। जांच को स्थिर होने में समय लगता है, इसलिए कुछ दिनों में बार-बार खुराक न बदलें। गर्भावस्था, बुजुर्ग और हृदय रोग में विशेष समीक्षा करें। ज्यादा दवा से धड़कन और हड्डी का जोखिम बढ़ सकता है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"hyperthyroidism","title":"Hyperthyroidism","subject":"Endocrine & Metabolic","icon":"droplets","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess symptoms, thyroid results, likely cause, pulse and systemic illness. Thyrotoxicosis has multiple causes; antithyroid medicines do not suit every cause of excess thyroid hormone."]},{"title":"Treatment principles","text":["Treatment may involve symptom control, antithyroid medication, radioactive iodine or surgery depending on the diagnosis and patient. Explain the exact monitoring plan and relevant pregnancy considerations."]},{"title":"Safety and follow-up","text":["Fever or sore throat during thionamide therapy requires urgent assessment for possible agranulocytosis and prompt prescriber instructions. Severe fever, marked tachycardia, agitation or heart failure may signal thyroid storm and requires emergency care."]}],"quick":["Assess symptoms, thyroid results, likely cause, pulse and systemic illness","Treatment may involve symptom control, antithyroid medication, radioactive iodine or surgery depending on the diagnosis and patient","Fever or sore throat during thionamide therapy requires urgent assessment for possible agranulocytosis and prompt prescriber instructions"],"date":"2026-09-18","overview":"Assess symptoms, thyroid results, likely cause, pulse and systemic illness.","hi":"हाइपरथायरॉइड में कारण, धड़कन और जांच देखें। हर कारण में एंटीथायरॉइड दवा काम नहीं करती। उपचार में दवा, रेडियोएक्टिव आयोडीन या ऑपरेशन हो सकता है। थायोनामाइड लेते समय बुखार या गले में दर्द पर गंभीर श्वेत रक्त कोशिका कमी की तुरंत जांच जरूरी है। बहुत तेज बुखार, धड़कन और भ्रम थायरॉइड स्टॉर्म का संकेत हो सकते हैं। गर्भावस्था की स्थिति जरूर पूछें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"allergic-rhinitis","title":"Allergic Rhinitis","subject":"Respiratory","icon":"wind","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess sneezing, itching, watery discharge, congestion, triggers and effect on sleep. Unilateral persistent symptoms, recurrent bleeding or unusual discharge may suggest another cause."]},{"title":"Treatment principles","text":["Allergen reduction, saline and an appropriate intranasal corticosteroid or antihistamine can help. Correct spray technique directs medication away from the septum and requires regular use for controller benefit."]},{"title":"Safety and follow-up","text":["Topical nasal decongestants can cause rebound congestion with prolonged use. Oral decongestants may worsen blood pressure, insomnia or urinary retention. Review asthma symptoms and avoid routinely choosing sedating antihistamines for daytime use."]}],"quick":["Assess sneezing, itching, watery discharge, congestion, triggers and effect on sleep","Allergen reduction, saline and an appropriate intranasal corticosteroid or antihistamine can help","Topical nasal decongestants can cause rebound congestion with prolonged use"],"date":"2026-09-18","overview":"Assess sneezing, itching, watery discharge, congestion, triggers and effect on sleep.","hi":"एलर्जिक राइनाइटिस में छींक, खुजली, पानी और बंद नाक के ट्रिगर पूछें। नाक की स्टेरॉयड स्प्रे को बीच की दीवार से दूर दिशा में लगाएं और नियमित उपयोग समझाएं। नाक खोलने वाली कुछ स्प्रे लंबे उपयोग से उल्टा बंद नाक बढ़ाती हैं। खाने वाले डीकंजेस्टेंट रक्तचाप, नींद या पेशाब की समस्या बढ़ा सकते हैं। एक तरफ लगातार लक्षण या खून हो तो जांच करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"asthma","title":"Asthma","subject":"Respiratory","icon":"wind","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Thoracic Society: guideline library","https://cts-sct.ca/guideline-library/"]],"sections":[{"title":"Assessment","text":["Assess daytime and night symptoms, reliever use, activity limits, exacerbations, inhaler technique and adherence. Confirm that the diagnosis and objective testing have been appropriately addressed."]},{"title":"Treatment principles","text":["An inhaled corticosteroid-containing plan addresses airway inflammation. Reliever and controller roles depend on the prescribed regimen; not every combination inhaler is suitable as a reliever. Provide a personalized written action plan."]},{"title":"Safety and follow-up","text":["Severe breathlessness, inability to speak normally, exhaustion or poor response to rescue treatment needs emergency care. Before stepping up, review technique and adherence. Teach device-specific use and mouth rinsing after inhaled corticosteroid doses."]}],"quick":["Assess daytime and night symptoms, reliever use, activity limits, exacerbations, inhaler technique and adherence","An inhaled corticosteroid-containing plan addresses airway inflammation","Severe breathlessness, inability to speak normally, exhaustion or poor response to rescue treatment needs emergency care"],"date":"2026-09-18","overview":"Assess daytime and night symptoms, reliever use, activity limits, exacerbations, inhaler technique and adherence.","hi":"अस्थमा में दिन और रात के लक्षण, रिलीवर उपयोग, अटैक और इनहेलर की विधि देखें। इनहेल्ड स्टेरॉयड वाली योजना सूजन नियंत्रित करती है। हर कॉम्बिनेशन इनहेलर रिलीवर नहीं होता। व्यक्तिगत लिखित एक्शन प्लान दें। बोलने में कठिनाई वाली सांस, थकावट या रेस्क्यू दवा से लाभ न होना आपातस्थिति है। दवा बढ़ाने से पहले तकनीक और नियमित उपयोग देखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"copd","title":"COPD","subject":"Respiratory","icon":"wind","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Thoracic Society: guideline library","https://cts-sct.ca/guideline-library/"]],"sections":[{"title":"Assessment","text":["Assess smoking or exposure history, symptoms, exacerbations, spirometry and comorbidities. Persistent airflow obstruction supports the diagnosis; distinguish an acute exacerbation from pneumonia, heart failure or PE."]},{"title":"Treatment principles","text":["Smoking cessation, vaccines, pulmonary rehabilitation and inhaled bronchodilators are central components. Inhaled corticosteroids are appropriate for selected patients rather than everyone, considering exacerbations, eosinophils and pneumonia risk."]},{"title":"Safety and follow-up","text":["Review inhaler suitability and technique before escalating therapy. Worsening breathlessness, confusion or low oxygen requires assessment. Oxygen and exacerbation medicine plans are individualized; antibiotics are not automatic for every increase in symptoms."]}],"quick":["Assess smoking or exposure history, symptoms, exacerbations, spirometry and comorbidities","Smoking cessation, vaccines, pulmonary rehabilitation and inhaled bronchodilators are central components","Review inhaler suitability and technique before escalating therapy"],"date":"2026-09-18","overview":"Assess smoking or exposure history, symptoms, exacerbations, spirometry and comorbidities.","hi":"सी ओ पी डी में धूम्रपान, एक्सपोजर, सांस की जांच और पुराने अटैक देखें। धूम्रपान छोड़ना, टीके, पुनर्वास और ब्रोंकोडायलेटर महत्वपूर्ण हैं। इनहेल्ड स्टेरॉयड हर मरीज को नहीं चाहिए; लाभ और निमोनिया जोखिम तौलें। इनहेलर तकनीक जांचें। अचानक सांस बिगड़ना दिल की बीमारी या निमोनिया भी हो सकता है। भ्रम या कम ऑक्सीजन में तुरंत जांच करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"smoking-cessation","title":"Smoking Cessation","subject":"Minor Ailments","icon":"cross","status":"available","minutes":2,"competency":"Leadership & Stewardship","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Ask permission to discuss tobacco use, dependence, previous attempts, triggers and the person's goals. Relapse is information for adapting support, not evidence of failure."]},{"title":"Treatment principles","text":["Behavioural support and appropriate pharmacotherapy can improve success. Nicotine replacement, varenicline and bupropion have different instructions and precautions; select around history, contraindications and preferences."]},{"title":"Safety and follow-up","text":["Stopping smoke exposure can change levels of some medicines because combustion products affect enzymes; nicotine itself is not the same mechanism. Arrange follow-up for withdrawal, mood, adverse effects and dose review of affected medicines."]}],"quick":["Ask permission to discuss tobacco use, dependence, previous attempts, triggers and the person's goals","Behavioural support and appropriate pharmacotherapy can improve success","Stopping smoke exposure can change levels of some medicines because combustion products affect enzymes; nicotine itself is not the same mechanism"],"date":"2026-09-18","overview":"Ask permission to discuss tobacco use, dependence, previous attempts, triggers and the person's goals.","hi":"धूम्रपान पर चर्चा की अनुमति लें और पुराने प्रयास, ट्रिगर तथा लक्ष्य पूछें। दोबारा शुरू होना असफल व्यक्ति होने का प्रमाण नहीं; योजना बदलने की जानकारी है। व्यवहार सहायता और निकोटीन रिप्लेसमेंट, वरेनिक्लिन या बुप्रोपियन उपयुक्त मरीज में मदद कर सकते हैं। धुआं बंद होने से कुछ दवाओं का स्तर बदलता है; इसका कारण केवल निकोटीन नहीं। फॉलो अप और संबंधित दवा समीक्षा करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pediatric-health","title":"Pediatric Health","subject":"Minor Ailments","icon":"cross","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Canadian Paediatric Society: current position statements","https://cps.ca/en/documents/statements-by-date"]],"sections":[{"title":"Assessment","text":["Use age, current weight in kilograms, development, hydration and caregiver observations. Infants are not small adults; fever, feeding changes and lethargy can have different implications by age."]},{"title":"Treatment principles","text":["Check whether self-care is appropriate before recommending a product. Use age-appropriate formulations and an oral syringe for measured liquids. Explain the active ingredients to prevent duplication across cough, cold and fever products."]},{"title":"Safety and follow-up","text":["Poor responsiveness, breathing difficulty, significant dehydration or fever in a young infant requires prompt medical assessment. Never estimate weight from appearance or use a household spoon as a dosing device. Give clear return precautions to the caregiver."]}],"quick":["Use age, current weight in kilograms, development, hydration and caregiver observations","Check whether self-care is appropriate before recommending a product","Poor responsiveness, breathing difficulty, significant dehydration or fever in a young infant requires prompt medical assessment"],"date":"2026-09-18","overview":"Use age, current weight in kilograms, development, hydration and caregiver observations.","hi":"बच्चों में उम्र, आज का वजन किलोग्राम में, पानी की स्थिति और व्यवहार देखें। छोटे बच्चे केवल छोटे वयस्क नहीं हैं। दवा का सही रूप और ओरल सिरिंज इस्तेमाल करें। कई सर्दी और बुखार उत्पाद में एक ही घटक दोहर सकता है। बहुत सुस्ती, सांस में परेशानी या छोटे शिशु का बुखार जल्दी जांच मांगता है। अनुमान का वजन और घर का चम्मच इस्तेमाल न करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"travel-medicine","title":"Travel Medicine","subject":"Minor Ailments","icon":"cross","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Public Health Agency of Canada: Canadian Immunization Guide","https://www.canada.ca/en/public-health/services/canadian-immunization-guide.html"]],"sections":[{"title":"Assessment","text":["Assess destination, itinerary, season, activities, accommodation, duration, health conditions, pregnancy and medicines. Advice depends on the actual journey, not just the country name."]},{"title":"Treatment principles","text":["Review routine and travel vaccines, malaria prevention where relevant, food and water safety, bite avoidance and medicine supply. Some preventive measures need advance planning; verify current destination-specific public-health guidance."]},{"title":"Safety and follow-up","text":["Fever after travel to a malaria-risk area needs urgent assessment even if prophylaxis was taken. Carry medicines in appropriate labelled packaging and check destination restrictions. Avoid giving one antibiotic or malaria regimen to every traveller."]}],"quick":["Assess destination, itinerary, season, activities, accommodation, duration, health conditions, pregnancy and medicines","Review routine and travel vaccines, malaria prevention where relevant, food and water safety, bite avoidance and medicine supply","Fever after travel to a malaria-risk area needs urgent assessment even if prophylaxis was taken"],"date":"2026-09-18","overview":"Assess destination, itinerary, season, activities, accommodation, duration, health conditions, pregnancy and medicines.","hi":"यात्रा की सलाह में देश के साथ रास्ता, मौसम, गतिविधि, अवधि और स्वास्थ्य स्थिति पूछें। नियमित और यात्रा टीके, जरूरत पर मलेरिया बचाव, मच्छर से सुरक्षा और दवा की आपूर्ति देखें। वर्तमान गंतव्य निर्देश जांचें। मलेरिया क्षेत्र से लौटने पर बुखार हो तो तुरंत जांच कराएं, बचाव की दवा लेने पर भी। हर यात्री को एक ही एंटीबायोटिक या मलेरिया दवा न दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"eye-health","title":"Eye Health","subject":"Ophthalmology","icon":"eye","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Assess pain, vision change, photophobia, trauma, contact-lens use and unilateral versus bilateral symptoms. A red eye can represent anything from irritation to a sight-threatening condition."]},{"title":"Treatment principles","text":["Simple lubrication or allergy treatment is considered only after excluding important red flags. Teach hand hygiene, avoiding bottle-tip contact and appropriate spacing between different eye drops."]},{"title":"Safety and follow-up","text":["Painful red eye with reduced vision, chemical exposure or contact-lens-associated pain needs urgent assessment. Do not recommend leftover steroid eye drops; they can worsen certain infections and delay diagnosis. Follow immediate irrigation guidance for chemical injury while arranging care."]}],"quick":["Assess pain, vision change, photophobia, trauma, contact-lens use and unilateral versus bilateral symptoms","Simple lubrication or allergy treatment is considered only after excluding important red flags","Painful red eye with reduced vision, chemical exposure or contact-lens-associated pain needs urgent assessment"],"date":"2026-09-18","overview":"Assess pain, vision change, photophobia, trauma, contact-lens use and unilateral versus bilateral symptoms.","hi":"आंख में दर्द, नजर बदलना, रोशनी से परेशानी, चोट और कॉन्टैक्ट लेंस पूछें। हर लाल आंख साधारण एलर्जी नहीं है। गंभीर संकेत न हों तब उपयुक्त लुब्रिकेंट या एलर्जी उपचार चुनें। बोतल का सिरा आंख से न छुएं। दर्द के साथ कम नजर, रसायन या लेंस से दर्द में जल्दी जांच करें। पुरानी स्टेरॉयड ड्रॉप अपनी तरफ से न दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"cataract-surgery-post-operative-care","title":"Cataract Surgery Post-Operative Care","subject":"Ophthalmology","icon":"eye","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Confirm the operated eye, date, surgeon's drop schedule and current symptoms. Reconcile multiple drops to prevent wrong-eye, duplicate or incorrect-duration use."]},{"title":"Treatment principles","text":["Explain the exact antibiotic, anti-inflammatory or other prescribed regimen and demonstrate clean drop technique. A written schedule can separate products and taper instructions; do not substitute a generic schedule for the surgeon's plan."]},{"title":"Safety and follow-up","text":["Increasing pain, worsening vision, significant redness or new flashes/floaters after surgery needs prompt ophthalmic assessment. Check that the patient can administer drops and obtain help if needed. Do not stop a prescribed taper solely because the eye feels better."]}],"quick":["Confirm the operated eye, date, surgeon's drop schedule and current symptoms","Explain the exact antibiotic, anti-inflammatory or other prescribed regimen and demonstrate clean drop technique","Increasing pain, worsening vision, significant redness or new flashes/floaters after surgery needs prompt ophthalmic assessment"],"date":"2026-09-18","overview":"Confirm the operated eye, date, surgeon's drop schedule and current symptoms.","hi":"मोतियाबिंद ऑपरेशन के बाद सही आंख, तारीख और सर्जन की ड्रॉप योजना पुष्टि करें। कई बूंदों में गलत आंख या अवधि की गलती हो सकती है। लिखित समय और स्टेरॉयड घटाने की योजना दें। आंख में बढ़ता दर्द, नजर गिरना, अधिक लाली या नई चमक और फ्लोटर होने पर तुरंत आंख की जांच करें। मरीज बूंद डाल सकता है या सहायता चाहिए, यह देखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"glaucoma","title":"Glaucoma","subject":"Ophthalmology","icon":"eye","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Clarify the glaucoma type, target pressure, eye-drop regimen and adherence. Chronic open-angle disease may have few symptoms even while damage progresses."]},{"title":"Treatment principles","text":["Correct regular drop use and ophthalmic monitoring protect vision. Review systemic effects of topical agents: beta-blocker drops can affect pulse and breathing. Teach punctal occlusion when appropriate to reduce systemic exposure."]},{"title":"Safety and follow-up","text":["A painful red eye with halos, headache, nausea or reduced vision can indicate acute angle closure and needs emergency assessment. Feeling well is not a reason to stop chronic drops. Verify eye, strength and storage instructions at each transition."]}],"quick":["Clarify the glaucoma type, target pressure, eye-drop regimen and adherence","Correct regular drop use and ophthalmic monitoring protect vision","A painful red eye with halos, headache, nausea or reduced vision can indicate acute angle closure and needs emergency assessment"],"date":"2026-09-18","overview":"Clarify the glaucoma type, target pressure, eye-drop regimen and adherence.","hi":"ग्लूकोमा में बीमारी का प्रकार, ड्रॉप और नियमित उपयोग देखें। लक्षण न होने पर भी नुकसान बढ़ सकता है। बीटा ब्लॉकर आंख की बूंद नाड़ी और सांस पर असर डाल सकती है। सही तकनीक और जरूरत पर आंसू की नली दबाने की विधि सिखाएं। दर्द वाली लाल आंख, रोशनी के चारों ओर घेरे, मतली और नजर घटना एक्यूट एंगल क्लोजर हो सकता है और आपात जांच चाहिए।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"oncology-general","title":"Oncology (general)","subject":"Oncology","icon":"ribbon","status":"available","minutes":2,"competency":"Clinical Care","sources":[["BC Cancer: supportive care resources","https://www.bccancer.bc.ca/pharmacy-site/Pages/Supportive-Care-Websites.aspx"]],"sections":[{"title":"Assessment","text":["Confirm the cancer regimen, cycle, intent, supportive medicines, organ function and current symptoms. Oral anticancer therapy is not inherently less hazardous than intravenous therapy."]},{"title":"Treatment principles","text":["Treatment schedules, interaction checks, safe handling and adherence are product specific. Reconcile nonprescription and herbal products and teach which symptoms must be reported immediately, using the oncology team's written plan."]},{"title":"Safety and follow-up","text":["Fever during possible neutropenia requires urgent oncology or emergency assessment. Do not advise simply treating the fever at home. Severe diarrhoea, dehydration, bleeding or new breathing symptoms also need prompt review. Avoid live-vaccine assumptions during immunosuppression."]}],"quick":["Confirm the cancer regimen, cycle, intent, supportive medicines, organ function and current symptoms","Treatment schedules, interaction checks, safe handling and adherence are product specific","Fever during possible neutropenia requires urgent oncology or emergency assessment"],"date":"2026-09-18","overview":"Confirm the cancer regimen, cycle, intent, supportive medicines, organ function and current symptoms.","hi":"कैंसर के इलाज में दवा, चक्र, उद्देश्य, सहायक दवाएं और अंगों की स्थिति पुष्टि करें। खाने वाली कैंसर दवा भी गंभीर जोखिम रख सकती है। हर्बल और बिना पर्चे की दवाएं जरूर पूछें। कम न्यूट्रोफिल की संभावना में बुखार तत्काल ऑन्कोलॉजी या आपात जांच मांगता है; केवल बुखार की गोली देकर न रुकें। सही भंडारण, संभालने की विधि और संपर्क योजना लिखित दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"chemotherapy-induced-nausea-and-vomiting","title":"Chemotherapy-Induced Nausea and Vomiting","subject":"Oncology","icon":"ribbon","status":"available","minutes":2,"competency":"Clinical Care","sources":[["BC Cancer: supportive care resources","https://www.bccancer.bc.ca/pharmacy-site/Pages/Supportive-Care-Websites.aspx"]],"sections":[{"title":"Assessment","text":["Assess the regimen's emetogenic risk, prior response and acute versus delayed symptoms. Prevention before treatment differs from rescue management once symptoms occur."]},{"title":"Treatment principles","text":["Antiemetic combinations may include a 5-HT3 antagonist, NK1 antagonist, dexamethasone and other agents according to the oncology protocol. Verify each day's schedule and interactions rather than supplying only an as-needed label for a preventive regimen."]},{"title":"Safety and follow-up","text":["Monitor dehydration, constipation, sedation, glucose and QT-related risks as relevant. Persistent vomiting, inability to retain fluids or fever needs contact with the oncology team. Review the plan before the next cycle if control was poor."]}],"quick":["Assess the regimen's emetogenic risk, prior response and acute versus delayed symptoms","Antiemetic combinations may include a 5-HT3 antagonist, NK1 antagonist, dexamethasone and other agents according to the oncology protocol","Monitor dehydration, constipation, sedation, glucose and QT-related risks as relevant"],"date":"2026-09-18","overview":"Assess the regimen's emetogenic risk, prior response and acute versus delayed symptoms.","hi":"कीमो से मतली में दवा के जोखिम और तत्काल तथा देर से होने वाले लक्षण अलग देखें। बचाव की दवा कीमो से पहले योजना अनुसार दी जाती है; केवल जरूरत पर लेने का लेबल पर्याप्त नहीं हो सकता। अलग दिनों का शेड्यूल समझाएं। कब्ज, नींद, शुगर और हृदय की लय के जोखिम देखें। पानी न रुकना या बुखार हो तो ऑन्कोलॉजी टीम से तुरंत संपर्क करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"electrolyte-disorders","title":"Electrolyte Disorders","subject":"Anemias, Electrolytes & Nutrition","icon":"flask-conical","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Interpret sodium, potassium, calcium and magnesium with symptoms, kidney function, fluid status and the cause. A haemolysed specimen can affect potassium, but a dangerous result cannot simply be dismissed."]},{"title":"Treatment principles","text":["Review contributing medicines and confirm the appropriate urgency. Replacement or correction depends on severity, chronicity, route and monitoring; concentration errors with intravenous electrolytes are high risk."]},{"title":"Safety and follow-up","text":["Marked weakness, arrhythmia, seizures or altered consciousness requires urgent assessment. Rapid correction of some chronic abnormalities can cause serious harm. Never treat an isolated number with an unmonitored universal replacement formula."]}],"quick":["Interpret sodium, potassium, calcium and magnesium with symptoms, kidney function, fluid status and the cause","Review contributing medicines and confirm the appropriate urgency","Marked weakness, arrhythmia, seizures or altered consciousness requires urgent assessment"],"date":"2026-09-18","overview":"Interpret sodium, potassium, calcium and magnesium with symptoms, kidney function, fluid status and the cause.","hi":"इलेक्ट्रोलाइट जांच को लक्षण, गुर्दे और पानी की स्थिति के साथ समझें। नमूना खराब होने से पोटैशियम बदल सकता है, लेकिन खतरनाक परिणाम यूं ही न छोड़ें। सुधार की गति और मार्ग गंभीरता तथा बीमारी की अवधि पर निर्भर हैं। दौरे, अनियमित धड़कन, कमजोरी या भ्रम में तुरंत जांच करें। कुछ पुराने असंतुलन तेजी से ठीक करना नुकसानदेह है। बिना निगरानी एक जैसा फार्मूला न लगाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"total-parenteral-nutrition","title":"Total Parenteral Nutrition","subject":"Anemias, Electrolytes & Nutrition","icon":"flask-conical","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Confirm the indication, access route, nutrition assessment, fluid needs and available enteral options. PN is a complex prescription involving energy, protein, electrolytes, micronutrients and compatibility."]},{"title":"Treatment principles","text":["Check the complete formulation, infusion instructions and monitoring with the nutrition team. Glucose, electrolytes, triglycerides, liver tests and fluid balance may guide adjustment. Calcium–phosphate compatibility and aseptic preparation are critical."]},{"title":"Safety and follow-up","text":["Refeeding risk is important in malnourished patients. Do not add a medicine to PN without verified compatibility and authorization. Line infection, abrupt glucose changes or significant electrolyte abnormalities require prompt review."]}],"quick":["Confirm the indication, access route, nutrition assessment, fluid needs and available enteral options","Check the complete formulation, infusion instructions and monitoring with the nutrition team","Refeeding risk is important in malnourished patients"],"date":"2026-09-18","overview":"Confirm the indication, access route, nutrition assessment, fluid needs and available enteral options.","hi":"टोटल पैरेंट्रल न्यूट्रिशन में जरूरत, नस का मार्ग, ऊर्जा, प्रोटीन, पानी और इलेक्ट्रोलाइट की पूरी योजना देखें। ग्लूकोज, ट्राइग्लिसराइड, लिवर और तरल संतुलन की निगरानी होती है। कैल्शियम और फॉस्फेट की अनुकूलता तथा निर्जीव तैयारी महत्वपूर्ण है। कुपोषित मरीज में रीफीडिंग का जोखिम देखें। बिना सत्यापित अनुकूलता और अनुमति पी एन में दूसरी दवा न मिलाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"common-anemias","title":"Common Anemias","subject":"Anemias, Electrolytes & Nutrition","icon":"flask-conical","status":"available","minutes":2,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Use blood count indices, reticulocytes and relevant iron, B12 or folate results to distinguish causes. Anaemia is a finding that requires an explanation, not a diagnosis of iron deficiency by itself."]},{"title":"Treatment principles","text":["Iron treatment needs a cause assessment, tolerable regimen and follow-up of response. B12 deficiency may cause neurological symptoms; folate alone can improve blood findings while missing the underlying B12 problem."]},{"title":"Safety and follow-up","text":["Severe symptoms, active bleeding or rapid deterioration needs urgent assessment. Review iron interactions, gastrointestinal adverse effects and safe storage away from children. Failure to respond should trigger review of adherence, absorption and the diagnosis."]}],"quick":["Use blood count indices, reticulocytes and relevant iron, B12 or folate results to distinguish causes","Iron treatment needs a cause assessment, tolerable regimen and follow-up of response","Severe symptoms, active bleeding or rapid deterioration needs urgent assessment"],"date":"2026-09-18","overview":"Use blood count indices, reticulocytes and relevant iron, B12 or folate results to distinguish causes.","hi":"एनीमिया में रक्त कोशिकाओं के आकार, आयरन, बी बारह और फोलेट की जानकारी देखें। हर एनीमिया आयरन की कमी नहीं है। आयरन देने के साथ कमी का कारण खोजें और प्रतिक्रिया देखें। बी बारह की कमी नसों को प्रभावित कर सकती है; केवल फोलेट देने से मूल समस्या छिप सकती है। सक्रिय रक्तस्राव या गंभीर कमजोरी में जल्दी जांच करें। आयरन बच्चों से सुरक्षित दूर रखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"acute-kidney-injury","title":"Acute Kidney Injury","subject":"Kidney Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"]],"sections":[{"title":"Assessment","text":["Assess the creatinine trend, urine output, hydration, recent illness, obstruction risk and nephrotoxic exposures. Creatinine-based estimates are less reliable when kidney function is changing rapidly."]},{"title":"Treatment principles","text":["Management identifies and treats the cause while reviewing medicines, fluid status and monitoring. Temporary medicine changes need a documented individualized plan including reassessment and restarting when appropriate."]},{"title":"Safety and follow-up","text":["Severe hyperkalaemia, pulmonary oedema, marked oliguria or systemic illness needs urgent care. Do not apply a stable chronic-kidney dose table mechanically to rapidly evolving AKI. Avoid attributing every creatinine rise to dehydration."]}],"quick":["Assess the creatinine trend, urine output, hydration, recent illness, obstruction risk and nephrotoxic exposures","Management identifies and treats the cause while reviewing medicines, fluid status and monitoring","Severe hyperkalaemia, pulmonary oedema, marked oliguria or systemic illness needs urgent care"],"date":"2026-09-18","overview":"Assess the creatinine trend, urine output, hydration, recent illness, obstruction risk and nephrotoxic exposures.","hi":"एक्यूट किडनी इंजरी में क्रिएटिनिन का बदलाव, पेशाब, पानी की स्थिति और गुर्दे को नुकसान देने वाली दवाएं देखें। तेजी से बदलती कार्यक्षमता में सामान्य अनुमान कम भरोसेमंद होते हैं। कारण का इलाज और दवा समीक्षा करें। दवा रोकने पर दोबारा शुरू करने की योजना भी लिखें। बहुत कम पेशाब, फेफड़े में पानी या गंभीर पोटैशियम बढ़ना तत्काल देखभाल मांगता है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"chronic-kidney-disease","title":"Chronic Kidney Disease","subject":"Kidney Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"],["KDIGO: CKD evaluation and management","https://kdigo.org/guidelines/ckd-evaluation-and-management/"]],"sections":[{"title":"Assessment","text":["CKD assessment uses persistent kidney abnormalities, filtration and albuminuria, not a single abnormal creatinine. Review the cause, progression, cardiovascular risk and medicine exposure."]},{"title":"Treatment principles","text":["Care includes appropriate blood-pressure, diabetes and kidney-protective treatment, dose review and avoidance of preventable harm. Monitoring and referral depend on stage, albuminuria, trajectory and complications."]},{"title":"Safety and follow-up","text":["Check whether a drug recommendation uses eGFR or creatinine clearance and its units. Avoid unreviewed NSAIDs, supplements and high-risk electrolyte products. New rapid deterioration is not automatically routine CKD progression."]}],"quick":["CKD assessment uses persistent kidney abnormalities, filtration and albuminuria, not a single abnormal creatinine","Care includes appropriate blood-pressure, diabetes and kidney-protective treatment, dose review and avoidance of preventable harm","Check whether a drug recommendation uses eGFR or creatinine clearance and its units"],"date":"2026-09-18","overview":"CKD assessment uses persistent kidney abnormalities, filtration and albuminuria, not a single abnormal creatinine.","hi":"क्रॉनिक किडनी डिजीज में लंबे समय की असामान्यता, फिल्ट्रेशन और पेशाब का एल्बुमिन देखें। एक असामान्य क्रिएटिनिन से अकेले निर्णय न करें। रक्तचाप, मधुमेह, गुर्दे की सुरक्षा और सही दवा मात्रा महत्वपूर्ण हैं। खुराक के संदर्भ में ई जी एफ आर या क्रिएटिनिन क्लीयरेंस किसका उपयोग है, देखें। बिना समीक्षा एन एस ए आई डी और सप्लीमेंट से बचें। अचानक बिगड़ाव नया कारण मांगता है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"dialysis","title":"Dialysis","subject":"Kidney Health","icon":"activity","status":"available","minutes":2,"competency":"Clinical Care","sources":[["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"]],"sections":[{"title":"Assessment","text":["Identify haemodialysis versus peritoneal dialysis, the schedule, residual kidney function and the exact medicine. Dialysis removal depends on the drug and treatment characteristics."]},{"title":"Treatment principles","text":["Some medicines need timing after dialysis or a supplemental dose; others do not. Use a dialysis-specific current reference and coordinate with the renal team. Review phosphate binders, anaemia therapy and adherence barriers."]},{"title":"Safety and follow-up","text":["Do not use one generic dose reduction for every drug. Access infection, breathlessness, confusion or major electrolyte symptoms needs prompt assessment. Protect the access according to the renal team's instructions and reconcile changes across care settings."]}],"quick":["Identify haemodialysis versus peritoneal dialysis, the schedule, residual kidney function and the exact medicine","Some medicines need timing after dialysis or a supplemental dose; others do not","Do not use one generic dose reduction for every drug"],"date":"2026-09-18","overview":"Identify haemodialysis versus peritoneal dialysis, the schedule, residual kidney function and the exact medicine.","hi":"डायलिसिस में हेमोडायलिसिस या पेरिटोनियल प्रकार, समय और बची गुर्दे की कार्यक्षमता पूछें। हर दवा डायलिसिस में समान मात्रा में नहीं निकलती। कुछ दवाएं सत्र के बाद या अतिरिक्त खुराक मांगती हैं, कुछ नहीं। वर्तमान डायलिसिस संदर्भ और रीनल टीम से योजना लें। एक जैसा खुराक घटाना सही नहीं। एक्सेस में संक्रमण, सांस या भ्रम में जल्दी जांच करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"renal-dose-adjustment","title":"Renal Dose Adjustment","subject":"Kidney Health","icon":"activity","status":"available","minutes":3,"competency":"Clinical Care","sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"],["KDIGO: CKD evaluation and management","https://kdigo.org/guidelines/ckd-evaluation-and-management/"]],"sections":[{"title":"Choose the right information","text":["Check the exact medicine and the renal measure used in its dosing reference. Creatinine clearance and estimated glomerular filtration rate are related but are not automatically interchangeable. Confirm units and whether body-surface-area indexing matters.","Consider the trend, hydration, recent illness, dialysis and timing. Creatinine-based equations are less reliable when kidney function is changing rapidly; a single apparently reassuring value can mislead."]},{"title":"Assess the whole regimen","text":["Identify renally eliminated medicines, active metabolites, nephrotoxic exposures and medicines that alter fluid or electrolyte balance. Use a current monograph or specialized reference for adjustment and monitoring.","Avoid using a classroom equation as an automatic prescribing recommendation. The appropriate response may be a dose change, interval change, alternative, temporary hold through an authorized process, or closer monitoring."]},{"title":"Communicate uncertainty","text":["A patient with acute illness and rising creatinine needs reassessment, not blind acceptance of yesterday’s dose. Clarify the plan, responsible clinician and follow-up measurements."]}],"quick":["Use the renal measure specified by the reference","Unstable kidney function limits equation accuracy","Dialysis needs specific guidance"],"date":"2026-09-18","overview":"Kidney function affects drug exposure, but one renal estimate cannot answer every dosing question.","hi":"गुर्दे के अनुसार दवा बदलते समय सही अनुमान और इकाई देखें। ई जी एफ आर और क्रिएटिनिन क्लीयरेंस हमेशा अदला-बदली योग्य नहीं हैं। संदर्भ किस विधि का उपयोग करता है, यह पुष्टि करें। तेजी से बदलते गुर्दे में स्थिर सूत्र कम भरोसेमंद हो सकता है। कुछ दवाओं की मात्रा और कुछ का अंतराल बदलता है। लोडिंग और रखरखाव खुराक अलग सोचें। उम्र, वजन, डायलिसिस, दवा स्तर और क्लिनिकल प्रतिक्रिया को साथ रखें; एक ही प्रतिशत सभी दवाओं पर न लगाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"health-promotion-and-immunizations","title":"Health Promotion and Immunizations","subject":"Law & Ethics","icon":"scale","status":"available","minutes":2,"competency":"Leadership & Stewardship","sources":[["Public Health Agency of Canada: Canadian Immunization Guide","https://www.canada.ca/en/public-health/services/canadian-immunization-guide.html"]],"sections":[{"title":"Assessment","text":["Assess vaccination history, age, medical risk, pregnancy, previous reactions and the relevant provincial schedule. Distinguish anaphylaxis to a component from expected local or systemic effects."]},{"title":"Treatment principles","text":["Use current NACI recommendations, the Canadian Immunization Guide and provincial eligibility rules. Check product, dose, route, interval, storage and consent. Prepare for anaphylaxis and document the administered vaccine and follow-up."]},{"title":"Safety and follow-up","text":["Live vaccines need particular assessment in pregnancy or significant immunosuppression. A cold-chain excursion requires quarantine and assessment rather than automatic use. Do not assume public funding and clinical eligibility are the same question."]}],"quick":["Assess vaccination history, age, medical risk, pregnancy, previous reactions and the relevant provincial schedule","Use current NACI recommendations, the Canadian Immunization Guide and provincial eligibility rules","Live vaccines need particular assessment in pregnancy or significant immunosuppression"],"date":"2026-09-18","overview":"Assess vaccination history, age, medical risk, pregnancy, previous reactions and the relevant provincial schedule.","hi":"टीकाकरण में इतिहास, उम्र, गर्भावस्था, बीमारी और पिछली प्रतिक्रिया देखें। सामान्य दर्द और वास्तविक एनाफिलैक्सिस अलग हैं। वर्तमान नैसी, कनाडाई गाइड और प्रांतीय पात्रता जांचें। उत्पाद, मात्रा, मार्ग, अंतराल, भंडारण और सहमति पुष्टि करें। कोल्ड चेन बिगड़ने पर वैक्सीन अलग रखें और जांच करवाएं। सरकारी भुगतान और चिकित्सकीय पात्रता एक ही प्रश्न नहीं हैं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"federal-law","title":"Federal Law","subject":"Law & Ethics","icon":"scale","status":"available","minutes":2,"competency":"Professionalism","sources":[["Health Canada: controlled substances exemption and October 2026 transition","https://www.canada.ca/en/health-canada/services/health-concerns/controlled-substances-precursor-chemicals/policy-regulations/policy-documents/section-56-1-class-exemption-patients-pharmacists-practitioners-controlled-substances-covid-19-pandemic.html"]],"sections":[{"title":"Assessment","text":["Identify which legal framework applies: medicines, controlled substances, privacy and provincial professional practice are not interchangeable. Federal rules and provincial requirements can both affect the same prescription."]},{"title":"Treatment principles","text":["Use the current consolidated legislation, regulations and applicable exemptions. Establish the drug category and the specific activity, such as dispensing, transfer, delivery or destruction, before checking the rule."]},{"title":"Safety and follow-up","text":["Never assume a temporary exemption remains active or applies to every profession and activity. Record the authority and date used for a decision. An employer policy may be stricter but cannot authorize an act prohibited by law."]}],"quick":["Identify which legal framework applies: medicines, controlled substances, privacy and provincial professional practice are not interchangeable","Use the current consolidated legislation, regulations and applicable exemptions","Never assume a temporary exemption remains active or applies to every profession and activity"],"date":"2026-09-18","overview":"Identify which legal framework applies: medicines, controlled substances, privacy and provincial professional practice are not interchangeable.","hi":"संघीय कानून में दवा, नियंत्रित पदार्थ और प्रांतीय व्यावसायिक नियम अलग पहचानें। एक पर्चे पर दोनों स्तर लागू हो सकते हैं। पहले दवा की श्रेणी और कार्य, जैसे वितरण, ट्रांसफर या नष्ट करना, तय करें। वर्तमान कानून और लागू छूट देखें। अस्थायी छूट को हमेशा सक्रिय न मानें। निर्णय में उपयोग की गई कानूनी authority और तारीख दर्ज करें। कार्यस्थल नीति कानून से ऊपर नहीं है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"ethics","title":"Ethics","subject":"Law & Ethics","icon":"scale","status":"available","minutes":3,"competency":"Professionalism","sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]],"sections":[{"title":"Identify the conflict","text":["Clarify facts, urgency, capacity, consent, privacy and the interests affected. Separate your assumptions from the patient’s expressed goals. Consider autonomy, benefit, avoidance of harm and fairness.","Check applicable law, professional standards and organizational policy. A policy does not erase a professional duty; an ethical preference does not erase a legal requirement."]},{"title":"Choose and explain a defensible action","text":["Consider practical alternatives and the likely consequences. Seek appropriate advice when uncertain, especially when significant harm or a conflict of interest is involved.","Communicate respectfully, document the rationale, and plan follow-up. Do not disclose information merely because a requester is a family member; establish consent or another applicable authority."]}],"quick":["Clarify facts and consent","Consider law and professional duties","Explain and document the decision"],"date":"2026-09-18","overview":"An ethical answer balances duties with the patient’s situation, rights and preferences.","hi":"नैतिक निर्णय में पहले तथ्य, मरीज की पसंद, सहमति, गोपनीयता और तुरंत जोखिम स्पष्ट करें। कानून, प्रोफेशनल स्टैंडर्ड और स्थानीय नीति में अंतर समझें। परिवार का सदस्य होना अपने आप निजी जानकारी लेने की अनुमति नहीं देता। उचित सहमति या दूसरी वैध अनुमति की पुष्टि करें। विकल्पों का लाभ और नुकसान समझाएं। अनिश्चित होने पर उपयुक्त सलाह लें। अपने निर्णय का कारण, बातचीत और आगे की योजना दर्ज करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"canadian-healthcare-system","title":"Canadian Healthcare System","subject":"Law & Ethics","icon":"scale","status":"available","minutes":2,"competency":"Knowledge & Expertise","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Canada's healthcare responsibilities are shared across federal, provincial and territorial systems. Registration, publicly funded services and drug coverage differ by jurisdiction and eligibility."]},{"title":"Treatment principles","text":["Help patients navigate care using the relevant provincial resources, private coverage and community supports. A product being prescribed or approved for sale does not automatically mean it is publicly reimbursed."]},{"title":"Safety and follow-up","text":["Do not equate PEBC certification with a provincial licence. Clarify the person's registration pathway with the regulator. In patient care, assess cost barriers without assuming coverage from age, employment or residence alone."]}],"quick":["Canada's healthcare responsibilities are shared across federal, provincial and territorial systems","Help patients navigate care using the relevant provincial resources, private coverage and community supports","Do not equate PEBC certification with a provincial licence"],"date":"2026-09-18","overview":"Canada's healthcare responsibilities are shared across federal, provincial and territorial systems.","hi":"कनाडा में स्वास्थ्य सेवाओं की जिम्मेदारी संघीय और प्रांतीय स्तर पर बंटी है। लाइसेंस, सेवाएं और दवा कवरेज अलग हो सकते हैं। दवा बाजार में मंजूर है या लिखी गई है, इससे सरकारी भुगतान निश्चित नहीं होता। मरीज की पात्रता और सहायता के विकल्प देखें। पी ई बी सी प्रमाणन अपने आप प्रांतीय लाइसेंस नहीं है। पंजीकरण का रास्ता संबंधित रेगुलेटर से पुष्टि करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"ontario-law-ethics","title":"Ontario Law & Ethics","subject":"Law & Ethics","icon":"scale","status":"available","minutes":3,"competency":"Professionalism","sources":[["Ontario exam preparation","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/prepare-for-the-exam/"],["OCP: JEP examination blueprint","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/examination-blueprint/"]],"sections":[{"title":"Use the right authority","text":["Identify whether your question concerns federal law, Ontario legislation, OCP standards or organizational policy. Check the applicable source and effective date rather than relying on an old summary.","For the Ontario Jurisprudence, Ethics and Professionalism exam, use the OCP blueprint and linked preparation resources to build a coverage checklist."]},{"title":"Keep your study current","text":["OCP states that its October 20, 2026 exam will reflect Controlled Substances Regulations effective October 1, 2026. Keep your intended exam date visible when choosing materials.","This introductory lesson is a navigation guide. It does not constitute a complete Ontario legal course or determine your registration eligibility."]}],"quick":["Separate federal law and provincial duties","Check effective dates","Use the OCP blueprint and official resources"],"date":"2026-09-18","overview":"Ontario preparation requires its own legal and professional context alongside national PEBC study.","hi":"ओंटारियो की तैयारी में राष्ट्रीय पी ई बी सी और प्रांतीय ज्यूरिस्प्रूडेंस, एथिक्स तथा प्रोफेशनलिज्म परीक्षा अलग रखें। ओंटारियो कॉलेज ऑफ फार्मासिस्ट्स का वर्तमान ब्लूप्रिंट और आधिकारिक संदर्भ उपयोग करें। पंजीकरण, कार्यक्षेत्र, पर्चे, नियंत्रित दवा, सहमति, गोपनीयता और रिकॉर्ड के नियम पढ़ें। किसी गतिविधि के लिए केवल सामान्य ज्ञान नहीं, लागू वर्तमान अधिकार जांचें। अस्थायी संघीय छूट और बदलती तारीखों को ध्यान से देखें। पी ए सी ई की जरूरत आपकी पंजीकरण राह पर निर्भर है; ऐप अभ्यास उसका विकल्प नहीं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"evidence-based-medicine-and-study-design","title":"Evidence-Based Medicine and Study Design","subject":"Evidence & Research","icon":"chart-no-axes-combined","status":"available","minutes":3,"competency":"Knowledge & Expertise","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Frame the question","text":["Identify the population, intervention, comparator and outcomes. Prioritize outcomes that matter to patients and consider both benefit and harm.","Randomization helps reduce baseline confounding; allocation concealment and blinding address different sources of bias. Observational studies can reveal associations but require careful assessment of confounding and selection."]},{"title":"Read critically","text":["Check the population, setting, follow-up, missing data, outcome definitions and analysis. A statistically significant result may still be too small or uncertain to be clinically useful.","Relative effects need baseline risk for interpretation. Consider absolute effects, confidence intervals, harms, patient preferences and applicability before recommending a change."]}],"quick":["Ask a focused question","Bias and applicability are separate issues","Interpret absolute and relative effects together"],"date":"2026-09-18","overview":"Start with a clinical question, then ask whether the evidence can answer it.","hi":"प्रमाण आधारित निर्णय में मरीज, हस्तक्षेप, तुलना और परिणाम से सवाल बनाएं। अध्ययन का डिजाइन सवाल से मेल खाना चाहिए। रैंडमाइजेशन समूहों को तुलनीय बनाने में मदद करता है, लेकिन हर पक्षपात खत्म नहीं करता। ब्लाइंडिंग, फॉलो अप, विश्लेषण और प्रासंगिकता देखें। सांख्यिकीय महत्व और मरीज के लिए महत्वपूर्ण लाभ अलग बातें हैं। रिश्ते से कारण अपने आप सिद्ध नहीं होता। प्रभाव का आकार, विश्वास अंतराल और मरीज की परिस्थिति के अनुसार निष्कर्ष लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"literature-references","title":"Literature & References","subject":"Evidence & Research","icon":"chart-no-axes-combined","status":"available","minutes":2,"competency":"Knowledge & Expertise","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Define the clinical question and the type of information needed before selecting a source. Product information, a practice guideline and a randomized trial answer different questions."]},{"title":"Treatment principles","text":["Use an appropriate current source, inspect its population, methods, funding and update date, and compare applicability to the Canadian setting. For a medicine question, check the exact formulation and indication."]},{"title":"Safety and follow-up","text":["A search snippet or AI response is not a verified clinical reference. Follow the claim to the original source and document uncertainty. Conflicting guidance should trigger a comparison of scope, evidence and publication dates rather than choosing the first result."]}],"quick":["Define the clinical question and the type of information needed before selecting a source","Use an appropriate current source, inspect its population, methods, funding and update date, and compare applicability to the Canadian setting","A search snippet or AI response is not a verified clinical reference"],"date":"2026-09-18","overview":"Define the clinical question and the type of information needed before selecting a source.","hi":"संदर्भ ढूंढने से पहले सवाल स्पष्ट करें। दवा मोनोग्राफ, दिशानिर्देश और शोध अध्ययन अलग सवालों के जवाब देते हैं। तारीख, आबादी, तरीके और कनाडाई परिस्थिति से मेल देखें। सर्च का छोटा अंश या ए आई का जवाब सत्यापित क्लिनिकल संदर्भ नहीं है। मूल स्रोत तक जाएं। विरोधी सलाह में क्षेत्र, प्रमाण और तारीख की तुलना करें, केवल पहला परिणाम न चुनें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"risk-benefit-nnt","title":"Risk, Benefit & NNT","subject":"Evidence & Research","icon":"chart-no-axes-combined","status":"available","minutes":3,"competency":"Knowledge & Expertise","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Work from event rates","text":["For an undesirable outcome, absolute risk reduction equals control event risk minus treatment event risk. Relative risk is treatment risk divided by control risk; relative risk reduction is one minus relative risk.","In a fictional study with risks of 10% and 6%, ARR is 4 percentage points, RR is 0.6 and RRR is 40%. NNT is 1 ÷ 0.04 = 25 over the study follow-up."]},{"title":"Keep the meaning attached","text":["Use proportions, not whole percentages, in the reciprocal. Specify outcome, population and timeframe. When conventional NNT calculation produces a fraction, round up to a whole person.","For increased harm, calculate the absolute risk increase and its reciprocal. Confidence intervals that span no effect can make a single NNT misleading. Compare benefit and harm rather than treating NNT as a universal score."]}],"quick":["NNT uses absolute risk difference as a proportion","Always state the outcome and timeframe","Relative reduction is not absolute reduction"],"date":"2026-09-18","overview":"Absolute effects show what a relative effect means for a particular baseline risk.","hi":"रिस्क को समझते समय एब्सोल्यूट और रिलेटिव असर को अलग रखें। एक काल्पनिक अध्ययन में बिना नए इलाज के घटना दस प्रतिशत और इलाज के साथ छह प्रतिशत है। एब्सोल्यूट रिस्क रिडक्शन चार प्रतिशत अंक है। रिलेटिव रिस्क रिडक्शन चालीस प्रतिशत है। एन एन टी निकालने के लिए एक को शून्य दशमलव शून्य चार से भाग दें। उत्तर पच्चीस है। इसके साथ अध्ययन का समय, मरीजों का समूह और किस घटना को मापा गया है, यह बताना जरूरी है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"diagnostic-test-interpretation","title":"Diagnostic Test Interpretation","subject":"Evidence & Research","icon":"chart-no-axes-combined","status":"available","minutes":3,"competency":"Knowledge & Expertise","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Use a two-by-two table","text":["Sensitivity is the fraction of people with the condition who test positive. Specificity is the fraction without the condition who test negative.","Positive predictive value is the fraction of positive results that are true positives. Negative predictive value is the fraction of negative results that are true negatives."]},{"title":"Interpret in context","text":["Predictive values depend on how common the condition is in the tested population. In a low-prevalence setting, a meaningful share of positive results can be false positives even when specificity is high.","Consider pre-test probability, consequences of errors and whether confirmation is required. A screening result should not be treated as a complete clinical diagnosis."]}],"quick":["Sensitivity starts with people who have the condition","PPV starts with positive test results","Prevalence changes predictive values"],"date":"2026-09-18","overview":"Test performance and the probability a result is correct answer different questions.","hi":"सेंसिटिविटी बीमारी वाले लोगों में सही पॉजिटिव और स्पेसिफिसिटी बीमारी न होने पर सही नेगेटिव पहचानती है। पॉजिटिव और नेगेटिव प्रेडिक्टिव वैल्यू पूछती हैं कि इस परिणाम के सही होने की संभावना क्या है। यह बीमारी की शुरुआती संभावना से बदलती है। कम प्रचलन में पॉजिटिव परिणाम की पुष्टि जरूरी हो सकती है। टेस्ट का समय, नमूना और उपयोग की आबादी देखें। एक नतीजे को मरीज के लक्षण और पहले की संभावना से अलग न पढ़ें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"hospital-pharmacy","title":"Hospital Pharmacy","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":2,"competency":"Distribution","sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]],"sections":[{"title":"Assessment","text":["Hospital medication use spans prescribing, verification, preparation, administration and monitoring. Transitions, urgent orders, infusions and formulary substitutions create distinct risks."]},{"title":"Treatment principles","text":["Clarify the indication, patient-specific factors and administration requirements. Reconcile admission and discharge medicines, including intentional changes. Coordinate with nurses and prescribers using closed-loop communication."]},{"title":"Safety and follow-up","text":["Check route, concentration, rate, line compatibility and independent-check requirements for high-risk infusions. A formulary substitution is not permission to ignore dose or formulation differences. Document unresolved issues and responsibility for follow-up."]}],"quick":["Hospital medication use spans prescribing, verification, preparation, administration and monitoring","Clarify the indication, patient-specific factors and administration requirements","Check route, concentration, rate, line compatibility and independent-check requirements for high-risk infusions"],"date":"2026-09-18","overview":"Hospital medication use spans prescribing, verification, preparation, administration and monitoring.","hi":"अस्पताल में दवा की सुरक्षा लिखने से लेकर देने और निगरानी तक है। भर्ती और छुट्टी की दवाएं मिलाएं और जानबूझकर हुए बदलाव स्पष्ट करें। इंजेक्शन में मार्ग, सांद्रता, गति और लाइन की अनुकूलता जांचें। फॉर्म्युलरी विकल्प होने से खुराक या रूप का अंतर खत्म नहीं होता। नर्स और डॉक्टर से बंद चक्र में पुष्टि करें तथा अधूरे मुद्दे और जिम्मेदारी लिखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"compounding","title":"Compounding","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":2,"competency":"Distribution","sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]],"sections":[{"title":"Assessment","text":["Determine whether compounding is appropriate and whether a suitable commercial product exists. Confirm the formulation, ingredients, calculations, equipment, competency and applicable sterile, nonsterile or hazardous-drug standards."]},{"title":"Treatment principles","text":["Use a validated master formulation and document the preparation record, actual ingredients, checks, packaging and assigned beyond-use date. A manufacturer's expiry and a compounded preparation's beyond-use date are different concepts."]},{"title":"Safety and follow-up","text":["Do not invent stability or compatibility data or extend a beyond-use date by appearance. Assess contamination and occupational exposure controls. Final release requires the designated quality checks and clear storage and administration counselling."]}],"quick":["Determine whether compounding is appropriate and whether a suitable commercial product exists","Use a validated master formulation and document the preparation record, actual ingredients, checks, packaging and assigned beyond-use date","Do not invent stability or compatibility data or extend a beyond-use date by appearance"],"date":"2026-09-18","overview":"Determine whether compounding is appropriate and whether a suitable commercial product exists.","hi":"कम्पाउंडिंग से पहले जरूरत, उपलब्ध बाजार उत्पाद, फार्मूला और उपयुक्त मानक देखें। सत्यापित मास्टर फार्मूला, सामग्री, गणना और तैयारी रिकॉर्ड रखें। निर्माता की एक्सपायरी और बनी तैयारी की बियॉन्ड यूज़ तारीख अलग हैं। केवल दिखने से स्थिरता न मानें और तारीख न बढ़ाएं। संक्रमण तथा कर्मचारियों के एक्सपोजर का नियंत्रण करें। अंतिम जांच और भंडारण की स्पष्ट सलाह दें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"social-determinants-of-health","title":"Social Determinants of Health","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":2,"competency":"Professionalism","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Explore practical barriers such as cost, transport, housing, food access, language, discrimination and caregiving demands. Ask respectfully instead of labelling the patient noncompliant."]},{"title":"Treatment principles","text":["Adapt the plan with the patient: simplify where appropriate, find coverage or community supports and arrange accessible communication. A clinically effective regimen may fail if the person cannot obtain or use it."]},{"title":"Safety and follow-up","text":["Do not make assumptions from identity or appearance. Obtain consent before involving supports and share only appropriate information. Record the agreed solution and whether the barrier was actually resolved."]}],"quick":["Explore practical barriers such as cost, transport, housing, food access, language, discrimination and caregiving demands","Adapt the plan with the patient: simplify where appropriate, find coverage or community supports and arrange accessible communication","Do not make assumptions from identity or appearance"],"date":"2026-09-18","overview":"Explore practical barriers such as cost, transport, housing, food access, language, discrimination and caregiving demands.","hi":"इलाज में खर्च, यातायात, घर, भोजन, भाषा और परिवार की जिम्मेदारियां असर डालती हैं। मरीज को गैरजिम्मेदार कहने के बजाय बाधा पूछें। योजना सरल करना, कवरेज और सामुदायिक सहायता ढूंढना मदद कर सकता है। पहचान या दिखावे से अनुमान न लगाएं। सहायता जोड़ने से पहले सहमति लें और केवल जरूरी जानकारी साझा करें। बाधा सच में हल हुई या नहीं, यह देखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"safety-and-documentation","title":"Safety and Documentation","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":2,"competency":"Professionalism","sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]],"sections":[{"title":"Assessment","text":["A useful record separates observations, patient reports, clinical interpretation and actions. Include the relevant time, participants and unresolved uncertainty so another clinician can follow the decision."]},{"title":"Treatment principles","text":["Document the problem, assessment, agreed plan, counselling, communication and follow-up responsibility. Correct errors through the approved process that preserves the audit trail rather than silently deleting the original record."]},{"title":"Safety and follow-up","text":["Avoid copied text that describes an assessment you did not perform. Record near misses and incidents through the appropriate learning process while prioritizing immediate patient safety. Secure access and minimum-necessary sharing remain essential."]}],"quick":["A useful record separates observations, patient reports, clinical interpretation and actions","Document the problem, assessment, agreed plan, counselling, communication and follow-up responsibility","Avoid copied text that describes an assessment you did not perform"],"date":"2026-09-18","overview":"A useful record separates observations, patient reports, clinical interpretation and actions.","hi":"अच्छे रिकॉर्ड में देखा गया तथ्य, मरीज की बात, आकलन और कार्रवाई अलग हों। समय, योजना, सलाह और फॉलो अप की जिम्मेदारी लिखें। गलत रिकॉर्ड सुधारते समय पुराना निशान सुरक्षित रखें; चुपचाप मिटाएं नहीं। ऐसी कॉपी की हुई जांच न लिखें जो की ही नहीं। गलती या नियर मिस से सीखने की प्रक्रिया अपनाएं और पहले मरीज की सुरक्षा देखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pharmacy-management","title":"Pharmacy Management","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":2,"competency":"Distribution","sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]],"sections":[{"title":"Assessment","text":["Management decisions affect safe staffing, inventory, workflow, privacy and continuity of care. Identify the service need and risks before prioritizing speed or sales."]},{"title":"Treatment principles","text":["Maintain ordering and recall systems, appropriate storage, training and documented procedures. Use workload and incident information to improve processes, and plan for shortages and service disruptions."]},{"title":"Safety and follow-up","text":["Expired, recalled or temperature-exposed stock should be separated pending the appropriate decision. Commercial pressure does not justify skipping professional checks. A useful quality measure examines patient outcomes and errors, not only prescription volume."]}],"quick":["Management decisions affect safe staffing, inventory, workflow, privacy and continuity of care","Maintain ordering and recall systems, appropriate storage, training and documented procedures","Expired, recalled or temperature-exposed stock should be separated pending the appropriate decision"],"date":"2026-09-18","overview":"Management decisions affect safe staffing, inventory, workflow, privacy and continuity of care.","hi":"फार्मेसी प्रबंधन में स्टाफ, स्टॉक, काम का प्रवाह, गोपनीयता और सेवा की निरंतरता आती है। केवल बिक्री या गति को लक्ष्य न बनाएं। रिकॉल, कमी, प्रशिक्षण और भंडारण की प्रक्रिया रखें। एक्सपायर या तापमान से प्रभावित स्टॉक अलग करें। व्यापार का दबाव जरूरी पेशेवर जांच छोड़ने का कारण नहीं है। गुणवत्ता में मरीज के परिणाम और त्रुटियां भी मापें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"inter-professional-care","title":"Inter-professional Care","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":2,"competency":"Communication & Collaboration","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Clarify each professional's role, the patient's goals and the decision requiring collaboration. Do not assume that sending a message means a recommendation was received or implemented."]},{"title":"Treatment principles","text":["Use a concise structure: situation, relevant background, assessment and recommendation. State urgency, the proposed action and how to reach you, then confirm the agreed plan and responsibility."]},{"title":"Safety and follow-up","text":["Disagreement should focus on patient safety and evidence. Escalate unresolved urgent concerns through the appropriate pathway. Document the communication and outcome; respect consent and confidentiality when sharing information."]}],"quick":["Clarify each professional's role, the patient's goals and the decision requiring collaboration","Use a concise structure: situation, relevant background, assessment and recommendation","Disagreement should focus on patient safety and evidence"],"date":"2026-09-18","overview":"Clarify each professional's role, the patient's goals and the decision requiring collaboration.","hi":"दूसरे स्वास्थ्य पेशेवरों के साथ काम में भूमिका, मरीज का लक्ष्य और जरूरी निर्णय स्पष्ट करें। स्थिति, जरूरी पृष्ठभूमि, आकलन और सुझाव संक्षेप में दें। संदेश भेजना मतलब कार्रवाई हो गई नहीं है; प्राप्ति और सहमति की पुष्टि करें। जिम्मेदारी तथा फॉलो अप लिखें। असहमति में व्यक्ति नहीं, प्रमाण और सुरक्षा पर बात करें। जरूरी अधूरा मुद्दा उचित स्तर पर उठाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"medication-reconciliation-and-soap","title":"Medication Reconciliation and SOAP","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":3,"competency":"Communication & Collaboration","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Reconcile differences","text":["Compare the best available medication history with the new orders. Identify omissions, duplications, dose changes and medicines stopped or started. Determine which changes were intentional and which need clarification.","Resolve discrepancies with the responsible clinician. Communicate the final list and reasons for changes to the patient and relevant professionals. An unexplained discrepancy should remain an open issue, not silently disappear."]},{"title":"Write a SOAP note","text":["Subjective: the patient’s symptoms, experience and goals. Objective: measured findings and reliable records. Assessment: the problem, interpretation and rationale. Plan: action, counselling, monitoring and follow-up.","Distinguish reported information from verified facts. Include the date, relevant context and professional responsibility. Concise documentation should still allow another clinician to understand your decision."]}],"quick":["Reconciliation includes resolving differences","Separate reported and measured information","Document the reasoning and follow-up"],"date":"2026-09-18","overview":"Medication reconciliation resolves differences at transitions of care. SOAP provides a structure for communicating your assessment.","hi":"मेडिकेशन रिकन्सिलिएशन में मरीज वास्तव में क्या लेता है, उसे नए ऑर्डर से मिलाएं। छूटी दवा, दोहराव और बदली मात्रा के कारण स्पष्ट करें। जानबूझकर और अनजाने बदलाव अलग हैं। अंतिम सूची मरीज और संबंधित टीम तक पहुंचाएं। सोप नोट में सब्जेक्टिव मरीज की बात, ऑब्जेक्टिव मापे तथ्य, असेसमेंट आपकी व्याख्या और प्लान कार्रवाई है। अधूरी जानकारी और फॉलो अप की जिम्मेदारी लिखें। केवल सूची बनाना रिकन्सिलिएशन पूरा नहीं करता।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"prescription-verification","title":"Prescription Verification","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":3,"competency":"Distribution","sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]],"sections":[{"title":"Three linked checks","text":["Confirm patient, prescriber, medicine, strength, dosage form, route, directions, quantity and relevant dates. Check indication, allergies, duplication, interactions and the patient’s ability to use the regimen.","Verify provincial and federal requirements using current authoritative references. Then compare the dispensed product and label against the verified prescription. A clinically appropriate order can still be assembled incorrectly."]},{"title":"Handle ambiguity safely","text":["If the prescription is illegible, internally inconsistent or potentially unsafe, hold the affected step and clarify with an appropriate source. Do not guess from a familiar dose or from the stock bottle.","For a discrepancy, document the concern, assessment, communication, resolution and follow-up. Explain delays in a way that maintains patient trust."]},{"title":"Practise a final check","text":["Inspect the identity, product, strength, dosage form, expiry, quantity, label and packaging separately. Use an independent check where the local process requires one; repeating a rushed glance is not independent verification."]}],"quick":["Clinical, legal and technical checks are distinct","Clarify before dispensing an ambiguous order","Record the resolution"],"date":"2026-09-18","overview":"Prescription review combines clinical assessment, legal requirements and a final technical check.","hi":"पर्चे की जांच में मरीज, लिखने वाला, दवा, ताकत, रूप, मार्ग, निर्देश, मात्रा और तारीख देखें। फिर जरूरत, एलर्जी, अंतःक्रिया, दोहराव और मरीज की क्षमता जांचें। क्लिनिकल, कानूनी और तकनीकी जांच अलग हैं। अस्पष्ट निर्देश का अनुमान न लगाएं; सही स्रोत से स्पष्ट करें। अंतिम उत्पाद और लेबल को सत्यापित पर्चे से मिलाएं। चिंता, बातचीत और समाधान दर्ज करें। परिचित दवा होने से स्वतंत्र जांच की जरूरत खत्म नहीं होती।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"patient-counselling","title":"Patient Counselling","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":3,"competency":"Communication & Collaboration","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Open with the patient","text":["Introduce yourself, confirm identity and privacy, and ask what the person already knows and most wants to discuss. Check language, hearing, health literacy and practical needs.","Explain the purpose of treatment, how to use it, expected benefit, relevant adverse effects, monitoring and when to seek help. Prioritize the information that changes safety and use."]},{"title":"Use teach-back","text":["Ask: “So I know I explained it clearly, how will you take this at home?” This checks your explanation rather than testing the patient. For devices, ask for a demonstration after teaching.","Do not finish with only “Do you understand?” A yes can reflect politeness, anxiety or misunderstanding. Correct gaps respectfully and repeat the check."]},{"title":"Make follow-up concrete","text":["Provide an actionable plan for missed doses and problems using a current product reference. Avoid inventing a universal missed-dose rule. Agree who to contact and when."]}],"quick":["Start with the patient’s goals","Use teach-back and demonstration","Avoid a universal missed-dose rule"],"date":"2026-09-18","overview":"Effective counselling ends with a patient who can explain and use the plan.","hi":"अच्छी काउंसलिंग मरीज की जरूरत से शुरू होती है। अपना परिचय दें, पहचान और गोपनीयता की पुष्टि करें, और पूछें कि मरीज सबसे पहले क्या जानना चाहता है। सरल भाषा में दवा का उद्देश्य, उपयोग, जरूरी सावधानियां और फॉलो अप समझाएं। केवल यह न पूछें कि समझ आया या नहीं। कहें, ताकि मुझे पता चले कि मैंने सही समझाया है, आप घर पर यह दवा कैसे लेंगे? डिवाइस हो तो मरीज से उपयोग करके दिखाने को कहें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"medication-history","title":"Medication History","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":3,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Ask in a useful order","text":["Confirm the patient and explain why you are reviewing medicines. Ask an open question first, then cover prescription medicines, nonprescription products, vitamins, herbals, inhalers, patches, injections and as-needed medicines.","For each product establish name, strength, amount, route, timing, indication, duration and actual use. Ask about recent changes, missed doses, access and side effects without blame."]},{"title":"Check reliability","text":["Compare the interview with another reliable source when possible: labelled containers, a dispensing history, a care record or a caregiver with appropriate consent. Record who supplied information and what remains uncertain.","Clarify allergies separately from other adverse effects. Obtain the specific reaction, timing, severity and subsequent exposure; do not delete an allergy simply because the account is incomplete."]},{"title":"Apply to a case","text":["“You take a water pill” is not enough to confirm a dose. Ask for the container or contact the dispensing pharmacy through the appropriate process. Document uncertainty and arrange verification before a high-risk decision."]}],"quick":["Include every route and nonprescription product","Record actual use and the source","Clarify the reaction, not just “allergy”"],"date":"2026-09-18","overview":"The best medication list describes what a person actually takes, not just what was prescribed.","hi":"दवाओं की सही जानकारी केवल प्रिस्क्रिप्शन की सूची नहीं है। पूछें कि मरीज वास्तव में क्या, कितना और कब लेता है। बिना प्रिस्क्रिप्शन की दवाएं, विटामिन, हर्बल उत्पाद, इनहेलर, पैच और जरूरत के समय ली जाने वाली दवाएं भी शामिल करें। नाम, शक्ति, मात्रा, तरीका और कारण स्पष्ट करें। एलर्जी में कौन सी प्रतिक्रिया हुई और कब हुई, यह जानें। जहां संभव हो, दूसरी विश्वसनीय जानकारी से सूची की जांच करें। किसी भी अनिश्चित जानकारी को स्पष्ट रूप से दर्ज करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"clinical-decision-making","title":"Clinical Decision Making","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":3,"competency":"Clinical Care","sources":[["PEBC examination blueprint","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/examination-blueprint/"]],"sections":[{"title":"Gather before deciding","text":["Start with the patient’s concern and the decision that needs to be made. Establish identity, symptoms, onset, severity and relevant history. Ask about prescriptions, nonprescription products, supplements, allergies and actual use.","Check immediate safety first. A case suggesting serious acute harm needs escalation before routine counselling. Distinguish missing information from a normal result; “not provided” does not mean “normal”."]},{"title":"Build and compare a plan","text":["Define the drug-related problem in one sentence. Is treatment needed, ineffective, unsafe or difficult to use? Agree on a measurable goal. Compare reasonable options using efficacy, safety, suitability and the patient’s preferences.","Check organ function, interactions, pregnancy considerations, ability to use the dosage form, access and adherence before recommending a change. A technically effective option may be impractical for this patient."]},{"title":"Close the loop","text":["Explain the plan in plain language. State what should improve, what harm to watch for, what monitoring is required and who is responsible for follow-up. Document your reasoning and unresolved questions.","Exam approach: decide what action is safest now. Do not skip a necessary assessment just because an answer names a familiar drug."]}],"quick":["Gather → assess → plan → implement → monitor","Missing information is not a normal finding","Give follow-up a person, measure and timeframe"],"date":"2026-09-18","overview":"A consistent care process helps you find the safest next step, even when a case contains distracting details.","hi":"फार्मासिस्ट की तरह सोचें। सबसे पहले मरीज की पहचान, मुख्य समस्या और तुरंत खतरे की जानकारी लें। दवाओं, एलर्जी, लक्षणों और वास्तविक उपयोग के बारे में पूछें। जो जानकारी नहीं दी गई है, उसे सामान्य मत मानें। समस्या को एक स्पष्ट वाक्य में बताएं। इलाज का लक्ष्य तय करें और लाभ, नुकसान, सुविधा तथा मरीज की पसंद की तुलना करें। योजना समझाएं, मरीज से अपने शब्दों में दोहराने को कहें, और निगरानी तथा फॉलो अप की जिम्मेदारी तय करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"antimicrobial-stewardship","title":"Antimicrobial Stewardship","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":3,"competency":"Leadership & Stewardship","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Ask the right questions","text":["Is there a likely infection, what is the suspected source, and how ill is the patient? Check relevant cultures, prior exposure, allergies, organ function, interactions and local guidance.","An antibiotic is not automatically appropriate for a symptom such as cough. When serious illness is suspected, prompt clinical assessment takes priority over a routine minor-ailment pathway."]},{"title":"Reassess the plan","text":["Review drug, dose, route and duration against the patient and evidence. Reassess when clinical response and microbiology become available. Communicate opportunities to narrow or stop treatment through the authorized care process.","Explain how to use the prescribed course and what worsening signs require review. Do not give a universal instruction to stop early or extend therapy without reassessment."]}],"quick":["Confirm indication and illness severity","Use local guidance and reassessment","Consider route, duration and spectrum"],"date":"2026-09-18","overview":"Stewardship aims for appropriate antimicrobial use while protecting the individual patient.","hi":"एंटीमाइक्रोबियल स्टूअर्डशिप का उद्देश्य सही मरीज को सही दवा, उचित मात्रा और अवधि देना है। पहले संक्रमण की जरूरत, स्थान और गंभीरता देखें। कल्चर और मरीज की प्रतिक्रिया मिलने पर दवा संकरी, बदली या बंद करनी पड़ सकती है। जहां जरूरी हो संक्रमण का स्रोत नियंत्रित करें। मरीज की सुरक्षा और प्रतिरोध दोनों ध्यान में रखें। केवल एंटीबायोटिक कम देना लक्ष्य नहीं; जरूरी इलाज देर करना भी हानिकारक है। कारण और समीक्षा की तारीख दर्ज करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"prescriber-calls","title":"Prescriber Calls","subject":"Pharmacy Practice","icon":"clipboard-check","status":"available","minutes":3,"competency":"Communication & Collaboration","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Prepare your message","text":["Have the patient identifiers, medicine list, relevant findings and references ready. Know the question you need answered. Use Situation, Background, Assessment and Recommendation to keep the conversation organized.","Describe the concrete safety or effectiveness problem. Distinguish what is confirmed from what needs clarification; avoid presenting a suspected issue as an established diagnosis."]},{"title":"Close the loop","text":["Recommend a reasonable option and explain why. Confirm the agreed action, who will inform the patient and who will monitor the outcome. Read back critical details when appropriate.","Document the communication and response. If the original prescriber is unavailable and the issue is urgent, follow an appropriate escalation pathway rather than leaving an unsafe ambiguity unresolved."]}],"quick":["Make a specific request","Separate facts from uncertainty","Confirm ownership of follow-up"],"date":"2026-09-18","overview":"A clear call identifies the concern and makes a specific, defensible request.","hi":"प्रिस्क्राइबर को फोन करते समय अपनी पहचान, मरीज और कॉल का उद्देश्य पहले बताएं। जरूरी पृष्ठभूमि और विशिष्ट सुरक्षा चिंता दें। अस्पष्ट शिकायत के बजाय स्पष्ट सुझाव और उसका कारण रखें। तत्काल कार्रवाई जरूरी हो तो बताएं। सुनी गई योजना को दोहराकर पुष्टि करें, खासकर खुराक और इकाई। बातचीत, जिम्मेदारी और फॉलो अप दर्ज करें। कॉल का उत्तर न मिले और जोखिम तत्काल हो तो उपयुक्त एस्केलेशन प्रक्रिया अपनाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pharmacokinetics-half-life","title":"Pharmacokinetics & Half-life","subject":"Pharmacy Foundations","icon":"book-open","status":"available","minutes":3,"competency":"Knowledge & Expertise","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Follow the medicine","text":["Absorption describes entry into the systemic circulation; distribution describes movement into tissues; metabolism and excretion remove drug or transform it. Bioavailability is the fraction reaching systemic circulation unchanged.","Clearance is a volume cleared per unit time, not an amount of drug. Volume of distribution relates the amount in the body to measured plasma concentration; it is a model parameter, not an anatomical container."]},{"title":"Use half-life carefully","text":["In an ideal first-order model, the fraction remaining after n half-lives is (1/2)^n. Roughly four to five half-lives bring repeated dosing near steady state. The same approximation can describe decline after stopping, but active metabolites and changing clearance complicate real cases.","A loading dose primarily depends on target concentration, volume of distribution and bioavailability. Maintenance dosing primarily depends on target exposure, clearance and bioavailability. Do not treat these as interchangeable."]},{"title":"Worked model","text":["Starting with a model amount of 80 mg, 40 mg remains after one half-life, 20 mg after two and 10 mg after three. This illustration assumes first-order elimination and does not prescribe a patient dose."]}],"quick":["After n half-lives, fraction remaining = (1/2)^n","Loading relates to distribution; maintenance to clearance","Check the assumptions behind the model"],"date":"2026-09-18","overview":"Pharmacokinetics connects a dosing regimen with exposure over time.","hi":"फार्माकोकाइनेटिक्स बताती है कि शरीर दवा के साथ क्या करता है। इसमें एब्जॉर्प्शन, डिस्ट्रीब्यूशन, मेटाबॉलिज्म और एक्सक्रीशन शामिल हैं। सरल फर्स्ट ऑर्डर मॉडल में हर हाफ लाइफ के बाद आधी मात्रा बचती है। अस्सी मिलीग्राम से एक हाफ लाइफ के बाद चालीस, फिर बीस, फिर दस मिलीग्राम बचेंगे। यह समझाने का मॉडल है, मरीज की खुराक का सुझाव नहीं। लोडिंग डोज मुख्य रूप से वितरण से और मेंटेनेंस डोज क्लियरेंस से जुड़ी होती है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"drug-interactions","title":"Drug Interactions","subject":"Pharmacy Foundations","icon":"book-open","status":"available","minutes":3,"competency":"Knowledge & Expertise","sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Two useful categories","text":["Pharmacokinetic interactions change exposure through absorption, metabolism or elimination. Pharmacodynamic interactions combine effects, such as sedation, bleeding or changes in cardiac conduction.","An inhibitor and an inducer can have different onset and offset patterns. The consequence depends on the pathway, active metabolites, dose and patient vulnerability."]},{"title":"Judge clinical relevance","text":["Confirm the actual products, route, dose, timing, duration and indication. Use a current interaction reference to assess severity, evidence and management. Patient-specific renal function, age and other medicines can change the risk.","Options may include avoiding the combination, selecting an alternative, changing timing when appropriate, adjusting therapy through an authorized process, or monitoring. Timing separation does not solve every interaction."]},{"title":"Communicate the action","text":["Explain the concern and proposed plan to the patient and prescriber as appropriate. State what will be monitored, when and by whom. Record why an alert was acted on or overridden."]}],"quick":["Exposure changes versus combined effects","Timing separation is not a universal fix","Document a monitoring plan"],"date":"2026-09-18","overview":"An interaction alert starts an assessment; it does not replace one.","hi":"दवा अंतःक्रिया का अलर्ट आकलन की शुरुआत है, अंतिम फैसला नहीं। कौन सी दवा, मात्रा, समय, मार्ग और मरीज के जोखिम हैं, देखें। एंजाइम, ट्रांसपोर्टर, फार्माकोडायनेमिक और अवशोषण के कारण अलग होते हैं। कुछ में समय अलग करना मदद करता है, कुछ में नहीं। वर्तमान संदर्भ से गंभीरता और विकल्प देखें। योजना में दवा बदलना, मात्रा, निगरानी या उपयुक्त संयोजन जारी रखना हो सकता है। जरूरी दवा अपनी तरफ से बंद न करवाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"allergy-vs-intolerance","title":"Allergy vs Intolerance","subject":"Pharmacy Foundations","icon":"book-open","status":"available","minutes":3,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Clarify the event","text":["Ask which medicine caused the reaction, what happened, when symptoms began, what treatment was needed and whether the person has taken related medicines since. Distinguish the patient’s words from your interpretation.","Nausea alone can be an adverse effect without establishing an immune allergy. Serious skin reactions, breathing difficulty, collapse or other severe features require careful assessment and appropriate escalation."]},{"title":"Preserve safety","text":["Do not challenge or remove a potentially serious allergy label through an unsupervised trial. Document details and uncertainty, then use an appropriate allergy assessment pathway.","Consider both the consequences of exposure and the consequences of an inaccurate label. Clarification can improve treatment options, but must be evidence based and safely performed."]}],"quick":["Record reaction, timing and severity","Do not assume every adverse effect is allergy","Do not perform an unsupervised rechallenge"],"date":"2026-09-18","overview":"A specific reaction history is more useful than an unexplained label.","hi":"एलर्जी लिखी हो तो वास्तविक प्रतिक्रिया, समय, गंभीरता, इलाज और दोबारा उपयोग पूछें। प्रतिरक्षा वाली एलर्जी और दूसरे दुष्प्रभाव अलग हैं, लेकिन अधूरी कहानी से एलर्जी हटा न दें। गंभीर सांस, रक्तचाप या त्वचा प्रतिक्रिया का इतिहास विशेष महत्व रखता है। सही दवा और संबंधित समूह स्पष्ट करें। मरीज की बात दस्तावेज करें और जरूरत पर विशेषज्ञ मूल्यांकन लें। केवल मतली या अस्पष्ट पुराने लेबल के आधार पर अनावश्यक व्यापक विकल्प न चुनें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"laboratory-interpretation","title":"Laboratory Interpretation","subject":"Pharmacy Foundations","icon":"book-open","status":"available","minutes":3,"competency":"Knowledge & Expertise","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Read beyond the flag","text":["Check the patient, collection time, units, reference interval, specimen quality and trend. A value outside an interval is not itself a diagnosis, and a value within it does not exclude illness.","Medicines, sampling conditions and acute changes can affect results. Relate the finding to symptoms, comorbidities and the decision under consideration."]},{"title":"Monitoring that can change care","text":["Before recommending a test, identify what question it answers, when it should be measured and what action a result would prompt. Safety monitoring and effectiveness monitoring answer different questions.","For drug levels, confirm dose timing, specimen timing, steady-state assumptions and the appropriate target for that patient and indication."]}],"quick":["Check units, time and trend","A reference interval is not a diagnosis","Monitoring needs a planned response"],"date":"2026-09-18","overview":"A laboratory result becomes useful when interpreted with units, timing and clinical context.","hi":"लैब परिणाम में नाम, इकाई, नमूने का समय और स्थानीय संदर्भ सीमा देखें। मरीज का पिछला पैटर्न और वर्तमान लक्षण महत्वपूर्ण हैं। एक असामान्य संख्या हमेशा बीमारी नहीं, और सामान्य सीमा हमेशा सुरक्षित स्थिति नहीं होती। नमूना समस्या, दवा और बीमारी परिणाम बदल सकती हैं। गंभीर परिणाम की उचित तात्कालिकता तय करें। गायब जांच को सामान्य न मानें। निर्णय के बाद कौन सी जांच कब और कौन देखेगा, यह तय करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"therapeutic-drug-monitoring","title":"Therapeutic Drug Monitoring","subject":"Pharmacy Foundations","icon":"book-open","status":"available","minutes":3,"competency":"Knowledge & Expertise","sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Before interpreting a level","text":["Confirm the medicine, regimen, recent doses, missed doses, route, dose changes and collection time. Assess kidney and liver function, interactions and signs of toxicity or inadequate effect.","Determine whether the relevant target is a trough, peak, area-under-the-curve estimate or another measure. Do not compare values collected at incompatible times."]},{"title":"From level to decision","text":["Use the appropriate current protocol and patient context. A result outside a target may reflect timing or adherence rather than a simple need to change the dose. Communicate the interpretation and follow-up clearly.","A level in range does not prove safety or effectiveness. Clinical assessment remains necessary."]}],"quick":["Verify dose and collection times","Use the correct target measure","A level does not replace clinical assessment"],"date":"2026-09-18","overview":"A drug level is a timed observation, not a stand-alone instruction.","hi":"दवा का स्तर समय से जुड़ा माप है। आखिरी खुराक, नमूने का समय, स्थिर अवस्था, पालन और गुर्दे की कार्यक्षमता पता करें। गलत समय के नमूने को सही ट्रफ मानकर मात्रा न बदलें। कुल और फ्री स्तर में अंतर प्रोटीन की स्थिति से महत्वपूर्ण हो सकता है। लक्ष्य बीमारी और मरीज अनुसार है। लक्षण और नुकसान के साथ स्तर समझें। नई मात्रा के बाद अगला स्तर कब होगा और कौन समीक्षा करेगा, यह स्पष्ट करें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"medication-safety","title":"Medication Safety","subject":"Pharmacy Foundations","icon":"book-open","status":"available","minutes":3,"competency":"Professionalism","sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"]],"sections":[{"title":"Reduce avoidable errors","text":["Use clear medicine names and units. Write a leading zero for values below one and avoid unnecessary trailing zeros. Separate look-alike products and verify high-risk steps through the established process.","Read a concentration as an amount per volume. A prescribed amount in milligrams is not automatically the volume to administer. Always carry units through a calculation."]},{"title":"Respond to an incident","text":["First assess and protect the patient. Obtain the facts, arrange appropriate clinical follow-up, communicate according to professional and organizational requirements, and document accurately.","Examine contributing conditions such as workload, interruptions, storage, software design and handoffs. Blaming an individual alone rarely fixes a process weakness."]},{"title":"Learn from near misses","text":["An error caught before reaching a patient can expose the same system vulnerability as an incident that caused harm. Use reporting and learning processes to reduce recurrence."]}],"quick":["Protect the patient first","Units belong in every calculation","A near miss is a learning opportunity"],"date":"2026-09-18","overview":"Safe practice anticipates predictable errors and makes recovery easier.","hi":"दवा सुरक्षा में छोटी अस्पष्टताएं भी महत्वपूर्ण हैं। दशमलव से पहले शून्य लिखें और अनावश्यक आखिरी शून्य से बचें। हर गणना में यूनिट लिखें। मिलीग्राम दवा की मात्रा है, जबकि मिलीलीटर तरल का आयतन है। दोनों को एक न समझें। गलती का संदेह हो तो पहले मरीज की सुरक्षा देखें, तथ्य जुटाएं और उचित सहायता लें। जो गलती मरीज तक पहुंचने से पहले पकड़ ली गई हो, उससे भी प्रक्रिया सुधारने का अवसर मिलता है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"units-dose-calculations","title":"Units & Dose Calculations","subject":"Pharmacy Foundations","icon":"book-open","status":"available","minutes":3,"competency":"Knowledge & Expertise","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Set up before calculating","text":["Write the required output unit first. Identify the supplied information and convert to compatible units. Use a labelled conversion factor so unwanted units cancel.","For volume, divide required drug amount by concentration in matching amount-per-volume units. A suspension labelled 100 mg per 5 mL contains 20 mg/mL."]},{"title":"Check the result","text":["In a fictional exercise requiring 150 mg from that suspension, volume is 150 mg ÷ 20 mg/mL = 7.5 mL. Check that 7.5 mL is one-and-a-half times 5 mL, matching 150 mg versus 100 mg.","Keep extra precision during intermediate steps and round the final answer according to the question or device. Distinguish a total daily dose from a dose given several times daily."]},{"title":"Prevent common mistakes","text":["Do not mix micrograms with milligrams or hours with minutes. Check whether a percentage is weight/volume, volume/volume or weight/weight. Write a leading zero before decimals."]}],"quick":["Write the output unit first","Daily dose is not necessarily one dose","Round at the final step"],"date":"2026-09-18","overview":"Unit tracking turns a calculation into something you can audit.","hi":"दवा की गणना शुरू करने से पहले उत्तर की यूनिट लिखें। मान लें कि एक अभ्यास में सौ मिलीग्राम दवा पांच मिलीलीटर में है। इसका मतलब है बीस मिलीग्राम प्रति मिलीलीटर। एक सौ पचास मिलीग्राम के लिए, एक सौ पचास को बीस से भाग दें। उत्तर है सात दशमलव पांच मिलीलीटर। बीच के चरणों में अतिरिक्त सटीकता रखें और अंतिम उत्तर को निर्देश के अनुसार राउंड करें। कुल दैनिक मात्रा और एक बार की मात्रा अलग हो सकती हैं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"routes-dosage-forms","title":"Routes & Dosage Forms","subject":"Pharmacy Foundations","icon":"book-open","status":"available","minutes":3,"competency":"Distribution","sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Check formulation intent","text":["Immediate-release, modified-release and enteric-coated products may not be interchangeable by crushing or splitting. Confirm the exact product and current handling guidance before altering it.","A route change may change bioavailability, onset and exposure. Do not assume that an oral, topical, inhaled or injectable amount can be substituted directly."]},{"title":"Match the patient","text":["Assess swallowing ability, dexterity, vision, cognition, device technique and the practicality of storage and preparation. Use an appropriate alternative or support when needed.","Explain whether the medicine needs shaking, reconstitution, measuring, priming or a specific technique using the exact product instructions."]}],"quick":["Formulation matters","Check before crushing or splitting","Teach the exact product technique"],"date":"2026-09-18","overview":"The route and formulation are part of the medicine’s identity.","hi":"दवा का मार्ग और रूप उसकी पहचान का हिस्सा हैं। एक ही घटक की सामान्य और मॉडिफाइड रिलीज गोली समान तरीके से नहीं दी जा सकती। कुचलने, खोलने या ट्यूब से देने से पहले उत्पाद का विश्वसनीय निर्देश देखें। पैच, इनहेलर, इंजेक्शन और तरल में अलग उपयोग तथा भंडारण हैं। निगलने में कठिनाई पर उपयुक्त विकल्प चुनें। केवल मिलीग्राम बराबर होने पर उत्पाद बदलना सुरक्षित मानकर न चलें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"geriatrics-frailty","title":"Geriatrics & Frailty","subject":"Special Populations","icon":"users","status":"available","minutes":3,"competency":"Clinical Care","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assess what changes care","text":["Consider frailty, cognition, falls, organ function, nutrition, swallowing, vision, dexterity and available support. Ask what matters most to the person and whether the regimen is manageable.","Look for duplicate treatment, medicines without a current indication, prescribing cascades and cumulative sedative or anticholinergic burden."]},{"title":"Review thoughtfully","text":["Evaluate expected time to benefit, risk of harm, withdrawal effects and feasibility of monitoring. Deprescribing needs a plan; not every medicine should be stopped abruptly.","Use shared decision making and coordinate with caregivers when appropriate and authorized. A simpler regimen can help, but changes must preserve clinical intent."]}],"quick":["Goals and function matter","Look for prescribing cascades","Deprescribing needs monitoring"],"date":"2026-09-18","overview":"Chronological age alone does not describe treatment risk or the patient’s goals.","hi":"बुजुर्ग मरीज में केवल उम्र नहीं, कमजोरी, रोजमर्रा की क्षमता, याददाश्त, गिरना, गुर्दे और व्यक्तिगत लक्ष्य देखें। कई दवाओं में एंटीकोलिनर्जिक और नींद का बोझ जुड़ता है। लाभ मिलने का समय और जीवन की प्राथमिकताएं भी महत्वपूर्ण हैं। दवा घटाना सहमति और निगरानी वाली प्रक्रिया है, अचानक सभी दवाएं बंद करना नहीं। देखभाल करने वाले को उचित सहमति से शामिल करें और सरल उपयोग योजना बनाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pregnancy-breastfeeding","title":"Pregnancy & Breastfeeding","subject":"Special Populations","icon":"users","status":"available","minutes":3,"competency":"Clinical Care","sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Establish the context","text":["Clarify pregnancy status or gestational timing, breastfeeding details, medicine exposure and the condition being treated. Use a current specialist reference rather than a remembered label or a blanket rule.","For breastfeeding, the infant’s age, prematurity, health and exposure matter. Pregnancy guidance cannot simply be reused as breastfeeding guidance."]},{"title":"Avoid unsupported reassurance","text":["Discuss uncertainty honestly and seek specialist input when needed. Do not automatically stop essential treatment; abrupt withdrawal or undertreatment can also cause harm.","Document the sources, discussion, plan and monitoring. Counselling should support an informed decision without overstating either safety or risk."]}],"quick":["Pregnancy and lactation assessments differ","Consider untreated illness as well as drug exposure","Use current specialist references"],"date":"2026-09-18","overview":"Risk assessment depends on the medicine, exposure, timing and the consequence of untreated illness.","hi":"गर्भावस्था में दवा का जोखिम गर्भ के चरण, मात्रा, मार्ग और बीमारी पर निर्भर है। स्तनपान में बच्चे की उम्र, समय से पहले जन्म और दूध से वास्तविक एक्सपोजर देखें। दोनों स्थितियां एक जैसी नहीं हैं। इलाज न होने का नुकसान भी चर्चा में रखें। वर्तमान विशेषज्ञ संदर्भ से दवा अनुसार सलाह दें। सभी प्राकृतिक उत्पाद सुरक्षित या सभी दवाएं खतरनाक नहीं होतीं। जरूरी इलाज बदलने से पहले संबंधित टीम के साथ योजना बनाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"pediatric-dosing","title":"Pediatric Dosing","subject":"Special Populations","icon":"users","status":"available","minutes":2,"competency":"Knowledge & Expertise","sources":[["Canadian Paediatric Society: current position statements","https://cps.ca/en/documents/statements-by-date"]],"sections":[{"title":"Assessment","text":["Use a verified current weight in kilograms and the correct age group. Distinguish mg/kg/dose from mg/kg/day and confirm the maximum dose and dosing interval from the specific reference."]},{"title":"Treatment principles","text":["Calculate the required amount before converting to volume with the dispensed concentration. Check whether the daily amount must be divided and whether the formulation is appropriate. Round only at the final practical administration step."]},{"title":"Safety and follow-up","text":["Do not calculate a clinical dose from a weight alone without an indication-specific regimen. Verify unusually large or small results independently. Demonstrate the oral syringe and ask the caregiver to show the measured dose back."]}],"quick":["Use a verified current weight in kilograms and the correct age group","Calculate the required amount before converting to volume with the dispensed concentration","Do not calculate a clinical dose from a weight alone without an indication-specific regimen"],"date":"2026-09-18","overview":"Use a verified current weight in kilograms and the correct age group.","hi":"बच्चे की खुराक में वर्तमान वजन किलोग्राम में लें। मिलीग्राम प्रति किलोग्राम प्रति खुराक और प्रति दिन अलग हैं। दवा, बीमारी, अंतराल और अधिकतम मात्रा संदर्भ से पुष्टि करें। पहले मिलीग्राम निकालें, फिर बोतल की सांद्रता से मिलीलीटर बनाएं। दैनिक मात्रा हो तो सही भाग करें। अंतिम कदम पर व्यावहारिक राउंडिंग करें और अभिभावक से सिरिंज में मात्रा दिखवाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"hepatic-impairment","title":"Hepatic Impairment","subject":"Special Populations","icon":"users","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Assessment","text":["Assess the nature and severity of liver disease, synthetic function, portal-hypertension complications and current medicines. Elevated transaminases alone do not fully describe drug clearance or clinical severity."]},{"title":"Treatment principles","text":["Use product-specific guidance and a suitable hepatic assessment when required. Consider active metabolites, protein binding, bleeding, sedation and the effect of untreated disease when selecting therapy."]},{"title":"Safety and follow-up","text":["There is no universal hepatic equivalent of a simple renal dose equation. New jaundice, confusion, bleeding or deterioration needs assessment. Review alcohol and supplements, and avoid assuming a medicine is safe merely because it is not renally eliminated."]}],"quick":["Assess the nature and severity of liver disease, synthetic function, portal-hypertension complications and current medicines","Use product-specific guidance and a suitable hepatic assessment when required","There is no universal hepatic equivalent of a simple renal dose equation"],"date":"2026-09-18","overview":"Assess the nature and severity of liver disease, synthetic function, portal-hypertension complications and current medicines.","hi":"लिवर की बीमारी में केवल ए एस टी या ए एल टी नहीं, गंभीरता, प्रोटीन बनाने की क्षमता और जटिलताएं देखें। दवा अनुसार निर्देश, सक्रिय मेटाबोलाइट, रक्तस्राव और नींद का जोखिम समझें। लिवर के लिए हर दवा पर लागू एक सरल खुराक फार्मूला नहीं है। नया पीलिया, भ्रम या खून में जांच करें। गुर्दे से न निकलने वाली दवा अपने आप सुरक्षित नहीं होती।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"transgender-health","title":"Transgender Health","subject":"Special Populations","icon":"users","status":"available","minutes":2,"competency":"Professionalism","sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]],"sections":[{"title":"Assessment","text":["Use the person's name and pronouns and ask only clinically relevant questions about anatomy, medicines and goals. Gender identity does not by itself specify reproductive potential, hormone use or screening needs."]},{"title":"Treatment principles","text":["Review gender-affirming therapy respectfully, including interactions, route-specific risks and the prescribed monitoring plan. Screening and preventive care should match organs present, age, exposure and individual risk."]},{"title":"Safety and follow-up","text":["Hormone therapy is not reliable contraception. Do not withhold unrelated care because gender-affirming care is outside your expertise; obtain appropriate support. Preserve confidentiality and avoid disclosing identity information unnecessarily."]}],"quick":["Use the person's name and pronouns and ask only clinically relevant questions about anatomy, medicines and goals","Review gender-affirming therapy respectfully, including interactions, route-specific risks and the prescribed monitoring plan","Hormone therapy is not reliable contraception"],"date":"2026-09-18","overview":"Use the person's name and pronouns and ask only clinically relevant questions about anatomy, medicines and goals.","hi":"ट्रांसजेंडर स्वास्थ्य में चुना नाम और सर्वनाम सम्मान से उपयोग करें। केवल जरूरी अंग, दवा और स्वास्थ्य लक्ष्य पूछें। पहचान से हार्मोन उपयोग या गर्भ की संभावना तय नहीं होती। हार्मोन थेरेपी की अंतःक्रिया और निगरानी देखें; यह भरोसेमंद गर्भनिरोध नहीं है। स्क्रीनिंग मौजूद अंग और जोखिम के अनुसार करें। गोपनीयता रखें और अपनी विशेषज्ञता के बाहर उचित सहायता लें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"inhalers-spacers","title":"Inhalers & Spacers","subject":"Devices & Technique","icon":"stethoscope","status":"available","minutes":3,"competency":"Communication & Collaboration","sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["Canadian Thoracic Society: guideline library","https://cts-sct.ca/guideline-library/"]],"sections":[{"title":"Identify the device","text":["Confirm the product, device type, prescribed regimen and which medicine is used for which purpose. Ask the person to show how they use it before correcting technique.","Metered-dose and dry-powder devices have different preparation and inhalation instructions. Follow the manufacturer’s steps for priming, loading, inhalation, cleaning and storage."]},{"title":"Teach and check","text":["Demonstrate one step at a time with an appropriate training device. Check seal, breathing manoeuvre, coordination and remaining-dose awareness. Discuss a spacer when appropriate for the device and patient.","Ask the patient to demonstrate again. If control remains poor, assess technique, adherence and clinical status rather than assuming the medicine has failed."]}],"quick":["Identify the exact device","Observe before correcting","Use return demonstration"],"date":"2026-09-18","overview":"Teaching inhaler technique requires the exact device and a return demonstration.","hi":"इनहेलर सिखाने से पहले सही उपकरण और दवा पहचानें। मीटर्ड डोज, ड्राय पाउडर और सॉफ्ट मिस्ट उपकरण की सांस लेने की विधि अलग होती है। जहां उपयुक्त हो स्पेसर मदद करता है। तैयारी, सांस छोड़ना, सही इनहेलेशन और रोकने की विधि उत्पाद अनुसार दिखाएं। मरीज से करके दिखाने को कहें। बची खुराक, सफाई और स्टेरॉयड के बाद कुल्ला समझाएं। केवल पूछना कि समझ आया, सही तकनीक की पुष्टि नहीं करता।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"insulin-pens","title":"Insulin Pens","subject":"Devices & Technique","icon":"stethoscope","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Assessment","text":["Confirm the exact insulin, concentration, pen type, dose in units and timing. Similar names and pen colours are not reliable identifiers; check the label at every administration."]},{"title":"Treatment principles","text":["Demonstrate a new needle, product-specific priming, dialing units, injection-site rotation and the required hold time. Explain storage, in-use expiry and disposal using the exact product instructions."]},{"title":"Safety and follow-up","text":["Pens are never shared, even after changing the needle. Do not withdraw insulin from a pen with a syringe or convert a dialed pen dose to volume without explicit product guidance. Teach hypoglycaemia recognition and the individualized response plan."]}],"quick":["Confirm the exact insulin, concentration, pen type, dose in units and timing","Demonstrate a new needle, product-specific priming, dialing units, injection-site rotation and the required hold time","Pens are never shared, even after changing the needle"],"date":"2026-09-18","overview":"Confirm the exact insulin, concentration, pen type, dose in units and timing.","hi":"इंसुलिन पेन में सही नाम, सांद्रता, यूनिट और समय पुष्टि करें। केवल रंग से पहचान न करें। नई सुई, प्राइमिंग, यूनिट सेट करना, जगह बदलना और दबाए रखने का समय उत्पाद अनुसार दिखाएं। पेन कभी साझा न करें, सुई बदलने पर भी नहीं। पेन से सिरिंज में इंसुलिन निकालकर न दें। कम शुगर की पहचान, उपचार और सही भंडारण समझाएं।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"naloxone","title":"Naloxone","subject":"Devices & Technique","icon":"stethoscope","status":"available","minutes":2,"competency":"Clinical Care","sources":[["BC Centre on Substance Use: clinical guidance","https://www.bccsu.ca/clinical-care-guidance/"]],"sections":[{"title":"Assessment","text":["Suspect opioid overdose when a person is unresponsive with slow or absent breathing. Pinpoint pupils may occur but are not required to act. Naloxone reverses opioid effects temporarily."]},{"title":"Treatment principles","text":["Call emergency services, give naloxone using the available product instructions and support breathing or CPR according to training and dispatcher directions. Repeat dosing may be needed; stay with the person."]},{"title":"Safety and follow-up","text":["Return of breathing does not remove the need for emergency assessment because sedation can recur. Explain kit storage, expiry and how contacts can respond. Naloxone does not reverse every cause of unconsciousness or replace airway support."]}],"quick":["Suspect opioid overdose when a person is unresponsive with slow or absent breathing","Call emergency services, give naloxone using the available product instructions and support breathing or CPR according to training and dispatcher directions","Return of breathing does not remove the need for emergency assessment because sedation can recur"],"date":"2026-09-18","overview":"Suspect opioid overdose when a person is unresponsive with slow or absent breathing.","hi":"ओपिओइड ओवरडोज में व्यक्ति जवाब नहीं देता और सांस धीमी या बंद हो सकती है। तुरंत आपातकालीन सेवा बुलाएं, उपलब्ध उत्पाद के निर्देश से नालॉक्सोन दें और प्रशिक्षण या डिस्पैचर के अनुसार सांस या सी पी आर की मदद करें। दोबारा खुराक लग सकती है। व्यक्ति जाग जाए तब भी साथ रहें; दवा का असर खत्म होने पर सांस फिर दब सकती है। नालॉक्सोन हर बेहोशी का इलाज नहीं है।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"epinephrine-auto-injectors","title":"Epinephrine Auto-injectors","subject":"Devices & Technique","icon":"stethoscope","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Assessment","text":["Recognize anaphylaxis from rapid airway, breathing or circulation problems, sometimes with skin or GI symptoms. A rash is not required for severe anaphylaxis."]},{"title":"Treatment principles","text":["Prompt intramuscular epinephrine using the prescribed auto-injector is first-line emergency treatment. Activate emergency services and follow the emergency plan; teach the correct device end, outer-thigh site and product-specific hold time with a trainer."]},{"title":"Safety and follow-up","text":["Antihistamines do not replace epinephrine for airway or circulatory compromise. Do not delay treatment while waiting for symptoms to become dramatic. Review storage, expiry, access to additional doses and observation after the event."]}],"quick":["Recognize anaphylaxis from rapid airway, breathing or circulation problems, sometimes with skin or GI symptoms","Prompt intramuscular epinephrine using the prescribed auto-injector is first-line emergency treatment","Antihistamines do not replace epinephrine for airway or circulatory compromise"],"date":"2026-09-18","overview":"Recognize anaphylaxis from rapid airway, breathing or circulation problems, sometimes with skin or GI symptoms.","hi":"एनाफिलैक्सिस में सांस, गले या रक्तसंचार की समस्या तेजी से हो सकती है; चकत्ता जरूरी नहीं। निर्धारित ऑटो इंजेक्टर से मांसपेशी में एपिनेफ्रिन पहला आपात इलाज है। आपातकालीन मदद बुलाएं। ट्रेनर से सही सिरा, जांघ की बाहरी जगह और उत्पाद अनुसार समय सिखाएं। एंटीहिस्टामिन एपिनेफ्रिन की जगह नहीं लेती। भंडारण, एक्सपायरी और आगे की खुराक की योजना जांचें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"},{"id":"blood-glucose-monitoring","title":"Blood Glucose Monitoring","subject":"Devices & Technique","icon":"stethoscope","status":"available","minutes":2,"competency":"Clinical Care","sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]],"sections":[{"title":"Assessment","text":["Clarify whether the person uses a meter or continuous glucose monitor and what decisions the readings support. Technique, strip storage, sensor limitations and timing affect interpretation."]},{"title":"Treatment principles","text":["For capillary testing, demonstrate clean dry hands, correct strip and meter use, and safe sharps disposal. For CGM, teach trend interpretation and the device-specific advice when symptoms do not match the sensor value."]},{"title":"Safety and follow-up","text":["Treat concerning hypoglycaemia according to the person's plan; severe symptoms need help. Do not change a long-term regimen from a single unexplained reading. Link patterns to meals, activity, illness and medicines and arrange follow-up."]}],"quick":["Clarify whether the person uses a meter or continuous glucose monitor and what decisions the readings support","For capillary testing, demonstrate clean dry hands, correct strip and meter use, and safe sharps disposal","Treat concerning hypoglycaemia according to the person's plan; severe symptoms need help"],"date":"2026-09-18","overview":"Clarify whether the person uses a meter or continuous glucose monitor and what decisions the readings support.","hi":"ग्लूकोज मीटर और लगातार सेंसर में फर्क समझाएं। हाथ साफ और सूखे, सही स्ट्रिप और उपकरण का सही उपयोग दिखाएं। सेंसर के नंबर और लक्षण मेल न खाएं तो उत्पाद की पुष्टि वाली प्रक्रिया अपनाएं। कम शुगर में व्यक्तिगत योजना के अनुसार तुरंत कदम लें। एक अस्पष्ट नंबर से पूरी दवा योजना न बदलें। भोजन, व्यायाम, बीमारी और दवाओं के साथ पैटर्न देखें।","reviewStatus":"Independent clinical review pending","depth":"Concise topic review"}],"questions":[{"id":"q1","topic":"clinical-decision-making","domain":"Clinical Care","level":"Foundation","stem":"A case does not provide kidney function. Which interpretation is safest?","options":["Assume normal function","Treat it as missing information that may need clarification","Assume severe impairment","Ignore it if the drug is familiar"],"answer":1,"explain":["Absence of a result does not establish normal function.","Correct. Identify whether the missing information is necessary before making the decision.","Missing information does not establish an abnormal result either.","Familiarity does not remove the need for patient-specific assessment."],"sources":[["PEBC examination blueprint","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/examination-blueprint/"]]},{"id":"q2","topic":"medication-history","domain":"Clinical Care","level":"Foundation","stem":"Which source best describes actual medication use?","options":["The prescription alone","The stock label alone","A patient interview checked against reliable records","A list of common doses"],"answer":2,"explain":["A prescription describes intent, not necessarily current use.","A stock label identifies a product, not the person’s regimen.","Correct. Reconcile what the person reports with reliable information and record uncertainty.","Common doses are not evidence of what this patient takes."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q3","topic":"patient-counselling","domain":"Communication & Collaboration","level":"Foundation","stem":"Which closing question best uses teach-back?","options":["Do you understand?","You know what to do, right?","Why did you not listen?","So I know I explained it clearly, how will you take this at home?"],"answer":3,"explain":["A yes/no response may hide uncertainty.","A leading question discourages clarification.","Blame undermines communication.","Correct. This invites a demonstration of understanding and places responsibility on the explanation."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q4","topic":"medication-safety","domain":"Professionalism","level":"Foundation","stem":"Which written dose avoids unnecessary decimal ambiguity?","options":[".5 mg","0.5 mg","0.50 mg","5.0 mg"],"answer":1,"explain":["A missing leading zero can obscure the decimal.","Correct. Use a leading zero without unnecessary trailing zeros.","The trailing zero is unnecessary.","This is a different dose and also includes a trailing zero."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"]]},{"id":"q5","topic":"pharmacokinetics-half-life","domain":"Knowledge & Expertise","level":"Foundation","stem":"In an ideal first-order model, what fraction remains after three half-lives?","options":["50%","25%","12.5%","3%"],"answer":2,"explain":["50% remains after one half-life.","25% remains after two.","Correct. (1/2) cubed is 1/8, or 12.5%.","The number of half-lives is not the remaining percentage."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q6","topic":"drug-interactions","domain":"Knowledge & Expertise","level":"Foundation","stem":"Separating the times of two medicines is best described as:","options":["A solution for every interaction","An option for some interactions, after checking the mechanism","A replacement for dose review","Proof that an interaction is harmless"],"answer":1,"explain":["Some effects persist despite timing separation.","Correct. Management depends on the interaction mechanism and patient context.","Timing does not remove the need to assess the regimen.","Harmlessness cannot be inferred from different administration times."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"q7","topic":"renal-dose-adjustment","domain":"Clinical Care","level":"Foundation","stem":"A patient’s creatinine is rising rapidly. What is a key limitation of a creatinine-based dosing estimate?","options":["It may not reflect stable kidney function","It must always be zero","It measures drug concentration directly","It automatically includes dialysis clearance"],"answer":0,"explain":["Correct. Rapidly changing function can violate assumptions behind the estimate.","There is no reason to substitute zero.","It estimates kidney function, not drug concentration.","Dialysis requires additional specific information."],"sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"],["KDIGO: CKD evaluation and management","https://kdigo.org/guidelines/ckd-evaluation-and-management/"]]},{"id":"q8","topic":"risk-benefit-nnt","domain":"Knowledge & Expertise","level":"Foundation","stem":"A trial reports an undesirable event in 12% of controls and 8% of treated participants. What is the absolute risk reduction?","options":["4 percentage points","33 percentage points","20 percentage points","66 percentage points"],"answer":0,"explain":["Correct. 12% minus 8% is 4 percentage points.","Approximately 33% is the relative reduction, not the absolute difference.","Adding the two event rates does not produce ARR.","This is not the difference in event rates."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q9","topic":"risk-benefit-nnt","domain":"Knowledge & Expertise","level":"Foundation","stem":"An ARR of 0.05 over two years corresponds to an NNT of:","options":["5","50","20 over two years","20 per day"],"answer":2,"explain":["Use the reciprocal of the proportion.","1 divided by 0.05 is 20.","Correct. The timeframe must remain attached.","The study timeframe cannot be replaced with a day."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q10","topic":"diagnostic-test-interpretation","domain":"Knowledge & Expertise","level":"Foundation","stem":"Sensitivity is calculated among:","options":["Everyone with a positive result","People who have the condition","Only people without the condition","Everyone with a negative result"],"answer":1,"explain":["That denominator is used for positive predictive value.","Correct. Sensitivity is true positives divided by everyone with the condition.","This population is used to consider specificity.","That denominator relates to negative predictive value."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q11","topic":"prescription-verification","domain":"Distribution","level":"Foundation","stem":"A prescription’s strength is unreadable. What is the best next action?","options":["Choose the most common strength","Use the strength currently in stock","Clarify using an appropriate reliable source before proceeding","Ask another person to make the same guess"],"answer":2,"explain":["Frequency of use does not resolve ambiguity.","Inventory does not establish prescribing intent.","Correct. Clarification prevents a potentially consequential error.","A second guess does not create verification."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"q12","topic":"medication-reconciliation-and-soap","domain":"Communication & Collaboration","level":"Foundation","stem":"Which information belongs primarily in the Assessment part of a SOAP note?","options":["Patient-reported nausea","Measured blood pressure","Your interpretation of the drug-related problem","The patient’s contact number"],"answer":2,"explain":["This is subjective information.","This is objective information.","Correct. Assessment connects facts to clinical interpretation.","This is an identifier, not an assessment."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q13","topic":"therapeutic-drug-monitoring","domain":"Knowledge & Expertise","level":"Foundation","stem":"Before interpreting a trough concentration, which missing information is particularly important?","options":["The pharmacy’s logo","The timing of doses and blood collection","The colour of the patient’s bag","The number of pages in the chart"],"answer":1,"explain":["The logo does not establish sampling context.","Correct. An incorrectly timed level may not be comparable with the trough target.","This does not inform the level interpretation.","Chart length does not verify dose or sample timing."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"q14","topic":"allergy-vs-intolerance","domain":"Clinical Care","level":"Foundation","stem":"A patient reports an “allergy” but cannot describe the event. What should you do?","options":["Erase the allergy immediately","Give a trial dose to find out","Record the uncertainty and seek details through an appropriate assessment","Assume every drug in every class is contraindicated"],"answer":2,"explain":["Incomplete information is not proof of safety.","An unsupervised rechallenge can be dangerous.","Correct. Clarify reaction, timing and severity while preserving safety.","A nonspecific report does not justify an unlimited class assumption."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q15","topic":"ethics","domain":"Professionalism","level":"Foundation","stem":"An adult patient’s family member requests private medication details. What should be established first?","options":["Whether the family member is curious","Consent or another applicable authority to disclose","Whether the pharmacy is busy","Whether the patient has many medicines"],"answer":1,"explain":["Curiosity does not establish authority.","Correct. A relationship alone does not authorize disclosure.","Workload does not remove confidentiality duties.","The number of medicines does not determine permission."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"q16","topic":"prescriber-calls","domain":"Communication & Collaboration","level":"Foundation","stem":"Which recommendation best closes a clinical communication?","options":["Please do something","There may be a problem","A specific proposed action with monitoring and follow-up responsibility","No need to document the call"],"answer":2,"explain":["The requested action is unclear.","The concern needs supporting facts and a request.","Correct. Make the next action and ownership clear.","Documentation supports continuity and accountability."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q17","topic":"geriatrics-frailty","domain":"Clinical Care","level":"Foundation","stem":"Which is most useful when assessing a medicine for a frail older adult?","options":["Age alone","Goals, function, likely benefit, harm and treatment burden","Number of tablets alone","The newest product by default"],"answer":1,"explain":["Chronological age does not capture the whole context.","Correct. Individual priorities and vulnerabilities guide assessment.","Count alone does not establish appropriateness.","Novelty is not a patient-specific reason to select treatment."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q18","topic":"inhalers-spacers","domain":"Communication & Collaboration","level":"Foundation","stem":"After explaining a device, what best checks technique?","options":["Ask only whether the patient understands","Assume all inhalers work the same way","Ask the patient to demonstrate using the exact device instructions","Increase the medicine immediately"],"answer":2,"explain":["A yes/no response does not demonstrate a skill.","Device instructions differ.","Correct. Return demonstration exposes practical misunderstandings.","Assess technique and clinical status before assuming medicine failure."],"sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["Canadian Thoracic Society: guideline library","https://cts-sct.ca/guideline-library/"]]},{"id":"q19","topic":"antimicrobial-stewardship","domain":"Leadership & Stewardship","level":"Foundation","stem":"Which question comes before routine antibiotic selection?","options":["Which box is easiest to reach?","Is there a likely infection, where is it, and how ill is the patient?","Which antibiotic has the longest name?","Can every cough be treated identically?"],"answer":1,"explain":["Convenience does not establish indication.","Correct. Indication and severity guide the next step.","Names do not guide clinical selection.","Cough has multiple possible causes."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q20","topic":"warfarin-dosing","domain":"Clinical Care","level":"Foundation","stem":"Which information is most useful before considering a warfarin dose change?","options":["One INR without history","Indication, prescribed target, regimen, recent doses and INR trend","The colour of the tablets alone","A neighbour’s dosing schedule"],"answer":1,"explain":["A single value lacks important context.","Correct. The decision requires patient-specific history and current guidance.","Appearance alone is insufficient.","Another patient’s schedule is not applicable."],"sources":[["Thrombosis Canada: Warfarin","https://thrombosiscanada.ca/clinical_guides/pdfs/WARFARIN_43.pdf"],["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"q21","topic":"hypertension","domain":"Clinical Care","level":"Foundation","stem":"A single clinic blood-pressure reading is unexpectedly high. What should be considered before a routine treatment decision?","options":["Measurement quality, symptoms and the broader pattern","Only the patient’s shoe size","Automatically doubling every medicine","Ignoring all high readings"],"answer":0,"explain":["Correct. Context and measurement quality affect interpretation, while concerning symptoms change urgency.","Shoe size does not inform this decision.","An automatic change is unsafe without assessment.","A high reading may require assessment and should not simply be dismissed."],"sources":[["Hypertension Canada guidelines","https://hypertension.ca/guidelines/"],["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"q22","topic":"diabetes","domain":"Clinical Care","level":"Foundation","stem":"Which approach best supports diabetes counselling?","options":["The same glucose target for everyone","Individual goals, hypoglycemia risk, technique and an agreed follow-up plan","Only explaining the brand name","Avoiding discussion of acute illness"],"answer":1,"explain":["Targets depend on patient context.","Correct. These connect treatment to safe daily use.","Brand identification alone does not teach use.","An appropriate sick-day plan is relevant to safety."],"sources":[["Diabetes Canada guidelines","https://www.diabetes.ca/for-professionals/full-guidelines"]]},{"id":"q23","topic":"routes-dosage-forms","domain":"Distribution","level":"Foundation","stem":"Before crushing a modified-release tablet, you should:","options":["Assume crushing has no effect","Check the exact product’s handling instructions and an appropriate alternative","Crush it if its colour is familiar","Use the advice for a different medicine"],"answer":1,"explain":["Altering the formulation can change release and exposure.","Correct. The exact product determines suitable handling.","Appearance does not establish formulation safety.","Advice for another product is not interchangeable."],"sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"q24","topic":"laboratory-interpretation","domain":"Knowledge & Expertise","level":"Foundation","stem":"Which is the strongest way to interpret a laboratory value?","options":["Using the number without units","Combining units, reference interval, timing, trend and patient context","Comparing it with a different test","Ignoring specimen quality"],"answer":1,"explain":["Units are essential to interpretation.","Correct. The value needs clinical and measurement context.","Different tests may measure different things.","Specimen problems can affect reliability."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q25","topic":"pregnancy-breastfeeding","domain":"Clinical Care","level":"Foundation","stem":"Which statement is best?","options":["Pregnancy and breastfeeding guidance are always identical","Essential medicines should always be stopped immediately","Assess exposure, timing, infant or pregnancy context and untreated illness using current references","Every medicine has zero uncertainty"],"answer":2,"explain":["The exposure and patient context differ.","Stopping treatment can also cause harm.","Correct. The assessment is specific to the medicine and situation.","Evidence often has uncertainty that should be discussed honestly."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"q26","topic":"medication-safety","domain":"Professionalism","level":"Foundation","stem":"A near miss should be viewed as:","options":["A chance to learn about a process vulnerability","Proof the process can never fail","A reason to hide the event","A substitute for all future checks"],"answer":0,"explain":["Correct. A prevented error can reveal conditions that need improvement.","One interception does not prove future safety.","Learning and reporting support improvement.","Other safeguards remain necessary."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"]]},{"id":"q27","topic":"pharmacokinetics-half-life","domain":"Knowledge & Expertise","level":"Foundation","stem":"In a simplified pharmacokinetic model, a loading dose is most closely related to:","options":["Only dosing interval","Target concentration and volume of distribution, adjusted for bioavailability","The number of refills","Only the medicine’s colour"],"answer":1,"explain":["Interval alone does not determine loading.","Correct. Maintenance dosing depends more directly on clearance and target exposure.","Refills do not determine distribution.","Colour does not determine dose."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q28","topic":"evidence-based-medicine-and-study-design","domain":"Knowledge & Expertise","level":"Foundation","stem":"A statistically significant treatment effect:","options":["Always matters greatly to patients","Must still be assessed for magnitude, uncertainty, harms and applicability","Proves there was no bias","Makes follow-up irrelevant"],"answer":1,"explain":["Statistical significance is not the same as clinical importance.","Correct. Statistical results are one component of a clinical decision.","Bias can remain despite a small p-value.","Follow-up affects interpretation of benefit and harm."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q29","topic":"diagnostic-test-interpretation","domain":"Knowledge & Expertise","level":"Foundation","stem":"Compared with a high-prevalence population, testing a low-prevalence population can lead to:","options":["A lower positive predictive value, other things being equal","No false positives ever","Automatic confirmation of every positive result","No need for clinical assessment"],"answer":0,"explain":["Correct. Fewer true cases among those tested can reduce the chance a positive result is a true positive.","False positives remain possible.","Confirmation needs depend on the test and context.","Clinical assessment remains important."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"q30","topic":"units-dose-calculations","domain":"Distribution","level":"Foundation","stem":"A fictional liquid contains 100 mg in 5 mL. What volume contains 150 mg?","options":["3 mL","5 mL","7.5 mL","15 mL"],"answer":2,"explain":["3 mL contains 60 mg at 20 mg/mL.","5 mL contains 100 mg.","Correct. 150 mg divided by 20 mg/mL is 7.5 mL.","15 mL contains 300 mg."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-e37c04968501","topic":"pediatric-dosing","domain":"Knowledge & Expertise","level":"Challenge","stem":"A fictional regimen is 24 mg/kg/day in three equal doses for a 15 kg child, with a 150 mg per-dose maximum. The liquid is 120 mg/5 mL. What is the calculated volume per dose?","options":["1.67 mL","5 mL","15 mL","6.25 mL"],"answer":1,"explain":["This divides the dose by three an extra time.","24 times 15 is 360 mg/day; divided by three is 120 mg/dose, below the maximum; 120 mg is 5 mL.","This gives the entire daily amount at each dose.","This uses the maximum rather than the calculated required dose."],"sources":[["Canadian Paediatric Society: current position statements","https://cps.ca/en/documents/statements-by-date"]]},{"id":"case-75d248e46ae4","topic":"units-dose-calculations","domain":"Knowledge & Expertise","level":"Challenge","stem":"A fictional infusion order is 2 micrograms/kg/min for a 60 kg model patient. The prepared concentration is 0.4 mg/mL. What rate follows mathematically?","options":["0.3 mL/hour","180 mL/hour","7200 mL/hour","18 mL/hour"],"answer":3,"explain":["This omits conversion from minutes to hours.","This introduces a tenfold error.","This fails to reconcile micrograms, milligrams and concentration.","120 micrograms/min equals 0.12 mg/min; divide by 0.4 and multiply by 60."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-5596d76f6e52","topic":"risk-benefit-nnt","domain":"Knowledge & Expertise","level":"Challenge","stem":"Over two years, an outcome occurs in 50 of 500 controls and 30 of 500 treated people. What is the NNT for that outcome over two years?","options":["40","4","20","25"],"answer":3,"explain":["Forty percent is the relative risk reduction, not NNT.","Four is the ARR in percentage points.","Twenty is the difference in observed event counts, not NNT.","Risks are 10% and 6%; ARR is 0.04 and NNT is 25."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-06bd3968f98c","topic":"diagnostic-test-interpretation","domain":"Knowledge & Expertise","level":"Challenge","stem":"In a hypothetical group of 1000 people, 100 have a disease. A test has 90% sensitivity and 90% specificity. What is the positive predictive value?","options":["10%","99%","50%","90%"],"answer":2,"explain":["This is the disease prevalence.","This is not supported by the two-by-two table.","There are 90 true positives and 90 false positives; 90 divided by 180 is 50%.","This confuses sensitivity or specificity with predictive value."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-e0cdd50f90f4","topic":"compounding","domain":"Distribution","level":"Challenge","stem":"For a fictional preparation, how much 20 mg/mL stock is needed to make 120 mL of 5 mg/mL solution?","options":["30 mL stock, diluted to 120 mL total","30 mL stock plus 120 mL diluent","120 mL stock","6 mL stock"],"answer":0,"explain":["Required drug is 600 mg; 600 divided by 20 is 30 mL.","The final volume would be too large.","That retains the stock concentration unless further diluted.","This contains only 120 mg, not the required 600 mg."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-8f275825b7c5","topic":"drug-interactions","domain":"Clinical Care","level":"Challenge","stem":"A patient stable on warfarin has an unexpected INR change after a new medicine and several missed doses. What is the best assessment approach?","options":["Ignore the result because the old regimen was stable","Review both the interaction and actual dosing history before choosing a plan","Attribute the entire change to the alert without asking about use","Use a universal dose change for every INR result"],"answer":1,"explain":["New exposure and adherence changes can alter risk.","Multiple contributors can affect INR; the clinical and bleeding context also matters.","The missed doses and other factors may be important.","Indication, degree of change and symptoms affect management."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-a074c555c5cb","topic":"renal-dose-adjustment","domain":"Clinical Care","level":"Challenge","stem":"A low-weight older adult with rapidly rising creatinine is prescribed a renally cleared medicine. Which approach is best?","options":["Use the drug-specific guidance while accounting for unstable function and body-size limitations","Treat a reported indexed eGFR as a universally interchangeable clearance","Assume the creatinine trend is irrelevant once a number is available","Halve every medicine automatically"],"answer":0,"explain":["No single stable estimate resolves all dosing uncertainty here.","Units, indexing and reference methods can differ.","Instability changes interpretation.","Adjustment depends on the specific medicine and context."],"sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"],["KDIGO: CKD evaluation and management","https://kdigo.org/guidelines/ckd-evaluation-and-management/"]]},{"id":"case-fe9e6bcc5c74","topic":"stroke-transient-ischemic-attack-tia","domain":"Clinical Care","level":"Application","stem":"A patient's sudden speech difficulty resolved after ten minutes. What is the best next step?","options":["Recommend an oral decongestant","Declare stroke excluded because speech recovered","Arrange urgent assessment for possible TIA","Wait for a second episode"],"answer":2,"explain":["It does not address possible cerebral ischaemia.","Symptom resolution does not exclude TIA.","Resolved symptoms can still signal a high-risk vascular event.","Waiting can miss an opportunity for urgent prevention."],"sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"case-d0c0d455a3d7","topic":"syncope","domain":"Clinical Care","level":"Application","stem":"Which feature makes a faint particularly concerning for a cardiac cause?","options":["Collapse during exertion","A familiar trigger followed by prompt recovery","Brief lightheadedness after standing in heat","Improvement when lying down"],"answer":0,"explain":["Exertional syncope warrants assessment for serious cardiac disease.","This may fit reflex syncope, though context still matters.","This suggests a different mechanism and is less specific for cardiac syncope.","This does not identify a cardiac cause by itself."],"sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"case-a480062edae0","topic":"dyslipidaemia","domain":"Clinical Care","level":"Application","stem":"A patient taking a statin reports severe muscle weakness and dark urine. What is most appropriate?","options":["Arrange prompt assessment for muscle injury","Reassure that all muscle symptoms are harmless","Double the statin because weakness suggests high cholesterol","Add an interacting medicine without review"],"answer":0,"explain":["This combination raises concern for serious muscle toxicity.","Severe symptoms require assessment.","These symptoms do not justify dose escalation.","Interactions can increase toxicity."],"sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"case-ddb0005fa301","topic":"dvt-and-pe","domain":"Clinical Care","level":"Application","stem":"A patient with a newly swollen leg develops unexplained breathlessness and pleuritic chest pain. What takes priority?","options":["Schedule routine compression-stocking fitting","Substitute aspirin for anticoagulant assessment","Advise walking until the pain resolves","Emergency evaluation for possible pulmonary embolism"],"answer":3,"explain":["This does not address possible PE.","Aspirin is not a substitute for evaluation and treatment of acute PE.","Exertion should not delay emergency evaluation.","The combination can indicate a life-threatening clot."],"sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"case-aa6415ec2895","topic":"atrial-fibrillation","domain":"Clinical Care","level":"Application","stem":"A patient with AF has good rate control. Which statement is correct?","options":["Every patient requires the same anticoagulant dose","Aspirin and anticoagulants are always interchangeable","Stroke-prevention assessment is still needed","A normal pulse removes the need for anticoagulation assessment"],"answer":2,"explain":["Dose and agent depend on patient and product factors.","They do not provide equivalent AF stroke prevention.","Rate control and embolic-stroke prevention have different goals.","Pulse control does not remove embolic risk."],"sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"case-a274d677a9ef","topic":"heart-failure","domain":"Clinical Care","level":"Application","stem":"In reduced-ejection-fraction heart failure, why is symptom relief from a diuretic not the entire treatment plan?","options":["Every heart-failure medicine has the same purpose","All other therapies must stop when oedema resolves","Other indicated therapies improve longer-term outcomes","Diuretics always eliminate the need for monitoring"],"answer":2,"explain":["Therapies target different mechanisms and outcomes.","Resolution of congestion does not erase their indications.","Congestion relief and disease modification have distinct roles.","Fluid, kidney and electrolyte monitoring remains important."],"sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"case-62e310591777","topic":"raynaud-s-phenomenon","domain":"Clinical Care","level":"Application","stem":"Which finding in a patient with cold-triggered finger colour changes needs prompt assessment?","options":["A clear cold-weather trigger alone","Normal colour between brief episodes","Persistent painful discoloration with an ulcer","Brief symmetric episodes that resolve with warming"],"answer":2,"explain":["A trigger does not itself indicate tissue damage.","This is less concerning than persistent ischaemia.","Tissue injury or ongoing ischaemia suggests a serious cause.","This pattern may fit uncomplicated Raynaud's."],"sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"case-95cbe5e0e627","topic":"acute-coronary-syndrome-and-stable-angina","domain":"Clinical Care","level":"Application","stem":"A patient prescribed nitroglycerin also uses sildenafil. What is the key concern?","options":["The products cancel each other's effect completely","Spacing every pair by ten minutes makes it safe","Sildenafil prevents acute coronary syndrome","Potentially severe hypotension from the combination"],"answer":3,"explain":["The concern is additive vasodilation, not cancellation.","Safe assessment depends on the exact drug and timing.","It does not remove the need for cardiac assessment.","Nitrates and PDE5 inhibitors can interact dangerously."],"sources":[["Canadian Cardiovascular Society: guideline library","https://ccs.ca/guidelines/"]]},{"id":"case-4f69c20051e5","topic":"sinusitis","domain":"Clinical Care","level":"Application","stem":"A patient has three days of nasal congestion and coloured discharge without red flags. Which interpretation is best?","options":["Failure to improve after one hour proves resistance","Discharge colour alone does not prove bacterial sinusitis","Green discharge always requires antibiotics","Any sinus symptom requires emergency transfer"],"answer":1,"explain":["This timeframe cannot establish antibiotic resistance.","Early symptoms are often viral and require context.","Colour is not a sufficient diagnostic criterion.","Urgency depends on severity and red flags."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-fb62a4e11249","topic":"meningitis","domain":"Clinical Care","level":"Application","stem":"Fever, severe headache and new confusion develop in a patient at the pharmacy. What is the priority?","options":["Offer a sedating antihistamine and observe overnight","Arrange emergency assessment","Complete a routine refill before discussing symptoms","Wait until neck stiffness appears"],"answer":1,"explain":["Sedation can obscure deterioration and does not treat the cause.","Possible meningitis or another serious illness needs urgent care.","Routine work must not delay urgent assessment.","The classic combination may be incomplete."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-6308b49c5b11","topic":"uti","domain":"Clinical Care","level":"Application","stem":"A patient with dysuria also has fever, flank pain and vomiting. What changes the assessment?","options":["Vomiting rules out urinary infection","Possible upper-tract infection requiring prompt evaluation","Urine symptoms now prove asymptomatic bacteriuria","Any cystitis medicine is equally suitable"],"answer":1,"explain":["Vomiting can accompany pyelonephritis.","These systemic and flank symptoms suggest more than simple cystitis.","The patient has symptoms.","Tissue penetration and severity affect treatment."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-e1e30ca25582","topic":"covid","domain":"Clinical Care","level":"Application","stem":"Before nirmatrelvir/ritonavir is dispensed, what is essential?","options":["Ask only about prescription pain medicines","Separate every interacting medicine by one hour","Assume over-the-counter products cannot interact","A complete interaction and kidney-function assessment"],"answer":3,"explain":["All relevant medicines and supplements matter.","Many interactions persist despite dose separation.","Nonprescription products can also affect safety.","Ritonavir can cause important interactions and dosing depends on renal context."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-c2cb8d577aa8","topic":"acute-otitis-media","domain":"Clinical Care","level":"Application","stem":"A caregiver asks for antibiotics because a child has ear pain. Which statement is best?","options":["Pain relief is unnecessary if antibiotics are used","Milligrams and millilitres are equivalent for all liquids","Diagnosis needs symptoms plus an appropriate ear assessment","Every earache is bacterial middle-ear infection"],"answer":2,"explain":["Pain management remains important.","Volume depends on the dispensed concentration.","Ear pain alone does not establish acute otitis media.","Several diagnoses cause ear pain."],"sources":[["Canadian Paediatric Society: acute otitis media","https://cps.ca/en/documents/position/acute-otitis-media"]]},{"id":"case-74287ff8866e","topic":"sepsis-septic-shock","domain":"Clinical Care","level":"Application","stem":"An infected patient becomes confused with very low blood pressure. What is the best action?","options":["Activate emergency care for possible sepsis or shock","Wait for fever before escalating","Recommend only oral rehydration at home","Delay care until all medicines are fully reconciled"],"answer":0,"explain":["Organ dysfunction and instability require urgent treatment.","Sepsis may occur without fever.","This is inadequate for a patient with possible shock.","A complete routine history must not delay emergency care."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-283aace977e1","topic":"diabetic-foot-infections","domain":"Clinical Care","level":"Application","stem":"Why might antibiotics alone fail to heal an infected diabetic foot ulcer?","options":["Pressure, perfusion and source control also matter","All ulcers are caused solely by antibiotic resistance","A positive swab always proves invasive infection","Neuropathy guarantees pain will reveal deterioration"],"answer":0,"explain":["Treating infection does not correct all contributors to wound failure.","Many nonmicrobial factors influence healing.","Colonization and infection differ.","Reduced sensation can mask serious problems."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-87ffc567f0c8","topic":"onychomycosis","domain":"Clinical Care","level":"Application","stem":"Why should a patient not expect a normal nail after a few days of antifungal treatment?","options":["A slow cosmetic response automatically requires double dosing","Healthy nail growth takes time","All antifungal therapy works within one day","A discoloured nail always proves fungal infection"],"answer":1,"explain":["Dose changes require assessment, not appearance alone.","Clinical appearance can improve slowly despite effective treatment.","This is unrealistic for nail disease.","Other conditions mimic onychomycosis."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-388b85e790f3","topic":"principles-of-infectious-disease","domain":"Clinical Care","level":"Application","stem":"Cultures identify a susceptible organism and the patient is improving on broad empiric therapy. What should be considered?","options":["Narrowing treatment to an appropriate targeted regimen","Continue the broadest regimen indefinitely","Ignore the culture because treatment already began","Add antibiotics solely to increase the number of covered organisms"],"answer":0,"explain":["Reassessment can reduce unnecessary antimicrobial exposure.","Indefinite broad treatment is not justified by initial empiric need.","Results can guide safer targeted therapy.","Additional coverage needs a clinical reason."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-b179cae1b3c6","topic":"tick-borne-infections","domain":"Clinical Care","level":"Application","stem":"What is the best approach after a tick bite without established illness?","options":["Give the same prophylaxis after every insect bite","Use a negative early antibody result to exclude all infection","Treat prophylaxis and established Lyme disease as identical regimens","Assess exposure details against current local prophylaxis criteria"],"answer":3,"explain":["Exposure and eligibility differ.","Early testing can be falsely reassuring.","Prevention and treatment have different indications and plans.","Prophylaxis is not indicated automatically after every bite."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-daee1b0afe10","topic":"fungal-infections","domain":"Clinical Care","level":"Application","stem":"An uncertain ring-like rash worsens during steroid-only treatment. What should happen next?","options":["Assume all rashes are allergic","Use an oral antifungal without checking interactions","Reassess the diagnosis, including possible fungal infection","Increase the steroid indefinitely without reassessment"],"answer":2,"explain":["Morphology and history need assessment.","Systemic antifungals can have substantial interactions.","Steroids can mask or aggravate some fungal eruptions.","This may worsen an unrecognized infection."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-f4a424790572","topic":"pep-occupational-infections","domain":"Clinical Care","level":"Application","stem":"After a needlestick, what is the most appropriate initial approach?","options":["Prompt exposure assessment and first aid through the designated pathway","Wait several days for every laboratory result","Assume the source is uninfected because they look well","Give the same prevention for HIV, hepatitis B and hepatitis C"],"answer":0,"explain":["Some prevention decisions are time sensitive.","Delay can reduce prevention options.","Appearance cannot establish infection status.","Their prevention and follow-up differ."],"sources":[["Public Health Agency of Canada: STBBI guidelines","https://www.canada.ca/en/public-health/services/infectious-diseases/sexual-health-sexually-transmitted-infections/canadian-guidelines.html"]]},{"id":"case-0ad5a5cd98bc","topic":"tuberculosis","domain":"Clinical Care","level":"Application","stem":"Why is a single antibiotic generally inappropriate for active TB disease?","options":["Symptom improvement means treatment can stop immediately","Rifamycin interactions are limited to food","Combination therapy is needed in an appropriate supervised regimen","TB infection and active disease always use the same regimen"],"answer":2,"explain":["Early improvement does not establish cure.","They can substantially affect other medicines.","Treatment must address efficacy and resistance risk.","They have different management needs."],"sources":[["Public Health Agency of Canada: Canadian Tuberculosis Standards","https://www.canada.ca/en/public-health/services/diseases/tuberculosis/health-professionals/canadian-tuberculosis-standards.html"]]},{"id":"case-b36f0a69207a","topic":"pharyngitis-bronchitis","domain":"Clinical Care","level":"Application","stem":"Which statement about an uncomplicated acute cough is most accurate?","options":["Drooling and stridor are routine self-care symptoms","Coloured sputum alone does not establish a bacterial indication","All productive coughs require antibiotics","A previous antibiotic prescription proves the same need now"],"answer":1,"explain":["They can signal an airway emergency.","Clinical context determines whether antibiotics are needed.","Many acute coughs are viral.","Each episode needs its own assessment."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-d285bae940f4","topic":"pneumonia","domain":"Clinical Care","level":"Application","stem":"Which finding most strongly supports urgent escalation in suspected pneumonia?","options":["A request for a specific antibiotic brand","Symptom onset after a common cold alone","New confusion with respiratory deterioration","A mild isolated cough with normal function"],"answer":2,"explain":["Preference does not determine clinical urgency.","The subsequent severity and findings matter.","This may indicate severe illness.","This alone is less indicative of severe pneumonia."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-8c3021d39dd1","topic":"influenza","domain":"Clinical Care","level":"Application","stem":"Which counselling point is appropriate for a child with a viral illness?","options":["Avoid aspirin-containing products unless specifically directed for another indication","Use adult combination products by guessing a smaller portion","Assume antivirals benefit every person equally","Ignore deterioration after initial improvement"],"answer":0,"explain":["Aspirin in viral illness is associated with serious risk in children.","Age, ingredients and dosing must be assessed.","Timing, severity and risk affect the decision.","Secondary complications may require reassessment."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-8ad6bda67cae","topic":"pep-prep","domain":"Clinical Care","level":"Application","stem":"What distinguishes HIV PEP from PrEP?","options":["PrEP can start without considering HIV status","Both eliminate the need for follow-up testing","PEP follows a possible exposure; PrEP addresses ongoing acquisition risk","PEP replaces emergency exposure assessment"],"answer":2,"explain":["Unrecognized infection changes management.","Testing and ongoing care remain necessary.","They are different preventive strategies.","Assessment is needed promptly."],"sources":[["Public Health Agency of Canada: STBBI guidelines","https://www.canada.ca/en/public-health/services/infectious-diseases/sexual-health-sexually-transmitted-infections/canadian-guidelines.html"]]},{"id":"case-1804e03bdd24","topic":"sexually-transmitted-infections","domain":"Clinical Care","level":"Application","stem":"What is the best basis for selecting sites for STI testing?","options":["Relevant anatomy, exposures, symptoms and current guidance","Gender identity alone","Only the patient's age","The last antibiotic taken"],"answer":0,"explain":["Testing should match the person's actual clinical context.","Identity does not specify exposure sites or anatomy.","Age alone is insufficient.","Prior therapy is relevant but does not determine all testing sites."],"sources":[["Public Health Agency of Canada: STBBI guidelines","https://www.canada.ca/en/public-health/services/infectious-diseases/sexual-health-sexually-transmitted-infections/canadian-guidelines.html"]]},{"id":"case-9f067502706a","topic":"herpes-simplex-virus","domain":"Clinical Care","level":"Application","stem":"Which statement about suppressive herpes therapy is correct?","options":["It makes painful eye symptoms suitable for routine self-care","It can reduce recurrences but does not eradicate latent virus","It proves every later lesion is a new acquisition","It removes all transmission risk"],"answer":1,"explain":["Eye involvement needs prompt assessment.","Control is different from eliminating infection.","Recurrence can arise from latent infection.","Risk is not reduced to zero."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-d08a065aef71","topic":"osteomyelitis-skin-and-soft-tissue-infections","domain":"Clinical Care","level":"Application","stem":"A skin infection spreads rapidly with pain out of proportion and systemic illness. What takes priority?","options":["Urgent assessment for a deep or surgical infection","Routine topical treatment and a review next month","Wait for visible pus before referring","Assume severe pain means only anxiety"],"answer":0,"explain":["These are red flags for serious tissue infection.","This would delay needed care.","Serious deep infection may not present as a simple abscess.","The clinical red flags require assessment."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-97a7793718b3","topic":"otitis-externa","domain":"Clinical Care","level":"Application","stem":"Why must tympanic-membrane status be considered before selecting ear drops?","options":["The bottle colour identifies safety in perforation","Some products are unsuitable when the middle ear may be exposed","All ear drops are interchangeable","A perforation prevents every adverse effect"],"answer":1,"explain":["Safety depends on the formulation and evidence.","Perforation or tubes affect product safety.","Ingredients and indications differ.","It can increase exposure to sensitive structures."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-131f9638560b","topic":"intra-abdominal-infections","domain":"Clinical Care","level":"Application","stem":"Why might an abdominal infection need a procedure as well as antibiotics?","options":["A familiar oral antibiotic excludes perforation","An uncontrolled source may need drainage or surgery","All abdominal pain needs surgery","Source control makes all medication assessment unnecessary"],"answer":1,"explain":["Medication familiarity does not establish the diagnosis.","Antibiotics alone cannot always correct the underlying source.","The decision depends on the diagnosis.","Antimicrobial and supportive care may still be required."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-f25ec9a8b4a4","topic":"viral-hepatitis","domain":"Clinical Care","level":"Application","stem":"Which statement is correct?","options":["Hepatitis B immunity is irrelevant before every immunosuppressive regimen","Confusion in worsening liver disease is routine self-care","Hepatitis C has effective curative regimens for many patients but no vaccine","All viral hepatitis has the same treatment"],"answer":2,"explain":["Reactivation risk may affect care.","It can indicate severe decompensation.","Prevention and treatment options differ by virus.","Virus and disease stage change management."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-bef2464ef94a","topic":"croup","domain":"Clinical Care","level":"Application","stem":"A child has stridor at rest, increasing work of breathing and exhaustion. What is the best action?","options":["Force a prolonged throat inspection at the counter","Give an adult sedating cough medicine","Arrange urgent emergency assessment while keeping the child calm","Use hot steam and wait overnight"],"answer":2,"explain":["Distress can worsen airway difficulty.","It does not address the airway problem and adds risk.","These signs suggest significant airway compromise.","Steam is not a substitute and may cause burns."],"sources":[["Canadian Paediatric Society: acute croup management","https://cps.ca/en/documents/position/acute-management-of-croup"]]},{"id":"case-f80ef1415ff5","topic":"infective-endocarditis","domain":"Clinical Care","level":"Application","stem":"A patient asks whether every heart murmur needs antibiotics before dental care. What is correct?","options":["Prophylaxis depends on specific cardiac conditions and procedures","Every murmur requires lifelong antibiotics","No cardiac condition ever needs prophylaxis","Leftover antibiotics are adequate for any dental procedure"],"answer":0,"explain":["A murmur alone does not define eligibility.","This is not an appropriate universal rule.","Some high-risk situations do qualify.","Agent, timing and indication must be appropriately assessed."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-7062c5b79cd0","topic":"pruritus-itch","domain":"Clinical Care","level":"Application","stem":"An older adult has generalized itch without a primary rash. What is the best approach?","options":["Assess medicines and possible systemic causes","Automatically add a strongly sedating antihistamine","Diagnose fungal infection solely from itching","Assume a normal-looking skin surface excludes illness"],"answer":0,"explain":["Itch may reflect more than dry skin or allergy.","This adds fall and cognitive risk and may miss the cause.","Itch alone is nonspecific.","Systemic causes may lack a primary rash."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-18da5cc7cd74","topic":"acne","domain":"Clinical Care","level":"Application","stem":"Why should topical antibiotic monotherapy generally be avoided for acne?","options":["It promotes unnecessary resistance risk and is not an optimal long-term strategy","Every topical antibiotic is ineffective in every situation","Benzoyl peroxide always requires oral antibiotics","Improvement must occur after the first application"],"answer":0,"explain":["Combination and duration should follow an appropriate acne plan.","They can have a role in appropriate combinations.","That is not a universal requirement.","Acne therapy generally takes weeks."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-8362abd11d6a","topic":"psoriasis","domain":"Clinical Care","level":"Application","stem":"A patient with psoriasis develops persistently swollen painful finger joints. What is appropriate?","options":["Assume it is age-related wear without assessment","Assessment for possible psoriatic arthritis","Treat only the skin because psoriasis cannot affect joints","Apply a stronger skin steroid to replace joint assessment"],"answer":1,"explain":["The inflammatory context matters.","Joint involvement can need disease-modifying care.","Psoriasis can be associated with inflammatory arthritis.","Topical treatment does not address the joint problem."],"sources":[["NICE (UK): Psoriasis guidance; apply Canadian context","https://www.nice.org.uk/guidance/cg153/chapter/recommendations"]]},{"id":"case-6d6d42a8292d","topic":"burns-and-sunburns","domain":"Clinical Care","level":"Application","stem":"Which initial approach is appropriate for a recent minor thermal burn?","options":["Apply ice directly for a prolonged period","Cover immediately with butter","Ignore location and depth if the area is small","Appropriate cool running water and assessment of severity"],"answer":3,"explain":["Ice can injure tissue.","Household remedies can interfere with proper care.","Some small burns involve critical areas or deeper injury.","Cooling and triage are preferable to unproven remedies."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-55148c613e9e","topic":"rosacea","domain":"Clinical Care","level":"Application","stem":"Which symptom in a patient with facial rosacea warrants prompt eye assessment?","options":["Stable mild flushing after a known trigger","A preference for a different moisturizer","Slow improvement of facial redness","Eye pain with visual change"],"answer":3,"explain":["This does not have the same urgency.","Preference alone is not an ocular red flag.","This may need review but does not equal acute visual risk.","Ocular involvement can threaten vision."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-048b39ba3008","topic":"lice-scabies","domain":"Clinical Care","level":"Application","stem":"Itch persists shortly after correctly completed scabies treatment. What is best?","options":["Assess new lesions, application and re-exposure before retreating","Repeat insecticide indefinitely without review","Assume every household member is cured without assessment","Conclude that persistent itch always proves resistance"],"answer":0,"explain":["Post-treatment itch does not automatically prove active infestation.","This can cause harm and miss another cause.","Contact management must be coordinated.","Several explanations are possible."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-e941fdb30dba","topic":"atopic-dermatitis","domain":"Clinical Care","level":"Application","stem":"A caregiver fears all topical steroids. What is the best counselling approach?","options":["Promise that every steroid can be used anywhere indefinitely","Advise avoiding all anti-inflammatory treatment","Give antibiotics for every flare instead","Explain the prescribed potency, site, amount and duration"],"answer":3,"explain":["Potency, site and duration matter.","Uncontrolled inflammation also causes harm.","Antibiotics are not routine flare treatment without an indication.","Specific correct-use teaching balances benefit and harm."],"sources":[["NICE (UK): Atopic Dermatitis guidance; apply Canadian context","https://www.nice.org.uk/guidance/cg57/chapter/recommendations"]]},{"id":"case-5a39da53abb5","topic":"attention-deficit-hyperactivity-disorder-adhd","domain":"Clinical Care","level":"Application","stem":"Two modified-release stimulant products have the same milligram strength. What should be checked before substitution?","options":["Only whether both names contain the same ingredient","Nothing because all modified-release products match","Release characteristics and product-specific equivalence","Only the package colour"],"answer":2,"explain":["Formulation differences can still matter.","This assumption can change symptom control or adverse effects.","Equal milligrams do not guarantee an equivalent exposure pattern.","Colour is not evidence of equivalence."],"sources":[["NICE (UK): Attention Deficit Hyperactivity Disorder (ADHD) guidance; apply Canadian context","https://www.nice.org.uk/guidance/ng87/chapter/recommendations"]]},{"id":"case-68b8f1b24818","topic":"dementia","domain":"Clinical Care","level":"Application","stem":"A person with established dementia becomes acutely confused and fluctuates through the day. What should be considered?","options":["Delirium and reversible causes","Inevitable dementia progression with no assessment","Automatic antipsychotic escalation","Stopping all medicines without a plan"],"answer":0,"explain":["An acute change needs a medical assessment.","The time course suggests a potentially reversible problem.","The cause and safety must be assessed first.","This may create additional harm."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-7dc23ab4a0a9","topic":"insomnia","domain":"Clinical Care","level":"Application","stem":"Which approach best supports persistent insomnia management?","options":["Increase sedatives after every poor night","Combine alcohol with a sleeping tablet","Abruptly stop a long-used benzodiazepine","Assess contributors and offer an appropriate CBT-I pathway"],"answer":3,"explain":["This can escalate harm without addressing causes.","Combined sedation can be dangerous.","Withdrawal needs an individualized plan.","Long-term care addresses behaviour and maintaining factors."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-06e457fc0be8","topic":"eating-disorders","domain":"Clinical Care","level":"Application","stem":"A patient with an eating disorder has a weight within a common reference range. Which statement is correct?","options":["Only appearance determines referral urgency","Rapid nutritional restoration never needs monitoring","Medical instability can still be present","Normal-range weight excludes electrolyte problems"],"answer":2,"explain":["Symptoms and clinical findings matter.","Refeeding risk requires assessment.","Body size alone does not establish safety.","Restriction or purging can still cause abnormalities."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-5530012821c4","topic":"schizophrenia","domain":"Clinical Care","level":"Application","stem":"A person taking clozapine reports severe constipation and abdominal distension. What is the best action?","options":["Reassure that constipation is always trivial","Wait until the next routine blood count","Double clozapine to improve bowel function","Prompt clinical assessment"],"answer":3,"explain":["Severity and distension are concerning.","Blood monitoring does not replace symptom assessment.","This is not an appropriate response and may worsen risk.","Severe gastrointestinal hypomotility can be serious."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-2d6549c8dd78","topic":"acute-agitation","domain":"Clinical Care","level":"Application","stem":"What is a sound first principle when a patient is acutely agitated?","options":["Assume every case is a primary psychiatric relapse","Escalate the confrontation to establish control","Choose a sedative without considering breathing or intoxication","Prioritize safety and assess reversible medical causes"],"answer":3,"explain":["Medical causes must be considered.","This can worsen risk.","Clinical context and monitoring are essential.","Agitation may reflect delirium, pain or another medical problem."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-039ea593b7d8","topic":"anxiety-and-related-disorders","domain":"Clinical Care","level":"Application","stem":"A patient with an anxiety history develops new exertional chest pain. What is most appropriate?","options":["Assume a previous normal assessment guarantees current safety","Assess for a possible medical cause","Label it panic without assessment","Recommend extra benzodiazepine as the only response"],"answer":1,"explain":["New symptoms require their own evaluation.","Anxiety history does not exclude cardiac illness.","This may miss a serious new problem.","It does not establish or treat the cause."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-c953d6b695db","topic":"bipolar-disorder","domain":"Clinical Care","level":"Application","stem":"Why ask about previous mania before treating depressive symptoms?","options":["Mania history only affects the choice of pharmacy","Any depression excludes bipolar disorder","A single antidepressant is universally appropriate","It can change the diagnosis and treatment strategy"],"answer":3,"explain":["It has direct clinical implications.","Depression can occur in bipolar illness.","Antidepressant monotherapy is generally unsuitable in bipolar I depression.","Bipolar depression differs from unipolar depression."],"sources":[["NICE (UK): Bipolar Disorder guidance; apply Canadian context","https://www.nice.org.uk/guidance/cg185/chapter/recommendations"]]},{"id":"case-ae4d44893ef3","topic":"depression","domain":"Clinical Care","level":"Application","stem":"An antidepressant was started a few days ago without clear benefit. What is usually most appropriate if there are no urgent concerns?","options":["Double the dose independently","Stop all follow-up until several months pass","Review expectations, tolerability and the planned follow-up","Declare every antidepressant ineffective"],"answer":2,"explain":["Changes require a clinical plan.","Early monitoring of safety and adherence remains important.","Benefit often takes time; early safety still needs assessment.","A few days is generally insufficient to assess the class."],"sources":[["NICE (UK): Depression guidance; apply Canadian context","https://www.nice.org.uk/guidance/ng222/chapter/recommendations"]]},{"id":"case-4f64c7f6635f","topic":"nausea-vomiting","domain":"Clinical Care","level":"Application","stem":"Which presentation requires prompt assessment rather than routine antiemetic advice?","options":["Mild motion-related symptoms that resolve after travel","Coffee-ground vomit with dizziness","Brief mild nausea with preserved intake","A dislike of a tablet flavour alone"],"answer":1,"explain":["This pattern differs from possible bleeding.","This can indicate GI bleeding.","Context matters, but this is less alarming.","Preference is not a bleeding red flag."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-8ec70d660453","topic":"ulcerative-colitis-crohn-s-disease","domain":"Clinical Care","level":"Application","stem":"Why is long-term corticosteroid use not the default maintenance strategy for IBD?","options":["Analgesics alone prevent inflammatory bowel damage","Every worsening symptom proves an inflammatory flare","Maintenance needs a suitable disease-control plan with less steroid harm","Steroids cannot improve any IBD flare"],"answer":2,"explain":["They do not replace disease-directed therapy.","Infection and other causes must also be considered.","Induction and maintenance have different roles.","They can have an induction role."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-5b5005303f82","topic":"women-s-health","domain":"Clinical Care","level":"Application","stem":"Which symptom requires evaluation after menopause?","options":["Stable symptoms already assessed with a follow-up plan","New vaginal bleeding","A request to discuss hot-flush treatment","A preference for nonhormonal therapy"],"answer":1,"explain":["New changes drive reassessment.","It should not be assumed to be a harmless hormonal change.","This needs counselling but is not the same red flag.","Preference guides shared decisions."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-3b9beaf9e254","topic":"dyspepsia-gerd-peptic-ulcer-disease","domain":"Clinical Care","level":"Application","stem":"A patient with reflux develops progressive difficulty swallowing. What is appropriate?","options":["Ignore the symptom if heartburn improves","Medical evaluation for an alarm symptom","Keep increasing an OTC dose without assessment","Assume all swallowing problems are reflux"],"answer":1,"explain":["Improved heartburn does not resolve the alarm feature.","Dysphagia requires assessment beyond routine acid suppression.","This may delay diagnosis.","Other serious causes are possible."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-ae05c3dd65e0","topic":"medical-abortion","domain":"Clinical Care","level":"Application","stem":"Which statement is essential in medication-abortion counselling?","options":["All severe persistent pain is expected and can be ignored","The drug sequence can be improvised from memory","The regimen does not treat ectopic pregnancy","Follow-up is unnecessary if bleeding starts"],"answer":2,"explain":["Such pain can signal a complication.","The current prescribed protocol must be followed.","Severe or concerning symptoms need appropriate assessment.","Bleeding alone does not establish completion."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-359276ff163c","topic":"pancreatitis","domain":"Clinical Care","level":"Application","stem":"Which statement about acute pancreatitis is correct?","options":["Every case is a bacterial infection","Severe persistent pain is routine pharmacy self-care","All pancreatic enzyme products can be crushed freely","Antibiotics are not routine for uncomplicated sterile inflammation"],"answer":3,"explain":["Pancreatic inflammation is not automatically infection.","It needs medical evaluation.","Formulation-specific instructions matter.","Their use requires an appropriate indication."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-021ae25f1dac","topic":"ibs","domain":"Clinical Care","level":"Application","stem":"A patient with IBS now has blood in stool and unexplained weight loss. What is best?","options":["Start a highly restrictive diet as the only action","Increase antidiarrhoeal medicine indefinitely","Reassess for another or additional diagnosis","Assume these are expected IBS symptoms"],"answer":2,"explain":["This can delay diagnosis and worsen nutrition.","The cause needs assessment first.","Alarm features are not explained away by the prior label.","They require investigation."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-9599e3cfe6fb","topic":"constipation","domain":"Clinical Care","level":"Application","stem":"Which situation makes an automatic fibre recommendation inappropriate?","options":["Mild dietary fibre insufficiency without alarm features","A desire to improve bowel routine","Ability to maintain suitable hydration","Severe abdominal pain and vomiting suggesting obstruction"],"answer":3,"explain":["Gradual fibre adjustment may be useful here.","This can support self-care discussion.","This does not itself contraindicate fibre.","Possible obstruction requires assessment."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-7e53d8b1df0d","topic":"contraception","domain":"Clinical Care","level":"Application","stem":"A patient misses oral contraceptive doses. Which advice is safest?","options":["Assume enzyme-inducing medicines never matter","Assume pregnancy prevention also provides STI protection","Use the exact product's missed-dose and backup guidance","Apply one universal rule to every contraceptive"],"answer":2,"explain":["They can reduce some contraceptives' effectiveness.","Most contraceptive methods do not protect against STIs.","Instructions vary by formulation and circumstances.","Methods and missed-dose situations differ."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-32a14ca217d0","topic":"benign-prostatic-hyperplasia","domain":"Clinical Care","level":"Application","stem":"A patient taking an alpha blocker is scheduled for cataract surgery. What should be communicated?","options":["Nothing if the medicine was stopped recently","An instruction to cancel all surgery permanently","Current or prior alpha-blocker use to the eye surgeon","Only the tablet colour"],"answer":2,"explain":["Prior exposure can still be relevant.","The surgical team should assess the situation.","This history can affect surgical planning.","The specific medicine history matters."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-f792d6c41cae","topic":"urinary-incontinence","domain":"Clinical Care","level":"Application","stem":"Why distinguish urge from overflow incontinence before choosing therapy?","options":["Every bladder medicine is free of systemic effects","The mechanisms and appropriate treatments differ","All leakage has the same cause","Age alone identifies the mechanism"],"answer":1,"explain":["Cognitive, bowel and cardiovascular effects can matter.","A generic bladder treatment may be unsuitable.","The differential affects care.","Assessment is still required."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-557c9f99acff","topic":"menopause","domain":"Clinical Care","level":"Application","stem":"Which counselling statement is correct?","options":["All vaginal and systemic products have identical purposes","Systemic estrogen never requires endometrial protection","New postmenopausal bleeding never needs assessment","Menopausal hormone therapy is not contraception"],"answer":3,"explain":["Routes and exposures differ.","People with a uterus generally need appropriate protection.","It is an important symptom to investigate.","Pregnancy prevention needs a separate assessment when relevant."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-4c8f64d8102a","topic":"erectile-dysfunction","domain":"Clinical Care","level":"Application","stem":"Which concurrent therapy is a major concern with a PDE5 inhibitor?","options":["Nitrates","A bland moisturizer","An oral rehydration solution alone","A nonmedicated dressing"],"answer":0,"explain":["The combination can cause severe hypotension.","It is not a comparable systemic interaction.","This is not the major contraindicating combination.","It does not produce the nitrate interaction."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-03ef246fa42d","topic":"reproductive-health","domain":"Clinical Care","level":"Application","stem":"What is the best basis for reproductive-health counselling?","options":["Avoiding confidentiality discussions","The patient's anatomy, goals, exposures and medicines","Assumptions based only on gender identity","Stopping all essential medicines immediately"],"answer":1,"explain":["Privacy and consent are central.","Relevant clinical information should guide care.","Identity does not determine every reproductive need.","Untreated disease can also cause harm."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-09880c5b31f8","topic":"upper-gi-bleeding","domain":"Clinical Care","level":"Application","stem":"Black tarry stool with faintness develops in an anticoagulated patient. What takes priority?","options":["Assume iron explains every dark stool","Independently set a permanent anticoagulant stop date","Recommend an antacid as the only intervention","Urgent assessment for possible bleeding"],"answer":3,"explain":["That assumption can miss bleeding.","The clinical team must balance bleeding and thrombosis.","This does not address possible haemorrhage.","The symptoms may indicate significant GI blood loss."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-f8f34be9f471","topic":"drugs-in-pregnancy-lactation","domain":"Clinical Care","level":"Application","stem":"Which factor is important when evaluating breastfeeding medicine exposure?","options":["Infant age and prematurity as well as the specific medicine","Only whether the product is natural","The pregnancy label alone","Assuming every detectable milk concentration is harmful"],"answer":0,"explain":["Infant vulnerability and exposure change risk.","Natural does not establish safety.","Pregnancy and lactation assessments differ.","Risk depends on the amount, drug and infant context."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-5af4906e762b","topic":"hepatic-encephalopathy","domain":"Clinical Care","level":"Application","stem":"A patient taking lactulose has excessive diarrhoea and dizziness. What is best?","options":["Assess treatment solely from an ammonia number","Add sedatives to suppress the symptoms","Review the regimen and hydration against the prescribed stool goal","Encourage unlimited diarrhoea as the treatment goal"],"answer":2,"explain":["Clinical status and precipitating factors matter.","Sedation can complicate assessment and safety.","Overtreatment can worsen fluid and electrolyte problems.","That can cause harm."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-b070d74ac565","topic":"diarrhoea","domain":"Clinical Care","level":"Application","stem":"Which feature makes routine antimotility self-treatment inappropriate without assessment?","options":["Bloody diarrhoea with fever and severe pain","A brief mild episode with good fluid intake","An interest in oral rehydration","A need to review recent dietary triggers"],"answer":0,"explain":["Invasive disease or another serious cause may be present.","This may be suitable for assessed self-care.","Rehydration is often appropriate.","This is part of assessment, not a contraindication by itself."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-739f59173a5c","topic":"opioid-and-alcohol-use-disorder","domain":"Clinical Care","level":"Application","stem":"A patient restarts an old opioid dose after weeks without opioids. What is a key risk?","options":["Alcohol prevents opioid respiratory depression","Loss of tolerance can increase overdose risk","Tolerance always remains unchanged","Naloxone makes any opioid dose safe"],"answer":1,"explain":["Alcohol can worsen respiratory depression.","A previous dose may no longer be tolerated.","It can decline during abstinence.","It is emergency treatment, not a guarantee."],"sources":[["BC Centre on Substance Use: clinical guidance","https://www.bccsu.ca/clinical-care-guidance/"],["BC Centre on Substance Use: opioid use disorder guideline","https://www.bccsu.ca/opioid-use-disorder/"]]},{"id":"case-854b7a878229","topic":"bell-palsy-and-gbs","domain":"Clinical Care","level":"Application","stem":"Progressive ascending weakness with new swallowing difficulty develops. What is appropriate?","options":["Routine self-care for muscle strain","Wait for complete paralysis","Use facial moisturizers as the primary treatment","Urgent hospital assessment for possible GBS or another serious cause"],"answer":3,"explain":["This misses neurological red flags.","Delay can endanger breathing.","They do not address progressive generalized weakness.","Respiratory and bulbar involvement may progress rapidly."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-61e513d1b25e","topic":"cannabis","domain":"Clinical Care","level":"Application","stem":"Why can repeated oral cannabis dosing before the first effect be risky?","options":["Oral products always act instantly","Legal products cannot cause impairment","CBD and THC are interchangeable in all effects","Oral effects can be delayed and prolonged"],"answer":3,"explain":["Their onset is often delayed.","Legality does not remove pharmacological risk.","Their effects and products differ.","Early redosing may produce excessive exposure."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-4c99dc2f7399","topic":"parkinson-s-disease","domain":"Clinical Care","level":"Application","stem":"Which hospital medication change needs particular attention?","options":["Moving all levodopa doses to routine ward times","Preserving the verified home schedule","Checking the exact formulation","Assessing swallowing ability"],"answer":0,"explain":["The patient's individualized timing may be essential.","This supports continuity when clinically appropriate.","This is a useful safety step.","This is necessary for appropriate administration."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-39fcfba569ac","topic":"headaches-migraines","domain":"Clinical Care","level":"Application","stem":"Which headache pattern is an emergency red flag?","options":["A stable familiar pattern already assessed","A diary showing the same known trigger","Mild symptoms relieved by an established plan","A sudden thunderclap headache"],"answer":3,"explain":["A stable pattern differs from a sudden new severe presentation.","The trigger alone does not establish an emergency.","Urgency depends on the broader context.","This can indicate a serious acute intracranial cause."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-316daf7d4f1e","topic":"pain-management-palliative-care","domain":"Clinical Care","level":"Application","stem":"Why does opioid rotation need more than an arithmetic equianalgesic conversion?","options":["All opioids have identical kinetics","Kidney function never matters","Sedation does not affect the plan","Incomplete cross-tolerance and patient factors affect safety"],"answer":3,"explain":["They differ in exposure, metabolites and effects.","Accumulation may alter safety.","Sedation can be an important toxicity signal.","A calculated equivalent is not automatically a safe starting dose."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-d4c9afa8c20f","topic":"chronic-spasticity","domain":"Clinical Care","level":"Application","stem":"An intrathecal baclofen pump may have stopped and the patient develops severe worsening with fever. What is best?","options":["Emergency assessment for possible withdrawal or another serious cause","Wait until the next routine refill appointment","Treat only with a moisturizer","Assume baclofen withdrawal is always mild"],"answer":0,"explain":["Interruption can cause dangerous withdrawal.","Delay may be dangerous.","This does not address systemic deterioration.","Severe withdrawal can be life threatening."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-f6d4fe1449fc","topic":"multiple-sclerosis","domain":"Clinical Care","level":"Application","stem":"An MS patient's old symptoms worsen during a urinary infection. What should be considered?","options":["Automatic discontinuation of all disease-modifying therapy","Ignoring the infection","Infection-related temporary worsening as well as relapse","Every deterioration proves a new inflammatory relapse"],"answer":2,"explain":["Stopping may create additional risk.","Treating the trigger is part of appropriate care.","The cause needs assessment before changing disease therapy.","Other triggers can worsen symptoms."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-afd180a41de8","topic":"restless-leg-syndrome","domain":"Clinical Care","level":"Application","stem":"On dopaminergic treatment, leg symptoms begin earlier each day and spread. What should be considered?","options":["That iron status can never be relevant","Augmentation requiring reassessment","Automatic repeated dose escalation","A guarantee of improved disease control"],"answer":1,"explain":["Iron assessment may be important.","Treatment can paradoxically shift or worsen the symptom pattern.","This may worsen augmentation.","The pattern suggests the opposite."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-7f94b5b0aefe","topic":"chronic-fatigue-syndrome","domain":"Clinical Care","level":"Application","stem":"Which activity approach is appropriate in ME/CFS?","options":["Assuming every new symptom is already explained","Individualized energy management respecting post-exertional worsening","Fixed activity increases regardless of deterioration","Calling fatigue a lack of motivation"],"answer":1,"explain":["New findings still need assessment.","Plans should respond to symptoms and limits.","This disregards characteristic symptom worsening.","This is inaccurate and undermines care."],"sources":[["NICE (UK): Chronic Fatigue Syndrome guidance; apply Canadian context","https://www.nice.org.uk/guidance/ng206/chapter/recommendations"]]},{"id":"case-120824254951","topic":"drug-withdrawal-syndromes","domain":"Clinical Care","level":"Application","stem":"Which statement about tapering is correct?","options":["Withdrawal only occurs with illegal substances","Every rebound symptom proves the original disease is worsening","The plan depends on the medicine and patient","All medicines can stop abruptly"],"answer":2,"explain":["Prescribed medicines can also cause it.","Withdrawal and recurrence may overlap.","There is no universal taper schedule.","Some withdrawals are dangerous."],"sources":[["BC Centre on Substance Use: clinical guidance","https://www.bccsu.ca/clinical-care-guidance/"]]},{"id":"case-ce6f00d9abcc","topic":"seizures","domain":"Clinical Care","level":"Application","stem":"During a convulsive seizure, which action is appropriate?","options":["Restrain all limb movements","Give oral tablets while consciousness is impaired","Protect the person from injury and time the event","Put a spoon into the mouth"],"answer":2,"explain":["Restraint can cause harm.","This creates aspiration risk.","Safety and duration guide the emergency response.","This can injure the person."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-87910124a04e","topic":"gout","domain":"Clinical Care","level":"Application","stem":"A patient with gout asks whether a flare means established urate-lowering therapy should automatically stop. What is correct?","options":["Colchicine has no serious interactions","Do not routinely stop it without clinical direction","Every flare proves the drug is toxic","All hot swollen joints can be assumed to be gout"],"answer":1,"explain":["Important toxicity-producing interactions exist.","Acute inflammation and long-term urate control are different goals.","Flares can occur for several reasons.","Septic arthritis must be considered."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-370b717f19d1","topic":"rheumatoid-arthritis","domain":"Clinical Care","level":"Application","stem":"Methotrexate for RA is labelled once weekly, but a prepared label says daily. What is the priority?","options":["Treat folic acid as a substitute for resolving the error","Hold dispensing and resolve the frequency discrepancy","Dispense because the milligram strength matches","Ask the patient to choose a schedule"],"answer":1,"explain":["Folate does not make an incorrect daily schedule safe.","Daily-versus-weekly errors can be fatal.","Correct strength does not correct wrong frequency.","The verified prescribed regimen must be established."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-33d900abc308","topic":"osteoporosis","domain":"Clinical Care","level":"Application","stem":"A patient plans to stop denosumab because appointments are inconvenient. What is important?","options":["A good recent scan guarantees no future fracture","Arrange a clinician-directed continuation or follow-on plan","Stopping never requires follow-up","Calcium alone always replaces every antiresorptive"],"answer":1,"explain":["Risk assessment is broader than one scan.","Unplanned discontinuation can increase fracture risk.","Rebound risk matters.","Replacement needs an individualized plan."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-1a331edecd1b","topic":"msk-pain","domain":"Clinical Care","level":"Application","stem":"Which OTC review is important before recommending an oral NSAID?","options":["Only the patient's preferred colour","Assume two NSAID brands are safe together","Kidney, GI bleeding and cardiovascular risks plus concurrent medicines","Only whether the brand is familiar"],"answer":2,"explain":["This does not assess risk.","Duplicate NSAID exposure can increase harm.","These factors can change suitability.","Familiarity does not establish safety."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-4b4de640b80f","topic":"systemic-lupus-erythematosus","domain":"Clinical Care","level":"Application","stem":"A patient on immunosuppression develops fever and worsening fatigue. What is best?","options":["Stop all therapy permanently at the counter","Assess infection as well as a lupus flare","Automatically increase steroids without assessment","Assume all fever is a harmless drug effect"],"answer":1,"explain":["A coordinated clinical plan is needed.","The presentations can overlap.","This can worsen an unrecognized infection.","Serious infection must be considered."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-20d80b590032","topic":"polymyalgia-rheumatica-giant-cell-arteritis","domain":"Clinical Care","level":"Application","stem":"An older person with shoulder stiffness develops jaw pain on chewing and visual change. What takes priority?","options":["Urgent assessment for possible giant cell arteritis","A routine analgesic trial for several weeks","Reassurance that PMR never affects related arteries","A stronger topical muscle cream as the only action"],"answer":0,"explain":["Prompt treatment may protect vision.","Delay can risk irreversible visual loss.","Giant cell arteritis can coexist.","It does not address the vascular emergency."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-1131ea7c6618","topic":"osteoarthritis","domain":"Clinical Care","level":"Application","stem":"Which outcome is useful when reviewing osteoarthritis treatment?","options":["Only the radiograph appearance","Number of medicines prescribed","Whether the strongest analgesic was chosen","Improvement in meaningful daily function and pain"],"answer":3,"explain":["Imaging and symptoms do not always match.","More medicines do not establish better care.","Intensity alone does not determine suitability.","Patient goals help judge benefit against harm."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-05fb796e09bd","topic":"fibromyalgia","domain":"Clinical Care","level":"Application","stem":"Which statement supports appropriate fibromyalgia care?","options":["All widespread pain requires opioid escalation","New focal weakness can always be ignored","Only complete pain elimination counts as benefit","Normal routine inflammatory tests do not make the symptoms unreal"],"answer":3,"explain":["Treatment should be individualized and multimodal.","New findings need reassessment.","Function and achievable symptom goals also matter.","Assessment and supportive treatment remain appropriate."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-a69d2744db23","topic":"hypothyroidism","domain":"Clinical Care","level":"Application","stem":"A patient takes levothyroxine with an iron supplement and has unstable control. What should be reviewed?","options":["Assume adherence is dishonest","Expect TSH to fully stabilize the next day","Administration consistency and absorption interactions","Double every dose immediately"],"answer":2,"explain":["Explore the regimen respectfully.","Thyroid follow-up needs an appropriate interval.","Iron can interfere with levothyroxine absorption.","Assessment should precede changes."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-51cf022b6238","topic":"hyperthyroidism","domain":"Clinical Care","level":"Application","stem":"A patient taking a thionamide develops fever and sore throat. What is appropriate?","options":["Reassure without assessment","Wait until a routine annual visit","Increase the thionamide independently","Urgent assessment and prescriber instructions for possible agranulocytosis"],"answer":3,"explain":["A potentially dangerous blood abnormality must be excluded.","The symptoms need prompt action.","This does not address the possible toxicity.","This is an important serious adverse-effect warning."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-aee6c6aa7553","topic":"allergic-rhinitis","domain":"Clinical Care","level":"Application","stem":"A patient uses a topical nasal decongestant continuously and congestion worsens. What is possible?","options":["An indication to use the spray indefinitely more often","Proof that intranasal corticosteroids have no role","Rebound congestion from prolonged use","A guarantee of bacterial infection"],"answer":2,"explain":["This may worsen the cycle.","Controller options need a separate assessment.","Some decongestant sprays can perpetuate symptoms.","The pattern does not prove infection."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-bf5eaab72ee0","topic":"asthma","domain":"Clinical Care","level":"Application","stem":"Before stepping up an asthma regimen, what should be checked?","options":["Assume frequent reliever use means excellent control","Inhaler technique, adherence and current control","Only the colour of the inhaler","Whether all inhalers can be used as relievers"],"answer":1,"explain":["Frequent use can signal poor control.","Correct use and assessment may explain poor response.","Colour is not a reliable regimen assessment.","They cannot all serve that role."],"sources":[["Canadian Thoracic Society: guideline library","https://cts-sct.ca/guideline-library/"]]},{"id":"case-a698e64088af","topic":"copd","domain":"Clinical Care","level":"Application","stem":"Which statement about inhaled corticosteroids in COPD is correct?","options":["They replace smoking cessation and rehabilitation","Pneumonia risk is irrelevant","They are selected for appropriate patients after benefit–risk assessment","Every patient must receive them irrespective of history"],"answer":2,"explain":["Non-drug measures remain important.","It can affect the treatment choice.","Exacerbations, eosinophils and pneumonia risk may matter.","They are not universal therapy."],"sources":[["Canadian Thoracic Society: guideline library","https://cts-sct.ca/guideline-library/"]]},{"id":"case-7de99a72e9ec","topic":"smoking-cessation","domain":"Leadership & Stewardship","level":"Application","stem":"Why might some medicine doses need review after smoking cessation?","options":["Nicotine replacement exactly reproduces every smoke interaction","Stopping smoking always lowers all drug levels","No medicine can be affected by smoking","Removing smoke exposure can alter enzyme activity and drug levels"],"answer":3,"explain":["Nicotine is not the same mechanism.","The direction depends on the medicine.","Several clinically relevant medicines are affected.","Combustion products can affect metabolism."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-f1a6bddf6ea7","topic":"pediatric-health","domain":"Clinical Care","level":"Application","stem":"Which device is appropriate for a precisely measured oral liquid dose?","options":["A household teaspoon assumed to hold a standard volume","The bottle cap without calibration","A guess based on the child's appearance","An oral syringe with suitable markings"],"answer":3,"explain":["Household spoons vary.","It is not a validated dosing measure.","Weight and the prescribed regimen must be verified.","It supports accurate measurement."],"sources":[["Canadian Paediatric Society: current position statements","https://cps.ca/en/documents/statements-by-date"]]},{"id":"case-1a69e230c8b9","topic":"travel-medicine","domain":"Clinical Care","level":"Application","stem":"A traveller returns from a malaria-risk area with fever despite prophylaxis. What is best?","options":["Use leftover antibiotics without assessment","Wait until the next planned trip","Urgent assessment with travel history","Rule malaria out because tablets were taken"],"answer":2,"explain":["This can delay appropriate diagnosis.","The current illness needs attention.","Prophylaxis does not exclude malaria.","Prevention is not perfect."],"sources":[["Public Health Agency of Canada: Canadian Immunization Guide","https://www.canada.ca/en/public-health/services/canadian-immunization-guide.html"]]},{"id":"case-af56563f8d6a","topic":"eye-health","domain":"Clinical Care","level":"Application","stem":"A contact-lens wearer has a painful red eye with reduced vision. What is most appropriate?","options":["Continue lens wear until symptoms resolve","Prompt eye assessment","Routine allergy drops without evaluation","Leftover steroid drops"],"answer":1,"explain":["This may worsen the problem and delay assessment.","This can indicate a sight-threatening condition.","They may delay needed care.","Steroids can worsen some infections."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-a4fea05f10f9","topic":"cataract-surgery-post-operative-care","domain":"Clinical Care","level":"Application","stem":"After cataract surgery, a patient has increasing pain and worsening vision. What is best?","options":["Prompt contact with ophthalmic care","Wait until the next routine refill","Assume every postoperative symptom is expected","Stop or improvise all drops without clinical advice"],"answer":0,"explain":["These are postoperative warning signs.","Delay can be harmful.","Progressive pain and vision loss are concerning.","The surgeon's plan needs review, not guessing."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-24d4608c9e5c","topic":"glaucoma","domain":"Clinical Care","level":"Application","stem":"Which systemic issue matters when reviewing a beta-blocker eye drop?","options":["Pulse and breathing effects","Only taste preferences","The assumption that eye drops never enter the circulation","The belief that symptom-free glaucoma needs no treatment"],"answer":0,"explain":["Topical eye medicines can have systemic effects.","These do not address the major safety issue.","Systemic absorption can occur.","Damage may progress without symptoms."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-b49f122f6be0","topic":"oncology-general","domain":"Clinical Care","level":"Application","stem":"A patient receiving myelosuppressive chemotherapy develops fever. What takes priority?","options":["Urgent oncology or emergency assessment according to the care plan","Mask the fever and wait several days","Assume oral chemotherapy cannot suppress immunity","Recommend a live vaccine immediately"],"answer":0,"explain":["Possible neutropenic infection can deteriorate quickly.","This may delay life-saving treatment.","Oral anticancer agents can also be hazardous.","Vaccination needs assessment in immunosuppression."],"sources":[["BC Cancer: supportive care resources","https://www.bccancer.bc.ca/pharmacy-site/Pages/Supportive-Care-Websites.aspx"]]},{"id":"case-d76941864986","topic":"chemotherapy-induced-nausea-and-vomiting","domain":"Clinical Care","level":"Application","stem":"A preventive antiemetic regimen has specific doses before and after chemotherapy. Which label approach is best?","options":["Use a single universal regimen for every chemotherapy","Preserve the scheduled regimen and distinguish rescue instructions","Label every medicine only as needed","Stop all prevention after one symptom-free hour"],"answer":1,"explain":["Emetogenic risk and patient factors differ.","Prevention and rescue are not interchangeable.","This may omit essential preventive doses.","Delayed symptoms can occur."],"sources":[["BC Cancer: supportive care resources","https://www.bccancer.bc.ca/pharmacy-site/Pages/Supportive-Care-Websites.aspx"]]},{"id":"case-cfede037521f","topic":"electrolyte-disorders","domain":"Clinical Care","level":"Application","stem":"Why is rapid correction of a chronic sodium abnormality potentially dangerous?","options":["A universal OTC replacement formula is sufficient","Correction speed can itself cause neurological harm","Every abnormal sodium must normalize immediately","Symptoms and chronicity never affect treatment"],"answer":1,"explain":["Electrolyte disorders require individualized assessment.","Severity and chronicity guide monitored treatment.","Uncontrolled rapid correction can be unsafe.","They are central to urgency and method."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-226152672967","topic":"total-parenteral-nutrition","domain":"Clinical Care","level":"Application","stem":"Before adding a medicine to a PN bag, what is required?","options":["Assuming all intravenous products mix safely","Ignoring calcium and phosphate","Verified compatibility and appropriate authorization","Only checking that both solutions look clear"],"answer":2,"explain":["Precipitation and instability can occur.","Their compatibility is particularly important.","PN is a complex mixture with stability and safety constraints.","Appearance does not establish compatibility."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-3e0247786ec1","topic":"common-anemias","domain":"Clinical Care","level":"Application","stem":"Why should B12 deficiency be considered before treating an unexplained anaemia with folate alone?","options":["Normal appearance excludes anaemia","Iron treatment never needs follow-up","Folate may improve blood findings while missing neurological B12 disease","All anaemia is iron deficiency"],"answer":2,"explain":["Clinical appearance is insufficient.","Response and the underlying cause must be reviewed.","The cause needs appropriate assessment.","There are multiple causes."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-ac429dea7d42","topic":"acute-kidney-injury","domain":"Clinical Care","level":"Application","stem":"Why can a routine creatinine-based estimate mislead during rapidly evolving AKI?","options":["The calculation assumes a steadier relationship than may exist","The patient's trend is irrelevant","A stable CKD dosing table always applies without modification","All creatinine rises are dehydration"],"answer":0,"explain":["Changing creatinine can lag changing function.","Trend is essential.","Rapidly changing function needs additional assessment.","Several causes require consideration."],"sources":[["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"]]},{"id":"case-585673bcab34","topic":"chronic-kidney-disease","domain":"Clinical Care","level":"Application","stem":"Which statement is correct when assessing CKD?","options":["Persistent abnormalities and albuminuria matter alongside filtration","One mildly abnormal result always proves chronic disease","All kidney-dose references use the same estimate and units","NSAID risk disappears when a patient feels well"],"answer":0,"explain":["A single result does not tell the whole story.","Chronicity must be established.","The required measure may differ.","Symptoms do not establish renal safety."],"sources":[["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"],["KDIGO: CKD evaluation and management","https://kdigo.org/guidelines/ckd-evaluation-and-management/"]]},{"id":"case-e0eef18f2923","topic":"dialysis","domain":"Clinical Care","level":"Application","stem":"Why is a dialysis-specific medicine reference useful?","options":["Removal and supplemental-dose needs differ by drug and dialysis method","Dialysis removes every medicine completely","All medicines must be given before every session","Residual kidney function never matters"],"answer":0,"explain":["One generic reduction is not adequate.","Removal varies substantially.","Timing is product and regimen specific.","It can influence overall clearance."],"sources":[["KDIGO: international kidney guideline library","https://kdigo.org/guidelines/"]]},{"id":"case-96024f35685f","topic":"ontario-law-ethics","domain":"Professionalism","level":"Application","stem":"For an Ontario JEP legal question, what should be the starting reference?","options":["Only the national clinical topic list","A colleague's memory without checking","The current OCP blueprint and applicable authoritative resources","An undated answer from another province"],"answer":2,"explain":["That does not replace provincial law preparation.","A current authoritative source is needed.","Ontario's legal context must be assessed directly.","Scope and law can differ and change."],"sources":[["Ontario exam preparation","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/prepare-for-the-exam/"],["OCP: JEP examination blueprint","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/examination-blueprint/"]]},{"id":"case-5140680a15c5","topic":"ethics","domain":"Professionalism","level":"Application","stem":"A capable patient declines a recommended treatment after an informed discussion. What is appropriate?","options":["Coerce agreement by threatening unrelated care","Record consent that was not given","Assume disagreement automatically proves incapacity","Respect the decision and discuss follow-up and alternatives"],"answer":3,"explain":["This undermines informed choice.","Documentation must be truthful.","Disagreement alone does not establish incapacity.","Autonomy remains relevant when the patient disagrees."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-111b174a27ea","topic":"ethics","domain":"Professionalism","level":"Application","stem":"A conflict of interest could affect a recommendation. What is best?","options":["Hide the conflict if the product is familiar","Let the financial incentive determine the recommendation","Assume disclosure alone makes any recommendation acceptable","Disclose and manage the conflict while prioritizing the patient"],"answer":3,"explain":["Familiarity does not remove the conflict.","Patient interests must guide care.","The recommendation still must be appropriate.","Transparency supports trustworthy professional judgment."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-097cccd13e9e","topic":"ethics","domain":"Professionalism","level":"Application","stem":"A patient has limited English proficiency for a complex counselling discussion. What is best?","options":["Assume a nod proves full comprehension","Skip risk information because translation takes time","Use a child for every sensitive discussion by default","Arrange appropriate language support and verify understanding"],"answer":3,"explain":["It may reflect politeness or misunderstanding.","Essential information still needs communication.","Interpreter choice requires attention to accuracy and privacy.","Accessible communication supports informed decisions."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-b0552c73cff6","topic":"safety-and-documentation","domain":"Professionalism","level":"Application","stem":"A dispensing error has reached a patient. What takes priority?","options":["Assess and protect the patient, then follow disclosure and reporting processes","Alter the record to conceal the event","Wait for a complaint before acting","Focus only on assigning blame"],"answer":0,"explain":["Immediate safety comes first with accountable follow-up.","That undermines care and integrity.","Delay can prolong harm.","The patient and system response need attention."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-81344b4aae83","topic":"social-determinants-of-health","domain":"Professionalism","level":"Application","stem":"A patient cannot afford the preferred therapy. What is appropriate?","options":["Document nonadherence without discussing access","Assume the patient is uninterested in health","Share their financial details with unrelated people","Discuss feasible alternatives and assistance with the patient"],"answer":3,"explain":["That misses the underlying barrier.","Cost does not reveal motivation.","Privacy and consent still apply.","Affordability affects whether treatment can be used."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-18fec8527cf2","topic":"federal-law","domain":"Professionalism","level":"Application","stem":"A workplace policy permits an activity that current law prohibits. Which governs?","options":["The applicable law and professional requirements","The workplace policy always overrides law","Whichever rule is fastest","The patient's request alone"],"answer":0,"explain":["A local policy cannot authorize prohibited conduct.","It has no such authority.","Speed does not establish legality.","A request does not create professional authority."],"sources":[["Health Canada: controlled substances exemption and October 2026 transition","https://www.canada.ca/en/health-canada/services/health-concerns/controlled-substances-precursor-chemicals/policy-regulations/policy-documents/section-56-1-class-exemption-patients-pharmacists-practitioners-controlled-substances-covid-19-pandemic.html"]]},{"id":"case-36139fea63fc","topic":"ontario-law-ethics","domain":"Professionalism","level":"Application","stem":"What should be checked when relying on a controlled-substance rule during a regulatory transition?","options":["Assume publication and commencement are identical","Apply the oldest remembered exemption indefinitely","The effective date and currently applicable provisions","Only the publication headline"],"answer":2,"explain":["They can differ.","Temporary authorities can expire.","A future rule may differ from the rule in force today.","The operative date and details matter."],"sources":[["Ontario exam preparation","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/prepare-for-the-exam/"],["OCP: JEP examination blueprint","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/examination-blueprint/"]]},{"id":"case-f8d36a8294c4","topic":"ethics","domain":"Professionalism","level":"Application","stem":"A person asks for a neighbour's medication history without appropriate authority. What is best?","options":["Protect confidentiality and assess whether lawful authorization exists","Share it because they know the address","Read the record aloud in the waiting area","Assume all acquaintances are part of the care team"],"answer":0,"explain":["Curiosity does not establish access rights.","Knowing an address is not authorization.","This creates an inappropriate disclosure.","The relationship and authority must be established."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-39c7f07b8d5a","topic":"safety-and-documentation","domain":"Professionalism","level":"Application","stem":"Which note is ethically appropriate?","options":["Copied normal findings that were never checked","A retrospective claim that an unmade call occurred","A note deleting uncertainty to appear confident","A factual account of what was assessed and agreed"],"answer":3,"explain":["This falsely documents an assessment.","That misrepresents the care.","Relevant uncertainty should be recorded.","Records should accurately reflect the encounter."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-45bf99cf5c0d","topic":"transgender-health","domain":"Professionalism","level":"Application","stem":"A patient asks staff to use their chosen name. What is appropriate?","options":["Refuse all care until identity terminology matches staff preference","Disclose their history unnecessarily to others","Assume gender identity determines every medicine risk","Use respectful communication while maintaining necessary record accuracy"],"answer":3,"explain":["This creates an inappropriate barrier.","Confidentiality still applies.","Individual clinical factors must be assessed.","Respect and accurate identification can coexist."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-95ed68d47d0d","topic":"ethics","domain":"Professionalism","level":"Application","stem":"A student is unsure how to manage a high-risk interaction. What is most appropriate?","options":["Invent a recommendation to appear competent","Hide the uncertainty from the supervisor","Assume an app score grants independent authority","Seek appropriate supervision and use a reliable reference"],"answer":3,"explain":["This can harm the patient.","The concern needs resolution.","Practice scores do not establish licensure or competence.","Recognizing limits supports safe care."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-9c2b9a1773d2","topic":"medication-safety","domain":"Professionalism","level":"Application","stem":"An automated recommendation conflicts with the patient's clinical picture. What should happen?","options":["Review the evidence, inputs and patient context","Follow it solely because it is automated","Ignore every automated tool permanently","Delete the clinical findings to fit the recommendation"],"answer":0,"explain":["Automation supports but does not replace judgment.","Systems can be wrong or misapplied.","Useful support can remain after appropriate assessment.","That would distort the record and decision."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"]]},{"id":"case-e4899c60c527","topic":"ethics","domain":"Professionalism","level":"Application","stem":"A colleague's behaviour may put patients at immediate risk. What is the appropriate focus?","options":["Protect patients and follow the relevant escalation process","Avoid action solely to preserve collegial comfort","Publicly speculate about the colleague's diagnosis","Assume no responsibility exists without a completed incident"],"answer":0,"explain":["Safety concerns require an accountable response.","Immediate risk cannot be ignored for convenience.","Speculation and unnecessary disclosure are inappropriate.","Imminent risk may also require action."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-504ffefea641","topic":"ontario-law-ethics","domain":"Professionalism","level":"Application","stem":"An applicant asks whether completing this app satisfies Ontario PACE. What is correct?","options":["The regulator determines PACE requirements; app practice does not replace the assessment","Yes, any completed app counts as PACE","PEBC topic review automatically removes PACE from every pathway","Province selection itself proves eligibility"],"answer":0,"explain":["Educational exercises and registration assessments are distinct.","The app cannot confer that status.","Requirements depend on the regulator and pathway.","Selection only changes the app context."],"sources":[["Ontario exam preparation","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/prepare-for-the-exam/"],["OCP: JEP examination blueprint","https://ocpinfo.com/applicants/registration-requirements/jurisprudence-ethics-and-professionalism-exam/examination-blueprint/"]]},{"id":"case-a14c50d46a40","topic":"ethics","domain":"Professionalism","level":"Application","stem":"A patient requests a decision outside the pharmacist's current competence. What is best?","options":["Guess a dose from a similar condition","Abandon the patient without a plan","Pretend the limitation does not exist","Provide appropriate immediate support and arrange qualified help"],"answer":3,"explain":["Similarity is not adequate support for a high-risk decision.","A safe transition of care is still needed.","Honesty about limits supports safe care.","Referral should preserve continuity and safety."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-815940cec4da","topic":"medication-safety","domain":"Professionalism","level":"Application","stem":"A team reviews incidents to improve care. Which approach is best?","options":["Suppress near misses because no harm occurred","Use only punishment as the improvement strategy","Declare success solely because reporting stopped","Examine contributing processes and implement measurable changes"],"answer":3,"explain":["They can reveal hazards before harm.","This may discourage reporting and leave system causes unresolved.","Reduced reporting does not necessarily mean fewer errors.","Learning should produce safer systems."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"]]},{"id":"case-0eb0a7d56133","topic":"risk-benefit-nnt","domain":"Knowledge & Expertise","level":"Application","stem":"A trial reports events in 12% of controls and 8% of treated patients. What is the ARR?","options":["20 percentage points","50 percentage points","4 percentage points","4% of the original risk"],"answer":2,"explain":["Adding the risks does not give ARR.","That is unrelated to these event rates.","Subtract the event risks: 12% minus 8%.","That confuses absolute and relative change."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-ce87b38969de","topic":"risk-benefit-nnt","domain":"Knowledge & Expertise","level":"Application","stem":"Using risks of 12% and 8%, what is the NNT for the reported outcome and timeframe?","options":["0.25","250","25","4"],"answer":2,"explain":["Percentages must be converted to proportions correctly.","This is a tenfold calculation error.","The ARR is 0.04, so 1 divided by 0.04 is 25.","This is the percentage-point ARR, not NNT."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-15dee78e298d","topic":"diagnostic-test-interpretation","domain":"Knowledge & Expertise","level":"Application","stem":"What happens to positive predictive value when disease prevalence falls, all else equal?","options":["It always rises","It is identical to sensitivity","It must remain exactly unchanged","It generally falls"],"answer":3,"explain":["This reverses the usual relationship.","They answer different questions.","Predictive values depend on pretest probability.","A larger share of positive results may be false positives."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-199eb8f7e00b","topic":"evidence-based-medicine-and-study-design","domain":"Knowledge & Expertise","level":"Application","stem":"What is a key purpose of random allocation in a trial?","options":["Guarantee every participant completes follow-up","Make every result clinically important","Eliminate every possible bias","Reduce systematic baseline differences between groups"],"answer":3,"explain":["Attrition can still occur.","Effect size and relevance still need assessment.","Other design and conduct problems can remain.","It supports a fairer comparison of interventions."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-3c8026a89a83","topic":"evidence-based-medicine-and-study-design","domain":"Knowledge & Expertise","level":"Application","stem":"A statistically significant benefit is very small. What should be assessed next?","options":["Clinical importance, harms and applicability","Assume every significant result must change practice","Ignore the effect size entirely","Treat a p-value as the probability the treatment works for this patient"],"answer":0,"explain":["Statistical evidence alone does not establish worthwhile benefit.","Magnitude and context matter.","It is central to interpretation.","That is not what a p-value means."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-481168dfacd4","topic":"units-dose-calculations","domain":"Knowledge & Expertise","level":"Application","stem":"A fictional order needs 0.75 g of an ingredient. How many milligrams is that?","options":["750 mg","75 mg","7.5 mg","7500 mg"],"answer":0,"explain":["One gram equals 1000 milligrams.","This is tenfold too small.","This is one hundredfold too small.","This is tenfold too large."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-0aa49cccbfc6","topic":"pharmacokinetics-half-life","domain":"Knowledge & Expertise","level":"Application","stem":"In a first-order model, 160 mg remains initially. How much remains after three half-lives?","options":["40 mg","0 mg","20 mg","80 mg"],"answer":2,"explain":["That is after two half-lives.","First-order elimination does not reach zero after three half-lives.","160 becomes 80, then 40, then 20 mg.","That is after only one half-life."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-03023fdb49fb","topic":"therapeutic-drug-monitoring","domain":"Knowledge & Expertise","level":"Application","stem":"A 'trough' sample was actually drawn soon after a dose. What is best?","options":["Discard the dosing history as irrelevant","Interpret or repeat it with correct timing before changing the regimen","Treat it as a correctly timed trough anyway","Assume the medicine is ineffective"],"answer":1,"explain":["Timing and exposure history are essential.","Sampling time changes the meaning of the level.","That may lead to an unsafe adjustment.","The sample timing does not establish lack of benefit."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-33a993a852f2","topic":"laboratory-interpretation","domain":"Knowledge & Expertise","level":"Application","stem":"A result is reported in a different unit than the reference threshold. What is necessary?","options":["Assume all international results use identical units","Use a verified conversion before comparison","Compare the numbers directly","Choose the unit that makes the result normal"],"answer":1,"explain":["Different reporting conventions exist.","Unmatched units can produce a wrong interpretation.","Their scale may differ.","Units are not a preference."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-f95e913cd74b","topic":"patient-counselling","domain":"Communication & Collaboration","level":"Application","stem":"Which question best checks understanding without blaming the patient?","options":["Do you understand, yes or no?","Why were you not listening?","Can you repeat only the brand colour?","So I know I explained it clearly, how will you take it at home?"],"answer":3,"explain":["A yes may not show usable understanding.","This is blaming and discourages questions.","That does not establish safe use.","Teach-back evaluates the explanation and reveals gaps."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-e7603b7cb842","topic":"prescriber-calls","domain":"Communication & Collaboration","level":"Application","stem":"Which recommendation is easiest for a prescriber to act on?","options":["Only the pharmacy's fax number","A specific concern, proposed action, rationale and urgency","This prescription is bad, with no details","A long unrelated patient history"],"answer":1,"explain":["Contact details do not explain the request.","The decision and needed response are clear.","It lacks actionable information.","It can obscure the problem."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-1531f15671a0","topic":"inter-professional-care","domain":"Communication & Collaboration","level":"Application","stem":"After a verbal dose change, what supports reliable communication?","options":["Assume the first sound heard was correct","Document a different schedule from memory","Leave responsibility for follow-up unspecified","Read back the drug, dose, units and schedule and confirm the plan"],"answer":3,"explain":["Similar names and numbers can be misheard.","The actual agreement must be recorded.","Clear ownership helps ensure the plan occurs.","Closed-loop confirmation reduces misunderstanding."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-52906ae16a51","topic":"antimicrobial-stewardship","domain":"Leadership & Stewardship","level":"Application","stem":"What is the aim of stewardship?","options":["Always choose the broadest spectrum","Treat every positive culture irrespective of context","Appropriate effective treatment while reducing avoidable antimicrobial harm","Withhold antibiotics in every case"],"answer":2,"explain":["Unnecessary broad exposure adds harm.","Colonization and clinical infection differ.","It balances individual care and responsible use.","Necessary treatment must not be delayed."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-09f39fcda676","topic":"health-promotion-and-immunizations","domain":"Leadership & Stewardship","level":"Application","stem":"A community has low vaccine uptake because appointment times are inaccessible. What is a useful response?","options":["Assume all residents reject vaccines","Repeat the same inaccessible schedule without review","Judge success only by posters printed","Explore accessible delivery and clear trusted information"],"answer":3,"explain":["Access may be the issue.","The barrier would remain.","Measures should relate to access and outcomes.","Addressing the barrier supports public health."],"sources":[["Public Health Agency of Canada: Canadian Immunization Guide","https://www.canada.ca/en/public-health/services/canadian-immunization-guide.html"]]},{"id":"case-03f3101f2c71","topic":"smoking-cessation","domain":"Leadership & Stewardship","level":"Application","stem":"What is a constructive response after a smoking-cessation relapse?","options":["Assume the same plan must work without adjustment","Review triggers and adapt support with the person","Label the attempt worthless","Withhold all future help"],"answer":1,"explain":["Barriers and preferences may have changed.","Relapse can guide a better plan.","This discourages future progress.","Ongoing support may be useful."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-0d9bc9705a46","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"Two patients share a surname. Which check is most useful before releasing a prescription?","options":["Use bag position on the shelf","Ask whether the medicine looks familiar","Assume the first search result is correct","Confirm the required independent patient identifiers"],"answer":3,"explain":["Shelf position is not an identity check.","Familiarity does not confirm the patient.","Record order does not establish identity.","A surname alone cannot distinguish the records."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-608a33e21eac","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"An order says 0.5 mg but the label says 5 mg. What should happen?","options":["Hold release and correct the tenfold discrepancy","Dispense if the tablet count is correct","Ask the patient to divide mentally at home","Ignore it because both contain the digit five"],"answer":0,"explain":["A missing decimal changes the dose substantially.","Quantity does not correct strength instructions.","The label must be accurate.","Decimal placement is essential."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-3f32c6361326","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A prescription names an immediate-release product, but extended-release stock was selected. What is best?","options":["Double the interval without authorization","Resolve the dosage-form discrepancy before release","Substitute solely because the ingredient matches","Crush the extended-release product to match it"],"answer":1,"explain":["A new regimen cannot be improvised.","Release characteristics are part of the order.","Exposure and dosing may differ.","Crushing may be unsafe and does not establish equivalence."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-8ee8ffb99cf1","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"The written directions and quantity imply different intended durations. What is best?","options":["Copy the last label without review","Let stock availability determine the duration","Clarify the inconsistency with an appropriate source","Use whichever duration is shorter automatically"],"answer":2,"explain":["The new order may intentionally differ.","Supply does not define clinical intent.","Do not choose an intended course by guesswork.","The intended treatment must be established."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-bd45905ee0a3","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A liquid order is 250 mg and the stock is 125 mg per 5 mL. What volume supplies that amount?","options":["2 mL","5 mL","25 mL","10 mL"],"answer":3,"explain":["This incorrectly reverses the concentration relationship.","That contains only 125 mg.","That would contain 625 mg.","250 mg multiplied by 5 mL divided by 125 mg equals 10 mL."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-324360b157ee","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A label says 'use as directed' for a new variable regimen the patient does not understand. What is best?","options":["Use the same schedule as another patient","Omit counselling because the phrase is common","Clarify and provide a usable individualized schedule","Assume the patient will remember an unverified schedule"],"answer":2,"explain":["Regimens are individual.","Common wording does not make instructions adequate.","Directions must support safe use.","Understanding must be established."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-33c1ccc0bd31","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"An allergy alert appears during processing. What should happen?","options":["Delete an unclear allergy without clarification","Assess the documented reaction and medicine relationship","Override every alert to prevent delay","Cancel every medicine in every related class automatically"],"answer":1,"explain":["Uncertainty is not evidence that the label is false.","An alert requires clinical interpretation.","This can miss serious harm.","Cross-reactivity and alternatives need assessment."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-887dceb7fe08","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"Two orders contain the same active ingredient under different names. What is the priority?","options":["Assess unintended therapeutic duplication","Assume different names mean unrelated medicines","Dispense both without considering the total dose","Use packaging size to decide which is correct"],"answer":0,"explain":["Different names may conceal duplicate exposure.","Brand and generic names can refer to the same drug.","Total exposure affects safety.","Clinical intent must be clarified."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-e34e4aadb9a4","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A prescriber's instruction is illegible at the dosing interval. What is best?","options":["Print the illegible wording on the label","Clarify before dispensing","Infer the most common interval","Ask a nonclinical staff member to guess"],"answer":1,"explain":["This transfers the unresolved risk to the patient.","A familiar regimen is not proof of intended instructions.","Common use may not match this patient.","The ambiguity still remains."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-e8631cec3dce","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"The correct medicine is prepared for the wrong route. Which principle applies?","options":["Route is an essential verification item","Routes are interchangeable when the dose matches","Only the patient name needs rechecking","The final checker should ignore formulation"],"answer":0,"explain":["A correct ingredient alone is insufficient.","Bioavailability and safety differ.","The route discrepancy still requires correction.","Formulation often determines route suitability."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-52922bf2123e","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A prepared product has expired. What is best?","options":["Change the date on the label","Let the patient decide without resolving supply","Remove it from dispensing and obtain suitable stock","Use it because the package is unopened"],"answer":2,"explain":["That would misrepresent product status.","The pharmacy must provide an appropriate product.","Expiry is a release criterion.","An intact package does not extend expiry."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-83301ba2a19e","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A recalled lot is found in dispensing stock. What is appropriate?","options":["Discard records immediately","Quarantine it and follow the recall process","Keep dispensing until a patient complains","Mix it with other lots"],"answer":1,"explain":["Records may be needed for recall follow-up.","Affected stock must be controlled and traced.","The recall requires proactive action.","This impairs traceability."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-ee4a272d929a","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"An independent check is required for a high-risk preparation. What best supports it?","options":["Repeat the same rushed glance by the same person","Skip it if the preparer feels confident","A second qualified check using the original relevant information","Read the first person's answer aloud before checking"],"answer":2,"explain":["That is not an independent check.","Confidence does not replace the required process.","Independence reduces confirmation bias.","This can bias the checker."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-86a0dc04f904","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A medicine must be refrigerated. What should release counselling include?","options":["A claim that all medicines tolerate any temperature","Advice to freeze it unless told otherwise","Product-specific storage and handling during transport","Only the purchase price"],"answer":2,"explain":["Stability differs by product.","Freezing may damage the product.","Storage requirements continue after dispensing.","This does not support proper storage."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-65f9bcd11562","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A patient cannot read the standard label comfortably. What is best?","options":["Use smaller print to fit more abbreviations","Assume a companion will always be present","Treat the difficulty as refusal of treatment","Arrange accessible labelling and confirm understanding"],"answer":3,"explain":["This worsens accessibility.","Support should be confirmed with consent.","It is an access barrier, not refusal.","Instructions should match the person's needs."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-2d5532ff112c","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A prescription is being transferred between pharmacies. What should determine the process?","options":["A rule recalled from a different province","Only whether both pharmacies use the same software","Assume all controlled and noncontrolled drugs follow identical rules","Current drug-category rules, authority and required information"],"answer":3,"explain":["Jurisdictions can differ.","Software does not establish legal authority.","Drug category can change the requirements.","Transfer requirements depend on the applicable legal context."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-9298b80ef175","topic":"routes-dosage-forms","domain":"Distribution","level":"Application","stem":"A patient needs medicine through a feeding tube. What is best before modifying a tablet?","options":["Mix all medicines together without review","Assume a liquid is always suitable without checking","Check formulation-specific suitability and tube administration guidance","Crush every tablet to a fine powder"],"answer":2,"explain":["Compatibility and administration issues can arise.","Osmolality, tube compatibility and formulation still matter.","Not every tablet can be crushed or used through every tube.","Some formulations become unsafe or ineffective."],"sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-b037e753415a","topic":"routes-dosage-forms","domain":"Distribution","level":"Application","stem":"Why should old transdermal patches be checked when applying a new one?","options":["Unremoved patches can cause unintended extra exposure","All patches stop instantly at a fixed clock time","Patch count has no relation to dose","Skin location makes identity verification unnecessary"],"answer":0,"explain":["The previous delivery system may still release medicine.","Exposure and residual drug require appropriate handling.","Multiple patches can change delivery.","Product and strength still must be checked."],"sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-63df21b99dc6","topic":"routes-dosage-forms","domain":"Distribution","level":"Application","stem":"A patient's formulation changes from tablet to oral liquid. What must be recalculated?","options":["Copy the old numeric dose without units","Volume using the new concentration and prescribed amount","The dose solely from the bottle colour","Assume one tablet always equals one teaspoon"],"answer":1,"explain":["Units are necessary for safe instructions.","The amount and volume are distinct.","Colour has no dosing meaning.","Concentrations and tablet strengths vary."],"sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-8d890c791930","topic":"routes-dosage-forms","domain":"Distribution","level":"Application","stem":"Which abbreviation is safest on patient-facing directions?","options":["An ambiguous handwritten abbreviation","A trailing zero after every whole dose","Omitting units to save space","Clear words describing the intended route and frequency"],"answer":3,"explain":["Ambiguity can cause errors.","It can create a tenfold reading error.","The dose becomes unclear.","Plain instructions reduce misunderstanding."],"sources":[["Health Canada drug product database","https://health-products.canada.ca/dpd-bdpp/index-eng.jsp"],["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-a71505be11d0","topic":"compounding","domain":"Distribution","level":"Application","stem":"A preparation is made from a validated master formula. What belongs in its actual preparation record?","options":["A signature for an unperformed check","Ingredients, quantities, lot details and required checks","Only a copy of the master title","An assumed lot number from a previous batch"],"answer":1,"explain":["Documentation must be accurate.","The record documents what was actually prepared.","That does not establish the actual preparation details.","Traceability must reflect the current ingredients."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-638ac918ca5e","topic":"compounding","domain":"Distribution","level":"Application","stem":"An ingredient substitution is proposed in a compounded formula. What is best?","options":["Use the longest possible BUD automatically","Assess the formulation impact before proceeding","Assume equal mass guarantees equivalence","Make the change without recording it"],"answer":1,"explain":["The altered formula may lack supporting stability data.","Excipients and forms can affect stability and performance.","Chemical form and function may differ.","The preparation must be traceable."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-bd306131094d","topic":"compounding","domain":"Distribution","level":"Application","stem":"A balance result is far outside the expected amount. What is appropriate?","options":["Continue because the balance displayed a number","Adjust the documentation to match the target","Use appearance to estimate the missing mass","Stop and investigate the measurement and calculation"],"answer":3,"explain":["A displayed value can still be wrong or misused.","Records must reflect actual verified preparation.","Visual estimation is not adequate measurement.","An implausible value needs resolution."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-4043a3e63dd6","topic":"compounding","domain":"Distribution","level":"Application","stem":"Hazardous-drug compounding requires which additional consideration?","options":["Occupational and environmental exposure controls","Only a larger label","The assumption that oral products cannot be hazardous","No special assessment if the quantity is small"],"answer":0,"explain":["Patient dose accuracy is not the only safety issue.","Labelling alone cannot control exposure.","Hazard depends on the substance, not simply route.","Risk must be assessed under applicable standards."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-bb10b1ba35f8","topic":"compounding","domain":"Distribution","level":"Application","stem":"A cloudy precipitate develops in a preparation expected to remain clear. What is best?","options":["Change the label to describe cloudiness as normal without evidence","Hold release and investigate compatibility and quality","Shake and dispense without review","Extend the BUD because cloudiness appeared early"],"answer":1,"explain":["Product information must be supported.","Unexpected physical change needs assessment.","That may conceal a quality problem.","This has no stability basis."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-f1ae17166862","topic":"compounding","domain":"Distribution","level":"Application","stem":"A 2% w/v solution contains how much solute per 100 mL of final solution?","options":["2 mg","20 g","2 g added to 100 mL regardless of final volume","2 g"],"answer":3,"explain":["This is a thousandfold smaller mass.","That would be 20% w/v.","The definition uses final solution volume.","Percent weight per volume means grams per 100 mL."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-f012db373ec7","topic":"compounding","domain":"Distribution","level":"Application","stem":"How should 20 mL of stock be used to make 100 mL final solution when the formula specifies that final volume?","options":["Dilute the stock to a total of 100 mL","Add 100 mL of diluent automatically","Use only 20 mL as the final product","Ignore the concentration calculation"],"answer":0,"explain":["Final volume is not the volume of diluent alone.","That would usually exceed the intended final volume.","The specified final volume would not be met.","Concentration and volume determine the preparation."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-7b577cd9815b","topic":"hospital-pharmacy","domain":"Distribution","level":"Application","stem":"A concentrated electrolyte is ordered for IV use. What is a key safety requirement?","options":["Treat a verbal shorthand as a complete unambiguous order","Verify the authorized dilution, route, rate and monitoring","Assume direct injection is acceptable for every electrolyte","Check only the patient's room number"],"answer":1,"explain":["Ambiguity must be clarified.","Concentration and administration errors can be dangerous.","Many concentrated products must not be given this way.","Patient and product checks are also required."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-7b85dbfaadf2","topic":"hospital-pharmacy","domain":"Distribution","level":"Application","stem":"A discharge list unintentionally omits a chronic medicine. What should happen?","options":["Ignore it because the inpatient chart differs","Clarify whether discontinuation was intended","Automatically restart every previous medicine","Assume every omission is deliberate"],"answer":1,"explain":["Reconciliation is specifically needed across settings.","Transitions can introduce omissions.","Some may have been intentionally stopped.","The intent must be established."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-feb17aa4c900","topic":"hospital-pharmacy","domain":"Distribution","level":"Application","stem":"Two IV medicines are proposed for the same line. What is best?","options":["Rely only on drug class names","Mix first and investigate later","Check current compatibility for the actual concentrations and conditions","Assume clear solutions are always compatible"],"answer":2,"explain":["Specific products and conditions matter.","Assessment should precede administration.","Compatibility is context specific.","Visible clarity does not prove compatibility."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-58f0ec4f332e","topic":"pharmacy-management","domain":"Distribution","level":"Application","stem":"A shortage prevents supply of the usual medicine. What is the best response?","options":["Assess alternatives and coordinate an authorized continuity plan","Substitute any medicine from the same shelf","Change the dose without communicating","Hide the shortage until the medicine runs out"],"answer":0,"explain":["Clinical and formulation differences must be addressed.","Storage location does not imply equivalence.","The patient and responsible clinicians need the plan.","Proactive planning can prevent treatment interruption."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-71b03daeebf8","topic":"pharmacy-management","domain":"Distribution","level":"Application","stem":"What does a useful inventory system support during a recall?","options":["Only the total sales revenue","Deletion of all old dispensing records","Mixing batches to reduce shelf space","Identification and control of affected lots"],"answer":3,"explain":["Revenue does not identify lots.","Records may be necessary for follow-up.","This can impair traceability.","Traceability helps locate relevant stock and supplies."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-bfe15bec91eb","topic":"pharmacy-management","domain":"Distribution","level":"Application","stem":"A dispensing near miss repeatedly occurs between similar packages. What is the best systems response?","options":["Rely only on a reminder to be careful","Investigate and redesign storage or checking steps","Blame one person without examining the workflow","Treat no-harm events as irrelevant"],"answer":1,"explain":["Reminders alone may be insufficient.","Process changes can reduce recurring error risk.","That may leave the hazard unchanged.","Near misses reveal vulnerabilities."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-615a6461bd0b","topic":"prescription-verification","domain":"Distribution","level":"Application","stem":"A patient reports taking a different strength than the dispensing history lists. What is best?","options":["Assume the computer record must always be correct","Assume the patient must always be correct","Dispense both strengths for the patient to choose","Verify actual use with reliable sources before resolving the discrepancy"],"answer":3,"explain":["Records may be incomplete or outdated.","The account also needs clarification.","This transfers an unresolved safety problem.","History and current use may differ."],"sources":[["NAPRA professional resources","https://www.napra.ca/resources/publications/"],["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-3c9309877a7e","topic":"health-promotion-and-immunizations","domain":"Leadership & Stewardship","level":"Application","stem":"A vaccine refrigerator excursion is discovered. What is the best action for affected stock?","options":["Quarantine and assess according to the cold-chain procedure","Use it if the vials look normal","Automatically return it to sale without documenting","Assume every excursion has identical consequences"],"answer":0,"explain":["Suitability requires the appropriate assessment.","Appearance cannot establish potency.","Traceability and assessment are required.","Product and exposure details matter."],"sources":[["Public Health Agency of Canada: Canadian Immunization Guide","https://www.canada.ca/en/public-health/services/canadian-immunization-guide.html"]]},{"id":"case-130d050e411e","topic":"federal-law","domain":"Professionalism","level":"Application","stem":"A temporary controlled-substance exemption was used last year. What should be checked before relying on it today?","options":["Assume it overrides every provincial requirement","Current validity, scope and conditions","Only whether the previous pharmacist used it","Whether the drug is inexpensive"],"answer":1,"explain":["Both levels may affect practice.","Temporary authority can expire or change.","Past use does not establish current authority.","Price does not define the law."],"sources":[["Health Canada: controlled substances exemption and October 2026 transition","https://www.canada.ca/en/health-canada/services/health-concerns/controlled-substances-precursor-chemicals/policy-regulations/policy-documents/section-56-1-class-exemption-patients-pharmacists-practitioners-controlled-substances-covid-19-pandemic.html"]]},{"id":"case-9eb7d98cc656","topic":"canadian-healthcare-system","domain":"Knowledge & Expertise","level":"Application","stem":"Which statement about PEBC certification is correct?","options":["It guarantees public drug coverage","It replaces all jurisprudence requirements","It is distinct from provincial registration","It automatically grants a licence in every province"],"answer":2,"explain":["Professional certification and patient reimbursement are unrelated.","Provincial requirements remain separate.","A regulator determines the applicable licensing pathway.","Additional provincial requirements apply."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-a6642758f064","topic":"literature-references","domain":"Knowledge & Expertise","level":"Application","stem":"An AI answer gives a drug dose without a traceable source. What is best?","options":["Copy it into the record as a guideline","Assume all formulations share that dose","Verify the exact claim in a current appropriate reference","Treat confident wording as proof"],"answer":2,"explain":["That misrepresents the source.","Formulation and indication can change dosing.","An unsourced answer is not adequate clinical verification.","Confidence does not establish accuracy."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-bb94122f5964","topic":"hospital-pharmacy","domain":"Distribution","level":"Application","stem":"An IV order specifies a concentration and rate. What must the pharmacy verify?","options":["Assume every ward uses the same preparation","Amount, concentration, route, rate and relevant compatibility","Only the medicine name","Only the total bag volume"],"answer":1,"explain":["Standardization must be verified, not assumed.","These are distinct safety checks.","The name alone is insufficient.","Correct volume does not guarantee a safe rate or concentration."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-27869d591e96","topic":"compounding","domain":"Distribution","level":"Application","stem":"What is the difference between expiry and beyond-use date?","options":["The longest ingredient expiry always becomes the BUD","They refer to different product and preparation contexts","They are always interchangeable","A normal appearance permits any extension"],"answer":1,"explain":["The preparation's stability and standards also matter.","A compounded preparation needs an appropriately assigned BUD.","They are based on different information.","Appearance is not stability evidence."],"sources":[["NAPRA: non-sterile compounding standards","https://www.napra.ca/publication/model-standards-for-pharmacy-compounding-of-non-sterile-preparations/"]]},{"id":"case-cadc4a630dfb","topic":"social-determinants-of-health","domain":"Professionalism","level":"Application","stem":"A patient repeatedly misses refills because transport is unreliable. What is best?","options":["Increase the dose to compensate for missed access","Share details widely without consent","Explore an accessible supply plan with the patient","Label the patient noncompliant and end discussion"],"answer":2,"explain":["This does not solve the barrier and can cause harm.","Privacy still applies when seeking support.","The barrier should shape a feasible treatment plan.","This misses the practical cause."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-42c2fb05303e","topic":"safety-and-documentation","domain":"Professionalism","level":"Application","stem":"A factual error is found in a clinical record. What is appropriate?","options":["Copy a new assessment that was never performed","Leave a known error forever","Correct it through a process preserving the audit trail","Silently erase the original entry"],"answer":2,"explain":["That would be inaccurate documentation.","A proper correction is needed.","The correction should remain traceable.","This compromises record integrity."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-d8b18b8f4fc4","topic":"pharmacy-management","domain":"Distribution","level":"Application","stem":"A manager proposes skipping final checks to meet a volume target. What is the best response?","options":["Address workload while preserving required safety checks","Skip checks for familiar medicines","Measure quality only by prescription count","Hide incident data to protect targets"],"answer":0,"explain":["Commercial pressure does not remove professional duties.","Familiarity does not eliminate error risk.","Volume alone is not a quality outcome.","Learning requires accurate safety information."],"sources":[["NAPRA: standards and publications","https://www.napra.ca/resources/publications/"]]},{"id":"case-082ad2bf2b58","topic":"inter-professional-care","domain":"Communication & Collaboration","level":"Application","stem":"A pharmacist sends an urgent recommendation but receives no acknowledgement. What is best?","options":["Confirm receipt and escalate appropriately if unresolved","Document that the recommendation was implemented","Assume silence means agreement","Wait indefinitely despite an immediate risk"],"answer":0,"explain":["Sending is not equivalent to implementation.","That outcome has not been confirmed.","It may mean the message was not seen.","Urgency requires an appropriate follow-up pathway."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-84aaed6541a6","topic":"pediatric-dosing","domain":"Knowledge & Expertise","level":"Application","stem":"An order states 30 mg/kg/day divided into three doses. Which step is correct?","options":["Calculate the daily amount, then divide by three","Give 30 mg/kg at every dose","Convert kilograms directly to millilitres","Ignore the maximum dose"],"answer":0,"explain":["The order is expressed per day, not per administration.","That triples the intended daily amount.","The drug concentration is required.","The reference maximum must also be checked."],"sources":[["Canadian Paediatric Society: current position statements","https://cps.ca/en/documents/statements-by-date"]]},{"id":"case-a440aba9ad02","topic":"hepatic-impairment","domain":"Clinical Care","level":"Application","stem":"Which statement about hepatic dose adjustment is correct?","options":["Product-specific assessment is needed","Any elevated ALT requires halving every medicine","Nonrenally cleared medicines are always safe in liver disease","Normal appetite proves normal hepatic function"],"answer":0,"explain":["There is no single universal hepatic dosing equation.","An isolated enzyme value cannot support that rule.","They may depend on hepatic clearance.","Clinical and laboratory assessment are broader."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-1504fc615156","topic":"transgender-health","domain":"Professionalism","level":"Application","stem":"Which approach is appropriate for a transgender patient requesting preventive care?","options":["Assume hormone therapy is reliable contraception","Disclose identity information to unrelated staff","Refuse unrelated care because hormone expertise is limited","Base screening on relevant anatomy, age and individual risk"],"answer":3,"explain":["It is not a reliable contraceptive method.","Only appropriate necessary information should be shared.","Obtain support while providing appropriate care.","Identity alone does not specify every screening need."],"sources":[["PEBC learning resources","https://pebc.ca/pharmacists/qualifying-examination/preparing-for-the-examination/references-and-learning-resources/"]]},{"id":"case-533158ca70b8","topic":"insulin-pens","domain":"Clinical Care","level":"Application","stem":"Which statement about insulin pens is correct?","options":["Units always mean the same volume across concentrations","A pen must not be shared even if the needle is changed","Pen colour is a sufficient identity check","Every pen's prime and hold instructions are identical"],"answer":1,"explain":["Volume differs with concentration.","Contamination risk can persist.","Labels and exact products must be verified.","Instructions vary by product."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-ce337297ef8d","topic":"naloxone","domain":"Clinical Care","level":"Application","stem":"A person starts breathing after naloxone. What should the responder do?","options":["Leave the person alone to sleep","Assume every cause of unconsciousness was treated","Continue emergency support and stay with the person","Cancel all emergency care immediately"],"answer":2,"explain":["Recurrent respiratory depression is possible.","Naloxone only reverses opioid effects.","Opioid effects can recur after naloxone wears off.","Recovery may be temporary."],"sources":[["BC Centre on Substance Use: clinical guidance","https://www.bccsu.ca/clinical-care-guidance/"]]},{"id":"case-982d7e825cbd","topic":"epinephrine-auto-injectors","domain":"Clinical Care","level":"Application","stem":"What is first-line emergency medication for anaphylaxis with breathing compromise?","options":["Prompt intramuscular epinephrine","An oral antihistamine as the sole treatment","A topical steroid","Wait for a rash before treatment"],"answer":0,"explain":["Antihistamines do not replace it for airway or circulatory compromise.","It is not an adequate substitute.","It does not treat the acute systemic reaction.","Severe anaphylaxis may occur without a rash."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]},{"id":"case-72af7e4ee829","topic":"blood-glucose-monitoring","domain":"Clinical Care","level":"Application","stem":"A CGM reading does not match the patient's symptoms. What is best?","options":["Change every long-term dose from that single result","Use any meter strip regardless of compatibility","Follow the device-specific confirmation and safety plan","Ignore symptoms because sensors are infallible"],"answer":2,"explain":["Patterns and confirmation matter.","Strips must match the meter.","Sensor limitations and clinical symptoms must be considered.","Sensors can lag or have inaccurate readings."],"sources":[["Health Canada: search current Canadian product monographs","https://www.canada.ca/en/health-canada/services/drugs-health-products/drug-products/drug-product-database.html"]]}],"stations":[{"id":"a-new-medicine-conversation","title":"A new medicine conversation","scenario":"A simulated patient has been prescribed a new long-term medicine and says, “I do not want another tablet.” The exact product details are intentionally left open for you to clarify.","task":"Explore the concern and demonstrate a structured counselling approach. Do not invent a dose.","check":["Introduce yourself and confirm identity","Invite the patient’s main concern","Clarify medicine, indication and instructions","Ask about understanding, preferences and barriers","Explain benefits and relevant risks in plain language","Use teach-back","Agree on follow-up"],"domain":"Communication & Collaboration"},{"id":"warfarin-medication-review","title":"Warfarin medication review","scenario":"A simulated patient taking warfarin has started an over-the-counter pain medicine. The product name and the most recent INR are not yet confirmed.","task":"Gather essential information and explain your next steps.","check":["Confirm the exact new product and actual use","Confirm indication, target, regimen and INR history","Ask about bleeding, injury and other medicines","Recognize when urgent assessment is needed","Consult an appropriate current interaction reference","Explain a patient-specific plan without inventing a dose","Document and arrange follow-up"],"domain":"Clinical Care"},{"id":"call-the-prescriber","title":"Call the prescriber","scenario":"A fictional prescription lists a medicine strength that conflicts with the referral letter. No dispensing has occurred.","task":"Make a concise call to clarify the discrepancy.","check":["Identify yourself and the patient","State the discrepancy precisely","Present relevant verified background","Explain the potential consequence","Make a specific clarification request","Read back the agreed instructions","Document who agreed to what"],"domain":"Communication & Collaboration"},{"id":"a-private-conversation","title":"A private conversation","scenario":"A family member asks for a competent adult patient’s medicine list. You have not established consent or another authority to disclose.","task":"Respond respectfully while protecting confidentiality.","check":["Acknowledge the request respectfully","Avoid disclosing details prematurely","Establish identity and authority","Seek the patient’s consent when appropriate","Explain a suitable next step","Document according to applicable requirements"],"domain":"Professionalism"},{"id":"inhaler-teach-back","title":"Inhaler teach-back","scenario":"A simulated patient says their inhaler “does not seem to do anything.” You have a demonstration device but must establish its exact type.","task":"Assess use and teach technique using current device instructions.","check":["Identify medicine and device","Explore symptoms and urgent concerns","Ask for the patient’s usual technique","Check adherence and practical barriers","Demonstrate the correct product-specific steps","Ask for a return demonstration","Agree on reassessment"],"domain":"Communication & Collaboration"},{"id":"discharge-reconciliation","title":"Discharge reconciliation","scenario":"A fictional discharge list omits a long-term medicine that the patient reports taking. The reason is not documented in the available information.","task":"Describe how you will resolve the discrepancy.","check":["Obtain the best available medication history","Compare with discharge instructions","Clarify whether the omission is intentional","Avoid independently assuming restart or discontinuation","Contact the appropriate care team","Provide the reconciled plan to the patient","Document unresolved and resolved issues"],"domain":"Distribution"},{"id":"an-upset-patient","title":"An upset patient","scenario":"A simulated patient is angry because a prescription cannot be supplied until ambiguous instructions are clarified.","task":"Explain the situation, listen and agree on a safe next step.","check":["Acknowledge the inconvenience","Listen without blame or defensiveness","Explain the concrete safety concern","Offer a practical update or contact plan","Assess urgency and continuity of care","Confirm the patient understands next steps"],"domain":"Communication & Collaboration"},{"id":"a-possible-dispensing-error","title":"A possible dispensing error","scenario":"A patient returns because the label directions differ from what they were told. It is not yet clear whether medicine has been taken.","task":"Prioritize patient safety and establish the facts.","check":["Confirm identity and medicine","Determine what was taken and when","Assess symptoms and immediate risk","Arrange appropriate clinical assessment","Check original records without speculation","Communicate and document according to policy","Identify follow-up and learning actions"],"domain":"Distribution"},{"id":"limited-health-literacy","title":"Limited health literacy","scenario":"A simulated patient is embarrassed about reading medicine instructions and repeatedly agrees without explaining the plan.","task":"Demonstrate respectful communication and confirm practical understanding.","check":["Offer privacy","Use plain language and short steps","Avoid judging literacy","Use a demonstration or suitable visual aid","Ask open teach-back questions","Correct gaps respectfully","Provide a usable follow-up plan"],"domain":"Communication & Collaboration"},{"id":"a-complicated-daily-routine","title":"A complicated daily routine","scenario":"A simulated older adult uses several medicines and reports missing afternoon doses. No change is yet authorized.","task":"Assess practical barriers and outline a collaborative review.","check":["Ask about actual use and goals","Review cognition, dexterity and support","Check indications and treatment burden","Identify potential medicine-related harm","Discuss feasible support options","Collaborate before changing prescribed regimens","Agree on monitoring"],"domain":"Clinical Care"},{"id":"pediatric-directions-check","title":"A child's liquid prescription","domain":"Distribution","scenario":"Fictional training order: Product L, 10 mg/kg/day in TWO equal doses for a child weighing 18 kg. The supplied concentration is 30 mg/mL. A draft label says 6 mL twice daily. No clinical indication or product identity is supplied.","task":"Check the arithmetic and draft directions, explain the discrepancy to a colleague, and identify what must still be verified before dispensing. These numbers describe a fictional order, not a recommended pediatric regimen.","check":["Confirm patient identity and a current weight in kilograms","Distinguish the daily amount from the amount per dose","Calculate 180 mg/day and 90 mg/dose","Calculate 3 mL per dose from the supplied concentration","Identify that the draft label doubles the ordered daily amount","Hold supply pending correction and the complete clinical and legal checks","Arrange an independent check and demonstrate an appropriate measuring device"],"debrief":["The arithmetic is 18 × 10 = 180 mg/day, divided by two gives 90 mg/dose, and 90 ÷ 30 = 3 mL/dose.","Correct arithmetic alone cannot establish whether a real product, indication or regimen is appropriate. Verify the complete prescription, concentration, duration and patient factors before supply."]},{"id":"same-name-different-patient","title":"Two patients with the same name","domain":"Distribution","scenario":"A package for Sam Patel, date of birth 1982-05-09, is ready. The person collecting it gives the same name and date of birth 1993-11-21. The queue is growing and a colleague suggests handing it over because the names match.","task":"Resolve the identity mismatch and explain your action respectfully without revealing either person's medicines to others.","check":["Pause the handover","Move sensitive discussion away from the queue","Use the required independent patient identifiers","Check the original order and correct profile","Explain why the mismatch needs resolution","Avoid exposing another person's medicine or history","Document and communicate the discrepancy through the local process"],"debrief":["A matching name does not resolve conflicting identifiers. Keep the package secure while establishing the correct patient.","A busy queue is a workflow issue; it does not remove the identity check."]},{"id":"cold-chain-excursion","title":"A refrigerator temperature alert","domain":"Distribution","scenario":"At opening, the pharmacy refrigerator logger shows an overnight temperature excursion. The duration is uncertain. Several medicines and vaccines are stored inside, and a patient is waiting for one of them.","task":"Describe your immediate response and how you will establish whether the affected stock can be used.","check":["Quarantine affected stock and prevent accidental supply","Preserve temperature records and note the time the issue was discovered","Identify affected products, lots and quantities","Follow the product, manufacturer and applicable public-health procedures","Do not assume that normal temperature now proves stock remains usable","Arrange a safe alternative for the waiting patient","Document the decision, communication and prevention actions"],"debrief":["The disposition of a product depends on its specific stability information and the excursion. The exercise intentionally omits those details.","Quarantine is a temporary control while obtaining an authorized assessment; do not automatically return stock to use or discard it without the applicable process."]},{"id":"interrupted-final-check","title":"An interrupted final check","domain":"Distribution","scenario":"While checking a new prescription, you answer a telephone call. Returning to the bench, you cannot remember whether you compared the selected strength with the original order. A colleague asks you to release it quickly.","task":"Complete the check and propose a practical way to reduce this interruption risk.","check":["Keep the prescription in an unverified state","Restart the affected check using the original order","Confirm patient, product, strength, form, directions and quantity","Complete the required clinical and legal review","Make the verification status clear to the team","Suggest an interruption-control step suited to the workplace","Discuss the event without blaming a colleague"],"debrief":["Memory of an interrupted task is not verification. Return to a defined checking point and record completion through the usual process.","A visible work status, a protected checking area or an agreed interruption protocol may help; choose an intervention that addresses the actual workflow."]},{"id":"relative-risk-conversation","title":"Explain a treatment benefit","domain":"Knowledge & Expertise","scenario":"A fictional one-year trial reports an unwanted event in 100 of 1,000 control participants and 60 of 1,000 treatment participants. A headline says the treatment lowers risk by 40%. A patient thinks this means 40 of every 100 people will benefit.","task":"Explain the absolute and relative effects in plain language, including the timeframe and limits of applying the result.","check":["Identify the control risk as 10% and treatment risk as 6%","Explain the absolute reduction as 4 percentage points","Explain the relative reduction as 40% of the control risk","Calculate an NNT of 25 over one year for this trial outcome","Use a consistent natural-frequency example","Discuss applicability, harms and uncertainty rather than guaranteeing benefit","Ask the patient to explain the difference in their own words"],"debrief":["Among 100 similar trial participants, the outcome occurred in about 10 without treatment and 6 with treatment: about 4 fewer over one year.","NNT is 1 ÷ 0.04 = 25. It is tied to the studied population, outcome, timeframe and estimate; it is not a promise that a particular person benefits."]},{"id":"positive-screening-test","title":"A positive screening result","domain":"Knowledge & Expertise","scenario":"A fictional screening program tests 1,000 people. Ten have the condition. The test identifies nine of those ten and also gives positive results in 99 people without the condition. A learner says every positive result is almost certainly disease.","task":"Use the supplied counts to explain positive predictive value and why a screening result needs the appropriate next assessment.","check":["Identify nine true positives and 99 false positives","Calculate 108 total positive results","Calculate positive predictive value as 9/108, about 8.3%","Distinguish predictive value from sensitivity","Explain that the population prevalence affects predictive value","Avoid treating the screening result as a diagnosis","Communicate the appropriate follow-up pathway without inventing an unsupported treatment"],"debrief":["This dataset has sensitivity 9/10 = 90%, but positive predictive value 9/108 ≈ 8.3%. Those are different questions.","Interpretation depends on the test and population. The arithmetic alone does not specify an individual person's diagnosis or management."]},{"id":"patient-request-for-privacy","title":"A family member wants an update","domain":"Professionalism","scenario":"An adult patient's relative asks which medicines the patient collects. They say they are helping with appointments, but you have no documented permission for disclosure and have not confirmed their authority. The patient is available to speak privately.","task":"Respond with empathy, establish consent or other valid authority, and protect the patient's information.","check":["Acknowledge the relative's intention without confirming confidential details","Verify identities and the nature of the request","Speak privately with the patient when appropriate","Clarify the patient's wishes and any valid authority to disclose","Apply the relevant provincial privacy requirements","Limit any authorized disclosure to what is appropriate","Document consent and the action taken"],"debrief":["Being a relative or helping with appointments does not by itself establish authority to receive all health information.","Use the applicable provincial rules and any valid substitute-decision-making authority. The station does not provide facts supporting an emergency exception."]},{"id":"interpreter-and-teach-back","title":"Counselling through an interpreter","domain":"Communication & Collaboration","scenario":"A patient asks for an interpreter for a medicine discussion. Their adult friend offers to translate, but the patient looks uncomfortable. No urgent emergency is apparent.","task":"Agree on a suitable communication plan, demonstrate how you would use an interpreter and check understanding.","check":["Ask the patient about their preferred language and communication support","Offer a qualified interpreter through the available service","Check whether the patient wants the friend involved","Speak to the patient directly using short, plain-language segments","Pause to allow interpretation and questions","Use teach-back without blaming the patient","Provide appropriate written or accessible follow-up information"],"debrief":["Language preference and consent to involve a companion should be established with the patient.","Teach-back checks how clearly the explanation was delivered; asking only whether the patient understands is less informative."]},{"id":"medicine-cost-barrier","title":"The refill costs too much","domain":"Clinical Care","scenario":"A patient has not refilled a long-term medicine because of cost. They have been stretching the remaining supply and are embarrassed to say so. The exact medicine and condition have not yet been clarified.","task":"Explore the barrier without judgment, assess whether delay creates an immediate problem and agree on a feasible next step.","check":["Thank the patient for describing the difficulty","Clarify the medicine, indication, actual use and remaining supply","Assess symptoms and any urgent risk from interruption","Ask about coverage, access and patient priorities","Investigate appropriate funding or treatment options within scope","Coordinate with the prescriber when a change is needed","Agree on a concrete follow-up plan without promising unverified coverage"],"debrief":["The missing product and clinical information must be obtained before proposing a specific substitute or regimen.","A useful plan addresses affordability, clinical appropriateness and the patient's ability to follow through."]},{"id":"improve-near-miss-system","title":"Learn from repeated near misses","domain":"Leadership & Stewardship","scenario":"Three similar packages have been selected incorrectly this month; the errors were caught before supply. The team wants to place all responsibility on the last staff member who touched the shelf.","task":"Lead a short discussion that identifies contributing factors, proposes a measurable improvement and maintains a fair reporting culture.","check":["Confirm that affected prescriptions and stock are secure","Describe the events factually without personal blame","Invite staff to explain workflow and environmental factors","Consider product similarity, shelf arrangement and interruptions","Choose a practical intervention and a responsible person","Define how and when the team will check whether it helped","Use the applicable incident-reporting and learning process"],"debrief":["A near miss provides information about the system even when no patient received the product.","A specific intervention with a review date is more useful than simply telling everyone to be more careful."]}],"audio":[{"id":"clinical-decision-making","title":"Clinical Decision Making","topic":"clinical-decision-making","en":"Clinical Decision Making. A consistent care process helps you find the safest next step, even when a case contains distracting details. Start with the patient’s concern and the decision that needs to be made. Establish identity, symptoms, onset, severity and relevant history. Ask about prescriptions, nonprescription products, supplements, allergies and actual use. Check immediate safety first. A case suggesting serious acute harm needs escalation before routine counselling. Distinguish missing information from a normal result; “not provided” does not mean “normal”. Define the drug-related problem in one sentence. Is treatment needed, ineffective, unsafe or difficult to use? Agree on a measurable goal. Compare reasonable options using efficacy, safety, suitability and the patient’s preferences. Check organ function, interactions, pregnancy considerations, ability to use the dosage form, access and adherence before recommending a change. A technically effective option may be impractical for this patient. Explain the plan in plain language. State what should improve, what harm to watch for, what monitoring is required and who is responsible for follow-up. Document your reasoning and unresolved questions. Exam approach: decide what action is safest now. Do not skip a necessary assessment just because an answer names a familiar drug.","hi":"फार्मासिस्ट की तरह सोचें। सबसे पहले मरीज की पहचान, मुख्य समस्या और तुरंत खतरे की जानकारी लें। दवाओं, एलर्जी, लक्षणों और वास्तविक उपयोग के बारे में पूछें। जो जानकारी नहीं दी गई है, उसे सामान्य मत मानें। समस्या को एक स्पष्ट वाक्य में बताएं। इलाज का लक्ष्य तय करें और लाभ, नुकसान, सुविधा तथा मरीज की पसंद की तुलना करें। योजना समझाएं, मरीज से अपने शब्दों में दोहराने को कहें, और निगरानी तथा फॉलो अप की जिम्मेदारी तय करें।","files":{"hi":"audio/clinical-decision-making-hi.mp3","en":"audio/clinical-decision-making-en.mp3"},"duration":{"hi":40.4,"en":89.4},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"medication-history","title":"Medication History","topic":"medication-history","en":"Medication History. The best medication list describes what a person actually takes, not just what was prescribed. Confirm the patient and explain why you are reviewing medicines. Ask an open question first, then cover prescription medicines, nonprescription products, vitamins, herbals, inhalers, patches, injections and as-needed medicines. For each product establish name, strength, amount, route, timing, indication, duration and actual use. Ask about recent changes, missed doses, access and side effects without blame. Compare the interview with another reliable source when possible: labelled containers, a dispensing history, a care record or a caregiver with appropriate consent. Record who supplied information and what remains uncertain. Clarify allergies separately from other adverse effects. Obtain the specific reaction, timing, severity and subsequent exposure; do not delete an allergy simply because the account is incomplete. “You take a water pill” is not enough to confirm a dose. Ask for the container or contact the dispensing pharmacy through the appropriate process. Document uncertainty and arrange verification before a high-risk decision.","hi":"दवाओं की सही जानकारी केवल प्रिस्क्रिप्शन की सूची नहीं है। पूछें कि मरीज वास्तव में क्या, कितना और कब लेता है। बिना प्रिस्क्रिप्शन की दवाएं, विटामिन, हर्बल उत्पाद, इनहेलर, पैच और जरूरत के समय ली जाने वाली दवाएं भी शामिल करें। नाम, शक्ति, मात्रा, तरीका और कारण स्पष्ट करें। एलर्जी में कौन सी प्रतिक्रिया हुई और कब हुई, यह जानें। जहां संभव हो, दूसरी विश्वसनीय जानकारी से सूची की जांच करें। किसी भी अनिश्चित जानकारी को स्पष्ट रूप से दर्ज करें।","files":{"hi":"audio/medication-history-hi.mp3","en":"audio/medication-history-en.mp3"},"duration":{"hi":40.8,"en":74.5},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"patient-counselling","title":"Patient Counselling","topic":"patient-counselling","en":"Patient Counselling. Effective counselling ends with a patient who can explain and use the plan. Introduce yourself, confirm identity and privacy, and ask what the person already knows and most wants to discuss. Check language, hearing, health literacy and practical needs. Explain the purpose of treatment, how to use it, expected benefit, relevant adverse effects, monitoring and when to seek help. Prioritize the information that changes safety and use. Ask: “So I know I explained it clearly, how will you take this at home?” This checks your explanation rather than testing the patient. For devices, ask for a demonstration after teaching. Do not finish with only “Do you understand?” A yes can reflect politeness, anxiety or misunderstanding. Correct gaps respectfully and repeat the check. Provide an actionable plan for missed doses and problems using a current product reference. Avoid inventing a universal missed-dose rule. Agree who to contact and when.","hi":"अच्छी काउंसलिंग मरीज की जरूरत से शुरू होती है। अपना परिचय दें, पहचान और गोपनीयता की पुष्टि करें, और पूछें कि मरीज सबसे पहले क्या जानना चाहता है। सरल भाषा में दवा का उद्देश्य, उपयोग, जरूरी सावधानियां और फॉलो अप समझाएं। केवल यह न पूछें कि समझ आया या नहीं। कहें, ताकि मुझे पता चले कि मैंने सही समझाया है, आप घर पर यह दवा कैसे लेंगे? डिवाइस हो तो मरीज से उपयोग करके दिखाने को कहें।","files":{"hi":"audio/patient-counselling-hi.mp3","en":"audio/patient-counselling-en.mp3"},"duration":{"hi":36.8,"en":63.8},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"medication-safety","title":"Medication Safety","topic":"medication-safety","en":"Medication Safety. Safe practice anticipates predictable errors and makes recovery easier. Use clear medicine names and units. Write a leading zero for values below one and avoid unnecessary trailing zeros. Separate look-alike products and verify high-risk steps through the established process. Read a concentration as an amount per volume. A prescribed amount in milligrams is not automatically the volume to administer. Always carry units through a calculation. First assess and protect the patient. Obtain the facts, arrange appropriate clinical follow-up, communicate according to professional and organizational requirements, and document accurately. Examine contributing conditions such as workload, interruptions, storage, software design and handoffs. Blaming an individual alone rarely fixes a process weakness. An error caught before reaching a patient can expose the same system vulnerability as an incident that caused harm. Use reporting and learning processes to reduce recurrence.","hi":"दवा सुरक्षा में छोटी अस्पष्टताएं भी महत्वपूर्ण हैं। दशमलव से पहले शून्य लिखें और अनावश्यक आखिरी शून्य से बचें। हर गणना में यूनिट लिखें। मिलीग्राम दवा की मात्रा है, जबकि मिलीलीटर तरल का आयतन है। दोनों को एक न समझें। गलती का संदेह हो तो पहले मरीज की सुरक्षा देखें, तथ्य जुटाएं और उचित सहायता लें। जो गलती मरीज तक पहुंचने से पहले पकड़ ली गई हो, उससे भी प्रक्रिया सुधारने का अवसर मिलता है।","files":{"hi":"audio/medication-safety-hi.mp3","en":"audio/medication-safety-en.mp3"},"duration":{"hi":39.1,"en":64.3},"subject":"Pharmacy Foundations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pharmacokinetics-half-life","title":"Pharmacokinetics & Half-life","topic":"pharmacokinetics-half-life","en":"Pharmacokinetics & Half-life. Pharmacokinetics connects a dosing regimen with exposure over time. Absorption describes entry into the systemic circulation; distribution describes movement into tissues; metabolism and excretion remove drug or transform it. Bioavailability is the fraction reaching systemic circulation unchanged. Clearance is a volume cleared per unit time, not an amount of drug. Volume of distribution relates the amount in the body to measured plasma concentration; it is a model parameter, not an anatomical container. In an ideal first-order model, the fraction remaining after n half-lives is (1/2)^n. Roughly four to five half-lives bring repeated dosing near steady state. The same approximation can describe decline after stopping, but active metabolites and changing clearance complicate real cases. A loading dose primarily depends on target concentration, volume of distribution and bioavailability. Maintenance dosing primarily depends on target exposure, clearance and bioavailability. Do not treat these as interchangeable. Starting with a model amount of 80 mg, 40 mg remains after one half-life, 20 mg after two and 10 mg after three. This illustration assumes first-order elimination and does not prescribe a patient dose.","hi":"फार्माकोकाइनेटिक्स बताती है कि शरीर दवा के साथ क्या करता है। इसमें एब्जॉर्प्शन, डिस्ट्रीब्यूशन, मेटाबॉलिज्म और एक्सक्रीशन शामिल हैं। सरल फर्स्ट ऑर्डर मॉडल में हर हाफ लाइफ के बाद आधी मात्रा बचती है। अस्सी मिलीग्राम से एक हाफ लाइफ के बाद चालीस, फिर बीस, फिर दस मिलीग्राम बचेंगे। यह समझाने का मॉडल है, मरीज की खुराक का सुझाव नहीं। लोडिंग डोज मुख्य रूप से वितरण से और मेंटेनेंस डोज क्लियरेंस से जुड़ी होती है।","files":{"en":"audio/pharmacokinetics-half-life-en.mp3","hi":"audio/pharmacokinetics-half-life-hi.mp3"},"duration":{"en":81.0,"hi":39.0},"subject":"Pharmacy Foundations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"units-dose-calculations","title":"Units & Dose Calculations","topic":"units-dose-calculations","en":"Units & Dose Calculations. Unit tracking turns a calculation into something you can audit. Write the required output unit first. Identify the supplied information and convert to compatible units. Use a labelled conversion factor so unwanted units cancel. For volume, divide required drug amount by concentration in matching amount-per-volume units. A suspension labelled 100 mg per 5 mL contains 20 mg/mL. In a fictional exercise requiring 150 mg from that suspension, volume is 150 mg ÷ 20 mg/mL = 7.5 mL. Check that 7.5 mL is one-and-a-half times 5 mL, matching 150 mg versus 100 mg. Keep extra precision during intermediate steps and round the final answer according to the question or device. Distinguish a total daily dose from a dose given several times daily. Do not mix micrograms with milligrams or hours with minutes. Check whether a percentage is weight/volume, volume/volume or weight/weight. Write a leading zero before decimals.","hi":"दवा की गणना शुरू करने से पहले उत्तर की यूनिट लिखें। मान लें कि एक अभ्यास में सौ मिलीग्राम दवा पांच मिलीलीटर में है। इसका मतलब है बीस मिलीग्राम प्रति मिलीलीटर। एक सौ पचास मिलीग्राम के लिए, एक सौ पचास को बीस से भाग दें। उत्तर है सात दशमलव पांच मिलीलीटर। बीच के चरणों में अतिरिक्त सटीकता रखें और अंतिम उत्तर को निर्देश के अनुसार राउंड करें। कुल दैनिक मात्रा और एक बार की मात्रा अलग हो सकती हैं।","files":{"hi":"audio/units-dose-calculations-hi.mp3","en":"audio/units-dose-calculations-en.mp3"},"duration":{"hi":38.2,"en":72.0},"subject":"Pharmacy Foundations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"ethics","title":"Ethics","topic":"ethics","en":"Ethics. An ethical answer balances duties with the patient’s situation, rights and preferences. Clarify facts, urgency, capacity, consent, privacy and the interests affected. Separate your assumptions from the patient’s expressed goals. Consider autonomy, benefit, avoidance of harm and fairness. Check applicable law, professional standards and organizational policy. A policy does not erase a professional duty; an ethical preference does not erase a legal requirement. Consider practical alternatives and the likely consequences. Seek appropriate advice when uncertain, especially when significant harm or a conflict of interest is involved. Communicate respectfully, document the rationale, and plan follow-up. Do not disclose information merely because a requester is a family member; establish consent or another applicable authority.","hi":"नैतिक निर्णय में पहले तथ्य, मरीज की पसंद, सहमति, गोपनीयता और तुरंत जोखिम स्पष्ट करें। कानून, प्रोफेशनल स्टैंडर्ड और स्थानीय नीति में अंतर समझें। परिवार का सदस्य होना अपने आप निजी जानकारी लेने की अनुमति नहीं देता। उचित सहमति या दूसरी वैध अनुमति की पुष्टि करें। विकल्पों का लाभ और नुकसान समझाएं। अनिश्चित होने पर उपयुक्त सलाह लें। अपने निर्णय का कारण, बातचीत और आगे की योजना दर्ज करें।","files":{"en":"audio/ethics-en.mp3","hi":"audio/ethics-hi.mp3"},"duration":{"en":54.6,"hi":36.8},"subject":"Law & Ethics","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"risk-benefit-nnt","title":"Risk, Benefit & NNT","topic":"risk-benefit-nnt","en":"Risk, Benefit & NNT. Absolute effects show what a relative effect means for a particular baseline risk. For an undesirable outcome, absolute risk reduction equals control event risk minus treatment event risk. Relative risk is treatment risk divided by control risk; relative risk reduction is one minus relative risk. In a fictional study with risks of 10% and 6%, ARR is 4 percentage points, RR is 0.6 and RRR is 40%. NNT is 1 ÷ 0.04 = 25 over the study follow-up. Use proportions, not whole percentages, in the reciprocal. Specify outcome, population and timeframe. When conventional NNT calculation produces a fraction, round up to a whole person. For increased harm, calculate the absolute risk increase and its reciprocal. Confidence intervals that span no effect can make a single NNT misleading. Compare benefit and harm rather than treating NNT as a universal score.","hi":"रिस्क को समझते समय एब्सोल्यूट और रिलेटिव असर को अलग रखें। एक काल्पनिक अध्ययन में बिना नए इलाज के घटना दस प्रतिशत और इलाज के साथ छह प्रतिशत है। एब्सोल्यूट रिस्क रिडक्शन चार प्रतिशत अंक है। रिलेटिव रिस्क रिडक्शन चालीस प्रतिशत है। एन एन टी निकालने के लिए एक को शून्य दशमलव शून्य चार से भाग दें। उत्तर पच्चीस है। इसके साथ अध्ययन का समय, मरीजों का समूह और किस घटना को मापा गया है, यह बताना जरूरी है।","files":{"hi":"audio/risk-benefit-nnt-hi.mp3","en":"audio/risk-benefit-nnt-en.mp3"},"duration":{"hi":41.1,"en":64.6},"subject":"Evidence & Research","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"hypertension","topic":"hypertension","title":"Hypertension","en":"Hypertension. Assess before changing therapy. Confirm measurement technique, cuff suitability, readings over time and relevant home or ambulatory measurements. Review symptoms, cardiovascular risk, comorbidities, medicines and adherence. A severe reading with concerning acute symptoms needs prompt assessment. A single reading without context should not become an automatic treatment change. Plan and monitor. Use current Canadian guidance to identify the applicable diagnostic threshold, treatment target and options for this patient. Discuss feasible lifestyle measures alongside medicine assessment. Link the monitoring plan to both effectiveness and safety. Evaluate tolerability, orthostatic symptoms and relevant laboratory needs after changes.","hi":"उच्च रक्तचाप में पहले मापने की सही विधि, कफ का आकार और कई रीडिंग देखें। एक संख्या से तुरंत इलाज बदलना सही नहीं। घर या एम्बुलेटरी रीडिंग और कुल हृदय जोखिम उपयोगी हैं। गंभीर रीडिंग के साथ छाती दर्द, सांस या न्यूरोलॉजिकल लक्षण हों तो तुरंत जांच जरूरी है। वर्तमान कनाडाई दिशानिर्देश से लक्ष्य और दवा चुनें। जीवनशैली, दवा पालन, चक्कर, इलेक्ट्रोलाइट और गुर्दे की निगरानी साथ रखें। दवा बदलने के बाद लाभ और नुकसान दोनों की समीक्षा करें।","files":{"hi":"audio/hypertension-hi.mp3","en":"audio/hypertension-en.mp3"},"duration":{"hi":41.4,"en":49.7},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"warfarin-dosing","topic":"warfarin-dosing","title":"Warfarin Dosing","en":"Warfarin Dosing. Before a dose decision. Confirm indication, the prescribed INR target, current regimen, recent doses and recent INR trend. Ask about missed doses, dietary changes, acute illness and new or stopped medicines. Do not adjust from one number without context. Use the current local anticoagulation protocol and patient-specific clinical assessment. Counselling priorities. Explain the purpose of INR monitoring and the individualized dosing schedule. Discuss adherence, interactions, consistent dietary habits and the agreed plan for missed doses. Serious bleeding, a head injury or symptoms suggesting thrombosis need urgent assessment. Explain warning signs and whom to contact using the current care plan.","hi":"वारफरिन में पहले कारण, निर्धारित आई एन आर लक्ष्य और वर्तमान साप्ताहिक योजना पुष्टि करें। आज का आई एन आर उसके पिछले पैटर्न, छूटी खुराक, भोजन, बीमारी और नई दवाओं के साथ समझें। खून आने के संकेत पहले पूछें। केवल एक संख्या से याद की हुई खुराक न दें। उत्पाद और स्थानीय प्रोटोकॉल के अनुसार सही टीम से योजना लें। अगली जांच की तारीख और मरीज को हर दिन की स्पष्ट मात्रा बताएं। विटामिन के वाले भोजन को बिल्कुल बंद करने के बजाय स्थिर सेवन की सलाह दें।","files":{"en":"audio/warfarin-dosing-en.mp3","hi":"audio/warfarin-dosing-hi.mp3"},"duration":{"en":49.1,"hi":41.5},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"stroke-transient-ischemic-attack-tia","topic":"stroke-transient-ischemic-attack-tia","title":"Stroke & Transient Ischemic Attack (TIA)","en":"Stroke & Transient Ischemic Attack (TIA). Assessment. Sudden facial weakness, arm weakness or speech difficulty may represent stroke. Record when the person was last known well; resolved symptoms can still indicate a TIA and require urgent assessment. Treatment principles. Activate emergency care for suspected acute stroke. Brain imaging and specialist assessment distinguish bleeding from ischaemia and determine treatment. Later prevention depends on the cause: antiplatelet therapy and anticoagulation are not interchangeable. Safety and follow-up. Do not delay referral to measure every risk factor or give oral medication to someone with impaired swallowing. After discharge, reconcile medicines and review blood pressure, lipids, smoking, adherence and bleeding symptoms.","hi":"अचानक चेहरा टेढ़ा होना, हाथ कमजोर होना या बोलने में परेशानी स्ट्रोक का संकेत हो सकता है। लक्षण शुरू होने से पहले मरीज आखिरी बार कब सामान्य था, यह समय लिखें। लक्षण ठीक हो जाएं तब भी तुरंत जांच जरूरी है। आपातकालीन मदद बुलाएं। निगलने में परेशानी हो तो मुंह से दवा न दें। जांच के बिना एस्पिरिन या खून पतला करने की दवा शुरू न करें। बाद में कारण के अनुसार इलाज, रक्तचाप, कोलेस्ट्रॉल और दवा पालन की समीक्षा करें।","files":{"hi":"audio/stroke-transient-ischemic-attack-tia-hi.mp3","en":"audio/stroke-transient-ischemic-attack-tia-en.mp3"},"duration":{"hi":39.6,"en":51.6},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"syncope","topic":"syncope","title":"Syncope","en":"Syncope. Assessment. Clarify whether there was true loss of consciousness, the posture and trigger, warning symptoms, duration, injury and recovery. Ask about exertion, palpitations, chest pain, heart disease and medicines that lower blood pressure or prolong QT. Treatment principles. A typical faint may have a recognizable trigger and rapid recovery, but a medicine explanation does not exclude an arrhythmia. Assess hydration, orthostatic symptoms and recent dose changes; arrange appropriate medical evaluation. Safety and follow-up. Exertional collapse, chest pain, persistent confusion, neurological symptoms or a family history of sudden death are concerning. Do not advise driving until the cause and relevant restrictions have been assessed.","hi":"बेहोशी के बारे में पूछें: घटना किस स्थिति में हुई, पहले क्या महसूस हुआ और होश कितनी जल्दी आया। व्यायाम के दौरान बेहोशी, छाती में दर्द, धड़कन या परिवार में अचानक मृत्यु का इतिहास गंभीर संकेत हैं। रक्तचाप कम करने वाली और हृदय की लय बदलने वाली दवाएं जांचें। केवल पानी की कमी मानकर बात खत्म न करें। कारण की जांच और सुरक्षित गतिविधियों की सलाह जरूरी है।","files":{"hi":"audio/syncope-hi.mp3","en":"audio/syncope-en.mp3"},"duration":{"hi":32.7,"en":48.2},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"dyslipidaemia","topic":"dyslipidaemia","title":"Dyslipidaemia","en":"Dyslipidaemia. Assessment. Interpret lipids with overall cardiovascular risk, previous vascular disease, diabetes, kidney disease and family history. Ask about secondary causes and medicines; LDL cholesterol alone does not describe the whole decision. Treatment principles. Lifestyle measures accompany medication when indicated. Statins reduce cardiovascular events in appropriate patients; select intensity and additional therapy using current Canadian guidance, expected benefit, tolerability and preferences. Safety and follow-up. Review interacting medicines and unexplained muscle symptoms. Severe muscle pain with weakness or dark urine needs prompt assessment. Check adherence and follow-up lipids before labelling a regimen ineffective; avoid stopping long-term prevention without a plan.","hi":"कोलेस्ट्रॉल का निर्णय केवल एल डी एल संख्या से नहीं होता। पहले हृदय रोग, मधुमेह, गुर्दे की बीमारी और कुल जोखिम देखें। उचित मरीजों में स्टैटिन दिल के दौरे और स्ट्रोक का जोखिम घटाती हैं। जीवनशैली और दवा पालन साथ चलें। नई मांसपेशियों की कमजोरी या गहरे रंग का पेशाब हो तो जल्दी जांच करवाएं। उपचार बदलने से पहले दवा का नियमित उपयोग, दवा अंतःक्रिया और दोबारा जांच की समीक्षा करें।","files":{"hi":"audio/dyslipidaemia-hi.mp3","en":"audio/dyslipidaemia-en.mp3"},"duration":{"hi":35.4,"en":52.9},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"dvt-and-pe","topic":"dvt-and-pe","title":"DVT and PE","en":"DVT and PE. Assessment. One swollen painful leg may indicate deep-vein thrombosis. New unexplained breathlessness, pleuritic chest pain, coughing blood or collapse may indicate pulmonary embolism. Symptoms require assessment; they do not confirm the diagnosis alone. Treatment principles. Suspected PE needs urgent emergency evaluation. Anticoagulant selection and duration depend on the confirmed diagnosis, provoking factors, recurrence risk, bleeding risk, kidney function, pregnancy and cancer context. Safety and follow-up. Check the exact anticoagulant and treatment phase because starting and maintenance regimens can differ. Teach adherence, bleeding precautions and what to do for missed doses using the product-specific plan. Do not substitute aspirin for prescribed VTE treatment.","hi":"एक पैर में नई सूजन और दर्द गहरी नस में थक्का होने का संकेत हो सकता है। अचानक सांस फूलना, छाती में दर्द या बेहोशी फेफड़े में थक्के के गंभीर संकेत हैं। तुरंत चिकित्सा जांच करवाएं। खून पतला करने वाली दवा का चुनाव और अवधि मरीज के जोखिम पर निर्भर हैं। शुरुआती और बाद की खुराक अलग हो सकती है। दवा का सही चरण, गुर्दे की स्थिति, रक्तस्राव और छूटी खुराक की सलाह जांचें।","files":{"hi":"audio/dvt-and-pe-hi.mp3","en":"audio/dvt-and-pe-en.mp3"},"duration":{"hi":35.8,"en":54.9},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"atrial-fibrillation","topic":"atrial-fibrillation","title":"Atrial Fibrillation","en":"Atrial Fibrillation. Assessment. An irregular pulse requires diagnostic assessment. Separate symptoms and ventricular-rate control from prevention of embolic stroke. Review heart failure, valvular disease, kidney function, previous stroke and bleeding factors. Treatment principles. Rate control, rhythm control and anticoagulation address different goals. Use the applicable Canadian risk approach and shared decision-making. Some valve conditions require warfarin rather than a direct oral anticoagulant. Safety and follow-up. Verify anticoagulant dose criteria and interacting medicines rather than reducing the dose solely because a person is older. Monitor symptoms, pulse, renal function and bleeding. Haemodynamic instability or new stroke symptoms requires emergency care.","hi":"एट्रियल फिब्रिलेशन में तीन अलग लक्ष्य याद रखें: हृदय की गति, उसकी लय और स्ट्रोक से बचाव। केवल धड़कन नियंत्रित होने से स्ट्रोक का खतरा खत्म नहीं होता। वाल्व की बीमारी, उम्र, वजन, गुर्दे की कार्यक्षमता और रक्तस्राव का जोखिम जांचें। कुछ वाल्व स्थितियों में वारफरिन जरूरी होती है। केवल बुजुर्ग होने पर खुराक कम न करें। नई कमजोरी, बोलने में परेशानी या अस्थिर हालत में तुरंत आपातकालीन मदद लें।","files":{"en":"audio/atrial-fibrillation-en.mp3","hi":"audio/atrial-fibrillation-hi.mp3"},"duration":{"en":53.2,"hi":35.5},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"heart-failure","topic":"heart-failure","title":"Heart Failure","en":"Heart Failure. Assessment. Assess breathlessness, swelling, weight trend, exercise tolerance, blood pressure and congestion. Identify the heart-failure phenotype and triggers such as missed medicines, infection, arrhythmia or NSAID exposure. Treatment principles. In reduced-ejection-fraction heart failure, disease-modifying classes include renin–angiotensin system therapy, selected beta blockers, mineralocorticoid antagonists and SGLT2 inhibitors when appropriate. Diuretics relieve congestion but do not replace the other indicated therapies. Safety and follow-up. Review potassium, kidney function, dizziness and fluid status after changes. Provide an individualized action plan for worsening symptoms. Severe breathlessness at rest, chest pain or confusion requires emergency assessment; do not independently double every medicine.","hi":"हार्ट फेल्योर में सांस, पैरों की सूजन, वजन, रक्तचाप और रोजमर्रा की क्षमता देखें। बीमारी का प्रकार जानना जरूरी है। कुछ दवाएं लंबे समय के परिणाम सुधारती हैं और मूत्रवर्धक दवाएं अतिरिक्त पानी कम करती हैं; दोनों का काम अलग है। दवा बदलने पर पोटैशियम और गुर्दे की जांच देखें। आराम में तेज सांस फूलना, छाती में दर्द या भ्रम हो तो आपातकालीन मदद लें। वजन बढ़ने पर अपनी लिखित योजना के अनुसार कदम उठाएं।","files":{"en":"audio/heart-failure-en.mp3","hi":"audio/heart-failure-hi.mp3"},"duration":{"en":56.6,"hi":38.0},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"raynaud-s-phenomenon","topic":"raynaud-s-phenomenon","title":"Raynaud's Phenomenon","en":"Raynaud's Phenomenon. Assessment. Ask about cold- or stress-triggered colour changes, symmetry, pain, ulcers and associated autoimmune symptoms. New severe, asymmetric or late-onset symptoms raise concern for a secondary cause. Treatment principles. Keep the body and hands warm, avoid smoking and review vasoconstricting medicines. Persistent symptoms may need a clinician-directed vasodilator such as a dihydropyridine calcium-channel blocker, with attention to blood pressure and tolerability. Safety and follow-up. Persistent ischaemic pain, ulcers or a finger remaining cold and discoloured need prompt assessment. Do not assume every colour change is benign Raynaud's; assess circulation and the broader history.","hi":"ठंड या तनाव से उंगलियों का रंग बदलना रेनॉड की समस्या हो सकती है। दोनों हाथों में समान लक्षण हैं या केवल एक तरफ, यह पूछें। शरीर और हाथ गर्म रखें, धूम्रपान और रक्तवाहिकाएं सिकोड़ने वाली दवाओं की समीक्षा करें। लगातार दर्द, घाव या उंगली ठंडी और नीली रहने पर जल्दी जांच जरूरी है। हर रंग परिवर्तन को सामान्य रेनॉड न मानें। जरूरत पर डॉक्टर रक्तवाहिका फैलाने वाली दवा चुनते हैं।","files":{"hi":"audio/raynaud-s-phenomenon-hi.mp3","en":"audio/raynaud-s-phenomenon-en.mp3"},"duration":{"hi":36.7,"en":47.9},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"acute-coronary-syndrome-and-stable-angina","topic":"acute-coronary-syndrome-and-stable-angina","title":"Acute Coronary Syndrome and Stable Angina","en":"Acute Coronary Syndrome and Stable Angina. Assessment. New, prolonged or worsening chest pressure, especially at rest or with sweating, breathlessness or nausea, may represent acute coronary syndrome. A previous angina diagnosis does not make new symptoms safe. Treatment principles. Activate emergency services for suspected acute coronary syndrome and follow the emergency plan. Stable angina management combines symptom relief with cardiovascular risk reduction. Confirm the patient's prescribed nitroglycerin instructions and contraindicating interactions. Safety and follow-up. Nitrates can interact dangerously with phosphodiesterase-5 inhibitors; clarify the exact drug and timing. Do not let apparent relief with an antacid or nitroglycerin rule out an infarction. Review adherence and prevention after acute care.","hi":"नया या बढ़ता छाती का दबाव, पसीना, मतली या सांस फूलना दिल के दौरे का संकेत हो सकता है। पुरानी एंजाइना होने से नया दर्द सुरक्षित नहीं हो जाता। आपातकालीन मदद लें। नाइट्रोग्लिसरीन की निर्धारित योजना और दूसरी दवाएं जांचें। इरेक्टाइल डिसफंक्शन की कुछ दवाओं के साथ नाइट्रेट खतरनाक रक्तचाप गिरा सकते हैं। दर्द कम होने से दिल का दौरा खारिज नहीं होता।","files":{"en":"audio/acute-coronary-syndrome-and-stable-angina-en.mp3","hi":"audio/acute-coronary-syndrome-and-stable-angina-hi.mp3"},"duration":{"en":54.8,"hi":33.0},"subject":"Cardiology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"sinusitis","topic":"sinusitis","title":"Sinusitis","en":"Sinusitis. Assessment. Ask about duration, initial improvement followed by worsening, fever, unilateral symptoms and dental pain. Most early acute sinus symptoms accompany viral illness; discharge colour alone does not establish bacterial infection. Treatment principles. Analgesia and saline measures can support symptom relief. Consider intranasal treatment and antibiotic assessment according to severity, duration and local guidance. Check pregnancy, allergies and comorbidities before recommending a product. Safety and follow-up. Eye swelling, visual change, severe frontal headache, neurological symptoms or systemic illness require urgent evaluation. Explain the expected course and when reassessment is needed rather than promising antibiotics for every episode.","hi":"साइनस में दर्द और नाक बहना अक्सर वायरस से होता है। लक्षण कितने दिन से हैं और पहले ठीक होकर फिर बिगड़े हैं या नहीं, पूछें। केवल पीले या हरे स्राव से एंटीबायोटिक तय नहीं करें। दर्द नियंत्रण और नमक वाले पानी से राहत मिल सकती है। आंख के आसपास सूजन, नजर बदलना, बहुत तेज सिरदर्द या गंभीर बीमारी हो तो तुरंत जांच करवाएं। सुधार न होने पर दोबारा मूल्यांकन की योजना दें।","files":{"hi":"audio/sinusitis-hi.mp3","en":"audio/sinusitis-en.mp3"},"duration":{"hi":35.3,"en":51.6},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"meningitis","topic":"meningitis","title":"Meningitis","en":"Meningitis. Assessment. Fever with severe headache, neck stiffness, altered consciousness or a concerning rash can signal meningitis. Infants and immunocompromised people may have less typical findings; absence of the classic combination does not exclude serious illness. Treatment principles. Suspected meningitis requires emergency assessment and timely hospital treatment. Empiric treatment depends on age, host factors and likely organism, then is refined with investigations. Pharmacy work includes allergy clarification, renal review and timely supply. Safety and follow-up. Do not delay emergency transfer for a complete community medication interview. Some organisms trigger public-health action and prophylaxis for specified contacts; casual contacts should not self-start leftover antibiotics.","hi":"बुखार के साथ तेज सिरदर्द, गर्दन अकड़ना, भ्रम या चिंताजनक चकत्ते मेनिन्जाइटिस के संकेत हो सकते हैं। छोटे बच्चों और कमजोर प्रतिरक्षा वाले मरीजों में सभी सामान्य लक्षण नहीं होते। तुरंत अस्पताल की जांच और इलाज जरूरी है। लंबी दवा सूची बनाने के लिए रेफरल न रोकें। कुछ संक्रमणों में खास संपर्कों को बचाव की दवा दी जाती है, लेकिन यह सार्वजनिक स्वास्थ्य टीम के निर्देश से होनी चाहिए।","files":{"hi":"audio/meningitis-hi.mp3","en":"audio/meningitis-en.mp3"},"duration":{"hi":34.3,"en":53.7},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"uti","topic":"uti","title":"UTI","en":"UTI. Assessment. Distinguish bladder symptoms from fever, flank pain, vomiting or systemic illness suggesting upper-tract infection. Ask about pregnancy, sex, age, catheters, previous cultures and recent antibiotics. Treatment principles. Choice of therapy depends on the infection site, local resistance, kidney function, allergies and culture information when indicated. A medicine appropriate for cystitis may not achieve adequate tissue levels for pyelonephritis. Safety and follow-up. Bacteria in urine without relevant symptoms is not automatically an indication for antibiotics; important exceptions require a specific indication. Escalate suspected pyelonephritis, sepsis or pregnancy-related concerns and reassess persistent symptoms.","hi":"पेशाब में जलन और बार-बार पेशाब को बुखार, कमर के एक तरफ दर्द और उल्टी से अलग करें। बाद वाले लक्षण गुर्दे के संक्रमण का संकेत हो सकते हैं। गर्भावस्था, पुरानी कल्चर रिपोर्ट, गुर्दे की स्थिति और एंटीबायोटिक का इतिहास देखें। मूत्राशय के संक्रमण की हर दवा गुर्दे के संक्रमण के लिए सही नहीं होती। बिना लक्षण केवल बैक्टीरिया मिलने पर हमेशा एंटीबायोटिक जरूरी नहीं है।","files":{"hi":"audio/uti-hi.mp3","en":"audio/uti-en.mp3"},"duration":{"hi":33.7,"en":50.6},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"covid","topic":"covid","title":"COVID","en":"COVID. Assessment. Establish symptom onset, severity, risk of progression, vaccination history and current medicines. Breathlessness, low oxygen when reliably measured, confusion or inability to maintain hydration warrants urgent assessment. Treatment principles. Antiviral eligibility and timing follow current provincial guidance. Before nirmatrelvir/ritonavir, reconcile all medicines and assess interactions and kidney function; some interactions need an alternative treatment rather than a simple dose separation. Safety and follow-up. Provide symptom care, transmission precautions and follow-up advice appropriate to current public-health guidance. Do not promise an antiviral to everyone or recommend an unreviewed interruption of an essential medicine.","hi":"कोविड में लक्षण शुरू होने का समय, गंभीरता और बिगड़ने का जोखिम देखें। सांस फूलना, भ्रम या पानी न पी पाना गंभीर संकेत हैं। एंटीवायरल की पात्रता और समय प्रांतीय निर्देशों पर निर्भर है। नर्माट्रेलविर और रिटोनाविर देने से पहले सभी दवाएं और गुर्दे की स्थिति जांचें। कुछ दवा अंतःक्रियाएं केवल समय अलग करने से ठीक नहीं होतीं। जरूरी दवा अपने आप बंद न करवाएं।","files":{"en":"audio/covid-en.mp3","hi":"audio/covid-hi.mp3"},"duration":{"en":49.0,"hi":34.2},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"acute-otitis-media","topic":"acute-otitis-media","title":"Acute Otitis Media","en":"Acute Otitis Media. Assessment. Ear pain alone does not confirm middle-ear infection. Diagnosis depends on otoscopic findings and symptoms. Assess age, severity, duration, fever, discharge and the child's ability to drink. Treatment principles. Pain relief is important whether observation or antibiotics are selected. Appropriate observation requires a reliable follow-up plan; antibiotic decisions depend on age, diagnostic certainty, severity and current guidance. Safety and follow-up. Swelling or tenderness behind the ear, a protruding ear, severe illness or neurological signs need urgent assessment. Check weight and concentration when dispensing a liquid; do not infer millilitres directly from a milligram dose.","hi":"कान का दर्द अकेले मध्य कान का संक्रमण साबित नहीं करता; कान की जांच जरूरी है। बच्चे की उम्र, बुखार, दर्द और पानी पीने की क्षमता देखें। दर्द कम करना महत्वपूर्ण है। कुछ स्थितियों में निगरानी और कुछ में एंटीबायोटिक जरूरी होते हैं। कान के पीछे सूजन, कान बाहर की ओर आना या गंभीर कमजोरी हो तो जल्दी जांच कराएं। तरल दवा में बच्चे का वजन और बोतल की सांद्रता अलग से जांचें।","files":{"en":"audio/acute-otitis-media-en.mp3","hi":"audio/acute-otitis-media-hi.mp3"},"duration":{"en":50.2,"hi":35.2},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"sepsis-septic-shock","topic":"sepsis-septic-shock","title":"Sepsis & Septic Shock","en":"Sepsis & Septic Shock. Assessment. Sepsis is life-threatening organ dysfunction related to infection. Confusion, marked deterioration, rapid breathing, low blood pressure or poor urine output are concerning; fever need not be present. Treatment principles. Activate urgent emergency care. Hospital priorities include assessment, timely antimicrobials, source control and haemodynamic support. Obtain cultures when appropriate without creating a harmful delay in treatment. Safety and follow-up. Pharmacy review includes allergies, likely source, organ function, dose timing, compatibility and subsequent narrowing of therapy. Do not manage a patient with shock by simply recommending oral fluids and an outpatient antibiotic.","hi":"सेप्सिस में संक्रमण के साथ अंगों की कार्यक्षमता बिगड़ती है। भ्रम, तेज सांस, कम रक्तचाप या कम पेशाब गंभीर संकेत हैं; बुखार न होने पर भी खतरा हो सकता है। तुरंत आपातकालीन इलाज जरूरी है। अस्पताल में समय पर एंटीबायोटिक, संक्रमण के स्रोत का नियंत्रण और रक्तसंचार की सहायता दी जाती है। फार्मासिस्ट एलर्जी, गुर्दे की स्थिति, सही समय और दवा की उपयुक्तता जांचता है।","files":{"hi":"audio/sepsis-septic-shock-hi.mp3","en":"audio/sepsis-septic-shock-en.mp3"},"duration":{"hi":35.2,"en":49.1},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"diabetic-foot-infections","topic":"diabetic-foot-infections","title":"Diabetic Foot Infections","en":"Diabetic Foot Infections. Assessment. Examine the history of an ulcer, neuropathy, circulation, trauma and systemic symptoms. Infection requires clinical evidence; colonization of a wound is not the same as an infected ulcer. Treatment principles. Management combines wound care, pressure off-loading, perfusion assessment, glycaemic care and antimicrobials when infection is present. Deep or severe infection may need imaging, surgical input and appropriately obtained cultures. Safety and follow-up. Spreading infection, necrosis, systemic illness or suspected critical ischaemia requires urgent assessment. Antibiotics alone cannot correct pressure injury or inadequate blood supply. Teach daily foot inspection and prompt reporting of new lesions.","hi":"मधुमेह के पैर के घाव में संक्रमण, रक्तप्रवाह और संवेदना तीनों देखें। हर कल्चर में बैक्टीरिया मिलना संक्रमण नहीं है। इलाज में घाव की देखभाल, दबाव कम करना, रक्तप्रवाह और शुगर नियंत्रण शामिल हैं। गहरा संक्रमण या मृत ऊतक होने पर अस्पताल की जरूरत हो सकती है। केवल एंटीबायोटिक पर्याप्त नहीं होती। रोज पैर देखें और नया घाव, सूजन या रंग बदलने पर जल्दी सूचना दें।","files":{"en":"audio/diabetic-foot-infections-en.mp3","hi":"audio/diabetic-foot-infections-hi.mp3"},"duration":{"en":50.4,"hi":35.3},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"onychomycosis","topic":"onychomycosis","title":"Onychomycosis","en":"Onychomycosis. Assessment. Thick or discoloured nails have several causes. Confirm fungal infection before prolonged systemic treatment when indicated, and assess extent, other skin infection, diabetes and circulation. Treatment principles. Topical and oral options differ in effectiveness, duration and monitoring. Oral terbinafine requires review of liver disease, interactions and appropriate baseline assessment. Nail appearance improves slowly as a healthy nail grows. Safety and follow-up. Avoid promising a normal-looking nail in a few days. Review adherence and adverse effects; concerning liver symptoms require assessment. Painful surrounding infection or a high-risk diabetic foot needs a broader evaluation.","hi":"मोटा या बदरंग नाखून हमेशा फंगस नहीं होता। लंबे समय की खाने वाली दवा से पहले निदान की पुष्टि करें। बाहरी और खाने वाली दवाओं की अवधि और असर अलग हैं। टर्बिनाफिन से पहले लिवर और दवा अंतःक्रिया देखें। नया नाखून धीरे बढ़ता है, इसलिए परिणाम में समय लगता है। लिवर संबंधी लक्षण या मधुमेह में दर्द वाला घाव हो तो जांच जरूरी है।","files":{"hi":"audio/onychomycosis-hi.mp3","en":"audio/onychomycosis-en.mp3"},"duration":{"hi":32.7,"en":49.5},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"principles-of-infectious-disease","topic":"principles-of-infectious-disease","title":"Principles of Infectious Disease","en":"Principles of Infectious Disease. Assessment. Identify the likely site, organism, severity and host factors. Ask whether infection is actually present and whether cultures or other tests will change management. Treatment principles. Choose an antimicrobial using spectrum, penetration, local susceptibility, allergy history and organ function. Empiric treatment is reassessed when microbiology and clinical progress become available; narrow or stop therapy when appropriate. Safety and follow-up. Correct drug selection does not replace drainage, device removal or other source control. Document indication and review date. Discuss adherence, relevant adverse effects and reassessment if symptoms worsen or fail to improve.","hi":"संक्रमण में पहले स्थान, गंभीरता, संभावित जीवाणु और मरीज के जोखिम पहचानें। सही एंटीबायोटिक चुनने में उसका क्षेत्र, ऊतक में पहुंच, स्थानीय प्रतिरोध, एलर्जी और गुर्दे की स्थिति शामिल हैं। कल्चर और मरीज की प्रगति मिलने पर इलाज दोबारा देखें। जहां जरूरी हो पस निकालना या संक्रमित उपकरण हटाना भी जरूरी है। हर एंटीबायोटिक के लिए कारण और समीक्षा की तारीख लिखें।","files":{"hi":"audio/principles-of-infectious-disease-hi.mp3","en":"audio/principles-of-infectious-disease-en.mp3"},"duration":{"hi":33.7,"en":48.7},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"tick-borne-infections","topic":"tick-borne-infections","title":"Tick-Borne Infections","en":"Tick-Borne Infections. Assessment. Ask where exposure occurred, attachment duration if known, removal time, rash and systemic symptoms. Lyme disease is only one tick-borne illness; geography and travel affect the differential. Treatment principles. Remove an attached tick correctly and assess whether the current local criteria support prophylaxis. Prophylaxis is not automatically indicated after every bite and is distinct from treating established disease. Safety and follow-up. An expanding rash, facial weakness, severe headache, palpitations or systemic illness needs assessment. A negative early antibody test does not reliably exclude early infection. Record exposure details and provide a symptom follow-up plan.","hi":"टिक काटने पर जगह, चिपके रहने का समय, हटाने का समय और लक्षण पूछें। हर टिक काटने के बाद बचाव की एंटीबायोटिक जरूरी नहीं होती। स्थानीय मानदंड देखें। फैलता लाल चकत्ता, चेहरे की कमजोरी, धड़कन या तेज सिरदर्द हो तो जांच कराएं। शुरुआती जांच नकारात्मक होने से बीमारी पूरी तरह खारिज नहीं होती। बचाव की खुराक और स्थापित बीमारी का इलाज अलग हैं।","files":{"en":"audio/tick-borne-infections-en.mp3","hi":"audio/tick-borne-infections-hi.mp3"},"duration":{"en":48.2,"hi":33.3},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"fungal-infections","topic":"fungal-infections","title":"Fungal Infections","en":"Fungal Infections. Assessment. Distinguish a localized skin infection from mucosal or invasive disease. Site, immune status, previous treatment and possible mimics guide assessment; a rash is not automatically fungal. Treatment principles. Select topical or systemic therapy according to the site and organism. Systemic azoles have important interactions and may require hepatic or electrocardiographic review. Some medicines suitable for skin cannot treat invasive infection. Safety and follow-up. Avoid masking an uncertain fungal rash with corticosteroid monotherapy. Fever in a severely immunocompromised patient needs urgent evaluation. Teach correct application, duration and when nonresponse requires diagnostic reassessment.","hi":"फंगल संक्रमण में त्वचा, मुंह और शरीर के अंदर के संक्रमण अलग हैं। स्थान और प्रतिरक्षा की स्थिति के अनुसार इलाज चुनें। खाने वाली एजोल दवाओं की महत्वपूर्ण अंतःक्रियाएं हो सकती हैं। बिना स्पष्ट निदान स्टेरॉयड अकेले लगाने से फंगस छिप या बिगड़ सकता है। कमजोर प्रतिरक्षा वाले मरीज में बुखार हो तो तुरंत जांच जरूरी है। इलाज से सुधार न हो तो निदान दोबारा देखें।","files":{"hi":"audio/fungal-infections-hi.mp3","en":"audio/fungal-infections-en.mp3"},"duration":{"hi":34.6,"en":50.8},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pep-occupational-infections","topic":"pep-occupational-infections","title":"PEP & Occupational Infections","en":"PEP & Occupational Infections. Assessment. After a needlestick or mucosal exposure, establish the exposure type, time, source information, vaccination history and baseline health. Provide immediate first aid and use the workplace exposure pathway promptly. Treatment principles. Assess HIV, hepatitis B and hepatitis C separately. HIV post-exposure prophylaxis is time sensitive; hepatitis B management depends on immunity and exposure circumstances. There is no vaccine against hepatitis C. Safety and follow-up. Do not wait for every result before urgent specialist advice. Protect confidentiality, document the event and arrange baseline and follow-up testing. A reassuring appearance of the source person does not establish absence of infection.","hi":"सुई चुभने या श्लेष्मा पर खून लगने के बाद समय, संपर्क का प्रकार और हेपेटाइटिस बी टीकाकरण पूछें। तुरंत प्राथमिक सहायता और कार्यस्थल की प्रक्रिया अपनाएं। एच आई वी की बचाव दवा समय पर शुरू करनी होती है। हेपेटाइटिस बी की योजना प्रतिरक्षा पर निर्भर है; हेपेटाइटिस सी का टीका नहीं है। जरूरी सलाह के लिए सभी रिपोर्ट का इंतजार न करें। गोपनीयता और बाद की जांच सुनिश्चित करें।","files":{"hi":"audio/pep-occupational-infections-hi.mp3","en":"audio/pep-occupational-infections-en.mp3"},"duration":{"hi":35.0,"en":51.9},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"tuberculosis","topic":"tuberculosis","title":"Tuberculosis","en":"Tuberculosis. Assessment. Persistent cough, weight loss, night sweats, fever and relevant exposure warrant assessment. Distinguish active TB disease from TB infection without disease; their public-health implications and regimens differ. Treatment principles. Active TB generally requires several medicines under specialist and public-health supervision. Review adherence support, liver risk, vision monitoring when relevant and the substantial interaction burden of rifamycins. Safety and follow-up. Suspected infectious pulmonary TB needs appropriate infection-control arrangements before routine in-person care. Do not treat active disease with a single drug. Stopping or missing treatment requires coordinated follow-up rather than blame.","hi":"लंबी खांसी, वजन कम होना, रात का पसीना और संपर्क का इतिहास टी बी की जांच का कारण हैं। सक्रिय बीमारी और केवल संक्रमण की स्थिति अलग हैं। सक्रिय टी बी में विशेषज्ञ की निगरानी में कई दवाएं दी जाती हैं। लिवर, कुछ दवाओं में नजर और रिफामाइसिन की अंतःक्रियाएं देखें। सक्रिय बीमारी का इलाज एक दवा से न करें। दवा पालन में परेशानी पर सहयोग और सार्वजनिक स्वास्थ्य टीम से समन्वय करें।","files":{"hi":"audio/tuberculosis-hi.mp3","en":"audio/tuberculosis-en.mp3"},"duration":{"hi":36.0,"en":49.0},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pharyngitis-bronchitis","topic":"pharyngitis-bronchitis","title":"Pharyngitis & Bronchitis","en":"Pharyngitis & Bronchitis. Assessment. Assess throat pain, cough, duration, fever, airway symptoms and illness severity. Viral causes are common. Clinical assessment and indicated testing distinguish streptococcal pharyngitis; sputum colour does not prove bacterial bronchitis. Treatment principles. Offer suitable symptom care and explain expected recovery. Antibiotics are reserved for an appropriate bacterial indication. Persistent cough may have alternatives such as asthma, pneumonia, pertussis or a medicine effect. Safety and follow-up. Stridor, drooling, inability to swallow fluids, respiratory distress or significant systemic illness requires urgent assessment. Do not prescribe an antibiotic solely because the patient requests one or had one previously.","hi":"गले में दर्द और खांसी अक्सर वायरस से होते हैं। हरे कफ से बैक्टीरिया सिद्ध नहीं होते। स्ट्रेप गले की बीमारी में उपयुक्त जांच मदद करती है। लक्षणों से राहत और ठीक होने की अपेक्षित अवधि समझाएं। सांस में कठिनाई, लार टपकना या पानी न निगल पाना गंभीर संकेत हैं। पुरानी बार एंटीबायोटिक मिली थी, यह इस बार देने का पर्याप्त कारण नहीं है।","files":{"en":"audio/pharyngitis-bronchitis-en.mp3","hi":"audio/pharyngitis-bronchitis-hi.mp3"},"duration":{"en":52.2,"hi":33.1},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pneumonia","topic":"pneumonia","title":"Pneumonia","en":"Pneumonia. Assessment. Assess cough, fever, breathlessness, chest pain, oxygenation where available, comorbidities and mental status. Older or immunocompromised people may present atypically; severity determines the care setting. Treatment principles. Treatment considers community versus healthcare exposure, likely pathogens, local resistance, allergies and organ function. Reassess response and investigations; not every cough needs antibiotic therapy. Safety and follow-up. Hypoxia, confusion, haemodynamic instability or inability to take oral treatment needs urgent escalation. Review interacting QT-prolonging medicines and antibiotic adverse effects. Give a clear plan if breathing worsens or improvement does not occur.","hi":"निमोनिया में खांसी के साथ सांस, बुखार, छाती का दर्द और मानसिक स्थिति देखें। बुजुर्गों में लक्षण अलग हो सकते हैं। गंभीरता तय करती है कि घर या अस्पताल में इलाज हो। ऑक्सीजन कम होना, भ्रम या दवा और पानी न ले पाना गंभीर है। एंटीबायोटिक का चुनाव एलर्जी, गुर्दे की स्थिति और स्थानीय प्रतिरोध के अनुसार करें। सुधार न होने पर दोबारा जांच का स्पष्ट निर्देश दें।","files":{"en":"audio/pneumonia-en.mp3","hi":"audio/pneumonia-hi.mp3"},"duration":{"en":50.8,"hi":34.1},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"influenza","topic":"influenza","title":"Influenza","en":"Influenza. Assessment. Ask about onset, severity, risk factors and exposure. Influenza can worsen chronic disease, and serious illness can occur without a textbook presentation. Treatment principles. Antiviral treatment depends on timing, severity and risk of complications; severe or high-risk illness may merit treatment even when presentation is later. Supportive care and prevention remain important. Adjust relevant medicines for kidney function. Safety and follow-up. Breathing difficulty, dehydration, confusion or deterioration after initial improvement needs reassessment. Avoid aspirin-containing products in children and adolescents with viral illness. Vaccination decisions follow current Canadian recommendations.","hi":"इन्फ्लुएंजा में लक्षण शुरू होने का समय और गंभीर बीमारी का जोखिम देखें। एंटीवायरल का निर्णय केवल एक समय सीमा से नहीं; गंभीरता और जोखिम से भी होता है। सांस में कठिनाई, पानी की कमी या पहले सुधार के बाद बिगड़ना दोबारा जांच का कारण है। वायरल बीमारी में बच्चों और किशोरों को एस्प्रिन वाले उत्पाद न दें। टीकाकरण के लिए वर्तमान कनाडाई सलाह देखें।","files":{"en":"audio/influenza-en.mp3","hi":"audio/influenza-hi.mp3"},"duration":{"en":49.8,"hi":32.5},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pep-prep","topic":"pep-prep","title":"PEP & PrEP","en":"PEP & PrEP. Assessment. PEP follows a possible HIV exposure; PrEP prevents acquisition during ongoing risk. Establish timing, HIV status, exposure context, kidney health, hepatitis B status and the person's preferences without judgment. Treatment principles. PEP assessment is urgent and should follow a current specialist or provincial protocol. PrEP requires appropriate HIV testing and follow-up; choosing a regimen depends on exposure type, formulation, adherence and clinical factors. Safety and follow-up. Neither approach replaces testing and broader sexual-health care. Starting prevention in unrecognized HIV infection can complicate treatment. Clarify missed doses and follow-up appointments; do not transfer one person's regimen to another.","hi":"पी ई पी संभावित एच आई वी संपर्क के बाद और प्रेप लगातार जोखिम से बचाव के लिए है। संपर्क का समय, एच आई वी जांच, गुर्दे और हेपेटाइटिस बी की स्थिति पूछें। पी ई पी का मूल्यांकन तुरंत करें। प्रेप से पहले और दौरान उचित जांच जरूरी है। बिना पहचाने एच आई वी संक्रमण में रोकथाम की दवा शुरू करना समस्या पैदा कर सकता है। एक व्यक्ति की योजना दूसरे को न दें।","files":{"en":"audio/pep-prep-en.mp3","hi":"audio/pep-prep-hi.mp3"},"duration":{"en":51.1,"hi":34.3},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"sexually-transmitted-infections","topic":"sexually-transmitted-infections","title":"Sexually Transmitted Infections","en":"Sexually Transmitted Infections. Assessment. Take a confidential, nonjudgmental sexual history based on anatomy, sites of exposure, symptoms and partners. Pregnancy possibility, assault concerns and systemic symptoms change the assessment. Treatment principles. Use current Canadian organism-specific testing and treatment guidance. Resistance patterns and recommendations change; confirm the regimen rather than recalling an old dose. Address partner management, reinfection prevention and follow-up testing when indicated. Safety and follow-up. Pelvic pain, testicular pain, pregnancy with concerning symptoms or disseminated illness needs prompt assessment. Explain confidentiality and its legal limits. Treat a positive result in context and arrange the required public-health process.","hi":"यौन संक्रमण में बिना निर्णय किए गोपनीय इतिहास लें। संपर्क का स्थान, लक्षण, गर्भावस्था और साथी की जानकारी उपचार को प्रभावित करते हैं। वर्तमान कनाडाई निर्देश से जांच और दवा चुनें; पुरानी खुराक याद करके न दें। साथी की देखभाल और दोबारा जांच की योजना बनाएं। पेट के नीचे तेज दर्द, अंडकोष में दर्द या गंभीर बीमारी हो तो जल्दी जांच जरूरी है।","files":{"hi":"audio/sexually-transmitted-infections-hi.mp3","en":"audio/sexually-transmitted-infections-en.mp3"},"duration":{"hi":32.4,"en":52.7},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"herpes-simplex-virus","topic":"herpes-simplex-virus","title":"Herpes Simplex Virus","en":"Herpes Simplex Virus. Assessment. Ask about the site, first versus recurrent episode, onset, pain, pregnancy and immune status. Oral or genital lesions can have alternative causes; diagnosis may need testing. Treatment principles. Antiviral treatment can shorten or suppress episodes but does not eradicate latent virus. Episodic and suppressive strategies have different purposes. Review kidney function and timing, and discuss transmission even when lesions are absent. Safety and follow-up. Eye pain or visual symptoms, neonatal exposure, extensive disease in an immunocompromised person or severe urinary difficulty needs prompt care. Use respectful counselling and avoid implying that recurrence proves recent acquisition.","hi":"हर्पीस में पहला और बार-बार होने वाला एपिसोड अलग समझें। एंटीवायरल लक्षण कम कर सकती है, लेकिन वायरस को शरीर से पूरी तरह नहीं निकालती। कभी-कभी रोज की रोकथाम और कभी शुरुआत में उपचार दिया जाता है। घाव न होने पर भी संक्रमण फैल सकता है। आंख में दर्द या नजर बदलना, नवजात का संपर्क या कमजोर प्रतिरक्षा में व्यापक बीमारी हो तो तुरंत चिकित्सा सलाह लें।","files":{"en":"audio/herpes-simplex-virus-en.mp3","hi":"audio/herpes-simplex-virus-hi.mp3"},"duration":{"en":49.3,"hi":32.9},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"osteomyelitis-skin-and-soft-tissue-infections","topic":"osteomyelitis-skin-and-soft-tissue-infections","title":"Osteomyelitis & Skin and Soft Tissue Infections","en":"Osteomyelitis & Skin and Soft Tissue Infections. Assessment. Distinguish cellulitis, a drainable abscess and deeper infection. Ask about trauma, wounds, diabetes, injection exposure and systemic symptoms; persistent focal bone pain raises concern for osteomyelitis. Treatment principles. An abscess may need drainage; antibiotics are chosen for the likely organisms and severity. Suspected bone infection often requires imaging, microbiological diagnosis and an extended coordinated treatment plan. Safety and follow-up. Pain out of proportion, rapid spread, bullae, crepitus or toxicity can indicate a surgical emergency. Do not wait for routine oral-antibiotic follow-up when these signs are present. Mark progression and arrange reassessment where appropriate.","hi":"त्वचा के संक्रमण, पस के फोड़े और हड्डी के संक्रमण को अलग करें। फोड़े में पस निकालना जरूरी हो सकता है। लगातार हड्डी का दर्द गहरी जांच मांगता है। दर्द बहुत ज्यादा होना, तेजी से फैलना, फफोले या गंभीर कमजोरी शल्य चिकित्सा की आपातस्थिति हो सकती है। ऐसे में केवल खाने वाली एंटीबायोटिक देकर इंतजार न करें। घाव, मधुमेह और चोट का इतिहास लें।","files":{"hi":"audio/osteomyelitis-skin-and-soft-tissue-infections-hi.mp3","en":"audio/osteomyelitis-skin-and-soft-tissue-infections-en.mp3"},"duration":{"hi":33.3,"en":53.1},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"otitis-externa","topic":"otitis-externa","title":"Otitis Externa","en":"Otitis Externa. Assessment. Pain with movement of the outer ear and canal symptoms suggest otitis externa, but examine or refer to establish the diagnosis. Ask about swimming, instrumentation, discharge, diabetes and tympanic-membrane status. Treatment principles. Topical therapy is often central for uncomplicated disease. Product selection must account for a possible perforation or tube; not all ear drops are appropriate when the middle ear may be exposed. Safety and follow-up. Severe persistent pain, cranial-nerve findings or illness in a person with diabetes or immunosuppression needs urgent assessment. Teach correct drop use and avoidance of canal trauma; do not advise inserting cotton swabs deeply.","hi":"बाहरी कान हिलाने पर दर्द और कान की नली के लक्षण बाहरी कान के संक्रमण में हो सकते हैं। तैरना, कान में वस्तु डालना और पर्दे की स्थिति पूछें। हर ईयर ड्रॉप फटे पर्दे में सुरक्षित नहीं होती। मधुमेह या कमजोर प्रतिरक्षा में बहुत तेज लगातार दर्द हो तो तुरंत जांच कराएं। बूंदें सही तरीके से डालना सिखाएं और कान में रुई की डंडी अंदर न डालने को कहें।","files":{"en":"audio/otitis-externa-en.mp3","hi":"audio/otitis-externa-hi.mp3"},"duration":{"en":47.1,"hi":30.8},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"intra-abdominal-infections","topic":"intra-abdominal-infections","title":"Intra-abdominal Infections","en":"Intra-abdominal Infections. Assessment. Abdominal infection assessment includes pain location, fever, vomiting, bowel symptoms, prior surgery and haemodynamic status. Peritoneal signs, instability or severe deterioration need urgent care. Treatment principles. Management often requires source control in addition to antibiotics. Regimens depend on the suspected source, severity, resistant-organism risk and kidney function; broad therapy is reassessed after clinical and microbiological information. Safety and follow-up. Do not treat possible perforation or appendicitis as simple indigestion. Review allergies, intravenous compatibility and antimicrobial duration after adequate source control. Monitor for ongoing infection and antibiotic-related complications.","hi":"पेट के अंदर संक्रमण में दर्द की जगह, बुखार, उल्टी, ऑपरेशन का इतिहास और रक्तचाप देखें। पेट बहुत कड़ा होना या हालत तेजी से बिगड़ना गंभीर है। इलाज में एंटीबायोटिक के साथ संक्रमण का स्रोत नियंत्रित करना जरूरी हो सकता है। अपेंडिक्स या आंत में छेद की संभावना को साधारण अपच न मानें। गुर्दे की स्थिति, एलर्जी और इलाज की समीक्षा की तारीख जांचें।","files":{"hi":"audio/intra-abdominal-infections-hi.mp3","en":"audio/intra-abdominal-infections-en.mp3"},"duration":{"hi":32.1,"en":52.9},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"viral-hepatitis","topic":"viral-hepatitis","title":"Viral Hepatitis","en":"Viral Hepatitis. Assessment. Differentiate acute illness from chronic infection and identify the virus with appropriate testing. Ask about exposure, immunization, alcohol, medicines and signs of liver dysfunction. Treatment principles. Hepatitis A and B are vaccine-preventable; hepatitis C has curative antiviral regimens for many patients but no vaccine. Chronic B and C management requires staged assessment and careful interaction review. Safety and follow-up. Confusion, significant bleeding or severe jaundice with deterioration needs urgent care. Check for hepatitis B reactivation considerations when relevant therapies are used. Counsel on transmission, avoidance of harmful exposures and specialist follow-up.","hi":"वायरल हेपेटाइटिस में वायरस का प्रकार और नई या पुरानी बीमारी का अंतर जानें। हेपेटाइटिस ए और बी के टीके हैं, सी का टीका नहीं है। हेपेटाइटिस सी के कई मरीज एंटीवायरल से ठीक हो सकते हैं। इलाज से पहले दवा अंतःक्रिया और लिवर की स्थिति देखें। भ्रम, रक्तस्राव या तेजी से बिगड़ता पीलिया हो तो तुरंत अस्पताल की जांच जरूरी है।","files":{"en":"audio/viral-hepatitis-en.mp3","hi":"audio/viral-hepatitis-hi.mp3"},"duration":{"en":48.8,"hi":30.6},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"croup","topic":"croup","title":"Croup","en":"Croup. Assessment. A barking cough and hoarseness in a young child can indicate croup. Assess stridor at rest, work of breathing, colour, alertness and ability to drink; consider alternative airway emergencies. Treatment principles. Keep the child calm while arranging the appropriate level of care. Corticosteroid treatment and, for more severe illness, nebulized epinephrine are clinician-directed treatments; observation is important after temporary improvement. Safety and follow-up. Stridor at rest with distress, cyanosis, exhaustion, drooling or reduced responsiveness requires urgent emergency assessment. Steam exposure is not a substitute for treatment and hot water can burn. Avoid upsetting the child with unnecessary throat inspection.","hi":"क्रूप में बच्चे को भौंकने जैसी खांसी और आवाज बैठना हो सकता है। आराम में सांस की आवाज, छाती का खिंचाव, रंग और जागरूकता देखें। बच्चे को शांत रखें। गंभीर स्थिति में डॉक्टर स्टेरॉयड और नेब्युलाइज्ड एपिनेफ्रिन देते हैं और निगरानी रखते हैं। नीला पड़ना, अत्यधिक थकना या लार टपकना गंभीर संकेत हैं। गर्म भाप को इलाज का विकल्प न बनाएं; जलने का खतरा है।","files":{"en":"audio/croup-en.mp3","hi":"audio/croup-hi.mp3"},"duration":{"en":49.2,"hi":34.6},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"infective-endocarditis","topic":"infective-endocarditis","title":"Infective Endocarditis","en":"Infective Endocarditis. Assessment. Persistent fever with risk factors such as a prosthetic valve, previous endocarditis or bloodstream infection warrants assessment. Embolic signs or new heart-failure symptoms increase concern. Treatment principles. Diagnosis uses clinical findings, blood cultures and cardiac imaging. Treatment is prolonged, organism-directed and sometimes surgical. Pharmacy review includes antimicrobial exposure, renal function, drug levels when indicated and line-related issues. Safety and follow-up. Do not assume every person with a murmur needs dental antibiotic prophylaxis; eligibility and procedures are specific. New neurological symptoms or haemodynamic deterioration need urgent care. Support adherence and monitoring during outpatient intravenous treatment.","hi":"लगातार बुखार के साथ कृत्रिम वाल्व या पुराने एंडोकार्डाइटिस का इतिहास महत्वपूर्ण है। निदान में ब्लड कल्चर और हृदय की जांच होती है। इलाज लंबे समय का, जीवाणु के अनुसार और कभी ऑपरेशन सहित होता है। हर हार्ट मर्मर वाले व्यक्ति को दांत के इलाज से पहले एंटीबायोटिक जरूरी नहीं है। गुर्दे की स्थिति, दवा स्तर और नस की लाइन की निगरानी करें। नई न्यूरोलॉजिकल समस्या में तत्काल मदद लें।","files":{"hi":"audio/infective-endocarditis-hi.mp3","en":"audio/infective-endocarditis-en.mp3"},"duration":{"hi":36.1,"en":53.4},"subject":"Infectious Disease","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pruritus-itch","topic":"pruritus-itch","title":"Pruritus (Itch)","en":"Pruritus (Itch). Assessment. Assess distribution, rash, duration, new medicines, contacts and systemic symptoms. Generalized itch without a primary rash can reflect more than a skin problem, including liver, kidney or haematological disease. Treatment principles. Gentle skin care and regular moisturization help dry-skin itch. Treatment should address the cause; an antihistamine is more useful for histamine-mediated symptoms than for every form of itch. Safety and follow-up. Jaundice, systemic illness, blistering, mucosal involvement or severe widespread symptoms need medical assessment. Sedating antihistamines can worsen falls, confusion and anticholinergic burden, especially in older adults.","hi":"खुजली में जगह, चकत्ता, समय, नई दवा और घर के अन्य लोगों के लक्षण पूछें। बिना चकत्ते पूरे शरीर की खुजली में लिवर या गुर्दे जैसे कारण भी हो सकते हैं। सूखी त्वचा में मॉइस्चराइज़र मदद करता है। हर खुजली में एंटीहिस्टामिन समान रूप से काम नहीं करती। नींद लाने वाली दवाएं बुजुर्गों में गिरने और भ्रम का जोखिम बढ़ा सकती हैं। पीलिया, फफोले या गंभीर लक्षण में जांच करवाएं।","files":{"hi":"audio/pruritus-itch-hi.mp3","en":"audio/pruritus-itch-en.mp3"},"duration":{"hi":34.3,"en":47.9},"subject":"Dermatology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"acne","topic":"acne","title":"Acne","en":"Acne. Assessment. Assess comedones versus inflammatory or nodular disease, scarring, psychosocial impact, pregnancy possibility and previous treatment. Steroid use and other medicines can contribute to acne-like eruptions. Treatment principles. Topical retinoids and benzoyl peroxide are common components of care. Start tolerably and explain that improvement takes weeks. Avoid antibiotic monotherapy; systemic treatment requires assessment of severity, contraindications and duration. Safety and follow-up. Isotretinoin is highly teratogenic and requires a structured prescribing and pregnancy-prevention process. Do not combine acne products indiscriminately when irritation develops. Painful nodules, scarring or substantial distress support earlier referral.","hi":"मुंहासों में ब्लैकहेड, सूजन, गांठ, निशान और मानसिक असर देखें। बेंज़ोइल पेरॉक्साइड और रेटिनॉइड आम विकल्प हैं, लेकिन असर में कई सप्ताह लगते हैं। जलन होने पर सभी उत्पाद ज्यादा मात्रा में न लगाएं। एंटीबायोटिक अकेली और अनिश्चित समय तक न चलाएं। आइसोट्रेटिनॉइन गर्भावस्था में गंभीर नुकसान कर सकती है और विशेष निगरानी चाहिए। गांठ, निशान या बहुत परेशानी हो तो रेफर करें।","files":{"en":"audio/acne-en.mp3","hi":"audio/acne-hi.mp3"},"duration":{"en":52.2,"hi":34.7},"subject":"Dermatology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"psoriasis","topic":"psoriasis","title":"Psoriasis","en":"Psoriasis. Assessment. Assess affected sites, extent, symptoms, nail changes, joint symptoms and quality of life. A small area on a sensitive or functional site can still cause major impairment. Treatment principles. Topical corticosteroids and vitamin-D analogues are options for selected disease; potency and duration depend on the site. More extensive or difficult disease may need phototherapy or systemic treatment with specialist monitoring. Safety and follow-up. New swollen painful joints warrant assessment for psoriatic arthritis. Widespread redness, pustules or systemic illness can be urgent. Avoid applying a potent steroid to the face or folds without a specific plan.","hi":"सोरायसिस में केवल त्वचा का प्रतिशत नहीं, जगह और जीवन पर असर भी देखें। नाखून और जोड़ों के लक्षण पूछें। बाहरी स्टेरॉयड की ताकत और अवधि शरीर की जगह के अनुसार होती है। गंभीर बीमारी में विशेषज्ञ की दवा या प्रकाश उपचार लग सकता है। दर्द वाले सूजे जोड़ सोरायटिक आर्थराइटिस का संकेत हैं। चेहरे पर शक्तिशाली स्टेरॉयड अपनी तरफ से न लगाएं।","files":{"hi":"audio/psoriasis-hi.mp3","en":"audio/psoriasis-en.mp3"},"duration":{"hi":32.9,"en":46.8},"subject":"Dermatology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"burns-and-sunburns","topic":"burns-and-sunburns","title":"Burns and Sunburns","en":"Burns and Sunburns. Assessment. Establish the cause, time, depth, size and site of injury. Electrical, chemical or inhalation injury, extensive burns and burns involving critical areas need professional assessment. Treatment principles. For a recent thermal burn, use appropriate cool running water and remove constricting items if safe; avoid ice and unproven household remedies. Protect the area with a suitable clean dressing and assess analgesia and tetanus needs. Safety and follow-up. Airway symptoms, facial burns with smoke exposure, deep burns or signs of infection require urgent care. Young children and frail people need a lower referral threshold. Sunburn prevention includes shade, clothing and appropriate sunscreen use.","hi":"जलने में कारण, समय, गहराई, क्षेत्र और शरीर की जगह देखें। सामान्य ताप से जलने पर सुरक्षित ठंडे बहते पानी से ठंडा करें; बर्फ या घरेलू पेस्ट न लगाएं। साफ उपयुक्त ड्रेसिंग और दर्द की देखभाल करें। रसायन, बिजली, धुएं से सांस की समस्या या गहरा घाव तुरंत जांच मांगता है। बच्चों और कमजोर बुजुर्गों में जल्दी रेफर करें। धूप से बचाव में कपड़े और छाया भी जरूरी हैं।","files":{"en":"audio/burns-and-sunburns-en.mp3","hi":"audio/burns-and-sunburns-hi.mp3"},"duration":{"en":50.6,"hi":34.8},"subject":"Dermatology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"rosacea","topic":"rosacea","title":"Rosacea","en":"Rosacea. Assessment. Look for persistent facial redness, flushing, inflammatory lesions and ocular symptoms. Rosacea is different from acne; comedones are not a defining feature. Ask about triggers and previous topical steroid use. Treatment principles. Gentle skin care, sun protection and avoidance of individual triggers support treatment. Prescription topical or oral therapy depends on the dominant features and severity, with realistic expectations about control rather than a permanent cure. Safety and follow-up. Eye pain, light sensitivity or visual change needs prompt assessment. Facial corticosteroids can aggravate rosacea. Review irritation from cosmetics and avoid assuming every red facial rash has the same diagnosis.","hi":"रोसैशिया में चेहरे की लाली, फ्लशिंग और सूजन वाले दाने होते हैं; यह सामान्य मुंहासों से अलग है। व्यक्तिगत ट्रिगर, धूप और स्टेरॉयड क्रीम का इतिहास पूछें। कोमल त्वचा देखभाल और धूप से बचाव मदद करते हैं। दवा प्रमुख लक्षण के अनुसार चुनी जाती है। आंख में दर्द, रोशनी से परेशानी या नजर बदलना जल्दी जांच का कारण है। चेहरे की स्टेरॉयड क्रीम बीमारी बढ़ा सकती है।","files":{"en":"audio/rosacea-en.mp3","hi":"audio/rosacea-hi.mp3"},"duration":{"en":50.3,"hi":35.2},"subject":"Dermatology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"lice-scabies","topic":"lice-scabies","title":"Lice & Scabies","en":"Lice & Scabies. Assessment. Confirm an active infestation where possible. Head lice and scabies differ in organism, spread, treatment application and contact management. Scabies often causes marked night-time itch and affects close contacts. Treatment principles. Follow the chosen product's exact application and repeat-treatment directions. Scabies usually requires coordinated treatment of relevant close contacts. For lice, assess live lice and correct combing/product use before declaring resistance. Safety and follow-up. Itch can persist after successful scabies treatment; assess new lesions and exposure rather than repeatedly applying insecticide without review. Crusted scabies, secondary infection, pregnancy and young infants need tailored advice.","hi":"जूं और स्केबीज़ अलग समस्याएं हैं। सक्रिय संक्रमण की पुष्टि करें और उत्पाद लगाने तथा दोहराने के सही निर्देश दें। स्केबीज़ में संबंधित करीबी संपर्कों का साथ इलाज जरूरी हो सकता है। इलाज के बाद कुछ समय खुजली रहने का मतलब हमेशा असफलता नहीं है। नई सुरंग, नए दाने और दोबारा संपर्क देखें। छोटे बच्चे, गर्भावस्था या पपड़ी वाली गंभीर स्केबीज़ में विशेष सलाह लें।","files":{"hi":"audio/lice-scabies-hi.mp3","en":"audio/lice-scabies-en.mp3"},"duration":{"hi":35.2,"en":51.7},"subject":"Dermatology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"atopic-dermatitis","topic":"atopic-dermatitis","title":"Atopic Dermatitis","en":"Atopic Dermatitis. Assessment. Assess itch, dryness, flare sites, infection, sleep and trigger exposure. Treatment failure may reflect insufficient quantity, unsuitable potency, difficult application or an incorrect diagnosis. Treatment principles. Regular emollients support the skin barrier; anti-inflammatory treatment controls flares. Explain site-appropriate topical steroid use and the planned duration rather than advising either indefinite use or avoidance of all steroids. Safety and follow-up. Painful rapidly spreading lesions, punched-out erosions, eye involvement or systemic illness needs urgent assessment. Do not routinely use antibiotics for every eczema flare. Demonstration and a written plan can reduce fear and improve correct use.","hi":"एटॉपिक डर्मेटाइटिस में सूखापन, खुजली, नींद और संक्रमण देखें। मॉइस्चराइज़र त्वचा की सुरक्षा मजबूत करता है, जबकि सूजन की दवा फ्लेयर नियंत्रित करती है। स्टेरॉयड की सही ताकत, मात्रा और अवधि समझाएं। हर फ्लेयर में एंटीबायोटिक जरूरी नहीं है। दर्द वाले तेजी से फैलते छोटे घाव, आंख की समस्या या बुखार हो तो तुरंत जांच करवाएं। लगाने की विधि दिखाना उपयोगी है।","files":{"en":"audio/atopic-dermatitis-en.mp3","hi":"audio/atopic-dermatitis-hi.mp3"},"duration":{"en":50.1,"hi":34.5},"subject":"Dermatology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"attention-deficit-hyperactivity-disorder-adhd","topic":"attention-deficit-hyperactivity-disorder-adhd","title":"Attention Deficit Hyperactivity Disorder (ADHD)","en":"Attention Deficit Hyperactivity Disorder (ADHD). Assessment. ADHD assessment considers persistent impairment across settings, developmental history and alternative explanations. Review sleep, anxiety, substance use, cardiovascular history and actual functional goals. Treatment principles. Medication and behavioural or educational supports can complement each other. Stimulant and nonstimulant products differ in onset, duration and titration. Monitor appetite, sleep, blood pressure, pulse and growth in children where relevant. Safety and follow-up. Do not interchange modified-release products solely by matching milligrams. Discuss secure storage and diversion prevention without stigma. New severe psychiatric symptoms, concerning cardiovascular symptoms or major weight loss needs reassessment.","hi":"ए डी एच डी में कई जगहों पर लगातार कामकाज की परेशानी और विकास का इतिहास देखें। नींद, चिंता और दूसरी वजहों की समीक्षा करें। दवा के साथ व्यवहार और पढ़ाई की सहायता महत्वपूर्ण है। भूख, नींद, रक्तचाप, नाड़ी और बच्चों की बढ़त देखें। अलग लंबे असर वाले उत्पाद केवल मिलीग्राम बराबर होने पर बदल न दें। सुरक्षित भंडारण और दवा साझा न करने की सलाह दें।","files":{"en":"audio/attention-deficit-hyperactivity-disorder-adhd-en.mp3","hi":"audio/attention-deficit-hyperactivity-disorder-adhd-hi.mp3"},"duration":{"en":55.1,"hi":33.8},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"dementia","topic":"dementia","title":"Dementia","en":"Dementia. Assessment. Establish the pattern and pace of cognitive change, daily function, medicines, sensory needs and caregiver concerns. Acute fluctuating confusion suggests delirium and needs assessment for reversible causes. Treatment principles. Support routines, communication and safety while reviewing anticholinergic and sedating medicines. Cognitive-symptom medicines have limited goals and require assessment of benefit, tolerability and the specific dementia diagnosis. Safety and follow-up. Behavioural symptoms first require assessment of pain, infection, environment and unmet needs. Antipsychotics carry important risks and are not a routine response to every behaviour. Respect capacity, consent and caregiver roles individually.","hi":"डिमेंशिया में याददाश्त के साथ रोजमर्रा की क्षमता और बदलाव की गति देखें। अचानक उतार-चढ़ाव वाला भ्रम डिलीरियम हो सकता है और कारण खोजने की जरूरत है। नींद लाने वाली और एंटीकोलिनर्जिक दवाओं की समीक्षा करें। व्यवहार बदलने पर दर्द, संक्रमण और वातावरण देखें। हर व्यवहार पर एंटीसाइकोटिक देना सही नहीं। मरीज की क्षमता, सहमति और देखभाल करने वाले की भूमिका अलग समझें।","files":{"en":"audio/dementia-en.mp3","hi":"audio/dementia-hi.mp3"},"duration":{"en":50.3,"hi":35.2},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"insomnia","topic":"insomnia","title":"Insomnia","en":"Insomnia. Assessment. Clarify difficulty falling asleep, staying asleep or waking early, duration and daytime impairment. Review shift work, sleep apnoea symptoms, pain, mood, caffeine, alcohol and medicines. Treatment principles. Cognitive behavioural therapy for insomnia is a central long-term approach. Sleep timing and behavioural strategies are more than a simple instruction to relax. If a medicine is used, define the goal, duration and reassessment plan. Safety and follow-up. Sedatives can impair driving and increase falls; combining them with alcohol or opioids adds risk. Do not abruptly stop a long-used benzodiazepine. Persistent snoring with witnessed apnoeas or marked daytime sleepiness warrants evaluation.","hi":"अनिद्रा में सोने में देर, बीच में जागना और दिन के काम पर असर पूछें। कैफीन, शराब, शिफ्ट काम, दर्द और स्लीप एप्निया की संभावना देखें। अनिद्रा की व्यवहार आधारित चिकित्सा लंबे समय में महत्वपूर्ण है। नींद की दवा के लिए अवधि और समीक्षा तय करें। शराब या ओपिओइड के साथ जोखिम बढ़ता है। लंबे समय की बेंज़ोडायज़ेपीन अचानक बंद न करें।","files":{"hi":"audio/insomnia-hi.mp3","en":"audio/insomnia-en.mp3"},"duration":{"hi":31.9,"en":51.6},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"eating-disorders","topic":"eating-disorders","title":"Eating Disorders","en":"Eating Disorders. Assessment. Assess restrictive eating, bingeing, compensatory behaviours, rapid weight change, medical symptoms and psychological distress without focusing only on body size. Serious instability can occur at different weights. Treatment principles. Care requires coordinated medical, nutritional and psychological assessment. Review medicines that affect appetite, electrolytes or QT interval and explore laxative or diuretic misuse respectfully. Safety and follow-up. Syncope, severe weakness, dehydration, bradycardia or electrolyte abnormalities may require urgent care. Refeeding after prolonged undernutrition can cause dangerous metabolic shifts; nutritional restoration needs an appropriate monitored plan.","hi":"खाने के विकार में केवल वजन नहीं, प्रतिबंध, बिंज ईटिंग, उल्टी, जुलाब और तेजी से वजन बदलना पूछें। अलग-अलग वजन पर गंभीर अस्थिरता हो सकती है। चिकित्सा, पोषण और मानसिक स्वास्थ्य टीम की संयुक्त देखभाल जरूरी है। बेहोशी, बहुत कमजोरी या इलेक्ट्रोलाइट बिगड़ना गंभीर संकेत हैं। लंबे कुपोषण के बाद भोजन तेजी से बढ़ाने में रीफीडिंग का जोखिम होता है और निगरानी चाहिए।","files":{"en":"audio/eating-disorders-en.mp3","hi":"audio/eating-disorders-hi.mp3"},"duration":{"en":49.5,"hi":33.9},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"schizophrenia","topic":"schizophrenia","title":"Schizophrenia","en":"Schizophrenia. Assessment. Review psychotic symptoms, functioning, physical health, substance use, medication response and adverse effects. Distinguish relapse from delirium, intoxication and other causes. Treatment principles. Antipsychotic selection considers previous benefit, metabolic effects, movement disorders, prolactin, QT effects and patient preferences. Long-acting injections can help selected patients but require the exact product initiation and missed-dose protocol. Safety and follow-up. Clozapine requires specific blood monitoring and assessment for serious adverse effects, including severe constipation and myocarditis symptoms. Fever, rigidity and altered consciousness during antipsychotic therapy can be an emergency. Plan ongoing metabolic monitoring and supportive care.","hi":"स्किज़ोफ्रेनिया में लक्षण, रोजमर्रा का काम, नशे का उपयोग और दवा के दुष्प्रभाव देखें। एंटीसाइकोटिक चुनते समय वजन, शुगर, गति संबंधी दुष्प्रभाव और हृदय की लय पर असर देखें। लंबे असर वाले इंजेक्शन की शुरुआत और छूटी खुराक के नियम उत्पाद अनुसार हैं। क्लोज़ापिन में रक्त जांच और गंभीर कब्ज की निगरानी जरूरी है। बुखार, अकड़न और भ्रम तुरंत जांच मांगते हैं।","files":{"hi":"audio/schizophrenia-hi.mp3","en":"audio/schizophrenia-en.mp3"},"duration":{"hi":33.6,"en":53.3},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"acute-agitation","topic":"acute-agitation","title":"Acute Agitation","en":"Acute Agitation. Assessment. Prioritize immediate safety and assess possible delirium, pain, hypoglycaemia, intoxication, withdrawal or psychiatric illness. Agitation is a presentation, not a diagnosis. Treatment principles. Use a calm voice, space, respectful choices and reduced stimulation when safe. Medication, restraint and emergency interventions require the appropriate clinical setting, consent framework and monitoring; avoid escalating a confrontation. Safety and follow-up. Altered consciousness, unstable vital signs, head injury or severe intoxication needs urgent medical care. Sedating medicines can suppress breathing, especially in combination. Document the cause assessment, response and ongoing monitoring.","hi":"तीव्र उत्तेजना में पहले मरीज और आसपास के लोगों की सुरक्षा देखें। कारण दर्द, कम शुगर, नशा, विड्रॉल या डिलीरियम भी हो सकता है। शांत आवाज, जगह और सरल विकल्प दें। बहस या टकराव न बढ़ाएं। बेहोशी, अस्थिर रक्तचाप या सिर की चोट में आपातकालीन जांच जरूरी है। शांत करने वाली दवाओं से सांस दब सकती है, इसलिए उचित निगरानी आवश्यक है।","files":{"en":"audio/acute-agitation-en.mp3","hi":"audio/acute-agitation-hi.mp3"},"duration":{"en":51.3,"hi":33.5},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"anxiety-and-related-disorders","topic":"anxiety-and-related-disorders","title":"Anxiety and Related Disorders","en":"Anxiety and Related Disorders. Assessment. Assess pattern, triggers, avoidance, functional impairment, sleep and medical or substance-related causes. Panic-like symptoms can overlap with acute cardiac or respiratory illness. Treatment principles. Psychological therapy and selected medicines are options according to the disorder and preferences. Antidepressants can take time to help and may initially cause adverse effects; explain titration, adherence and follow-up. Safety and follow-up. Benzodiazepines have dependence, sedation and withdrawal risks. Do not dismiss new chest pain as anxiety without assessment. Review worsening mood, major functional decline and safety concerns promptly.","hi":"चिंता में पैटर्न, ट्रिगर, बचने का व्यवहार और रोज के काम पर असर देखें। छाती का नया दर्द केवल पैनिक मानकर न छोड़ें। मनोचिकित्सा और चुनी हुई दवाएं मदद कर सकती हैं। कुछ दवाओं का असर धीरे आता है और शुरुआत में दुष्प्रभाव हो सकते हैं। बेंज़ोडायज़ेपीन में निर्भरता और विड्रॉल का जोखिम समझाएं। सुधार और नुकसान दोनों की समीक्षा की तारीख तय करें।","files":{"en":"audio/anxiety-and-related-disorders-en.mp3","hi":"audio/anxiety-and-related-disorders-hi.mp3"},"duration":{"en":46.8,"hi":32.6},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"bipolar-disorder","topic":"bipolar-disorder","title":"Bipolar Disorder","en":"Bipolar Disorder. Assessment. A history of mania or hypomania changes the interpretation of depressive symptoms. Ask about reduced need for sleep, increased activity, impulsivity, psychosis and previous episodes. Treatment principles. Treatment depends on whether the person has mania, bipolar depression or maintenance needs. Mood stabilizers and selected antipsychotics have different roles. Antidepressant monotherapy is generally unsuitable for bipolar I depression. Safety and follow-up. Lithium requires correctly timed levels, renal and thyroid monitoring, and attention to dehydration and interactions. Pregnancy planning is essential for potentially teratogenic therapies. Severe mania, psychosis or inability to maintain safety requires urgent care.","hi":"बाइपोलर में अवसाद के साथ पुराने उन्माद या हाइपोमेनिया का इतिहास पूछें। कम नींद में भी बहुत ऊर्जा, आवेग और बढ़ी गतिविधि महत्वपूर्ण हैं। उन्माद, अवसाद और रखरखाव के इलाज अलग हो सकते हैं। बाइपोलर वन में केवल एंटीडिप्रेसेंट सामान्यतः उचित नहीं। लिथियम में सही समय का स्तर, गुर्दे, थायरॉइड, पानी की कमी और अंतःक्रियाएं देखें। गर्भावस्था की योजना पहले चर्चा करें।","files":{"hi":"audio/bipolar-disorder-hi.mp3","en":"audio/bipolar-disorder-en.mp3"},"duration":{"hi":34.8,"en":52.5},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"depression","topic":"depression","title":"Depression","en":"Depression. Assessment. Assess duration, functional impact, sleep, appetite, medical causes and previous treatment. Ask about bipolar symptoms and immediate safety concerns before assuming unipolar depression. Treatment principles. Treatment may include psychological therapy, social supports and an antidepressant selected for benefit, adverse effects, interactions and preference. Explain that response takes time and use planned follow-up rather than automatic early switching. Safety and follow-up. Assess worsening agitation, emerging mania, serotonin toxicity and discontinuation symptoms. Do not abruptly stop long-term therapy without a taper plan when appropriate. Immediate safety concerns or severe deterioration require urgent professional assessment.","hi":"अवसाद में अवधि, कामकाज, नींद, भूख और पुराने इलाज की समीक्षा करें। बाइपोलर के लक्षण और तत्काल सुरक्षा की चिंता भी पूछें। बातचीत की चिकित्सा, सामाजिक सहायता और दवा का चुनाव मरीज के अनुसार करें। असर में समय लग सकता है, इसलिए फॉलो अप तय करें। नई अत्यधिक उत्तेजना, उन्माद या गंभीर बिगड़ाव पर जल्दी मदद लें। लंबे इलाज की दवा अचानक बंद न करें।","files":{"en":"audio/depression-en.mp3","hi":"audio/depression-hi.mp3"},"duration":{"en":50.8,"hi":34.1},"subject":"Psychiatry","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"nausea-vomiting","topic":"nausea-vomiting","title":"Nausea & Vomiting","en":"Nausea & Vomiting. Assessment. Assess duration, fluid intake, urine output, abdominal pain, headache, pregnancy possibility and medicine changes. Identify the likely cause before choosing an antiemetic. Treatment principles. Oral rehydration and treatment of the cause are often central. Antiemetics differ in indication, sedation, anticholinergic effects, movement effects and QT risk; check other medicines and patient factors. Safety and follow-up. Blood or coffee-ground vomit, severe abdominal pain, neurological symptoms, marked dehydration or persistent vomiting requires prompt assessment. Children and frail adults can deteriorate quickly. A medicine that suppresses vomiting should not mask an unresolved serious cause.","hi":"मतली और उल्टी में समय, पानी पीने की क्षमता, पेशाब, पेट दर्द, गर्भावस्था और नई दवा पूछें। पहले कारण पहचानें। पानी और नमक की कमी पूरी करना महत्वपूर्ण है। उल्टी रोकने वाली दवाओं में नींद, हृदय की लय और दूसरे दुष्प्रभाव अलग हैं। खून वाली उल्टी, तेज पेट दर्द, भ्रम या गंभीर पानी की कमी में तुरंत जांच करवाएं। लक्षण दबने से गंभीर कारण खत्म नहीं होता।","files":{"hi":"audio/nausea-vomiting-hi.mp3","en":"audio/nausea-vomiting-en.mp3"},"duration":{"hi":34.4,"en":50.7},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"ulcerative-colitis-crohn-s-disease","topic":"ulcerative-colitis-crohn-s-disease","title":"Ulcerative Colitis & Crohn's Disease","en":"Ulcerative Colitis & Crohn's Disease. Assessment. Assess bowel frequency, bleeding, pain, weight loss, extraintestinal symptoms and infection risk. Ulcerative colitis and Crohn's disease differ in location and complications; confirm the diagnosis and disease activity. Treatment principles. Induction and maintenance therapy serve different purposes. Corticosteroids can control selected flares but are not a routine maintenance solution. Immunomodulators and advanced therapies require screening, vaccination planning and monitoring. Safety and follow-up. Severe pain, distension, fever, significant bleeding or dehydration requires urgent assessment. Review infection before assuming every deterioration is a flare. Discuss adherence, nutrition, smoking and avoidance of unreviewed NSAID use.","hi":"अल्सरेटिव कोलाइटिस और क्रोन्स में दस्त, खून, दर्द और वजन देखें। सक्रिय फ्लेयर का इलाज और लंबे समय की रोकथाम अलग हैं। स्टेरॉयड कुछ फ्लेयर में उपयोगी हैं, लेकिन नियमित रखरखाव का विकल्प नहीं। प्रतिरक्षा प्रभावित करने वाली दवाओं से पहले संक्रमण की जांच और टीकों की योजना चाहिए। तेज दर्द, पेट फूलना, बुखार या अधिक रक्तस्राव पर तुरंत जांच करवाएं।","files":{"en":"audio/ulcerative-colitis-crohn-s-disease-en.mp3","hi":"audio/ulcerative-colitis-crohn-s-disease-hi.mp3"},"duration":{"en":54.5,"hi":31.1},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"women-s-health","topic":"women-s-health","title":"Women's Health","en":"Women's Health. Assessment. Start with the person's symptoms and goals rather than assumptions about age, anatomy, gender or pregnancy intentions. Menstrual history, bleeding pattern, pain, medicines and relevant screening help focus the assessment. Treatment principles. Common pharmacy discussions include menstrual symptoms, contraception, iron deficiency, pregnancy planning and menopause. Match recommendations to the identified problem, contraindications and the patient's preferences. Safety and follow-up. Heavy bleeding with faintness, severe pelvic pain, possible ectopic pregnancy or new postmenopausal bleeding requires assessment. Use a private setting, consent and inclusive language. Do not attribute every symptom to hormones without considering alternatives.","hi":"महिला स्वास्थ्य में उम्र या पहचान के आधार पर अनुमान न लगाएं। मरीज की समस्या, लक्ष्य, मासिक धर्म, खून की मात्रा, दर्द और गर्भावस्था की संभावना पूछें। गर्भनिरोध, आयरन की कमी, गर्भ की योजना और मेनोपॉज अलग जरूरतें हैं। बहुत खून के साथ चक्कर, तेज पेल्विक दर्द या मेनोपॉज के बाद नया रक्तस्राव जांच मांगता है। गोपनीयता और सम्मानजनक भाषा रखें।","files":{"hi":"audio/women-s-health-hi.mp3","en":"audio/women-s-health-en.mp3"},"duration":{"hi":33.1,"en":51.3},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"dyspepsia-gerd-peptic-ulcer-disease","topic":"dyspepsia-gerd-peptic-ulcer-disease","title":"Dyspepsia, GERD & Peptic Ulcer Disease","en":"Dyspepsia, GERD & Peptic Ulcer Disease. Assessment. Distinguish reflux symptoms from dyspepsia and possible ulcer disease. Ask about alarm symptoms, NSAIDs, aspirin, prior Helicobacter pylori treatment and medicines that aggravate symptoms. Treatment principles. Lifestyle measures and acid suppression are selected according to the diagnosis. H. pylori treatment uses a current locally appropriate combination regimen and confirmation-of-eradication plan. Test timing and acid-suppressing medicines can affect results. Safety and follow-up. Dysphagia, GI bleeding, unintentional weight loss or persistent vomiting requires evaluation. New chest pain should not simply be labelled reflux. Reassess the indication and lowest appropriate duration of long-term acid suppression.","hi":"एसिड रिफ्लक्स, अपच और अल्सर को अलग समझें। एन एस ए आई डी, एस्प्रिन और एच पाइलोरी का इतिहास पूछें। एच पाइलोरी में वर्तमान उपयुक्त कई दवाओं की योजना और इलाज के बाद पुष्टि जरूरी है। जांच का समय और एसिड की दवा परिणाम बदल सकती है। निगलने में परेशानी, वजन घटना या रक्तस्राव में जांच करवाएं। नए छाती दर्द को केवल एसिड न मानें।","files":{"hi":"audio/dyspepsia-gerd-peptic-ulcer-disease-hi.mp3","en":"audio/dyspepsia-gerd-peptic-ulcer-disease-en.mp3"},"duration":{"hi":32.8,"en":53.0},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"medical-abortion","topic":"medical-abortion","title":"Medical Abortion","en":"Medical Abortion. Assessment. Provide confidential, nonjudgmental care. Confirm the prescribed regimen, gestational assessment, access to follow-up and warning signs that could suggest ectopic pregnancy or another urgent problem. Treatment principles. Mifepristone and misoprostol have distinct roles in common medication-abortion regimens. Dispense against the current Canadian monograph and care protocol, explaining the sequence, expected bleeding and pain-management plan. Safety and follow-up. Give clear instructions for excessive bleeding, fainting, severe persistent pain, fever or feeling very unwell. Confirm how completion will be assessed. Medication abortion does not treat ectopic pregnancy; do not improvise a regimen or omit the follow-up plan.","hi":"दवा से गर्भसमापन में गोपनीय और बिना निर्णय वाली देखभाल दें। निर्धारित योजना, गर्भ की अवधि और फॉलो अप स्पष्ट करें। मिफेप्रिस्टोन और मिसोप्रोस्टोल का क्रम अलग भूमिका निभाता है; वर्तमान कनाडाई निर्देश के अनुसार समझाएं। बहुत अधिक रक्तस्राव, बेहोशी, लगातार तेज दर्द या बुखार में तुरंत मदद लें। एक्टोपिक गर्भ का इलाज इन दवाओं से नहीं होता। समापन की पुष्टि कैसे होगी, यह जरूर बताएं।","files":{"en":"audio/medical-abortion-en.mp3","hi":"audio/medical-abortion-hi.mp3"},"duration":{"en":50.0,"hi":35.6},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pancreatitis","topic":"pancreatitis","title":"Pancreatitis","en":"Pancreatitis. Assessment. Severe upper-abdominal pain, often with vomiting and possible radiation to the back, needs medical assessment. Gallstones, alcohol, high triglycerides and medicines are among possible contributors. Treatment principles. Acute pancreatitis is managed with assessment of severity, supportive care and treatment of the cause. Antibiotics are not routinely used for uncomplicated sterile inflammation. Chronic pancreatitis can cause pain, malabsorption and diabetes. Safety and follow-up. Persistent severe pain, dehydration, jaundice or instability warrants urgent care. If pancreatic enzymes are prescribed, teach their relationship to meals and snacks and the exact product directions. Avoid crushing delayed-release enzyme products without specialist product-specific advice.","hi":"अग्न्याशय की सूजन में ऊपर पेट का तेज दर्द और उल्टी हो सकती है। पथरी, शराब, बहुत अधिक ट्राइग्लिसराइड और दवाएं कारण हो सकते हैं। तीव्र बीमारी में गंभीरता और कारण का अस्पताल में मूल्यांकन जरूरी है। बिना संक्रमण हर मरीज को एंटीबायोटिक नहीं चाहिए। पैंक्रियाटिक एंजाइम भोजन के साथ सही तरीके से लें और विशेष कैप्सूल अपनी तरफ से न कुचलें।","files":{"en":"audio/pancreatitis-en.mp3","hi":"audio/pancreatitis-hi.mp3"},"duration":{"en":54.6,"hi":31.9},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"ibs","topic":"ibs","title":"IBS","en":"IBS. Assessment. IBS involves recurrent abdominal pain associated with bowel changes after appropriate assessment. Determine constipation-, diarrhoea- or mixed-predominant symptoms and the effect on daily life. Treatment principles. Management combines explanation, individual dietary and lifestyle measures, and symptom-targeted treatment. A restrictive diet should have a structured review and reintroduction plan, ideally with dietetic support. Safety and follow-up. Blood in stool, unexplained weight loss, anaemia, nocturnal symptoms or a concerning new pattern requires reassessment. Do not assume an existing IBS diagnosis explains every future abdominal symptom. Match treatment to the predominant bowel pattern.","hi":"आई बी एस में बार-बार पेट दर्द और मल की आदत बदलती है। कब्ज, दस्त या दोनों का पैटर्न पहचानें। भोजन और जीवनशैली का व्यक्तिगत बदलाव और लक्षण अनुसार दवा मदद कर सकते हैं। बहुत प्रतिबंध वाला आहार बिना समीक्षा हमेशा न चलाएं। मल में खून, वजन घटना, एनीमिया या नया रात का लक्षण हो तो दोबारा जांच करें। पुराना आई बी एस हर नए दर्द का कारण नहीं है।","files":{"en":"audio/ibs-en.mp3","hi":"audio/ibs-hi.mp3"},"duration":{"en":49.1,"hi":34.3},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"constipation","topic":"constipation","title":"Constipation","en":"Constipation. Assessment. Assess stool pattern, straining, duration, diet, mobility and constipating medicines. Ask about severe pain, vomiting, bleeding, weight loss and possible obstruction before recommending a laxative. Treatment principles. Gradual fibre changes, suitable fluid intake and activity may help when appropriate. Osmotic or stimulant laxatives are selected according to the cause and response. Opioid-related constipation often needs a proactive medication plan. Safety and follow-up. Fibre is not a remedy for suspected obstruction or every case of faecal impaction. Avoid inappropriate magnesium- or phosphate-containing products in susceptible patients. Reassess new persistent constipation and document response to treatment.","hi":"कब्ज में मल का पैटर्न, जोर लगाना, भोजन, चलना और कब्ज करने वाली दवाएं देखें। तेज दर्द, उल्टी या खून हो तो पहले जांच जरूरी है। उपयुक्त मरीज में फाइबर धीरे बढ़ाएं और पानी तथा गतिविधि पर बात करें। ओपिओइड के साथ पहले से कब्ज की योजना चाहिए। आंत रुकने की संभावना में केवल फाइबर न दें। गुर्दे की बीमारी में कुछ मैग्नीशियम या फॉस्फेट उत्पाद अनुपयुक्त हो सकते हैं।","files":{"en":"audio/constipation-en.mp3","hi":"audio/constipation-hi.mp3"},"duration":{"en":50.6,"hi":34.1},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"contraception","topic":"contraception","title":"Contraception","en":"Contraception. Assessment. Explore pregnancy intentions, preferred method, adherence, menstrual concerns, smoking, migraine history, thrombotic risk and interacting medicines. Emergency contraception is a separate time-sensitive assessment. Treatment principles. Methods differ in effectiveness, user dependence, bleeding effects and contraindications. Estrogen-containing methods are unsuitable for some patients; long-acting reversible options and progestin-only choices may be appropriate alternatives. Safety and follow-up. Use the exact product's missed-dose and backup instructions. Enzyme-inducing medicines can reduce some methods' effectiveness. Contraception does not generally protect against STIs; discuss barrier protection and confidential shared decisions.","hi":"गर्भनिरोध में मरीज की पसंद, गर्भ की योजना, नियमित उपयोग, माइग्रेन, धूम्रपान और थक्के का जोखिम पूछें। सभी तरीकों में एस्ट्रोजन नहीं होता और प्रभावशीलता तथा ब्लीडिंग अलग हैं। छूटी खुराक और अतिरिक्त बचाव के निर्देश उत्पाद अनुसार दें। एंजाइम बढ़ाने वाली कुछ दवाएं असर कम कर सकती हैं। अधिकांश गर्भनिरोध तरीके यौन संक्रमण से नहीं बचाते। आपातकालीन गर्भनिरोध समय पर मूल्यांकन मांगता है।","files":{"hi":"audio/contraception-hi.mp3","en":"audio/contraception-en.mp3"},"duration":{"hi":37.2,"en":50.9},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"benign-prostatic-hyperplasia","topic":"benign-prostatic-hyperplasia","title":"Benign Prostatic Hyperplasia","en":"Benign Prostatic Hyperplasia. Assessment. Assess voiding and storage symptoms, severity, medicines and complications. Lower urinary tract symptoms are not automatically BPH; infection, cancer, neurological disease and medicine effects may need consideration. Treatment principles. Alpha blockers can improve symptoms, while 5-alpha-reductase inhibitors have a different role in selected patients with prostate enlargement. Explain expected onset and monitor dizziness, blood pressure and sexual adverse effects. Safety and follow-up. Acute inability to pass urine, fever with urinary symptoms, visible blood or renal concerns requires assessment. Inform the eye surgeon about current or previous alpha-blocker use before cataract surgery. Review decongestant and anticholinergic exposure.","hi":"प्रोस्टेट बढ़ने में पेशाब शुरू करने में देर, कमजोर धार और बार-बार पेशाब देखें। हर लक्षण को प्रोस्टेट न मानें। अल्फा ब्लॉकर और फाइव अल्फा रिडक्टेज अवरोधक का काम और असर का समय अलग है। चक्कर और रक्तचाप देखें। पेशाब बिल्कुल न होना आपातस्थिति है। मोतियाबिंद ऑपरेशन से पहले अल्फा ब्लॉकर के वर्तमान या पुराने उपयोग की जानकारी आंख के डॉक्टर को दें।","files":{"hi":"audio/benign-prostatic-hyperplasia-hi.mp3","en":"audio/benign-prostatic-hyperplasia-en.mp3"},"duration":{"hi":33.2,"en":53.5},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"urinary-incontinence","topic":"urinary-incontinence","title":"Urinary Incontinence","en":"Urinary Incontinence. Assessment. Distinguish stress, urge, overflow and functional incontinence. Review onset, urinary symptoms, mobility, cognition, constipation, fluids and medicines; treatment differs by mechanism. Treatment principles. Bladder training, pelvic-floor approaches and addressing contributing factors are often important. Antimuscarinic and beta-3 agonist therapies have different risks and require individual assessment rather than a generic 'bladder pill'. Safety and follow-up. Retention, haematuria, recurrent infection or new neurological findings needs evaluation. Anticholinergic burden can worsen cognition and constipation; some alternatives require blood-pressure monitoring. Reassess benefit and daily-life goals.","hi":"पेशाब छूटने में खांसने पर, तेज इच्छा के साथ, रुकावट के कारण और चलने की परेशानी वाले प्रकार अलग हैं। कब्ज, दवाएं और तरल सेवन देखें। ब्लैडर ट्रेनिंग और पेल्विक फ्लोर सहायता उपयोगी हो सकती है। हर व्यक्ति को एक जैसी दवा नहीं चाहिए। एंटीकोलिनर्जिक दवाएं भ्रम और कब्ज बढ़ा सकती हैं। पेशाब रुकना, खून या नई कमजोरी हो तो जांच करवाएं।","files":{"en":"audio/urinary-incontinence-en.mp3","hi":"audio/urinary-incontinence-hi.mp3"},"duration":{"en":50.6,"hi":33.0},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"menopause","topic":"menopause","title":"Menopause","en":"Menopause. Assessment. Assess vasomotor symptoms, sleep, genitourinary symptoms, bleeding and personal treatment goals. Review thrombotic, cardiovascular and cancer history and whether the uterus is present. Treatment principles. Hormonal and nonhormonal options are selected through individualized benefit–risk discussion. Systemic and local vaginal therapies have different purposes. People with a uterus generally need appropriate endometrial protection with systemic estrogen. Safety and follow-up. New postmenopausal bleeding needs assessment. Menopausal hormone therapy is not contraception and should not be presented as universal prevention of chronic disease. Review symptom response, adverse effects and ongoing need.","hi":"मेनोपॉज में गर्मी के दौरे, नींद, योनि के लक्षण और मरीज के लक्ष्य पूछें। थक्के, कैंसर और गर्भाशय की स्थिति उपचार बदलती है। पूरे शरीर की हार्मोन दवा और स्थानीय योनि दवा का काम अलग है। गर्भाशय होने पर सिस्टमिक एस्ट्रोजन के साथ उचित सुरक्षा जरूरी होती है। मेनोपॉज के बाद नया रक्तस्राव जांच मांगता है। हार्मोन थेरेपी गर्भनिरोध नहीं है।","files":{"hi":"audio/menopause-hi.mp3","en":"audio/menopause-en.mp3"},"duration":{"hi":34.2,"en":49.1},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"erectile-dysfunction","topic":"erectile-dysfunction","title":"Erectile Dysfunction","en":"Erectile Dysfunction. Assessment. Ask privately about onset, consistency, libido, psychological factors and medicines. Erectile dysfunction can accompany diabetes, vascular disease or hormonal problems and merits a broader risk assessment. Treatment principles. PDE5 inhibitors require counselling on timing, sexual stimulation, food effects where relevant and realistic expectations. Review cardiovascular suitability and interacting medicines before recommending treatment. Safety and follow-up. Nitrates and PDE5 inhibitors can produce dangerous hypotension; assess the exact product and timing. Persistent painful erection or sudden vision/hearing symptoms requires urgent care. Do not source unregulated enhancement products.","hi":"इरेक्टाइल डिसफंक्शन पर निजी और सम्मानजनक बातचीत करें। मधुमेह, रक्तवाहिका की बीमारी, दवाएं और मानसिक कारण देखें। पी डी ई फाइव दवा में समय, भोजन और यौन उत्तेजना के निर्देश अलग हो सकते हैं। नाइट्रेट के साथ खतरनाक रक्तचाप गिर सकता है। लंबे दर्द वाले इरेक्शन या अचानक नजर और सुनने में बदलाव पर तुरंत मदद लें। अनियमित ऑनलाइन उत्पाद से बचें।","files":{"hi":"audio/erectile-dysfunction-hi.mp3","en":"audio/erectile-dysfunction-en.mp3"},"duration":{"hi":33.4,"en":50.8},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"reproductive-health","topic":"reproductive-health","title":"Reproductive Health","en":"Reproductive Health. Assessment. Use an inclusive history focused on anatomy, fertility goals, sexual health, pregnancy potential and medicines. Do not infer reproductive needs from gender identity or relationship status. Treatment principles. Preconception care includes medication review, appropriate supplementation and vaccination review. Fertility or pregnancy-related therapies require product-specific counselling, storage and administration teaching. Safety and follow-up. Possible ectopic pregnancy, severe pelvic pain or heavy bleeding requires urgent assessment. Discuss consent, confidentiality and safeguarding where appropriate. Coordinate changes to essential medicines instead of abruptly stopping them because pregnancy is possible.","hi":"प्रजनन स्वास्थ्य में पहचान के आधार पर अनुमान न लगाएं। संबंधित अंग, गर्भ की संभावना, प्रजनन लक्ष्य और दवाएं पूछें। गर्भ से पहले दवा, उचित सप्लीमेंट और टीके की समीक्षा करें। कुछ इलाज में विशेष भंडारण और लगाने की विधि होती है। तेज पेल्विक दर्द, बहुत रक्तस्राव या एक्टोपिक गर्भ की संभावना में तुरंत जांच करें। जरूरी दवा अचानक बंद करवाने के बजाय समन्वित योजना बनाएं।","files":{"en":"audio/reproductive-health-en.mp3","hi":"audio/reproductive-health-hi.mp3"},"duration":{"en":49.9,"hi":34.5},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"upper-gi-bleeding","topic":"upper-gi-bleeding","title":"Upper GI Bleeding","en":"Upper GI Bleeding. Assessment. Vomiting blood or coffee-ground material and black tarry stool can indicate upper GI bleeding. Assess dizziness, collapse, anticoagulants, NSAIDs, liver disease and the amount and timing of bleeding. Treatment principles. Suspected significant bleeding needs urgent hospital assessment, stabilization and source evaluation. Acid suppression or a medicine review does not replace emergency care. Antithrombotic decisions require the responsible clinical team. Safety and follow-up. Do not independently advise a universal stop or restart date for anticoagulation. After treatment, reconcile the plan, address the cause and clarify follow-up. Iron or bismuth can darken stool, but do not use that fact to dismiss concerning symptoms.","hi":"खून या कॉफी जैसे रंग की उल्टी और काला चिपचिपा मल ऊपर पाचन तंत्र के रक्तस्राव का संकेत हो सकता है। चक्कर, बेहोशी, खून पतला करने वाली दवा और एन एस ए आई डी पूछें। गंभीर रक्तस्राव में तुरंत अस्पताल जाएं। एसिड की दवा आपातकालीन देखभाल का विकल्प नहीं। एंटीकोआगुलेंट कब रोकना या शुरू करना है, यह इलाज करने वाली टीम तय करे।","files":{"en":"audio/upper-gi-bleeding-en.mp3","hi":"audio/upper-gi-bleeding-hi.mp3"},"duration":{"en":51.9,"hi":31.1},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"drugs-in-pregnancy-lactation","topic":"drugs-in-pregnancy-lactation","title":"Drugs in Pregnancy & Lactation","en":"Drugs in Pregnancy & Lactation. Assessment. Assessment depends on gestational stage or infant age, indication, dose, route, duration and alternatives. A medicine's pregnancy risk cannot be inferred solely from whether it enters breast milk. Treatment principles. Balance the risks of treatment against untreated disease using a current teratology or lactation reference. Consider premature infants, infant health and the extent of exposure. Optimize necessary treatment with the relevant clinicians. Safety and follow-up. Do not describe all natural products as safe or recommend stopping every medicine. Document the source and counselling. A new exposure needs a specific risk assessment; uncertainty alone is not proof that harm has occurred.","hi":"गर्भावस्था और स्तनपान की दवा समीक्षा अलग है। गर्भ का समय, शिशु की उम्र, दवा की जरूरत, मात्रा और अवधि देखें। बीमारी का इलाज न होने का जोखिम भी तौलें। वर्तमान विश्वसनीय गर्भ और स्तनपान संदर्भ इस्तेमाल करें। प्राकृतिक उत्पाद हमेशा सुरक्षित नहीं होते। सभी दवाएं बंद न करवाएं। अनिश्चितता का मतलब यह नहीं कि नुकसान निश्चित हुआ है; व्यक्तिगत मूल्यांकन करें।","files":{"en":"audio/drugs-in-pregnancy-lactation-en.mp3","hi":"audio/drugs-in-pregnancy-lactation-hi.mp3"},"duration":{"en":49.5,"hi":34.6},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"hepatic-encephalopathy","topic":"hepatic-encephalopathy","title":"Hepatic Encephalopathy","en":"Hepatic Encephalopathy. Assessment. New confusion in cirrhosis needs assessment for infection, bleeding, constipation, dehydration, medicines and other causes. Do not attribute every altered mental state to the liver without evaluation. Treatment principles. Management targets precipitating factors and commonly uses lactulose, with rifaximin in appropriate circumstances. The plan should specify the stool goal and follow-up rather than encouraging uncontrolled diarrhoea. Safety and follow-up. Severe drowsiness or inability to protect the airway requires emergency care. Excessive diarrhoea can worsen dehydration and electrolytes. Review sedatives, adherence and caregiver understanding, and distinguish a clinical assessment from an ammonia number alone.","hi":"सिरोसिस में नया भ्रम होने पर संक्रमण, रक्तस्राव, कब्ज, पानी की कमी और दवाएं देखें। हर भ्रम को केवल लिवर का कारण न मानें। लैक्टुलोज और कुछ स्थितियों में रिफैक्सिमिन उपयोग होती हैं। मल का लक्ष्य डॉक्टर की योजना से समझाएं; बहुत दस्त होना अच्छा लक्ष्य नहीं। अत्यधिक नींद या सांस की सुरक्षा न रख पाना आपातस्थिति है। परिवार को निगरानी और फॉलो अप बताएं।","files":{"hi":"audio/hepatic-encephalopathy-hi.mp3","en":"audio/hepatic-encephalopathy-en.mp3"},"duration":{"hi":33.0,"en":49.7},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"diarrhoea","topic":"diarrhoea","title":"Diarrhoea","en":"Diarrhoea. Assessment. Assess duration, frequency, blood, fever, dehydration, travel, antibiotics and vulnerable contacts. Recent antibiotic exposure or hospitalization raises concern for C. difficile; chronic diarrhoea needs a wider assessment. Treatment principles. Oral rehydration is central. Symptom medicines are appropriate only after considering age, cause and contraindications. Antibiotics are not routine for every episode; organism-specific treatment and infection-control measures may be needed. Safety and follow-up. Blood, severe pain, high fever, marked dehydration or significant immunocompromise warrants assessment. Avoid indiscriminate antimotility treatment in suspected invasive disease. Review urine output, fluid intake and a clear plan if symptoms persist.","hi":"दस्त में अवधि, खून, बुखार, यात्रा और हाल की एंटीबायोटिक पूछें। पानी और नमक की कमी पूरी करना सबसे जरूरी कदमों में है। हर दस्त में एंटीबायोटिक नहीं चाहिए। खून, तेज पेट दर्द, गंभीर पानी की कमी या कमजोर प्रतिरक्षा में जांच करवाएं। आक्रामक संक्रमण की संभावना में दस्त रोकने की दवा बिना समीक्षा न दें। पेशाब और तरल सेवन की निगरानी तथा फॉलो अप समझाएं।","files":{"en":"audio/diarrhoea-en.mp3","hi":"audio/diarrhoea-hi.mp3"},"duration":{"en":56.2,"hi":33.9},"subject":"GI, GU & Reproductive Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"opioid-and-alcohol-use-disorder","topic":"opioid-and-alcohol-use-disorder","title":"Opioid and Alcohol Use Disorder","en":"Opioid and Alcohol Use Disorder. Assessment. Use a nonjudgmental assessment of substance use, goals, withdrawal, overdose history, other sedatives and support. Physical dependence, tolerance and use disorder are related but not identical concepts. Treatment principles. Offer harm reduction and evidence-based treatment referral. Opioid agonist treatment has product-specific initiation and missed-dose rules. Alcohol withdrawal can require monitored medical treatment; long-term relapse-prevention treatment is a separate decision. Safety and follow-up. Slow or absent breathing after opioid exposure requires emergency response and naloxone when available. Severe alcohol withdrawal can cause seizures or delirium. Do not advise abrupt unsupported withdrawal in a person at risk or restart an old opioid dose after lost tolerance.","hi":"ओपिओइड और शराब के उपयोग पर बिना दोष दिए बात करें। विड्रॉल, ओवरडोज, दूसरी नींद की दवाएं और लक्ष्य पूछें। शारीरिक निर्भरता और उपयोग विकार एक ही बात नहीं हैं। नालॉक्सोन और नुकसान कम करने की सहायता दें। गंभीर शराब विड्रॉल में दौरे या डिलीरियम हो सकता है। लंबे अंतराल के बाद पुरानी ओपिओइड खुराक फिर शुरू करना खतरनाक है क्योंकि सहनशीलता घट सकती है।","files":{"hi":"audio/opioid-and-alcohol-use-disorder-hi.mp3","en":"audio/opioid-and-alcohol-use-disorder-en.mp3"},"duration":{"hi":34.5,"en":55.3},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"bell-palsy-and-gbs","topic":"bell-palsy-and-gbs","title":"Bell Palsy and GBS","en":"Bell Palsy and GBS. Assessment. Sudden facial weakness requires assessment to distinguish Bell palsy from stroke and other causes. Guillain–Barré syndrome can present with progressive weakness, sensory symptoms and reduced reflexes, often after infection. Treatment principles. Bell palsy care includes timely assessment and eye protection when closure is impaired. Suspected GBS requires urgent hospital evaluation for respiratory and autonomic involvement; it is not a routine self-care problem. Safety and follow-up. Facial weakness with speech or limb symptoms requires emergency stroke assessment. Ascending weakness, swallowing difficulty or breathlessness can deteriorate rapidly. Do not delay referral while trying a topical or over-the-counter remedy.","hi":"अचानक चेहरे की कमजोरी में बेल पाल्सी और स्ट्रोक को अलग करना जरूरी है। आंख बंद न हो तो आंख की सुरक्षा की योजना चाहिए। गिलैन बारे में बढ़ती कमजोरी और सांस या निगलने की परेशानी हो सकती है। बोलने या हाथ-पैर की कमजोरी के साथ चेहरे का बदलाव आपातकालीन स्ट्रोक जांच मांगता है। बढ़ती कमजोरी को घर की दवा से संभालने की कोशिश में रेफरल न रोकें।","files":{"en":"audio/bell-palsy-and-gbs-en.mp3","hi":"audio/bell-palsy-and-gbs-hi.mp3"},"duration":{"en":49.9,"hi":32.2},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"cannabis","topic":"cannabis","title":"Cannabis","en":"Cannabis. Assessment. Ask about formulation, THC and CBD content, route, frequency, goals, other medicines and adverse effects. Oral and inhaled products differ in onset and duration; a product being legal does not establish that it is risk free. Treatment principles. Discuss impairment, interactions, safer storage and uncertainty about benefit for the intended condition. Delayed oral effects can lead to repeated dosing before the first dose has taken effect. Safety and follow-up. Avoid driving while impaired and combining with sedatives. Pregnancy, adolescent use and a history of psychosis require particular caution. Severe vomiting, chest pain, marked confusion or accidental child ingestion needs assessment.","hi":"कैनबिस में टी एच सी, सी बी डी, रूप, मात्रा और उपयोग का कारण पूछें। खाने वाले उत्पाद का असर देर से आता है और जल्दी दोबारा लेने से नुकसान हो सकता है। वैध होने का मतलब जोखिम रहित नहीं। नशे में गाड़ी न चलाएं और नींद की दवाओं के साथ खतरा समझें। बच्चे द्वारा गलती से लेना, गंभीर भ्रम या लगातार उल्टी होने पर चिकित्सा मदद लें।","files":{"hi":"audio/cannabis-hi.mp3","en":"audio/cannabis-en.mp3"},"duration":{"hi":30.8,"en":49.9},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"parkinson-s-disease","topic":"parkinson-s-disease","title":"Parkinson's Disease","en":"Parkinson's Disease. Assessment. Assess movement symptoms, falls, swallowing, cognition, hallucinations, constipation and fluctuations related to dose timing. Medicines that block dopamine can worsen parkinsonism. Treatment principles. Levodopa regimens are time sensitive and individualized. Preserve the exact schedule during transitions of care and assess wearing-off or dyskinesia with the treating team. Dopamine agonists can affect impulse control and cause sleepiness. Safety and follow-up. Do not abruptly stop dopaminergic therapy. Review orthostatic symptoms and hallucinations without assuming every problem is disease progression. If swallowing becomes difficult, obtain a safe formulation plan rather than crushing all products.","hi":"पार्किन्सन में गति के साथ गिरना, निगलना, कब्ज, भ्रम और खुराक के समय से बदलते लक्षण देखें। लेवोडोपा का सही समय महत्वपूर्ण है, खासकर अस्पताल में। डोपामिन रोकने वाली कुछ दवाएं लक्षण बिगाड़ सकती हैं। दवा अचानक बंद न करें। कुछ डोपामिन एगोनिस्ट आवेग नियंत्रण और नींद प्रभावित करते हैं। निगलने में परेशानी पर हर गोली कुचलने के बजाय सही विकल्प की योजना लें।","files":{"en":"audio/parkinson-s-disease-en.mp3","hi":"audio/parkinson-s-disease-hi.mp3"},"duration":{"en":50.2,"hi":34.1},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"headaches-migraines","topic":"headaches-migraines","title":"Headaches & Migraines","en":"Headaches & Migraines. Assessment. Clarify onset, pattern, neurological symptoms, triggers and frequency of acute medicine use. A first thunderclap headache, new deficit, fever with stiffness or concerning pregnancy-related headache needs urgent assessment. Treatment principles. Acute and preventive migraine therapies serve different goals. Select treatment around comorbidities, interactions and contraindications. Frequent use of acute medicines can contribute to medication-overuse headache. Safety and follow-up. Triptans are not suitable for every vascular-risk context. Track headache days, disability and medicine days in a diary. Do not dismiss a major change in pattern because the patient has a previous migraine diagnosis.","hi":"सिरदर्द में शुरुआत, पैटर्न, न्यूरोलॉजिकल लक्षण और दर्द की दवा कितने दिन ली जाती है, पूछें। अचानक सबसे तेज सिरदर्द या नई कमजोरी में तुरंत जांच करें। माइग्रेन के तत्काल और रोकथाम के इलाज अलग हैं। ज्यादा बार दर्द की दवा लेने से सिरदर्द बढ़ सकता है। ट्रिप्टान सभी मरीजों के लिए सही नहीं। सिरदर्द और दवा वाले दिनों का रिकॉर्ड रखें।","files":{"en":"audio/headaches-migraines-en.mp3","hi":"audio/headaches-migraines-hi.mp3"},"duration":{"en":49.9,"hi":31.5},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pain-management-palliative-care","topic":"pain-management-palliative-care","title":"Pain Management & Palliative Care","en":"Pain Management & Palliative Care. Assessment. Assess the pain mechanism, severity, function, goals and emotional context. Palliative care addresses quality of life and symptoms; it is not restricted to the final days of life. Treatment principles. Combine appropriate non-drug strategies with medicines selected for the pain mechanism and patient. Opioid therapy requires a clear indication, individualized titration, constipation planning and assessment of sedation and breathing risk. Safety and follow-up. Account for kidney function, other sedatives, falls and previous opioid exposure. Do not apply a simple equianalgesic conversion without accounting for incomplete cross-tolerance and clinical context. New neurological deficits or severe unexplained pain needs assessment.","hi":"दर्द में तीव्रता के साथ कारण, कामकाज और मरीज के लक्ष्य देखें। पैलिएटिव देखभाल जीवन की गुणवत्ता पर केंद्रित है और केवल अंतिम दिनों के लिए नहीं है। ओपिओइड में कब्ज, नींद, सांस और गुर्दे की स्थिति की योजना चाहिए। दूसरी नींद की दवाओं से जोखिम बढ़ता है। एक ओपिओइड से दूसरी में बदलते समय केवल गणित की बराबरी पर्याप्त नहीं; सहनशीलता और व्यक्तिगत स्थिति जरूरी हैं।","files":{"hi":"audio/pain-management-palliative-care-hi.mp3","en":"audio/pain-management-palliative-care-en.mp3"},"duration":{"hi":33.7,"en":51.9},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"chronic-spasticity","topic":"chronic-spasticity","title":"Chronic Spasticity","en":"Chronic Spasticity. Assessment. Determine whether increased muscle tone is painful, limits function or sometimes helps transfers. Review the neurological cause, triggers, weakness and goals with the patient and rehabilitation team. Treatment principles. Physical and positioning strategies may accompany medicines such as baclofen or focal treatments. Balance reduced tone against sedation and loss of useful strength; renal function is important for some agents. Safety and follow-up. Abrupt baclofen withdrawal, especially interruption of an intrathecal pump, can be dangerous. Sudden severe worsening, fever, confusion or suspected pump failure requires urgent assessment. Document the exact route and delivery system.","hi":"स्पास्टिसिटी में मांसपेशी का बढ़ा खिंचाव दर्द और काम को कैसे प्रभावित करता है, पूछें। कभी कुछ टोन खड़े होने में मदद भी करता है। व्यायाम, स्थिति और दवा की योजना साथ बनाएं। बैक्लोफेन से नींद और कमजोरी हो सकती है। दवा अचानक बंद करना, खासकर पंप रुकना, खतरनाक है। बुखार, भ्रम या तेजी से बिगड़ाव में तुरंत मदद लें और सही मार्ग दर्ज करें।","files":{"hi":"audio/chronic-spasticity-hi.mp3","en":"audio/chronic-spasticity-en.mp3"},"duration":{"hi":33.3,"en":47.0},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"multiple-sclerosis","topic":"multiple-sclerosis","title":"Multiple Sclerosis","en":"Multiple Sclerosis. Assessment. Distinguish a possible relapse from temporary worsening during infection, heat or another stressor. Assess new neurological symptoms, functional change, current disease-modifying therapy and infection risk. Treatment principles. Acute relapse treatment, long-term disease modification and symptom control are separate plans. Disease-modifying products differ substantially in infection screening, vaccines, laboratory monitoring, reproductive counselling and administration. Safety and follow-up. Do not stop or switch treatment without a coordinated plan because rebound or disease activity may be relevant. New severe neurological symptoms require assessment. Review fatigue, mobility, bladder symptoms and adherence respectfully.","hi":"मल्टिपल स्क्लेरोसिस में असली रिलैप्स और बुखार या गर्मी से अस्थायी बिगड़ाव अलग करें। नई न्यूरोलॉजिकल समस्या की जांच जरूरी है। रिलैप्स का इलाज, बीमारी बदलने वाली दवा और लक्षण नियंत्रण तीन अलग लक्ष्य हैं। दवाओं में संक्रमण जांच, टीके और गर्भ की योजना अलग होती है। उपचार अपने आप बंद या बदलने से पहले विशेषज्ञ से समन्वय करें।","files":{"hi":"audio/multiple-sclerosis-hi.mp3","en":"audio/multiple-sclerosis-en.mp3"},"duration":{"hi":31.0,"en":50.4},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"restless-leg-syndrome","topic":"restless-leg-syndrome","title":"Restless Leg Syndrome","en":"Restless Leg Syndrome. Assessment. An urge to move the legs that worsens at rest and in the evening and improves with movement suggests restless legs. Distinguish cramps, neuropathy, akathisia and other mimics. Treatment principles. Review iron status, kidney disease, sleep and aggravating medicines. Treat reversible contributors and select medication using current guidance; the appropriate iron plan depends on laboratory findings and context. Safety and follow-up. Dopaminergic treatment can cause augmentation, with symptoms starting earlier or becoming more extensive. Do not repeatedly increase a dose without reassessment. Monitor sleepiness, falls and the effect on daily function.","hi":"रेस्टलेस लेग्स में आराम और शाम को पैर हिलाने की इच्छा बढ़ती और हिलाने से घटती है। ऐंठन या न्यूरोपैथी से अलग करें। आयरन, गुर्दे, नींद और बढ़ाने वाली दवाएं देखें। कुछ डोपामिन दवाओं से लक्षण दिन में पहले और ज्यादा फैल सकते हैं; इसे ऑगमेंटेशन कहते हैं। ऐसी स्थिति में खुराक बार-बार बढ़ाने के बजाय दोबारा मूल्यांकन करें।","files":{"en":"audio/restless-leg-syndrome-en.mp3","hi":"audio/restless-leg-syndrome-hi.mp3"},"duration":{"en":46.4,"hi":30.4},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"chronic-fatigue-syndrome","topic":"chronic-fatigue-syndrome","title":"Chronic Fatigue Syndrome","en":"Chronic Fatigue Syndrome. Assessment. ME/CFS involves substantial functional impairment and characteristic post-exertional symptom worsening. Assess sleep, cognition, orthostatic symptoms and alternative or coexisting medical causes. Treatment principles. Support individualized energy management and symptom care. Activity plans should respect the person's limits and post-exertional worsening rather than impose fixed increases regardless of symptoms. Safety and follow-up. Do not frame the illness as lack of motivation. Review medicines that worsen fatigue and define practical goals. New focal signs, significant weight loss or a major change from baseline needs reassessment for another cause.","hi":"एम ई या क्रॉनिक फटीग सिंड्रोम में गतिविधि के बाद लक्षण बढ़ना महत्वपूर्ण है। नींद, ध्यान, खड़े होने पर परेशानी और दूसरे कारण देखें। ऊर्जा का उपयोग मरीज की क्षमता के अनुसार बांटें। लक्षण बिगड़ने पर भी तय मात्रा में व्यायाम बढ़ाने की जिद न करें। इसे आलस न कहें। नया अलग लक्षण या वजन घटना हो तो अन्य कारण की जांच करें।","files":{"hi":"audio/chronic-fatigue-syndrome-hi.mp3","en":"audio/chronic-fatigue-syndrome-en.mp3"},"duration":{"hi":30.7,"en":46.5},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"drug-withdrawal-syndromes","topic":"drug-withdrawal-syndromes","title":"Drug Withdrawal Syndromes","en":"Drug Withdrawal Syndromes. Assessment. Identify the substance or medicine, dose, duration, last use, taper history and symptoms. Withdrawal can occur with prescribed medicines as well as nonmedical substances. Treatment principles. Different agents need different plans: benzodiazepines, alcohol, opioids, antidepressants, corticosteroids and other therapies are not managed by a single taper schedule. Coordinate an individualized plan and monitor response. Safety and follow-up. Seizures, delirium, severe autonomic symptoms or suspected adrenal crisis require emergency assessment. Rebound symptoms can resemble recurrence of disease. Do not advise abrupt discontinuation simply because a medicine has adverse effects.","hi":"विड्रॉल में कौन सी दवा, कितनी अवधि और आखिरी खुराक कब ली, पूछें। लिखी हुई दवा से भी विड्रॉल हो सकता है। शराब, बेंज़ोडायज़ेपीन, ओपिओइड, एंटीडिप्रेसेंट और स्टेरॉयड की योजना एक जैसी नहीं है। दौरे, डिलीरियम या गंभीर कमजोरी में तुरंत मदद लें। लक्षण लौटना बीमारी या विड्रॉल दोनों हो सकता है। दुष्प्रभाव होने पर भी बिना योजना अचानक बंद न करें।","files":{"en":"audio/drug-withdrawal-syndromes-en.mp3","hi":"audio/drug-withdrawal-syndromes-hi.mp3"},"duration":{"en":50.5,"hi":33.1},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"seizures","topic":"seizures","title":"Seizures","en":"Seizures. Assessment. Clarify the event, duration, recovery, known seizure diagnosis, missed doses, triggers and medicines. A first seizure needs medical assessment; not every collapse is epilepsy. Treatment principles. Antiseizure therapy depends on seizure type, comorbidities, interactions and reproductive considerations. Maintain consistent use and the exact formulation. Rescue medicines require a written individualized plan and caregiver teaching. Safety and follow-up. A prolonged seizure, repeated seizures without recovery, breathing difficulty or major injury needs emergency care. Protect from injury, do not restrain and put nothing in the mouth. Abruptly stopping long-term antiseizure treatment can provoke seizures.","hi":"दौरे में अवधि, होश लौटने का समय, पुरानी बीमारी और छूटी दवा पूछें। हर बेहोशी मिर्गी नहीं है। दवा दौरे के प्रकार और गर्भ संबंधी जोखिम के अनुसार चुनी जाती है। लंबे दौरे या बीच में होश न लौटने पर आपातकालीन मदद लें। चोट से बचाएं, मरीज को न दबाएं और मुंह में कुछ न डालें। दवा अचानक बंद न करें; रेस्क्यू योजना लिखित हो।","files":{"hi":"audio/seizures-hi.mp3","en":"audio/seizures-en.mp3"},"duration":{"hi":32.3,"en":51.0},"subject":"Neurology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"gout","topic":"gout","title":"Gout","en":"Gout. Assessment. An acutely hot swollen joint needs assessment; septic arthritis is an important alternative. Review attack pattern, kidney function, medicines, alcohol and previous urate-lowering treatment. Treatment principles. Acute anti-inflammatory treatment and long-term urate reduction address different goals. Colchicine, NSAIDs and corticosteroids have patient-specific limitations. Starting urate-lowering therapy involves a titration and flare-prevention plan. Safety and follow-up. Colchicine can have serious interactions and toxicity, especially with organ impairment. Do not routinely stop established urate-lowering therapy during a flare without clinical direction. Fever or concern for joint infection requires urgent assessment.","hi":"गाउट में अचानक गर्म सूजे जोड़ को देखें, लेकिन जोड़ का संक्रमण भी संभव है। तीव्र दर्द कम करना और लंबे समय में यूरिक एसिड कम करना अलग लक्ष्य हैं। कोल्चिसिन, एन एस ए आई डी और स्टेरॉयड की सीमाएं मरीज अनुसार हैं। कोल्चिसिन की गंभीर अंतःक्रियाएं हो सकती हैं। फ्लेयर में पुरानी यूरिक एसिड की दवा अपने आप बंद न करें। बुखार या संक्रमण की आशंका में जल्दी जांच करें।","files":{"en":"audio/gout-en.mp3","hi":"audio/gout-hi.mp3"},"duration":{"en":49.9,"hi":35.5},"subject":"Musculoskeletal","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"rheumatoid-arthritis","topic":"rheumatoid-arthritis","title":"Rheumatoid Arthritis","en":"Rheumatoid Arthritis. Assessment. Persistent inflammatory joint symptoms, morning stiffness and functional decline warrant early assessment. RA is systemic disease, not simply age-related joint wear. Treatment principles. Disease-modifying antirheumatic drugs aim to control inflammation and prevent damage; analgesics do not replace them. Methotrexate for inflammatory disease is commonly weekly, with a specific folate and monitoring plan. Safety and follow-up. Daily-versus-weekly methotrexate errors can be fatal. Verify the indication, schedule, interactions, blood counts, liver and kidney monitoring. Infection symptoms and reproductive planning require careful coordination with the treating team.","hi":"रूमेटॉइड आर्थराइटिस में सुबह की अकड़न और लगातार सूजे जोड़ जल्दी जांच मांगते हैं। बीमारी नियंत्रित करने वाली दवाएं नुकसान रोकती हैं; केवल दर्द की दवा उनका विकल्प नहीं। सूजन की बीमारी में मेथोट्रेक्सेट आमतौर पर साप्ताहिक होती है। उसे गलती से रोज लेना जानलेवा हो सकता है। समय, फोलेट, रक्त, लिवर और गुर्दे की निगरानी स्पष्ट करें।","files":{"hi":"audio/rheumatoid-arthritis-hi.mp3","en":"audio/rheumatoid-arthritis-en.mp3"},"duration":{"hi":31.1,"en":48.2},"subject":"Musculoskeletal","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"osteoporosis","topic":"osteoporosis","title":"Osteoporosis","en":"Osteoporosis. Assessment. Assess fracture history, falls, bone density when available, glucocorticoids and other risk factors. Treatment decisions use overall fracture risk rather than bone density alone. Treatment principles. Exercise suited to the person, fall prevention and appropriate calcium/vitamin-D intake accompany drug therapy when indicated. Oral bisphosphonates have exact fasting, water and upright-position instructions that vary by product. Safety and follow-up. Check renal function, swallowing or oesophageal problems and dental concerns where relevant. Denosumab should not be delayed or stopped without a follow-on plan because rebound fracture risk matters. New severe back pain may represent a vertebral fracture.","hi":"ऑस्टियोपोरोसिस में पुराना फ्रैक्चर, गिरना, हड्डी की जांच और स्टेरॉयड का उपयोग देखें। कुल फ्रैक्चर जोखिम से निर्णय लें। व्यायाम, गिरने से बचाव और उचित कैल्शियम तथा विटामिन डी साथ जरूरी हैं। खाने वाली बिसफॉस्फोनेट की पानी, खाली पेट और सीधे बैठने की विधि समझाएं। डेनोसुमैब बिना आगे की योजना बंद या देर न करें; फ्रैक्चर जोखिम बढ़ सकता है।","files":{"en":"audio/osteoporosis-en.mp3","hi":"audio/osteoporosis-hi.mp3"},"duration":{"en":48.7,"hi":31.7},"subject":"Musculoskeletal","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"msk-pain","topic":"msk-pain","title":"MSK Pain","en":"MSK Pain. Assessment. Establish location, injury mechanism, duration, swelling, neurological symptoms and functional goals. Differentiate a self-limited strain from fracture, infection or a neurological emergency. Treatment principles. Activity modification, appropriate movement and physical strategies may accompany topical or oral analgesia. Select an NSAID only after considering GI bleeding, kidney disease, cardiovascular risk, pregnancy and interacting medicines. Safety and follow-up. Do not combine multiple NSAIDs unknowingly through combination products. Red flags include severe trauma, hot swollen joint with systemic illness, progressive weakness or new bladder/bowel dysfunction with back pain. Reassess persistent symptoms.","hi":"मांसपेशी और जोड़ के दर्द में चोट, सूजन, अवधि और काम पर असर देखें। हल्की खिंचाव और फ्रैक्चर या संक्रमण अलग हैं। दवा चुनते समय पेट का रक्तस्राव, गुर्दे, हृदय, गर्भावस्था और दूसरी दवाएं देखें। अलग ब्रांड से दो एन एस ए आई डी साथ न लें। पीठ दर्द के साथ नई पेशाब या मल की समस्या और कमजोरी आपात जांच मांगती है।","files":{"hi":"audio/msk-pain-hi.mp3","en":"audio/msk-pain-en.mp3"},"duration":{"hi":31.1,"en":52.4},"subject":"Musculoskeletal","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"systemic-lupus-erythematosus","topic":"systemic-lupus-erythematosus","title":"Systemic Lupus Erythematosus","en":"Systemic Lupus Erythematosus. Assessment. Lupus can affect skin, joints, blood, kidneys and other organs. Assess the current organ involvement, symptoms, infection risk and prescribed monitoring rather than treating it as one uniform rash disorder. Treatment principles. Hydroxychloroquine and immunomodulating therapies have roles determined by the disease and patient. Eye monitoring, adherence, sun protection and reproductive planning are important elements of ongoing care. Safety and follow-up. Infection and flare can look similar, particularly during immunosuppression. New chest pain, neurological symptoms, marked swelling or renal concerns need assessment. Do not independently increase corticosteroids whenever symptoms recur.","hi":"लुपस त्वचा, जोड़, रक्त, गुर्दे और अन्य अंगों को प्रभावित कर सकता है। वर्तमान अंग संबंधी समस्या और संक्रमण जोखिम देखें। हाइड्रॉक्सीक्लोरोक्वीन में आंख की निगरानी, नियमित उपयोग और धूप से बचाव महत्वपूर्ण हैं। संक्रमण और फ्लेयर एक जैसे दिख सकते हैं। नया छाती दर्द, न्यूरोलॉजिकल लक्षण या सूजन में जांच कराएं। हर बार अपनी तरफ से स्टेरॉयड न बढ़ाएं।","files":{"en":"audio/systemic-lupus-erythematosus-en.mp3","hi":"audio/systemic-lupus-erythematosus-hi.mp3"},"duration":{"en":49.0,"hi":33.8},"subject":"Musculoskeletal","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"polymyalgia-rheumatica-giant-cell-arteritis","topic":"polymyalgia-rheumatica-giant-cell-arteritis","title":"Polymyalgia Rheumatica & Giant Cell Arteritis","en":"Polymyalgia Rheumatica & Giant Cell Arteritis. Assessment. PMR commonly causes shoulder and hip-girdle pain and stiffness in older adults. New headache, scalp tenderness, jaw claudication or visual symptoms raises concern for associated giant cell arteritis. Treatment principles. Suspected giant cell arteritis requires urgent medical evaluation and time-sensitive treatment to protect vision. PMR treatment and tapering require follow-up of symptoms and adverse effects; the two conditions need different levels of urgency. Safety and follow-up. Do not delay referral for a routine analgesic trial when vision is threatened. Long-term corticosteroid care includes bone, glucose, blood-pressure and infection-risk review. Relapse assessment should consider alternative diagnoses.","hi":"पॉलीमायल्जिया में बुजुर्गों के कंधे और कूल्हे में दर्द तथा अकड़न होती है। नया सिरदर्द, सिर की त्वचा में दर्द, चबाने पर जबड़े में दर्द या नजर बदलना जाइंट सेल आर्टराइटिस का संकेत हो सकता है। दृष्टि बचाने के लिए तत्काल चिकित्सा जांच जरूरी है। केवल दर्द की दवा देकर इंतजार न करें। लंबे स्टेरॉयड में हड्डी, शुगर, रक्तचाप और संक्रमण की निगरानी करें।","files":{"hi":"audio/polymyalgia-rheumatica-giant-cell-arteritis-hi.mp3","en":"audio/polymyalgia-rheumatica-giant-cell-arteritis-en.mp3"},"duration":{"hi":31.8,"en":52.3},"subject":"Musculoskeletal","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"osteoarthritis","topic":"osteoarthritis","title":"Osteoarthritis","en":"Osteoarthritis. Assessment. Assess activity-related joint pain, stiffness, mobility and daily-life goals. A hot joint, systemic illness or a rapid unusual change should prompt consideration of another diagnosis. Treatment principles. Exercise, strengthening and weight-management support when relevant are central. Topical NSAIDs can be useful for selected superficial joints; oral therapy requires a GI, renal and cardiovascular risk assessment. Safety and follow-up. Imaging changes and pain severity do not always match. Avoid escalating medicines without reviewing benefit and function. Injections and surgery are individualized options; persistent major disability merits referral and shared decision-making.","hi":"ऑस्टियोआर्थराइटिस में गतिविधि से दर्द, अकड़न और रोजमर्रा की क्षमता देखें। व्यायाम, ताकत बढ़ाना और जरूरत पर वजन प्रबंधन मुख्य भाग हैं। कुछ जोड़ों में बाहरी एन एस ए आई डी मदद कर सकती है। खाने वाली दवा से पहले पेट, गुर्दे और हृदय जोखिम देखें। एक्स रे और दर्द हमेशा समान नहीं होते। बिना लाभ देखे दवा बढ़ाते न जाएं; कार्यक्षमता का लक्ष्य तय करें।","files":{"hi":"audio/osteoarthritis-hi.mp3","en":"audio/osteoarthritis-en.mp3"},"duration":{"hi":33.6,"en":49.1},"subject":"Musculoskeletal","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"fibromyalgia","topic":"fibromyalgia","title":"Fibromyalgia","en":"Fibromyalgia. Assessment. Widespread pain with fatigue, sleep and cognitive symptoms requires a positive clinical assessment and consideration of alternatives. The symptoms are real even when routine inflammatory tests are normal. Treatment principles. Education, individualized physical activity, sleep strategies and psychological support form part of care. Selected medicines target pain and associated symptoms; benefit should be judged against adverse effects and function. Safety and follow-up. Avoid assuming that stronger opioid treatment is the default next step. Set gradual achievable goals and review sedating combinations. New focal deficits, inflammatory signs or a significant change in symptoms needs reassessment.","hi":"फाइब्रोमायल्जिया में पूरे शरीर का दर्द, थकान, नींद और ध्यान की समस्या हो सकती है। सामान्य सूजन जांच होने पर भी लक्षण वास्तविक हैं। समझाना, व्यक्ति अनुसार गतिविधि, नींद और मानसिक सहायता महत्वपूर्ण हैं। दवा का लाभ कार्यक्षमता और दुष्प्रभाव से तौलें। अधिक शक्तिशाली ओपिओइड को स्वतः अगला कदम न मानें। नई अलग कमजोरी या सूजन में दोबारा जांच करें।","files":{"hi":"audio/fibromyalgia-hi.mp3","en":"audio/fibromyalgia-en.mp3"},"duration":{"hi":34.1,"en":49.2},"subject":"Musculoskeletal","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"diabetes","topic":"diabetes","title":"Diabetes","en":"Diabetes. Build the picture. Clarify diabetes type, current therapy, glucose pattern, individualized targets, hypoglycemia history and the person’s daily routine. Review kidney function, comorbidities, access and device use. Do not treat a single glucose reading as the whole assessment. Acute illness, symptoms and the ability to eat or drink may change the urgency and plan. Support safe use. Teach relevant monitoring, recognition of hypoglycemia, device technique and a patient-specific sick-day plan using current guidance. Confirm understanding through teach-back. Choose and reassess treatment with current Canadian recommendations, individualized goals, risks, preferences and prescriber collaboration.","hi":"मधुमेह में शुगर के साथ हृदय, गुर्दे, कम शुगर का जोखिम और इलाज का बोझ देखें। मरीज के लक्ष्य और स्वयं निगरानी की क्षमता पूछें। दवा का चुनाव केवल एच बी ए वन सी से नहीं होता। कम शुगर की पहचान और व्यक्ति की उपचार योजना समझाएं। बीमारी के दिनों में पानी, जांच और दवाओं की स्पष्ट योजना चाहिए। मतली, उल्टी, पेट दर्द या तेज सांस में कीटोएसिडोसिस की संभावना पर जांच करें; कुछ दवाओं में शुगर बहुत ऊंची न होने पर भी यह हो सकता है।","files":{"en":"audio/diabetes-en.mp3","hi":"audio/diabetes-hi.mp3"},"duration":{"en":48.6,"hi":39.6},"subject":"Endocrine & Metabolic","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"hypothyroidism","topic":"hypothyroidism","title":"Hypothyroidism","en":"Hypothyroidism. Assessment. Assess symptoms alongside thyroid results, diagnosis, adherence and interfering medicines. Fatigue alone is nonspecific; distinguish primary thyroid disease from other causes and special situations. Treatment principles. Levothyroxine is taken consistently according to product instructions. Food, calcium, iron and other agents can affect absorption. Dose assessment uses the appropriate follow-up interval because thyroid hormone and TSH do not stabilize immediately. Safety and follow-up. Avoid rapid repeated dose changes based on a few days of symptoms. Pregnancy, older age and cardiac disease require tailored review. Excess replacement may cause palpitations and contribute to atrial fibrillation or bone loss.","hi":"हाइपोथायरॉइड में लक्षण के साथ सही जांच और दवा पालन देखें। केवल थकान से निदान न करें। लेवोथायरॉक्सिन एक जैसी विधि से लें; भोजन, कैल्शियम और आयरन अवशोषण बदल सकते हैं। जांच को स्थिर होने में समय लगता है, इसलिए कुछ दिनों में बार-बार खुराक न बदलें। गर्भावस्था, बुजुर्ग और हृदय रोग में विशेष समीक्षा करें। ज्यादा दवा से धड़कन और हड्डी का जोखिम बढ़ सकता है।","files":{"en":"audio/hypothyroidism-en.mp3","hi":"audio/hypothyroidism-hi.mp3"},"duration":{"en":52.1,"hi":34.9},"subject":"Endocrine & Metabolic","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"hyperthyroidism","topic":"hyperthyroidism","title":"Hyperthyroidism","en":"Hyperthyroidism. Assessment. Assess symptoms, thyroid results, likely cause, pulse and systemic illness. Thyrotoxicosis has multiple causes; antithyroid medicines do not suit every cause of excess thyroid hormone. Treatment principles. Treatment may involve symptom control, antithyroid medication, radioactive iodine or surgery depending on the diagnosis and patient. Explain the exact monitoring plan and relevant pregnancy considerations. Safety and follow-up. Fever or sore throat during thionamide therapy requires urgent assessment for possible agranulocytosis and prompt prescriber instructions. Severe fever, marked tachycardia, agitation or heart failure may signal thyroid storm and requires emergency care.","hi":"हाइपरथायरॉइड में कारण, धड़कन और जांच देखें। हर कारण में एंटीथायरॉइड दवा काम नहीं करती। उपचार में दवा, रेडियोएक्टिव आयोडीन या ऑपरेशन हो सकता है। थायोनामाइड लेते समय बुखार या गले में दर्द पर गंभीर श्वेत रक्त कोशिका कमी की तुरंत जांच जरूरी है। बहुत तेज बुखार, धड़कन और भ्रम थायरॉइड स्टॉर्म का संकेत हो सकते हैं। गर्भावस्था की स्थिति जरूर पूछें।","files":{"hi":"audio/hyperthyroidism-hi.mp3","en":"audio/hyperthyroidism-en.mp3"},"duration":{"hi":34.1,"en":49.4},"subject":"Endocrine & Metabolic","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"allergic-rhinitis","topic":"allergic-rhinitis","title":"Allergic Rhinitis","en":"Allergic Rhinitis. Assessment. Assess sneezing, itching, watery discharge, congestion, triggers and effect on sleep. Unilateral persistent symptoms, recurrent bleeding or unusual discharge may suggest another cause. Treatment principles. Allergen reduction, saline and an appropriate intranasal corticosteroid or antihistamine can help. Correct spray technique directs medication away from the septum and requires regular use for controller benefit. Safety and follow-up. Topical nasal decongestants can cause rebound congestion with prolonged use. Oral decongestants may worsen blood pressure, insomnia or urinary retention. Review asthma symptoms and avoid routinely choosing sedating antihistamines for daytime use.","hi":"एलर्जिक राइनाइटिस में छींक, खुजली, पानी और बंद नाक के ट्रिगर पूछें। नाक की स्टेरॉयड स्प्रे को बीच की दीवार से दूर दिशा में लगाएं और नियमित उपयोग समझाएं। नाक खोलने वाली कुछ स्प्रे लंबे उपयोग से उल्टा बंद नाक बढ़ाती हैं। खाने वाले डीकंजेस्टेंट रक्तचाप, नींद या पेशाब की समस्या बढ़ा सकते हैं। एक तरफ लगातार लक्षण या खून हो तो जांच करें।","files":{"en":"audio/allergic-rhinitis-en.mp3","hi":"audio/allergic-rhinitis-hi.mp3"},"duration":{"en":48.9,"hi":31.7},"subject":"Respiratory","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"asthma","topic":"asthma","title":"Asthma","en":"Asthma. Assessment. Assess daytime and night symptoms, reliever use, activity limits, exacerbations, inhaler technique and adherence. Confirm that the diagnosis and objective testing have been appropriately addressed. Treatment principles. An inhaled corticosteroid-containing plan addresses airway inflammation. Reliever and controller roles depend on the prescribed regimen; not every combination inhaler is suitable as a reliever. Provide a personalized written action plan. Safety and follow-up. Severe breathlessness, inability to speak normally, exhaustion or poor response to rescue treatment needs emergency care. Before stepping up, review technique and adherence. Teach device-specific use and mouth rinsing after inhaled corticosteroid doses.","hi":"अस्थमा में दिन और रात के लक्षण, रिलीवर उपयोग, अटैक और इनहेलर की विधि देखें। इनहेल्ड स्टेरॉयड वाली योजना सूजन नियंत्रित करती है। हर कॉम्बिनेशन इनहेलर रिलीवर नहीं होता। व्यक्तिगत लिखित एक्शन प्लान दें। बोलने में कठिनाई वाली सांस, थकावट या रेस्क्यू दवा से लाभ न होना आपातस्थिति है। दवा बढ़ाने से पहले तकनीक और नियमित उपयोग देखें।","files":{"hi":"audio/asthma-hi.mp3","en":"audio/asthma-en.mp3"},"duration":{"hi":32.0,"en":50.4},"subject":"Respiratory","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"copd","topic":"copd","title":"COPD","en":"COPD. Assessment. Assess smoking or exposure history, symptoms, exacerbations, spirometry and comorbidities. Persistent airflow obstruction supports the diagnosis; distinguish an acute exacerbation from pneumonia, heart failure or PE. Treatment principles. Smoking cessation, vaccines, pulmonary rehabilitation and inhaled bronchodilators are central components. Inhaled corticosteroids are appropriate for selected patients rather than everyone, considering exacerbations, eosinophils and pneumonia risk. Safety and follow-up. Review inhaler suitability and technique before escalating therapy. Worsening breathlessness, confusion or low oxygen requires assessment. Oxygen and exacerbation medicine plans are individualized; antibiotics are not automatic for every increase in symptoms.","hi":"सी ओ पी डी में धूम्रपान, एक्सपोजर, सांस की जांच और पुराने अटैक देखें। धूम्रपान छोड़ना, टीके, पुनर्वास और ब्रोंकोडायलेटर महत्वपूर्ण हैं। इनहेल्ड स्टेरॉयड हर मरीज को नहीं चाहिए; लाभ और निमोनिया जोखिम तौलें। इनहेलर तकनीक जांचें। अचानक सांस बिगड़ना दिल की बीमारी या निमोनिया भी हो सकता है। भ्रम या कम ऑक्सीजन में तुरंत जांच करें।","files":{"en":"audio/copd-en.mp3","hi":"audio/copd-hi.mp3"},"duration":{"en":54.9,"hi":32.3},"subject":"Respiratory","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"smoking-cessation","topic":"smoking-cessation","title":"Smoking Cessation","en":"Smoking Cessation. Assessment. Ask permission to discuss tobacco use, dependence, previous attempts, triggers and the person's goals. Relapse is information for adapting support, not evidence of failure. Treatment principles. Behavioural support and appropriate pharmacotherapy can improve success. Nicotine replacement, varenicline and bupropion have different instructions and precautions; select around history, contraindications and preferences. Safety and follow-up. Stopping smoke exposure can change levels of some medicines because combustion products affect enzymes; nicotine itself is not the same mechanism. Arrange follow-up for withdrawal, mood, adverse effects and dose review of affected medicines.","hi":"धूम्रपान पर चर्चा की अनुमति लें और पुराने प्रयास, ट्रिगर तथा लक्ष्य पूछें। दोबारा शुरू होना असफल व्यक्ति होने का प्रमाण नहीं; योजना बदलने की जानकारी है। व्यवहार सहायता और निकोटीन रिप्लेसमेंट, वरेनिक्लिन या बुप्रोपियन उपयुक्त मरीज में मदद कर सकते हैं। धुआं बंद होने से कुछ दवाओं का स्तर बदलता है; इसका कारण केवल निकोटीन नहीं। फॉलो अप और संबंधित दवा समीक्षा करें।","files":{"en":"audio/smoking-cessation-en.mp3","hi":"audio/smoking-cessation-hi.mp3"},"duration":{"en":47.3,"hi":33.8},"subject":"Minor Ailments","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pediatric-health","topic":"pediatric-health","title":"Pediatric Health","en":"Pediatric Health. Assessment. Use age, current weight in kilograms, development, hydration and caregiver observations. Infants are not small adults; fever, feeding changes and lethargy can have different implications by age. Treatment principles. Check whether self-care is appropriate before recommending a product. Use age-appropriate formulations and an oral syringe for measured liquids. Explain the active ingredients to prevent duplication across cough, cold and fever products. Safety and follow-up. Poor responsiveness, breathing difficulty, significant dehydration or fever in a young infant requires prompt medical assessment. Never estimate weight from appearance or use a household spoon as a dosing device. Give clear return precautions to the caregiver.","hi":"बच्चों में उम्र, आज का वजन किलोग्राम में, पानी की स्थिति और व्यवहार देखें। छोटे बच्चे केवल छोटे वयस्क नहीं हैं। दवा का सही रूप और ओरल सिरिंज इस्तेमाल करें। कई सर्दी और बुखार उत्पाद में एक ही घटक दोहर सकता है। बहुत सुस्ती, सांस में परेशानी या छोटे शिशु का बुखार जल्दी जांच मांगता है। अनुमान का वजन और घर का चम्मच इस्तेमाल न करें।","files":{"hi":"audio/pediatric-health-hi.mp3","en":"audio/pediatric-health-en.mp3"},"duration":{"hi":32.8,"en":51.5},"subject":"Minor Ailments","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"travel-medicine","topic":"travel-medicine","title":"Travel Medicine","en":"Travel Medicine. Assessment. Assess destination, itinerary, season, activities, accommodation, duration, health conditions, pregnancy and medicines. Advice depends on the actual journey, not just the country name. Treatment principles. Review routine and travel vaccines, malaria prevention where relevant, food and water safety, bite avoidance and medicine supply. Some preventive measures need advance planning; verify current destination-specific public-health guidance. Safety and follow-up. Fever after travel to a malaria-risk area needs urgent assessment even if prophylaxis was taken. Carry medicines in appropriate labelled packaging and check destination restrictions. Avoid giving one antibiotic or malaria regimen to every traveller.","hi":"यात्रा की सलाह में देश के साथ रास्ता, मौसम, गतिविधि, अवधि और स्वास्थ्य स्थिति पूछें। नियमित और यात्रा टीके, जरूरत पर मलेरिया बचाव, मच्छर से सुरक्षा और दवा की आपूर्ति देखें। वर्तमान गंतव्य निर्देश जांचें। मलेरिया क्षेत्र से लौटने पर बुखार हो तो तुरंत जांच कराएं, बचाव की दवा लेने पर भी। हर यात्री को एक ही एंटीबायोटिक या मलेरिया दवा न दें।","files":{"hi":"audio/travel-medicine-hi.mp3","en":"audio/travel-medicine-en.mp3"},"duration":{"hi":31.8,"en":50.3},"subject":"Minor Ailments","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"eye-health","topic":"eye-health","title":"Eye Health","en":"Eye Health. Assessment. Assess pain, vision change, photophobia, trauma, contact-lens use and unilateral versus bilateral symptoms. A red eye can represent anything from irritation to a sight-threatening condition. Treatment principles. Simple lubrication or allergy treatment is considered only after excluding important red flags. Teach hand hygiene, avoiding bottle-tip contact and appropriate spacing between different eye drops. Safety and follow-up. Painful red eye with reduced vision, chemical exposure or contact-lens-associated pain needs urgent assessment. Do not recommend leftover steroid eye drops; they can worsen certain infections and delay diagnosis. Follow immediate irrigation guidance for chemical injury while arranging care.","hi":"आंख में दर्द, नजर बदलना, रोशनी से परेशानी, चोट और कॉन्टैक्ट लेंस पूछें। हर लाल आंख साधारण एलर्जी नहीं है। गंभीर संकेत न हों तब उपयुक्त लुब्रिकेंट या एलर्जी उपचार चुनें। बोतल का सिरा आंख से न छुएं। दर्द के साथ कम नजर, रसायन या लेंस से दर्द में जल्दी जांच करें। पुरानी स्टेरॉयड ड्रॉप अपनी तरफ से न दें।","files":{"en":"audio/eye-health-en.mp3","hi":"audio/eye-health-hi.mp3"},"duration":{"en":50.1,"hi":30.1},"subject":"Ophthalmology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"cataract-surgery-post-operative-care","topic":"cataract-surgery-post-operative-care","title":"Cataract Surgery Post-Operative Care","en":"Cataract Surgery Post-Operative Care. Assessment. Confirm the operated eye, date, surgeon's drop schedule and current symptoms. Reconcile multiple drops to prevent wrong-eye, duplicate or incorrect-duration use. Treatment principles. Explain the exact antibiotic, anti-inflammatory or other prescribed regimen and demonstrate clean drop technique. A written schedule can separate products and taper instructions; do not substitute a generic schedule for the surgeon's plan. Safety and follow-up. Increasing pain, worsening vision, significant redness or new flashes/floaters after surgery needs prompt ophthalmic assessment. Check that the patient can administer drops and obtain help if needed. Do not stop a prescribed taper solely because the eye feels better.","hi":"मोतियाबिंद ऑपरेशन के बाद सही आंख, तारीख और सर्जन की ड्रॉप योजना पुष्टि करें। कई बूंदों में गलत आंख या अवधि की गलती हो सकती है। लिखित समय और स्टेरॉयड घटाने की योजना दें। आंख में बढ़ता दर्द, नजर गिरना, अधिक लाली या नई चमक और फ्लोटर होने पर तुरंत आंख की जांच करें। मरीज बूंद डाल सकता है या सहायता चाहिए, यह देखें।","files":{"hi":"audio/cataract-surgery-post-operative-care-hi.mp3","en":"audio/cataract-surgery-post-operative-care-en.mp3"},"duration":{"hi":30.5,"en":50.2},"subject":"Ophthalmology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"glaucoma","topic":"glaucoma","title":"Glaucoma","en":"Glaucoma. Assessment. Clarify the glaucoma type, target pressure, eye-drop regimen and adherence. Chronic open-angle disease may have few symptoms even while damage progresses. Treatment principles. Correct regular drop use and ophthalmic monitoring protect vision. Review systemic effects of topical agents: beta-blocker drops can affect pulse and breathing. Teach punctal occlusion when appropriate to reduce systemic exposure. Safety and follow-up. A painful red eye with halos, headache, nausea or reduced vision can indicate acute angle closure and needs emergency assessment. Feeling well is not a reason to stop chronic drops. Verify eye, strength and storage instructions at each transition.","hi":"ग्लूकोमा में बीमारी का प्रकार, ड्रॉप और नियमित उपयोग देखें। लक्षण न होने पर भी नुकसान बढ़ सकता है। बीटा ब्लॉकर आंख की बूंद नाड़ी और सांस पर असर डाल सकती है। सही तकनीक और जरूरत पर आंसू की नली दबाने की विधि सिखाएं। दर्द वाली लाल आंख, रोशनी के चारों ओर घेरे, मतली और नजर घटना एक्यूट एंगल क्लोजर हो सकता है और आपात जांच चाहिए।","files":{"en":"audio/glaucoma-en.mp3","hi":"audio/glaucoma-hi.mp3"},"duration":{"en":47.8,"hi":32.0},"subject":"Ophthalmology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"oncology-general","topic":"oncology-general","title":"Oncology (general)","en":"Oncology (general). Assessment. Confirm the cancer regimen, cycle, intent, supportive medicines, organ function and current symptoms. Oral anticancer therapy is not inherently less hazardous than intravenous therapy. Treatment principles. Treatment schedules, interaction checks, safe handling and adherence are product specific. Reconcile nonprescription and herbal products and teach which symptoms must be reported immediately, using the oncology team's written plan. Safety and follow-up. Fever during possible neutropenia requires urgent oncology or emergency assessment. Do not advise simply treating the fever at home. Severe diarrhoea, dehydration, bleeding or new breathing symptoms also need prompt review. Avoid live-vaccine assumptions during immunosuppression.","hi":"कैंसर के इलाज में दवा, चक्र, उद्देश्य, सहायक दवाएं और अंगों की स्थिति पुष्टि करें। खाने वाली कैंसर दवा भी गंभीर जोखिम रख सकती है। हर्बल और बिना पर्चे की दवाएं जरूर पूछें। कम न्यूट्रोफिल की संभावना में बुखार तत्काल ऑन्कोलॉजी या आपात जांच मांगता है; केवल बुखार की गोली देकर न रुकें। सही भंडारण, संभालने की विधि और संपर्क योजना लिखित दें।","files":{"en":"audio/oncology-general-en.mp3","hi":"audio/oncology-general-hi.mp3"},"duration":{"en":52.3,"hi":32.3},"subject":"Oncology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"chemotherapy-induced-nausea-and-vomiting","topic":"chemotherapy-induced-nausea-and-vomiting","title":"Chemotherapy-Induced Nausea and Vomiting","en":"Chemotherapy-Induced Nausea and Vomiting. Assessment. Assess the regimen's emetogenic risk, prior response and acute versus delayed symptoms. Prevention before treatment differs from rescue management once symptoms occur. Treatment principles. Antiemetic combinations may include a 5-HT3 antagonist, NK1 antagonist, dexamethasone and other agents according to the oncology protocol. Verify each day's schedule and interactions rather than supplying only an as-needed label for a preventive regimen. Safety and follow-up. Monitor dehydration, constipation, sedation, glucose and QT-related risks as relevant. Persistent vomiting, inability to retain fluids or fever needs contact with the oncology team. Review the plan before the next cycle if control was poor.","hi":"कीमो से मतली में दवा के जोखिम और तत्काल तथा देर से होने वाले लक्षण अलग देखें। बचाव की दवा कीमो से पहले योजना अनुसार दी जाती है; केवल जरूरत पर लेने का लेबल पर्याप्त नहीं हो सकता। अलग दिनों का शेड्यूल समझाएं। कब्ज, नींद, शुगर और हृदय की लय के जोखिम देखें। पानी न रुकना या बुखार हो तो ऑन्कोलॉजी टीम से तुरंत संपर्क करें।","files":{"en":"audio/chemotherapy-induced-nausea-and-vomiting-en.mp3","hi":"audio/chemotherapy-induced-nausea-and-vomiting-hi.mp3"},"duration":{"en":52.7,"hi":29.9},"subject":"Oncology","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"electrolyte-disorders","topic":"electrolyte-disorders","title":"Electrolyte Disorders","en":"Electrolyte Disorders. Assessment. Interpret sodium, potassium, calcium and magnesium with symptoms, kidney function, fluid status and the cause. A haemolysed specimen can affect potassium, but a dangerous result cannot simply be dismissed. Treatment principles. Review contributing medicines and confirm the appropriate urgency. Replacement or correction depends on severity, chronicity, route and monitoring; concentration errors with intravenous electrolytes are high risk. Safety and follow-up. Marked weakness, arrhythmia, seizures or altered consciousness requires urgent assessment. Rapid correction of some chronic abnormalities can cause serious harm. Never treat an isolated number with an unmonitored universal replacement formula.","hi":"इलेक्ट्रोलाइट जांच को लक्षण, गुर्दे और पानी की स्थिति के साथ समझें। नमूना खराब होने से पोटैशियम बदल सकता है, लेकिन खतरनाक परिणाम यूं ही न छोड़ें। सुधार की गति और मार्ग गंभीरता तथा बीमारी की अवधि पर निर्भर हैं। दौरे, अनियमित धड़कन, कमजोरी या भ्रम में तुरंत जांच करें। कुछ पुराने असंतुलन तेजी से ठीक करना नुकसानदेह है। बिना निगरानी एक जैसा फार्मूला न लगाएं।","files":{"en":"audio/electrolyte-disorders-en.mp3","hi":"audio/electrolyte-disorders-hi.mp3"},"duration":{"en":49.0,"hi":34.3},"subject":"Anemias, Electrolytes & Nutrition","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"total-parenteral-nutrition","topic":"total-parenteral-nutrition","title":"Total Parenteral Nutrition","en":"Total Parenteral Nutrition. Assessment. Confirm the indication, access route, nutrition assessment, fluid needs and available enteral options. PN is a complex prescription involving energy, protein, electrolytes, micronutrients and compatibility. Treatment principles. Check the complete formulation, infusion instructions and monitoring with the nutrition team. Glucose, electrolytes, triglycerides, liver tests and fluid balance may guide adjustment. Calcium–phosphate compatibility and aseptic preparation are critical. Safety and follow-up. Refeeding risk is important in malnourished patients. Do not add a medicine to PN without verified compatibility and authorization. Line infection, abrupt glucose changes or significant electrolyte abnormalities require prompt review.","hi":"टोटल पैरेंट्रल न्यूट्रिशन में जरूरत, नस का मार्ग, ऊर्जा, प्रोटीन, पानी और इलेक्ट्रोलाइट की पूरी योजना देखें। ग्लूकोज, ट्राइग्लिसराइड, लिवर और तरल संतुलन की निगरानी होती है। कैल्शियम और फॉस्फेट की अनुकूलता तथा निर्जीव तैयारी महत्वपूर्ण है। कुपोषित मरीज में रीफीडिंग का जोखिम देखें। बिना सत्यापित अनुकूलता और अनुमति पी एन में दूसरी दवा न मिलाएं।","files":{"hi":"audio/total-parenteral-nutrition-hi.mp3","en":"audio/total-parenteral-nutrition-en.mp3"},"duration":{"hi":31.7,"en":54.0},"subject":"Anemias, Electrolytes & Nutrition","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"common-anemias","topic":"common-anemias","title":"Common Anemias","en":"Common Anemias. Assessment. Use blood count indices, reticulocytes and relevant iron, B12 or folate results to distinguish causes. Anaemia is a finding that requires an explanation, not a diagnosis of iron deficiency by itself. Treatment principles. Iron treatment needs a cause assessment, tolerable regimen and follow-up of response. B12 deficiency may cause neurological symptoms; folate alone can improve blood findings while missing the underlying B12 problem. Safety and follow-up. Severe symptoms, active bleeding or rapid deterioration needs urgent assessment. Review iron interactions, gastrointestinal adverse effects and safe storage away from children. Failure to respond should trigger review of adherence, absorption and the diagnosis.","hi":"एनीमिया में रक्त कोशिकाओं के आकार, आयरन, बी बारह और फोलेट की जानकारी देखें। हर एनीमिया आयरन की कमी नहीं है। आयरन देने के साथ कमी का कारण खोजें और प्रतिक्रिया देखें। बी बारह की कमी नसों को प्रभावित कर सकती है; केवल फोलेट देने से मूल समस्या छिप सकती है। सक्रिय रक्तस्राव या गंभीर कमजोरी में जल्दी जांच करें। आयरन बच्चों से सुरक्षित दूर रखें।","files":{"en":"audio/common-anemias-en.mp3","hi":"audio/common-anemias-hi.mp3"},"duration":{"en":52.1,"hi":32.9},"subject":"Anemias, Electrolytes & Nutrition","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"acute-kidney-injury","topic":"acute-kidney-injury","title":"Acute Kidney Injury","en":"Acute Kidney Injury. Assessment. Assess the creatinine trend, urine output, hydration, recent illness, obstruction risk and nephrotoxic exposures. Creatinine-based estimates are less reliable when kidney function is changing rapidly. Treatment principles. Management identifies and treats the cause while reviewing medicines, fluid status and monitoring. Temporary medicine changes need a documented individualized plan including reassessment and restarting when appropriate. Safety and follow-up. Severe hyperkalaemia, pulmonary oedema, marked oliguria or systemic illness needs urgent care. Do not apply a stable chronic-kidney dose table mechanically to rapidly evolving AKI. Avoid attributing every creatinine rise to dehydration.","hi":"एक्यूट किडनी इंजरी में क्रिएटिनिन का बदलाव, पेशाब, पानी की स्थिति और गुर्दे को नुकसान देने वाली दवाएं देखें। तेजी से बदलती कार्यक्षमता में सामान्य अनुमान कम भरोसेमंद होते हैं। कारण का इलाज और दवा समीक्षा करें। दवा रोकने पर दोबारा शुरू करने की योजना भी लिखें। बहुत कम पेशाब, फेफड़े में पानी या गंभीर पोटैशियम बढ़ना तत्काल देखभाल मांगता है।","files":{"en":"audio/acute-kidney-injury-en.mp3","hi":"audio/acute-kidney-injury-hi.mp3"},"duration":{"en":50.3,"hi":31.8},"subject":"Kidney Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"chronic-kidney-disease","topic":"chronic-kidney-disease","title":"Chronic Kidney Disease","en":"Chronic Kidney Disease. Assessment. CKD assessment uses persistent kidney abnormalities, filtration and albuminuria, not a single abnormal creatinine. Review the cause, progression, cardiovascular risk and medicine exposure. Treatment principles. Care includes appropriate blood-pressure, diabetes and kidney-protective treatment, dose review and avoidance of preventable harm. Monitoring and referral depend on stage, albuminuria, trajectory and complications. Safety and follow-up. Check whether a drug recommendation uses eGFR or creatinine clearance and its units. Avoid unreviewed NSAIDs, supplements and high-risk electrolyte products. New rapid deterioration is not automatically routine CKD progression.","hi":"क्रॉनिक किडनी डिजीज में लंबे समय की असामान्यता, फिल्ट्रेशन और पेशाब का एल्बुमिन देखें। एक असामान्य क्रिएटिनिन से अकेले निर्णय न करें। रक्तचाप, मधुमेह, गुर्दे की सुरक्षा और सही दवा मात्रा महत्वपूर्ण हैं। खुराक के संदर्भ में ई जी एफ आर या क्रिएटिनिन क्लीयरेंस किसका उपयोग है, देखें। बिना समीक्षा एन एस ए आई डी और सप्लीमेंट से बचें। अचानक बिगड़ाव नया कारण मांगता है।","files":{"hi":"audio/chronic-kidney-disease-hi.mp3","en":"audio/chronic-kidney-disease-en.mp3"},"duration":{"hi":35.1,"en":50.6},"subject":"Kidney Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"dialysis","topic":"dialysis","title":"Dialysis","en":"Dialysis. Assessment. Identify haemodialysis versus peritoneal dialysis, the schedule, residual kidney function and the exact medicine. Dialysis removal depends on the drug and treatment characteristics. Treatment principles. Some medicines need timing after dialysis or a supplemental dose; others do not. Use a dialysis-specific current reference and coordinate with the renal team. Review phosphate binders, anaemia therapy and adherence barriers. Safety and follow-up. Do not use one generic dose reduction for every drug. Access infection, breathlessness, confusion or major electrolyte symptoms needs prompt assessment. Protect the access according to the renal team's instructions and reconcile changes across care settings.","hi":"डायलिसिस में हेमोडायलिसिस या पेरिटोनियल प्रकार, समय और बची गुर्दे की कार्यक्षमता पूछें। हर दवा डायलिसिस में समान मात्रा में नहीं निकलती। कुछ दवाएं सत्र के बाद या अतिरिक्त खुराक मांगती हैं, कुछ नहीं। वर्तमान डायलिसिस संदर्भ और रीनल टीम से योजना लें। एक जैसा खुराक घटाना सही नहीं। एक्सेस में संक्रमण, सांस या भ्रम में जल्दी जांच करें।","files":{"hi":"audio/dialysis-hi.mp3","en":"audio/dialysis-en.mp3"},"duration":{"hi":31.3,"en":50.2},"subject":"Kidney Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"renal-dose-adjustment","topic":"renal-dose-adjustment","title":"Renal Dose Adjustment","en":"Renal Dose Adjustment. Choose the right information. Check the exact medicine and the renal measure used in its dosing reference. Creatinine clearance and estimated glomerular filtration rate are related but are not automatically interchangeable. Confirm units and whether body-surface-area indexing matters. Consider the trend, hydration, recent illness, dialysis and timing. Creatinine-based equations are less reliable when kidney function is changing rapidly; a single apparently reassuring value can mislead. Assess the whole regimen. Identify renally eliminated medicines, active metabolites, nephrotoxic exposures and medicines that alter fluid or electrolyte balance. Use a current monograph or specialized reference for adjustment and monitoring. Avoid using a classroom equation as an automatic prescribing recommendation. The appropriate response may be a dose change, interval change, alternative, temporary hold through an authorized process, or closer monitoring. Communicate uncertainty. A patient with acute illness and rising creatinine needs reassessment, not blind acceptance of yesterday’s dose. Clarify the plan, responsible clinician and follow-up measurements.","hi":"गुर्दे के अनुसार दवा बदलते समय सही अनुमान और इकाई देखें। ई जी एफ आर और क्रिएटिनिन क्लीयरेंस हमेशा अदला-बदली योग्य नहीं हैं। संदर्भ किस विधि का उपयोग करता है, यह पुष्टि करें। तेजी से बदलते गुर्दे में स्थिर सूत्र कम भरोसेमंद हो सकता है। कुछ दवाओं की मात्रा और कुछ का अंतराल बदलता है। लोडिंग और रखरखाव खुराक अलग सोचें। उम्र, वजन, डायलिसिस, दवा स्तर और क्लिनिकल प्रतिक्रिया को साथ रखें; एक ही प्रतिशत सभी दवाओं पर न लगाएं।","files":{"hi":"audio/renal-dose-adjustment-hi.mp3","en":"audio/renal-dose-adjustment-en.mp3"},"duration":{"hi":40.9,"en":75.9},"subject":"Kidney Health","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"health-promotion-and-immunizations","topic":"health-promotion-and-immunizations","title":"Health Promotion and Immunizations","en":"Health Promotion and Immunizations. Assessment. Assess vaccination history, age, medical risk, pregnancy, previous reactions and the relevant provincial schedule. Distinguish anaphylaxis to a component from expected local or systemic effects. Treatment principles. Use current NACI recommendations, the Canadian Immunization Guide and provincial eligibility rules. Check product, dose, route, interval, storage and consent. Prepare for anaphylaxis and document the administered vaccine and follow-up. Safety and follow-up. Live vaccines need particular assessment in pregnancy or significant immunosuppression. A cold-chain excursion requires quarantine and assessment rather than automatic use. Do not assume public funding and clinical eligibility are the same question.","hi":"टीकाकरण में इतिहास, उम्र, गर्भावस्था, बीमारी और पिछली प्रतिक्रिया देखें। सामान्य दर्द और वास्तविक एनाफिलैक्सिस अलग हैं। वर्तमान नैसी, कनाडाई गाइड और प्रांतीय पात्रता जांचें। उत्पाद, मात्रा, मार्ग, अंतराल, भंडारण और सहमति पुष्टि करें। कोल्ड चेन बिगड़ने पर वैक्सीन अलग रखें और जांच करवाएं। सरकारी भुगतान और चिकित्सकीय पात्रता एक ही प्रश्न नहीं हैं।","files":{"en":"audio/health-promotion-and-immunizations-en.mp3","hi":"audio/health-promotion-and-immunizations-hi.mp3"},"duration":{"en":52.8,"hi":34.7},"subject":"Law & Ethics","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"federal-law","topic":"federal-law","title":"Federal Law","en":"Federal Law. Assessment. Identify which legal framework applies: medicines, controlled substances, privacy and provincial professional practice are not interchangeable. Federal rules and provincial requirements can both affect the same prescription. Treatment principles. Use the current consolidated legislation, regulations and applicable exemptions. Establish the drug category and the specific activity, such as dispensing, transfer, delivery or destruction, before checking the rule. Safety and follow-up. Never assume a temporary exemption remains active or applies to every profession and activity. Record the authority and date used for a decision. An employer policy may be stricter but cannot authorize an act prohibited by law.","hi":"संघीय कानून में दवा, नियंत्रित पदार्थ और प्रांतीय व्यावसायिक नियम अलग पहचानें। एक पर्चे पर दोनों स्तर लागू हो सकते हैं। पहले दवा की श्रेणी और कार्य, जैसे वितरण, ट्रांसफर या नष्ट करना, तय करें। वर्तमान कानून और लागू छूट देखें। अस्थायी छूट को हमेशा सक्रिय न मानें। निर्णय में उपयोग की गई कानूनी authority और तारीख दर्ज करें। कार्यस्थल नीति कानून से ऊपर नहीं है।","files":{"en":"audio/federal-law-en.mp3","hi":"audio/federal-law-hi.mp3"},"duration":{"en":48.6,"hi":36.0},"subject":"Law & Ethics","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"canadian-healthcare-system","topic":"canadian-healthcare-system","title":"Canadian Healthcare System","en":"Canadian Healthcare System. Assessment. Canada's healthcare responsibilities are shared across federal, provincial and territorial systems. Registration, publicly funded services and drug coverage differ by jurisdiction and eligibility. Treatment principles. Help patients navigate care using the relevant provincial resources, private coverage and community supports. A product being prescribed or approved for sale does not automatically mean it is publicly reimbursed. Safety and follow-up. Do not equate PEBC certification with a provincial licence. Clarify the person's registration pathway with the regulator. In patient care, assess cost barriers without assuming coverage from age, employment or residence alone.","hi":"कनाडा में स्वास्थ्य सेवाओं की जिम्मेदारी संघीय और प्रांतीय स्तर पर बंटी है। लाइसेंस, सेवाएं और दवा कवरेज अलग हो सकते हैं। दवा बाजार में मंजूर है या लिखी गई है, इससे सरकारी भुगतान निश्चित नहीं होता। मरीज की पात्रता और सहायता के विकल्प देखें। पी ई बी सी प्रमाणन अपने आप प्रांतीय लाइसेंस नहीं है। पंजीकरण का रास्ता संबंधित रेगुलेटर से पुष्टि करें।","files":{"en":"audio/canadian-healthcare-system-en.mp3","hi":"audio/canadian-healthcare-system-hi.mp3"},"duration":{"en":48.0,"hi":33.9},"subject":"Law & Ethics","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"ontario-law-ethics","topic":"ontario-law-ethics","title":"Ontario Law & Ethics","en":"Ontario Law & Ethics. Use the right authority. Identify whether your question concerns federal law, Ontario legislation, OCP standards or organizational policy. Check the applicable source and effective date rather than relying on an old summary. For the Ontario Jurisprudence, Ethics and Professionalism exam, use the OCP blueprint and linked preparation resources to build a coverage checklist. Keep your study current. OCP states that its October 20, 2026 exam will reflect Controlled Substances Regulations effective October 1, 2026. Keep your intended exam date visible when choosing materials. This introductory lesson is a navigation guide. It does not constitute a complete Ontario legal course or determine your registration eligibility.","hi":"ओंटारियो की तैयारी में राष्ट्रीय पी ई बी सी और प्रांतीय ज्यूरिस्प्रूडेंस, एथिक्स तथा प्रोफेशनलिज्म परीक्षा अलग रखें। ओंटारियो कॉलेज ऑफ फार्मासिस्ट्स का वर्तमान ब्लूप्रिंट और आधिकारिक संदर्भ उपयोग करें। पंजीकरण, कार्यक्षेत्र, पर्चे, नियंत्रित दवा, सहमति, गोपनीयता और रिकॉर्ड के नियम पढ़ें। किसी गतिविधि के लिए केवल सामान्य ज्ञान नहीं, लागू वर्तमान अधिकार जांचें। अस्थायी संघीय छूट और बदलती तारीखों को ध्यान से देखें। पी ए सी ई की जरूरत आपकी पंजीकरण राह पर निर्भर है; ऐप अभ्यास उसका विकल्प नहीं।","files":{"en":"audio/ontario-law-ethics-en.mp3","hi":"audio/ontario-law-ethics-hi.mp3"},"duration":{"en":50.7,"hi":43.9},"subject":"Law & Ethics","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"evidence-based-medicine-and-study-design","topic":"evidence-based-medicine-and-study-design","title":"Evidence-Based Medicine and Study Design","en":"Evidence-Based Medicine and Study Design. Frame the question. Identify the population, intervention, comparator and outcomes. Prioritize outcomes that matter to patients and consider both benefit and harm. Randomization helps reduce baseline confounding; allocation concealment and blinding address different sources of bias. Observational studies can reveal associations but require careful assessment of confounding and selection. Read critically. Check the population, setting, follow-up, missing data, outcome definitions and analysis. A statistically significant result may still be too small or uncertain to be clinically useful. Relative effects need baseline risk for interpretation. Consider absolute effects, confidence intervals, harms, patient preferences and applicability before recommending a change.","hi":"प्रमाण आधारित निर्णय में मरीज, हस्तक्षेप, तुलना और परिणाम से सवाल बनाएं। अध्ययन का डिजाइन सवाल से मेल खाना चाहिए। रैंडमाइजेशन समूहों को तुलनीय बनाने में मदद करता है, लेकिन हर पक्षपात खत्म नहीं करता। ब्लाइंडिंग, फॉलो अप, विश्लेषण और प्रासंगिकता देखें। सांख्यिकीय महत्व और मरीज के लिए महत्वपूर्ण लाभ अलग बातें हैं। रिश्ते से कारण अपने आप सिद्ध नहीं होता। प्रभाव का आकार, विश्वास अंतराल और मरीज की परिस्थिति के अनुसार निष्कर्ष लें।","files":{"en":"audio/evidence-based-medicine-and-study-design-en.mp3","hi":"audio/evidence-based-medicine-and-study-design-hi.mp3"},"duration":{"en":53.5,"hi":40.2},"subject":"Evidence & Research","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"literature-references","topic":"literature-references","title":"Literature & References","en":"Literature & References. Assessment. Define the clinical question and the type of information needed before selecting a source. Product information, a practice guideline and a randomized trial answer different questions. Treatment principles. Use an appropriate current source, inspect its population, methods, funding and update date, and compare applicability to the Canadian setting. For a medicine question, check the exact formulation and indication. Safety and follow-up. A search snippet or AI response is not a verified clinical reference. Follow the claim to the original source and document uncertainty. Conflicting guidance should trigger a comparison of scope, evidence and publication dates rather than choosing the first result.","hi":"संदर्भ ढूंढने से पहले सवाल स्पष्ट करें। दवा मोनोग्राफ, दिशानिर्देश और शोध अध्ययन अलग सवालों के जवाब देते हैं। तारीख, आबादी, तरीके और कनाडाई परिस्थिति से मेल देखें। सर्च का छोटा अंश या ए आई का जवाब सत्यापित क्लिनिकल संदर्भ नहीं है। मूल स्रोत तक जाएं। विरोधी सलाह में क्षेत्र, प्रमाण और तारीख की तुलना करें, केवल पहला परिणाम न चुनें।","files":{"en":"audio/literature-references-en.mp3","hi":"audio/literature-references-hi.mp3"},"duration":{"en":48.0,"hi":32.9},"subject":"Evidence & Research","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"diagnostic-test-interpretation","topic":"diagnostic-test-interpretation","title":"Diagnostic Test Interpretation","en":"Diagnostic Test Interpretation. Use a two-by-two table. Sensitivity is the fraction of people with the condition who test positive. Specificity is the fraction without the condition who test negative. Positive predictive value is the fraction of positive results that are true positives. Negative predictive value is the fraction of negative results that are true negatives. Interpret in context. Predictive values depend on how common the condition is in the tested population. In a low-prevalence setting, a meaningful share of positive results can be false positives even when specificity is high. Consider pre-test probability, consequences of errors and whether confirmation is required. A screening result should not be treated as a complete clinical diagnosis.","hi":"सेंसिटिविटी बीमारी वाले लोगों में सही पॉजिटिव और स्पेसिफिसिटी बीमारी न होने पर सही नेगेटिव पहचानती है। पॉजिटिव और नेगेटिव प्रेडिक्टिव वैल्यू पूछती हैं कि इस परिणाम के सही होने की संभावना क्या है। यह बीमारी की शुरुआती संभावना से बदलती है। कम प्रचलन में पॉजिटिव परिणाम की पुष्टि जरूरी हो सकती है। टेस्ट का समय, नमूना और उपयोग की आबादी देखें। एक नतीजे को मरीज के लक्षण और पहले की संभावना से अलग न पढ़ें।","files":{"en":"audio/diagnostic-test-interpretation-en.mp3","hi":"audio/diagnostic-test-interpretation-hi.mp3"},"duration":{"en":48.0,"hi":37.8},"subject":"Evidence & Research","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"hospital-pharmacy","topic":"hospital-pharmacy","title":"Hospital Pharmacy","en":"Hospital Pharmacy. Assessment. Hospital medication use spans prescribing, verification, preparation, administration and monitoring. Transitions, urgent orders, infusions and formulary substitutions create distinct risks. Treatment principles. Clarify the indication, patient-specific factors and administration requirements. Reconcile admission and discharge medicines, including intentional changes. Coordinate with nurses and prescribers using closed-loop communication. Safety and follow-up. Check route, concentration, rate, line compatibility and independent-check requirements for high-risk infusions. A formulary substitution is not permission to ignore dose or formulation differences. Document unresolved issues and responsibility for follow-up.","hi":"अस्पताल में दवा की सुरक्षा लिखने से लेकर देने और निगरानी तक है। भर्ती और छुट्टी की दवाएं मिलाएं और जानबूझकर हुए बदलाव स्पष्ट करें। इंजेक्शन में मार्ग, सांद्रता, गति और लाइन की अनुकूलता जांचें। फॉर्म्युलरी विकल्प होने से खुराक या रूप का अंतर खत्म नहीं होता। नर्स और डॉक्टर से बंद चक्र में पुष्टि करें तथा अधूरे मुद्दे और जिम्मेदारी लिखें।","files":{"hi":"audio/hospital-pharmacy-hi.mp3","en":"audio/hospital-pharmacy-en.mp3"},"duration":{"hi":31.0,"en":52.1},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"compounding","topic":"compounding","title":"Compounding","en":"Compounding. Assessment. Determine whether compounding is appropriate and whether a suitable commercial product exists. Confirm the formulation, ingredients, calculations, equipment, competency and applicable sterile, nonsterile or hazardous-drug standards. Treatment principles. Use a validated master formulation and document the preparation record, actual ingredients, checks, packaging and assigned beyond-use date. A manufacturer's expiry and a compounded preparation's beyond-use date are different concepts. Safety and follow-up. Do not invent stability or compatibility data or extend a beyond-use date by appearance. Assess contamination and occupational exposure controls. Final release requires the designated quality checks and clear storage and administration counselling.","hi":"कम्पाउंडिंग से पहले जरूरत, उपलब्ध बाजार उत्पाद, फार्मूला और उपयुक्त मानक देखें। सत्यापित मास्टर फार्मूला, सामग्री, गणना और तैयारी रिकॉर्ड रखें। निर्माता की एक्सपायरी और बनी तैयारी की बियॉन्ड यूज़ तारीख अलग हैं। केवल दिखने से स्थिरता न मानें और तारीख न बढ़ाएं। संक्रमण तथा कर्मचारियों के एक्सपोजर का नियंत्रण करें। अंतिम जांच और भंडारण की स्पष्ट सलाह दें।","files":{"en":"audio/compounding-en.mp3","hi":"audio/compounding-hi.mp3"},"duration":{"en":51.3,"hi":33.7},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"social-determinants-of-health","topic":"social-determinants-of-health","title":"Social Determinants of Health","en":"Social Determinants of Health. Assessment. Explore practical barriers such as cost, transport, housing, food access, language, discrimination and caregiving demands. Ask respectfully instead of labelling the patient noncompliant. Treatment principles. Adapt the plan with the patient: simplify where appropriate, find coverage or community supports and arrange accessible communication. A clinically effective regimen may fail if the person cannot obtain or use it. Safety and follow-up. Do not make assumptions from identity or appearance. Obtain consent before involving supports and share only appropriate information. Record the agreed solution and whether the barrier was actually resolved.","hi":"इलाज में खर्च, यातायात, घर, भोजन, भाषा और परिवार की जिम्मेदारियां असर डालती हैं। मरीज को गैरजिम्मेदार कहने के बजाय बाधा पूछें। योजना सरल करना, कवरेज और सामुदायिक सहायता ढूंढना मदद कर सकता है। पहचान या दिखावे से अनुमान न लगाएं। सहायता जोड़ने से पहले सहमति लें और केवल जरूरी जानकारी साझा करें। बाधा सच में हल हुई या नहीं, यह देखें।","files":{"en":"audio/social-determinants-of-health-en.mp3","hi":"audio/social-determinants-of-health-hi.mp3"},"duration":{"en":46.1,"hi":34.0},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"safety-and-documentation","topic":"safety-and-documentation","title":"Safety and Documentation","en":"Safety and Documentation. Assessment. A useful record separates observations, patient reports, clinical interpretation and actions. Include the relevant time, participants and unresolved uncertainty so another clinician can follow the decision. Treatment principles. Document the problem, assessment, agreed plan, counselling, communication and follow-up responsibility. Correct errors through the approved process that preserves the audit trail rather than silently deleting the original record. Safety and follow-up. Avoid copied text that describes an assessment you did not perform. Record near misses and incidents through the appropriate learning process while prioritizing immediate patient safety. Secure access and minimum-necessary sharing remain essential.","hi":"अच्छे रिकॉर्ड में देखा गया तथ्य, मरीज की बात, आकलन और कार्रवाई अलग हों। समय, योजना, सलाह और फॉलो अप की जिम्मेदारी लिखें। गलत रिकॉर्ड सुधारते समय पुराना निशान सुरक्षित रखें; चुपचाप मिटाएं नहीं। ऐसी कॉपी की हुई जांच न लिखें जो की ही नहीं। गलती या नियर मिस से सीखने की प्रक्रिया अपनाएं और पहले मरीज की सुरक्षा देखें।","files":{"hi":"audio/safety-and-documentation-hi.mp3","en":"audio/safety-and-documentation-en.mp3"},"duration":{"hi":29.7,"en":49.3},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pharmacy-management","topic":"pharmacy-management","title":"Pharmacy Management","en":"Pharmacy Management. Assessment. Management decisions affect safe staffing, inventory, workflow, privacy and continuity of care. Identify the service need and risks before prioritizing speed or sales. Treatment principles. Maintain ordering and recall systems, appropriate storage, training and documented procedures. Use workload and incident information to improve processes, and plan for shortages and service disruptions. Safety and follow-up. Expired, recalled or temperature-exposed stock should be separated pending the appropriate decision. Commercial pressure does not justify skipping professional checks. A useful quality measure examines patient outcomes and errors, not only prescription volume.","hi":"फार्मेसी प्रबंधन में स्टाफ, स्टॉक, काम का प्रवाह, गोपनीयता और सेवा की निरंतरता आती है। केवल बिक्री या गति को लक्ष्य न बनाएं। रिकॉल, कमी, प्रशिक्षण और भंडारण की प्रक्रिया रखें। एक्सपायर या तापमान से प्रभावित स्टॉक अलग करें। व्यापार का दबाव जरूरी पेशेवर जांच छोड़ने का कारण नहीं है। गुणवत्ता में मरीज के परिणाम और त्रुटियां भी मापें।","files":{"en":"audio/pharmacy-management-en.mp3","hi":"audio/pharmacy-management-hi.mp3"},"duration":{"en":47.5,"hi":31.6},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"inter-professional-care","topic":"inter-professional-care","title":"Inter-professional Care","en":"Inter-professional Care. Assessment. Clarify each professional's role, the patient's goals and the decision requiring collaboration. Do not assume that sending a message means a recommendation was received or implemented. Treatment principles. Use a concise structure: situation, relevant background, assessment and recommendation. State urgency, the proposed action and how to reach you, then confirm the agreed plan and responsibility. Safety and follow-up. Disagreement should focus on patient safety and evidence. Escalate unresolved urgent concerns through the appropriate pathway. Document the communication and outcome; respect consent and confidentiality when sharing information.","hi":"दूसरे स्वास्थ्य पेशेवरों के साथ काम में भूमिका, मरीज का लक्ष्य और जरूरी निर्णय स्पष्ट करें। स्थिति, जरूरी पृष्ठभूमि, आकलन और सुझाव संक्षेप में दें। संदेश भेजना मतलब कार्रवाई हो गई नहीं है; प्राप्ति और सहमति की पुष्टि करें। जिम्मेदारी तथा फॉलो अप लिखें। असहमति में व्यक्ति नहीं, प्रमाण और सुरक्षा पर बात करें। जरूरी अधूरा मुद्दा उचित स्तर पर उठाएं।","files":{"hi":"audio/inter-professional-care-hi.mp3","en":"audio/inter-professional-care-en.mp3"},"duration":{"hi":32.9,"en":45.2},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"medication-reconciliation-and-soap","topic":"medication-reconciliation-and-soap","title":"Medication Reconciliation and SOAP","en":"Medication Reconciliation and SOAP. Reconcile differences. Compare the best available medication history with the new orders. Identify omissions, duplications, dose changes and medicines stopped or started. Determine which changes were intentional and which need clarification. Resolve discrepancies with the responsible clinician. Communicate the final list and reasons for changes to the patient and relevant professionals. An unexplained discrepancy should remain an open issue, not silently disappear. Write a SOAP note. Subjective: the patient’s symptoms, experience and goals. Objective: measured findings and reliable records. Assessment: the problem, interpretation and rationale. Plan: action, counselling, monitoring and follow-up. Distinguish reported information from verified facts. Include the date, relevant context and professional responsibility. Concise documentation should still allow another clinician to understand your decision.","hi":"मेडिकेशन रिकन्सिलिएशन में मरीज वास्तव में क्या लेता है, उसे नए ऑर्डर से मिलाएं। छूटी दवा, दोहराव और बदली मात्रा के कारण स्पष्ट करें। जानबूझकर और अनजाने बदलाव अलग हैं। अंतिम सूची मरीज और संबंधित टीम तक पहुंचाएं। सोप नोट में सब्जेक्टिव मरीज की बात, ऑब्जेक्टिव मापे तथ्य, असेसमेंट आपकी व्याख्या और प्लान कार्रवाई है। अधूरी जानकारी और फॉलो अप की जिम्मेदारी लिखें। केवल सूची बनाना रिकन्सिलिएशन पूरा नहीं करता।","files":{"en":"audio/medication-reconciliation-and-soap-en.mp3","hi":"audio/medication-reconciliation-and-soap-hi.mp3"},"duration":{"en":64.4,"hi":39.5},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"prescription-verification","topic":"prescription-verification","title":"Prescription Verification","en":"Prescription Verification. Three linked checks. Confirm patient, prescriber, medicine, strength, dosage form, route, directions, quantity and relevant dates. Check indication, allergies, duplication, interactions and the patient’s ability to use the regimen. Verify provincial and federal requirements using current authoritative references. Then compare the dispensed product and label against the verified prescription. A clinically appropriate order can still be assembled incorrectly. Handle ambiguity safely. If the prescription is illegible, internally inconsistent or potentially unsafe, hold the affected step and clarify with an appropriate source. Do not guess from a familiar dose or from the stock bottle. For a discrepancy, document the concern, assessment, communication, resolution and follow-up. Explain delays in a way that maintains patient trust. Practise a final check. Inspect the identity, product, strength, dosage form, expiry, quantity, label and packaging separately. Use an independent check where the local process requires one; repeating a rushed glance is not independent verification.","hi":"पर्चे की जांच में मरीज, लिखने वाला, दवा, ताकत, रूप, मार्ग, निर्देश, मात्रा और तारीख देखें। फिर जरूरत, एलर्जी, अंतःक्रिया, दोहराव और मरीज की क्षमता जांचें। क्लिनिकल, कानूनी और तकनीकी जांच अलग हैं। अस्पष्ट निर्देश का अनुमान न लगाएं; सही स्रोत से स्पष्ट करें। अंतिम उत्पाद और लेबल को सत्यापित पर्चे से मिलाएं। चिंता, बातचीत और समाधान दर्ज करें। परिचित दवा होने से स्वतंत्र जांच की जरूरत खत्म नहीं होती।","files":{"hi":"audio/prescription-verification-hi.mp3","en":"audio/prescription-verification-en.mp3"},"duration":{"hi":38.6,"en":74.3},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"antimicrobial-stewardship","topic":"antimicrobial-stewardship","title":"Antimicrobial Stewardship","en":"Antimicrobial Stewardship. Ask the right questions. Is there a likely infection, what is the suspected source, and how ill is the patient? Check relevant cultures, prior exposure, allergies, organ function, interactions and local guidance. An antibiotic is not automatically appropriate for a symptom such as cough. When serious illness is suspected, prompt clinical assessment takes priority over a routine minor-ailment pathway. Reassess the plan. Review drug, dose, route and duration against the patient and evidence. Reassess when clinical response and microbiology become available. Communicate opportunities to narrow or stop treatment through the authorized care process. Explain how to use the prescribed course and what worsening signs require review. Do not give a universal instruction to stop early or extend therapy without reassessment.","hi":"एंटीमाइक्रोबियल स्टूअर्डशिप का उद्देश्य सही मरीज को सही दवा, उचित मात्रा और अवधि देना है। पहले संक्रमण की जरूरत, स्थान और गंभीरता देखें। कल्चर और मरीज की प्रतिक्रिया मिलने पर दवा संकरी, बदली या बंद करनी पड़ सकती है। जहां जरूरी हो संक्रमण का स्रोत नियंत्रित करें। मरीज की सुरक्षा और प्रतिरोध दोनों ध्यान में रखें। केवल एंटीबायोटिक कम देना लक्ष्य नहीं; जरूरी इलाज देर करना भी हानिकारक है। कारण और समीक्षा की तारीख दर्ज करें।","files":{"en":"audio/antimicrobial-stewardship-en.mp3","hi":"audio/antimicrobial-stewardship-hi.mp3"},"duration":{"en":55.7,"hi":41.0},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"prescriber-calls","topic":"prescriber-calls","title":"Prescriber Calls","en":"Prescriber Calls. Prepare your message. Have the patient identifiers, medicine list, relevant findings and references ready. Know the question you need answered. Use Situation, Background, Assessment and Recommendation to keep the conversation organized. Describe the concrete safety or effectiveness problem. Distinguish what is confirmed from what needs clarification; avoid presenting a suspected issue as an established diagnosis. Close the loop. Recommend a reasonable option and explain why. Confirm the agreed action, who will inform the patient and who will monitor the outcome. Read back critical details when appropriate. Document the communication and response. If the original prescriber is unavailable and the issue is urgent, follow an appropriate escalation pathway rather than leaving an unsafe ambiguity unresolved.","hi":"प्रिस्क्राइबर को फोन करते समय अपनी पहचान, मरीज और कॉल का उद्देश्य पहले बताएं। जरूरी पृष्ठभूमि और विशिष्ट सुरक्षा चिंता दें। अस्पष्ट शिकायत के बजाय स्पष्ट सुझाव और उसका कारण रखें। तत्काल कार्रवाई जरूरी हो तो बताएं। सुनी गई योजना को दोहराकर पुष्टि करें, खासकर खुराक और इकाई। बातचीत, जिम्मेदारी और फॉलो अप दर्ज करें। कॉल का उत्तर न मिले और जोखिम तत्काल हो तो उपयुक्त एस्केलेशन प्रक्रिया अपनाएं।","files":{"hi":"audio/prescriber-calls-hi.mp3","en":"audio/prescriber-calls-en.mp3"},"duration":{"hi":37.9,"en":54.1},"subject":"Pharmacy Practice","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"drug-interactions","topic":"drug-interactions","title":"Drug Interactions","en":"Drug Interactions. Two useful categories. Pharmacokinetic interactions change exposure through absorption, metabolism or elimination. Pharmacodynamic interactions combine effects, such as sedation, bleeding or changes in cardiac conduction. An inhibitor and an inducer can have different onset and offset patterns. The consequence depends on the pathway, active metabolites, dose and patient vulnerability. Judge clinical relevance. Confirm the actual products, route, dose, timing, duration and indication. Use a current interaction reference to assess severity, evidence and management. Patient-specific renal function, age and other medicines can change the risk. Options may include avoiding the combination, selecting an alternative, changing timing when appropriate, adjusting therapy through an authorized process, or monitoring. Timing separation does not solve every interaction. Communicate the action. Explain the concern and proposed plan to the patient and prescriber as appropriate. State what will be monitored, when and by whom. Record why an alert was acted on or overridden.","hi":"दवा अंतःक्रिया का अलर्ट आकलन की शुरुआत है, अंतिम फैसला नहीं। कौन सी दवा, मात्रा, समय, मार्ग और मरीज के जोखिम हैं, देखें। एंजाइम, ट्रांसपोर्टर, फार्माकोडायनेमिक और अवशोषण के कारण अलग होते हैं। कुछ में समय अलग करना मदद करता है, कुछ में नहीं। वर्तमान संदर्भ से गंभीरता और विकल्प देखें। योजना में दवा बदलना, मात्रा, निगरानी या उपयुक्त संयोजन जारी रखना हो सकता है। जरूरी दवा अपनी तरफ से बंद न करवाएं।","files":{"hi":"audio/drug-interactions-hi.mp3","en":"audio/drug-interactions-en.mp3"},"duration":{"hi":39.9,"en":72.8},"subject":"Pharmacy Foundations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"allergy-vs-intolerance","topic":"allergy-vs-intolerance","title":"Allergy vs Intolerance","en":"Allergy vs Intolerance. Clarify the event. Ask which medicine caused the reaction, what happened, when symptoms began, what treatment was needed and whether the person has taken related medicines since. Distinguish the patient’s words from your interpretation. Nausea alone can be an adverse effect without establishing an immune allergy. Serious skin reactions, breathing difficulty, collapse or other severe features require careful assessment and appropriate escalation. Preserve safety. Do not challenge or remove a potentially serious allergy label through an unsupervised trial. Document details and uncertainty, then use an appropriate allergy assessment pathway. Consider both the consequences of exposure and the consequences of an inaccurate label. Clarification can improve treatment options, but must be evidence based and safely performed.","hi":"एलर्जी लिखी हो तो वास्तविक प्रतिक्रिया, समय, गंभीरता, इलाज और दोबारा उपयोग पूछें। प्रतिरक्षा वाली एलर्जी और दूसरे दुष्प्रभाव अलग हैं, लेकिन अधूरी कहानी से एलर्जी हटा न दें। गंभीर सांस, रक्तचाप या त्वचा प्रतिक्रिया का इतिहास विशेष महत्व रखता है। सही दवा और संबंधित समूह स्पष्ट करें। मरीज की बात दस्तावेज करें और जरूरत पर विशेषज्ञ मूल्यांकन लें। केवल मतली या अस्पष्ट पुराने लेबल के आधार पर अनावश्यक व्यापक विकल्प न चुनें।","files":{"en":"audio/allergy-vs-intolerance-en.mp3","hi":"audio/allergy-vs-intolerance-hi.mp3"},"duration":{"en":53.1,"hi":39.7},"subject":"Pharmacy Foundations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"laboratory-interpretation","topic":"laboratory-interpretation","title":"Laboratory Interpretation","en":"Laboratory Interpretation. Read beyond the flag. Check the patient, collection time, units, reference interval, specimen quality and trend. A value outside an interval is not itself a diagnosis, and a value within it does not exclude illness. Medicines, sampling conditions and acute changes can affect results. Relate the finding to symptoms, comorbidities and the decision under consideration. Monitoring that can change care. Before recommending a test, identify what question it answers, when it should be measured and what action a result would prompt. Safety monitoring and effectiveness monitoring answer different questions. For drug levels, confirm dose timing, specimen timing, steady-state assumptions and the appropriate target for that patient and indication.","hi":"लैब परिणाम में नाम, इकाई, नमूने का समय और स्थानीय संदर्भ सीमा देखें। मरीज का पिछला पैटर्न और वर्तमान लक्षण महत्वपूर्ण हैं। एक असामान्य संख्या हमेशा बीमारी नहीं, और सामान्य सीमा हमेशा सुरक्षित स्थिति नहीं होती। नमूना समस्या, दवा और बीमारी परिणाम बदल सकती हैं। गंभीर परिणाम की उचित तात्कालिकता तय करें। गायब जांच को सामान्य न मानें। निर्णय के बाद कौन सी जांच कब और कौन देखेगा, यह तय करें।","files":{"en":"audio/laboratory-interpretation-en.mp3","hi":"audio/laboratory-interpretation-hi.mp3"},"duration":{"en":49.5,"hi":39.3},"subject":"Pharmacy Foundations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"therapeutic-drug-monitoring","topic":"therapeutic-drug-monitoring","title":"Therapeutic Drug Monitoring","en":"Therapeutic Drug Monitoring. Before interpreting a level. Confirm the medicine, regimen, recent doses, missed doses, route, dose changes and collection time. Assess kidney and liver function, interactions and signs of toxicity or inadequate effect. Determine whether the relevant target is a trough, peak, area-under-the-curve estimate or another measure. Do not compare values collected at incompatible times. From level to decision. Use the appropriate current protocol and patient context. A result outside a target may reflect timing or adherence rather than a simple need to change the dose. Communicate the interpretation and follow-up clearly. A level in range does not prove safety or effectiveness. Clinical assessment remains necessary.","hi":"दवा का स्तर समय से जुड़ा माप है। आखिरी खुराक, नमूने का समय, स्थिर अवस्था, पालन और गुर्दे की कार्यक्षमता पता करें। गलत समय के नमूने को सही ट्रफ मानकर मात्रा न बदलें। कुल और फ्री स्तर में अंतर प्रोटीन की स्थिति से महत्वपूर्ण हो सकता है। लक्ष्य बीमारी और मरीज अनुसार है। लक्षण और नुकसान के साथ स्तर समझें। नई मात्रा के बाद अगला स्तर कब होगा और कौन समीक्षा करेगा, यह स्पष्ट करें।","files":{"hi":"audio/therapeutic-drug-monitoring-hi.mp3","en":"audio/therapeutic-drug-monitoring-en.mp3"},"duration":{"hi":37.4,"en":50.0},"subject":"Pharmacy Foundations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"routes-dosage-forms","topic":"routes-dosage-forms","title":"Routes & Dosage Forms","en":"Routes & Dosage Forms. Check formulation intent. Immediate-release, modified-release and enteric-coated products may not be interchangeable by crushing or splitting. Confirm the exact product and current handling guidance before altering it. A route change may change bioavailability, onset and exposure. Do not assume that an oral, topical, inhaled or injectable amount can be substituted directly. Match the patient. Assess swallowing ability, dexterity, vision, cognition, device technique and the practicality of storage and preparation. Use an appropriate alternative or support when needed. Explain whether the medicine needs shaking, reconstitution, measuring, priming or a specific technique using the exact product instructions.","hi":"दवा का मार्ग और रूप उसकी पहचान का हिस्सा हैं। एक ही घटक की सामान्य और मॉडिफाइड रिलीज गोली समान तरीके से नहीं दी जा सकती। कुचलने, खोलने या ट्यूब से देने से पहले उत्पाद का विश्वसनीय निर्देश देखें। पैच, इनहेलर, इंजेक्शन और तरल में अलग उपयोग तथा भंडारण हैं। निगलने में कठिनाई पर उपयुक्त विकल्प चुनें। केवल मिलीग्राम बराबर होने पर उत्पाद बदलना सुरक्षित मानकर न चलें।","files":{"en":"audio/routes-dosage-forms-en.mp3","hi":"audio/routes-dosage-forms-hi.mp3"},"duration":{"en":48.0,"hi":34.5},"subject":"Pharmacy Foundations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"geriatrics-frailty","topic":"geriatrics-frailty","title":"Geriatrics & Frailty","en":"Geriatrics & Frailty. Assess what changes care. Consider frailty, cognition, falls, organ function, nutrition, swallowing, vision, dexterity and available support. Ask what matters most to the person and whether the regimen is manageable. Look for duplicate treatment, medicines without a current indication, prescribing cascades and cumulative sedative or anticholinergic burden. Review thoughtfully. Evaluate expected time to benefit, risk of harm, withdrawal effects and feasibility of monitoring. Deprescribing needs a plan; not every medicine should be stopped abruptly. Use shared decision making and coordinate with caregivers when appropriate and authorized. A simpler regimen can help, but changes must preserve clinical intent.","hi":"बुजुर्ग मरीज में केवल उम्र नहीं, कमजोरी, रोजमर्रा की क्षमता, याददाश्त, गिरना, गुर्दे और व्यक्तिगत लक्ष्य देखें। कई दवाओं में एंटीकोलिनर्जिक और नींद का बोझ जुड़ता है। लाभ मिलने का समय और जीवन की प्राथमिकताएं भी महत्वपूर्ण हैं। दवा घटाना सहमति और निगरानी वाली प्रक्रिया है, अचानक सभी दवाएं बंद करना नहीं। देखभाल करने वाले को उचित सहमति से शामिल करें और सरल उपयोग योजना बनाएं।","files":{"en":"audio/geriatrics-frailty-en.mp3","hi":"audio/geriatrics-frailty-hi.mp3"},"duration":{"en":48.2,"hi":35.6},"subject":"Special Populations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pregnancy-breastfeeding","topic":"pregnancy-breastfeeding","title":"Pregnancy & Breastfeeding","en":"Pregnancy & Breastfeeding. Establish the context. Clarify pregnancy status or gestational timing, breastfeeding details, medicine exposure and the condition being treated. Use a current specialist reference rather than a remembered label or a blanket rule. For breastfeeding, the infant’s age, prematurity, health and exposure matter. Pregnancy guidance cannot simply be reused as breastfeeding guidance. Avoid unsupported reassurance. Discuss uncertainty honestly and seek specialist input when needed. Do not automatically stop essential treatment; abrupt withdrawal or undertreatment can also cause harm. Document the sources, discussion, plan and monitoring. Counselling should support an informed decision without overstating either safety or risk.","hi":"गर्भावस्था में दवा का जोखिम गर्भ के चरण, मात्रा, मार्ग और बीमारी पर निर्भर है। स्तनपान में बच्चे की उम्र, समय से पहले जन्म और दूध से वास्तविक एक्सपोजर देखें। दोनों स्थितियां एक जैसी नहीं हैं। इलाज न होने का नुकसान भी चर्चा में रखें। वर्तमान विशेषज्ञ संदर्भ से दवा अनुसार सलाह दें। सभी प्राकृतिक उत्पाद सुरक्षित या सभी दवाएं खतरनाक नहीं होतीं। जरूरी इलाज बदलने से पहले संबंधित टीम के साथ योजना बनाएं।","files":{"en":"audio/pregnancy-breastfeeding-en.mp3","hi":"audio/pregnancy-breastfeeding-hi.mp3"},"duration":{"en":49.2,"hi":39.4},"subject":"Special Populations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"pediatric-dosing","topic":"pediatric-dosing","title":"Pediatric Dosing","en":"Pediatric Dosing. Assessment. Use a verified current weight in kilograms and the correct age group. Distinguish mg/kg/dose from mg/kg/day and confirm the maximum dose and dosing interval from the specific reference. Treatment principles. Calculate the required amount before converting to volume with the dispensed concentration. Check whether the daily amount must be divided and whether the formulation is appropriate. Round only at the final practical administration step. Safety and follow-up. Do not calculate a clinical dose from a weight alone without an indication-specific regimen. Verify unusually large or small results independently. Demonstrate the oral syringe and ask the caregiver to show the measured dose back.","hi":"बच्चे की खुराक में वर्तमान वजन किलोग्राम में लें। मिलीग्राम प्रति किलोग्राम प्रति खुराक और प्रति दिन अलग हैं। दवा, बीमारी, अंतराल और अधिकतम मात्रा संदर्भ से पुष्टि करें। पहले मिलीग्राम निकालें, फिर बोतल की सांद्रता से मिलीलीटर बनाएं। दैनिक मात्रा हो तो सही भाग करें। अंतिम कदम पर व्यावहारिक राउंडिंग करें और अभिभावक से सिरिंज में मात्रा दिखवाएं।","files":{"en":"audio/pediatric-dosing-en.mp3","hi":"audio/pediatric-dosing-hi.mp3"},"duration":{"en":49.3,"hi":32.0},"subject":"Special Populations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"hepatic-impairment","topic":"hepatic-impairment","title":"Hepatic Impairment","en":"Hepatic Impairment. Assessment. Assess the nature and severity of liver disease, synthetic function, portal-hypertension complications and current medicines. Elevated transaminases alone do not fully describe drug clearance or clinical severity. Treatment principles. Use product-specific guidance and a suitable hepatic assessment when required. Consider active metabolites, protein binding, bleeding, sedation and the effect of untreated disease when selecting therapy. Safety and follow-up. There is no universal hepatic equivalent of a simple renal dose equation. New jaundice, confusion, bleeding or deterioration needs assessment. Review alcohol and supplements, and avoid assuming a medicine is safe merely because it is not renally eliminated.","hi":"लिवर की बीमारी में केवल ए एस टी या ए एल टी नहीं, गंभीरता, प्रोटीन बनाने की क्षमता और जटिलताएं देखें। दवा अनुसार निर्देश, सक्रिय मेटाबोलाइट, रक्तस्राव और नींद का जोखिम समझें। लिवर के लिए हर दवा पर लागू एक सरल खुराक फार्मूला नहीं है। नया पीलिया, भ्रम या खून में जांच करें। गुर्दे से न निकलने वाली दवा अपने आप सुरक्षित नहीं होती।","files":{"hi":"audio/hepatic-impairment-hi.mp3","en":"audio/hepatic-impairment-en.mp3"},"duration":{"hi":31.4,"en":49.0},"subject":"Special Populations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"transgender-health","topic":"transgender-health","title":"Transgender Health","en":"Transgender Health. Assessment. Use the person's name and pronouns and ask only clinically relevant questions about anatomy, medicines and goals. Gender identity does not by itself specify reproductive potential, hormone use or screening needs. Treatment principles. Review gender-affirming therapy respectfully, including interactions, route-specific risks and the prescribed monitoring plan. Screening and preventive care should match organs present, age, exposure and individual risk. Safety and follow-up. Hormone therapy is not reliable contraception. Do not withhold unrelated care because gender-affirming care is outside your expertise; obtain appropriate support. Preserve confidentiality and avoid disclosing identity information unnecessarily.","hi":"ट्रांसजेंडर स्वास्थ्य में चुना नाम और सर्वनाम सम्मान से उपयोग करें। केवल जरूरी अंग, दवा और स्वास्थ्य लक्ष्य पूछें। पहचान से हार्मोन उपयोग या गर्भ की संभावना तय नहीं होती। हार्मोन थेरेपी की अंतःक्रिया और निगरानी देखें; यह भरोसेमंद गर्भनिरोध नहीं है। स्क्रीनिंग मौजूद अंग और जोखिम के अनुसार करें। गोपनीयता रखें और अपनी विशेषज्ञता के बाहर उचित सहायता लें।","files":{"en":"audio/transgender-health-en.mp3","hi":"audio/transgender-health-hi.mp3"},"duration":{"en":50.3,"hi":34.1},"subject":"Special Populations","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"inhalers-spacers","topic":"inhalers-spacers","title":"Inhalers & Spacers","en":"Inhalers & Spacers. Identify the device. Confirm the product, device type, prescribed regimen and which medicine is used for which purpose. Ask the person to show how they use it before correcting technique. Metered-dose and dry-powder devices have different preparation and inhalation instructions. Follow the manufacturer’s steps for priming, loading, inhalation, cleaning and storage. Teach and check. Demonstrate one step at a time with an appropriate training device. Check seal, breathing manoeuvre, coordination and remaining-dose awareness. Discuss a spacer when appropriate for the device and patient. Ask the patient to demonstrate again. If control remains poor, assess technique, adherence and clinical status rather than assuming the medicine has failed.","hi":"इनहेलर सिखाने से पहले सही उपकरण और दवा पहचानें। मीटर्ड डोज, ड्राय पाउडर और सॉफ्ट मिस्ट उपकरण की सांस लेने की विधि अलग होती है। जहां उपयुक्त हो स्पेसर मदद करता है। तैयारी, सांस छोड़ना, सही इनहेलेशन और रोकने की विधि उत्पाद अनुसार दिखाएं। मरीज से करके दिखाने को कहें। बची खुराक, सफाई और स्टेरॉयड के बाद कुल्ला समझाएं। केवल पूछना कि समझ आया, सही तकनीक की पुष्टि नहीं करता।","files":{"hi":"audio/inhalers-spacers-hi.mp3","en":"audio/inhalers-spacers-en.mp3"},"duration":{"hi":37.2,"en":50.3},"subject":"Devices & Technique","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"insulin-pens","topic":"insulin-pens","title":"Insulin Pens","en":"Insulin Pens. Assessment. Confirm the exact insulin, concentration, pen type, dose in units and timing. Similar names and pen colours are not reliable identifiers; check the label at every administration. Treatment principles. Demonstrate a new needle, product-specific priming, dialing units, injection-site rotation and the required hold time. Explain storage, in-use expiry and disposal using the exact product instructions. Safety and follow-up. Pens are never shared, even after changing the needle. Do not withdraw insulin from a pen with a syringe or convert a dialed pen dose to volume without explicit product guidance. Teach hypoglycaemia recognition and the individualized response plan.","hi":"इंसुलिन पेन में सही नाम, सांद्रता, यूनिट और समय पुष्टि करें। केवल रंग से पहचान न करें। नई सुई, प्राइमिंग, यूनिट सेट करना, जगह बदलना और दबाए रखने का समय उत्पाद अनुसार दिखाएं। पेन कभी साझा न करें, सुई बदलने पर भी नहीं। पेन से सिरिंज में इंसुलिन निकालकर न दें। कम शुगर की पहचान, उपचार और सही भंडारण समझाएं।","files":{"en":"audio/insulin-pens-en.mp3","hi":"audio/insulin-pens-hi.mp3"},"duration":{"en":48.2,"hi":30.7},"subject":"Devices & Technique","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"naloxone","topic":"naloxone","title":"Naloxone","en":"Naloxone. Assessment. Suspect opioid overdose when a person is unresponsive with slow or absent breathing. Pinpoint pupils may occur but are not required to act. Naloxone reverses opioid effects temporarily. Treatment principles. Call emergency services, give naloxone using the available product instructions and support breathing or CPR according to training and dispatcher directions. Repeat dosing may be needed; stay with the person. Safety and follow-up. Return of breathing does not remove the need for emergency assessment because sedation can recur. Explain kit storage, expiry and how contacts can respond. Naloxone does not reverse every cause of unconsciousness or replace airway support.","hi":"ओपिओइड ओवरडोज में व्यक्ति जवाब नहीं देता और सांस धीमी या बंद हो सकती है। तुरंत आपातकालीन सेवा बुलाएं, उपलब्ध उत्पाद के निर्देश से नालॉक्सोन दें और प्रशिक्षण या डिस्पैचर के अनुसार सांस या सी पी आर की मदद करें। दोबारा खुराक लग सकती है। व्यक्ति जाग जाए तब भी साथ रहें; दवा का असर खत्म होने पर सांस फिर दब सकती है। नालॉक्सोन हर बेहोशी का इलाज नहीं है।","files":{"en":"audio/naloxone-en.mp3","hi":"audio/naloxone-hi.mp3"},"duration":{"en":47.7,"hi":34.2},"subject":"Devices & Technique","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"epinephrine-auto-injectors","topic":"epinephrine-auto-injectors","title":"Epinephrine Auto-injectors","en":"Epinephrine Auto-injectors. Assessment. Recognize anaphylaxis from rapid airway, breathing or circulation problems, sometimes with skin or GI symptoms. A rash is not required for severe anaphylaxis. Treatment principles. Prompt intramuscular epinephrine using the prescribed auto-injector is first-line emergency treatment. Activate emergency services and follow the emergency plan; teach the correct device end, outer-thigh site and product-specific hold time with a trainer. Safety and follow-up. Antihistamines do not replace epinephrine for airway or circulatory compromise. Do not delay treatment while waiting for symptoms to become dramatic. Review storage, expiry, access to additional doses and observation after the event.","hi":"एनाफिलैक्सिस में सांस, गले या रक्तसंचार की समस्या तेजी से हो सकती है; चकत्ता जरूरी नहीं। निर्धारित ऑटो इंजेक्टर से मांसपेशी में एपिनेफ्रिन पहला आपात इलाज है। आपातकालीन मदद बुलाएं। ट्रेनर से सही सिरा, जांघ की बाहरी जगह और उत्पाद अनुसार समय सिखाएं। एंटीहिस्टामिन एपिनेफ्रिन की जगह नहीं लेती। भंडारण, एक्सपायरी और आगे की खुराक की योजना जांचें।","files":{"hi":"audio/epinephrine-auto-injectors-hi.mp3","en":"audio/epinephrine-auto-injectors-en.mp3"},"duration":{"hi":33.8,"en":49.6},"subject":"Devices & Technique","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"},{"id":"blood-glucose-monitoring","topic":"blood-glucose-monitoring","title":"Blood Glucose Monitoring","en":"Blood Glucose Monitoring. Assessment. Clarify whether the person uses a meter or continuous glucose monitor and what decisions the readings support. Technique, strip storage, sensor limitations and timing affect interpretation. Treatment principles. For capillary testing, demonstrate clean dry hands, correct strip and meter use, and safe sharps disposal. For CGM, teach trend interpretation and the device-specific advice when symptoms do not match the sensor value. Safety and follow-up. Treat concerning hypoglycaemia according to the person's plan; severe symptoms need help. Do not change a long-term regimen from a single unexplained reading. Link patterns to meals, activity, illness and medicines and arrange follow-up.","hi":"ग्लूकोज मीटर और लगातार सेंसर में फर्क समझाएं। हाथ साफ और सूखे, सही स्ट्रिप और उपकरण का सही उपयोग दिखाएं। सेंसर के नंबर और लक्षण मेल न खाएं तो उत्पाद की पुष्टि वाली प्रक्रिया अपनाएं। कम शुगर में व्यक्तिगत योजना के अनुसार तुरंत कदम लें। एक अस्पष्ट नंबर से पूरी दवा योजना न बदलें। भोजन, व्यायाम, बीमारी और दवाओं के साथ पैटर्न देखें।","files":{"en":"audio/blood-glucose-monitoring-en.mp3","hi":"audio/blood-glucose-monitoring-hi.mp3"},"duration":{"en":49.4,"hi":32.1},"subject":"Devices & Technique","depth":"Concise topic review","reviewStatus":"Independent clinical review pending"}],"drugs":[{"name":"Warfarin","drugClass":"Anticoagulant","topic":"warfarin-dosing","focus":"INR monitoring, bleeding assessment, interactions and an individualized regimen."},{"name":"Metformin","drugClass":"Glucose-lowering medicine","topic":"diabetes","focus":"Review kidney function, tolerability and the patient-specific monitoring plan."},{"name":"Insulin","drugClass":"Glucose-lowering medicine","topic":"diabetes","focus":"Confirm the exact product, concentration, device and units; address hypoglycemia and technique."},{"name":"Salbutamol","drugClass":"Bronchodilator","topic":"inhalers-spacers","focus":"Check the exact inhaler, technique, symptom pattern and the agreed respiratory care plan."},{"name":"Ramipril","drugClass":"ACE inhibitor","topic":"hypertension","focus":"Review the indication, blood pressure, renal and electrolyte monitoring, and precautions."},{"name":"Amlodipine","drugClass":"Calcium-channel blocker","topic":"hypertension","focus":"Review blood pressure, tolerability and adherence in the context of current guidance."},{"name":"Acetaminophen","drugClass":"Analgesic / antipyretic","topic":"medication-history","focus":"Check all combination products to identify duplication and establish total exposure."},{"name":"Ibuprofen","drugClass":"NSAID","topic":"medication-safety","focus":"Assess gastrointestinal, renal, cardiovascular and interaction risks before recommending use."}],"domains":["Clinical Care","Distribution","Knowledge & Expertise","Communication & Collaboration","Leadership & Stewardship","Professionalism"],"release":{"label":"All-topic review edition","topicCount":150,"independentClinicalReview":false,"fullDetailedClinicalCourse":false,"audioScope":"English and Hindi concise reviews for every topic","examBankValidated":false},"blueprint":[{"domain":"Clinical Care","mcq":50,"count":100},{"domain":"Distribution","mcq":20,"count":40},{"domain":"Knowledge & Expertise","mcq":11,"count":22},{"domain":"Communication & Collaboration","mcq":4,"count":8},{"domain":"Leadership & Stewardship","mcq":3,"count":6},{"domain":"Professionalism","mcq":12,"count":24}],"competencies":[{"code":"1.1","label":"Gather relevant patient information","domain":"Clinical Care"},{"code":"1.2","label":"Assess health, needs and goals","domain":"Clinical Care"},{"code":"1.3","label":"Develop a care plan together","domain":"Clinical Care"},{"code":"1.4","label":"Put the care plan into action","domain":"Clinical Care"},{"code":"1.5","label":"Monitor and adjust the plan","domain":"Clinical Care"},{"code":"1.6","label":"Review and process prescriptions","domain":"Distribution"},{"code":"1.7","label":"Prepare medicines for dispensing","domain":"Distribution"},{"code":"1.8","label":"Check product accuracy and quality","domain":"Distribution"},{"code":"1.9","label":"Release verified medicines safely","domain":"Distribution"},{"code":"1.10","label":"Manage inventory and supply","domain":"Distribution"},{"code":"2.2","label":"Use evidence and professional judgment","domain":"Knowledge & Expertise"},{"code":"3.1","label":"Communicate clearly and effectively","domain":"Communication & Collaboration"},{"code":"3.2","label":"Work in partnership with the patient","domain":"Communication & Collaboration"},{"code":"3.3","label":"Collaborate with the care team","domain":"Communication & Collaboration"},{"code":"3.4","label":"Document care and maintain records","domain":"Communication & Collaboration"},{"code":"4.2","label":"Support public and community health","domain":"Leadership & Stewardship"},{"code":"5.1","label":"Apply current law and regulation","domain":"Professionalism"},{"code":"5.2","label":"Make ethical decisions","domain":"Professionalism"},{"code":"5.4","label":"Support equity and inclusion","domain":"Professionalism"},{"code":"5.5","label":"Improve safety and quality","domain":"Professionalism"}]};
